import { useEffect, useState } from 'react'
import { Autocomplete, CircularProgress, TextField } from '@mui/material'

export interface AsyncSelectOption {
  value: string | number
  label: string
  [extra: string]: any
}

interface AsyncSelectFieldProps<T extends AsyncSelectOption> {
  label: string
  value: T | null
  onChange: (option: T | null) => void
  /** Busca en el servidor lo que el usuario escribió. */
  loadOptions: (input: string) => Promise<T[]>
  /** Opciones que se ofrecen antes de escribir (recientes o la lista corta). */
  defaultOptions?: T[]
  required?: boolean
  disabled?: boolean
  helperText?: string
  /** Marca el campo con error; el texto del error va en `helperText`. */
  error?: boolean
}

const SEARCH_DELAY_MS = 350

/**
 * Campo de búsqueda con opciones que vienen del servidor (clientes, equipos,
 * tipos). Mismo contorno y foco turquesa que los demás campos del
 * `FormDialog`; reemplaza al `react-select` asíncrono suelto.
 */
const AsyncSelectField = <T extends AsyncSelectOption>({
  label,
  value,
  onChange,
  loadOptions,
  defaultOptions = [],
  required = false,
  disabled = false,
  helperText,
  error = false
}: AsyncSelectFieldProps<T>) => {
  const [inputValue, setInputValue] = useState('')
  const [options, setOptions] = useState<T[]>(defaultOptions)
  const [loading, setLoading] = useState(false)

  useEffect(() => {
    const term = inputValue.trim()
    // Sin texto, o con el texto de la opción ya elegida, se ofrecen las de siempre
    if (!term || term === value?.label) {
      setOptions(defaultOptions)
      return undefined
    }
    let cancelled = false
    const timer = setTimeout(() => {
      setLoading(true)
      loadOptions(term)
        .then((found) => {
          if (!cancelled) setOptions(found)
        })
        .catch(() => {
          if (!cancelled) setOptions([])
        })
        .finally(() => {
          if (!cancelled) setLoading(false)
        })
    }, SEARCH_DELAY_MS)
    return () => {
      cancelled = true
      clearTimeout(timer)
    }
    // defaultOptions cambia de identidad en cada render del padre
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [inputValue, value])

  return (
    <Autocomplete<T, false, false, false>
      options={options}
      value={value}
      onChange={(_event, option) => onChange(option)}
      inputValue={inputValue}
      onInputChange={(_event, text) => setInputValue(text)}
      // El servidor ya filtró: no volver a filtrar en el navegador
      filterOptions={(all) => all}
      isOptionEqualToValue={(a, b) => String(a.value) === String(b.value)}
      getOptionLabel={(option) => option.label}
      loading={loading}
      loadingText='Buscando…'
      noOptionsText='Sin resultados'
      openText='Abrir'
      closeText='Cerrar'
      clearText='Limpiar'
      disabled={disabled}
      renderInput={(params) => (
        <TextField
          {...params}
          label={label}
          required={required}
          error={error}
          helperText={helperText}
          InputProps={{
            ...params.InputProps,
            endAdornment: (
              <>
                {loading ? (
                  <CircularProgress color='inherit' size={18} />
                ) : null}
                {params.InputProps.endAdornment}
              </>
            )
          }}
        />
      )}
    />
  )
}

export default AsyncSelectField

import SignalLoader from 'src/Components/Common/SignalLoader'
import { useMemo, useState } from 'react'
import {
  Container,
  Typography,
  Box,
  Grid,
  Button,
  IconButton,
  Avatar,
  Tooltip
} from '@mui/material'
import {
  Assignment as AssignmentIcon,
  ArrowBack as ArrowBackIcon,
  Business as BusinessIcon,
  Error as ErrorIcon,
  SimCardDownloadOutlined,
  TaskAltOutlined,
  VisibilityOutlined,
  Warning as WarningIcon
} from '@mui/icons-material'
import { type MRT_ColumnDef } from 'material-react-table'
import { differenceInDays, format } from 'date-fns'
import { useCertificatesNextToExpire } from 'src/hooks/dashboard/useCertificatesDue'
import { useStore } from '@nanostores/react'
import { userStore } from 'src/store/userStore'
import { FileData } from '../TableFiles/types/fileTypes'
import { useParams, useNavigate } from 'react-router-dom'
import { saveAs } from 'file-saver'
import DataTable from '../Common/DataTable'
import EmptyState from '../Common/EmptyState'
import StatusPill, { StatusPillTone } from '../Common/StatusPill'
import { notify } from 'src/utils/notify'
import LmsPageHeader from '../lms/admin/LmsPageHeader'
import LmsStatCard from '../lms/admin/LmsStatCard'

import { logger } from 'src/utils/logger'
type FilterType = 'all' | 'warning' | 'expired'

const FILTER_FILE_SUFFIX: Record<FilterType, string> = {
  all: '',
  warning: '-proximos-vencer',
  expired: '-vencidos'
}

/** Estado de un certificado según los días que faltan (o pasaron) para su vencimiento. */
const getCertificateStatus = (
  cert: FileData
): {
  kind: FilterType | 'vigente'
  tone: StatusPillTone
  label: string
  daysText: string
  days: number
} => {
  const days = differenceInDays(new Date(cert.nextCalibrationDate), new Date())
  if (days < 0) {
    return {
      kind: 'expired',
      tone: 'error',
      label: 'Vencido',
      daysText: `hace ${Math.abs(days).toLocaleString('es-CO')} ${Math.abs(days) === 1 ? 'día' : 'días'}`,
      days
    }
  }
  if (days <= 30) {
    return {
      kind: 'warning',
      tone: 'warning',
      label: 'Próximo a vencer',
      daysText:
        days === 0 ? 'vence hoy' : `en ${days} ${days === 1 ? 'día' : 'días'}`,
      days
    }
  }
  return {
    kind: 'vigente',
    tone: 'success',
    label: 'Vigente',
    daysText: `en ${days.toLocaleString('es-CO')} días`,
    days
  }
}

const formatDate = (value?: string | Date | null) =>
  value ? format(new Date(value), 'dd/MM/yyyy') : '—'

/**
 * Certificados de un cliente que requieren atención: vencidos y por vencer
 * en 30 días. El personal interno entra desde el inicio; el cliente ve el
 * suyo como pantalla principal.
 */
const Dashboard: React.FC = () => {
  const navigate = useNavigate()
  const { id } = useParams<{ id: string }>()
  const $userStore = useStore(userStore)
  const customerId: number | null =
    $userStore.customer?.id || id ? $userStore.customer?.id || Number(id) : null
  const { data: tableData = [], isLoading: loading } =
    useCertificatesNextToExpire<FileData>(customerId, {
      onError: (error) => {
        logger.error('Error fetching file data:', error)
        notify.error('No se pudieron cargar los certificados del cliente')
      }
    })
  // Información del cliente tomada del primer registro
  const customerInfo: any = tableData.length > 0 ? tableData[0].customer : null
  const [filterType, setFilterType] = useState<FilterType>('all')

  const counts = useMemo(() => {
    let warning = 0
    let expired = 0
    tableData.forEach((cert) => {
      const { kind } = getCertificateStatus(cert)
      if (kind === 'warning') warning++
      else if (kind === 'expired') expired++
    })
    return { all: tableData.length, warning, expired }
  }, [tableData])

  const filteredData = useMemo(
    () =>
      filterType === 'all'
        ? tableData
        : tableData.filter(
            (cert) => getCertificateStatus(cert).kind === filterType
          ),
    [tableData, filterType]
  )

  const toggleFilter = (next: FilterType) =>
    setFilterType((current) => (current === next ? 'all' : next))

  const handleExportExcel = async () => {
    if (filteredData.length === 0) {
      notify.info('No hay certificados para exportar')
      return
    }

    const XLSX = await import('xlsx')

    const exportData = filteredData.map((row) => {
      const status = getCertificateStatus(row)
      return {
        Compañía: row.customer?.nombre || '',
        Equipo: row.device?.name || '',
        'Tipo de Certificado': row.certificateType?.name || '',
        Ciudad: row.city,
        Ubicación: row.location,
        Sede: row.sede,
        'Activo Fijo': row.activoFijo,
        Serie: row.serie,
        'Fecha de Calibración': row.calibrationDate
          ? format(new Date(row.calibrationDate), 'dd/MM/yyyy')
          : '',
        'Próxima Fecha de Calibración': row.nextCalibrationDate
          ? format(new Date(row.nextCalibrationDate), 'dd/MM/yyyy')
          : '',
        Estado: status.label,
        'Días Restantes': status.daysText
      }
    })

    const worksheet = XLSX.utils.json_to_sheet(exportData)
    const workbook = XLSX.utils.book_new()
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Certificados')
    const excelBuffer = XLSX.write(workbook, {
      bookType: 'xlsx',
      type: 'array'
    })
    const data = new Blob([excelBuffer], { type: 'application/octet-stream' })

    const fileName = `${customerInfo?.nombre || 'Cliente'}-certificados${FILTER_FILE_SUFFIX[filterType]}-${format(new Date(), 'yyyy-MM-dd')}.xlsx`
    saveAs(data, fileName)
    notify.success('Excel descargado')
  }

  const columns = useMemo<MRT_ColumnDef<FileData>[]>(
    () => [
      {
        id: 'equipo',
        header: 'Equipo',
        size: 280,
        accessorFn: (row) => row.device?.name || '',
        Cell: ({ row }) => {
          const name = row.original.device?.name || 'N/A'
          return (
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
              <Avatar
                sx={{
                  width: 32,
                  height: 32,
                  bgcolor: '#00BFA5',
                  fontSize: 14,
                  fontWeight: 700
                }}
              >
                {name.charAt(0).toUpperCase()}
              </Avatar>
              <Box sx={{ minWidth: 0 }}>
                <Typography variant='body2' fontWeight={600}>
                  {name}
                </Typography>
                <Typography variant='caption' color='text.secondary'>
                  Serie {row.original.serie || '—'}
                </Typography>
              </Box>
            </Box>
          )
        }
      },
      {
        id: 'ubicacion',
        header: 'Ubicación',
        size: 260,
        accessorFn: (row) =>
          [row.city, row.location, row.sede].filter(Boolean).join(' '),
        Cell: ({ row }) => (
          <Box>
            <Typography variant='body2'>{row.original.city || '—'}</Typography>
            <Typography variant='caption' color='text.secondary'>
              {[row.original.location, row.original.sede]
                .filter(Boolean)
                .join(' · ')}
            </Typography>
          </Box>
        )
      },
      {
        id: 'ultima',
        header: 'Última calibración',
        size: 150,
        accessorFn: (row) =>
          row.calibrationDate ? new Date(row.calibrationDate).getTime() : 0,
        Cell: ({ row }) => formatDate(row.original.calibrationDate)
      },
      {
        id: 'proxima',
        header: 'Próxima calibración',
        size: 170,
        // Se ordena por la fecha real, no por el texto
        accessorFn: (row) => new Date(row.nextCalibrationDate).getTime(),
        Cell: ({ row }) => (
          <Box>
            <Typography variant='body2'>
              {formatDate(row.original.nextCalibrationDate)}
            </Typography>
            <Typography variant='caption' color='text.secondary'>
              {getCertificateStatus(row.original).daysText}
            </Typography>
          </Box>
        )
      },
      {
        id: 'estado',
        header: 'Estado',
        size: 170,
        accessorFn: (row) => getCertificateStatus(row).days,
        Cell: ({ row }) => {
          const status = getCertificateStatus(row.original)
          return (
            <StatusPill size='small' tone={status.tone} label={status.label} />
          )
        }
      },
      {
        id: 'tipo',
        header: 'Tipo',
        size: 160,
        accessorFn: (row) => row.certificateType?.name || '',
        Cell: ({ cell }) => cell.getValue<string>() || '—'
      }
    ],
    []
  )

  if (loading) {
    return <SignalLoader fullPage />
  }

  const backButton = id ? (
    <Tooltip title='Volver'>
      <IconButton
        aria-label='Volver'
        onClick={() => navigate(-1)}
        sx={{ border: '1px solid #e5e7eb', borderRadius: '10px' }}
      >
        <ArrowBackIcon />
      </IconButton>
    </Tooltip>
  ) : null

  if (tableData.length === 0) {
    return (
      <Container maxWidth='xl' sx={{ py: 3 }}>
        <LmsPageHeader
          title={customerInfo?.nombre || 'Certificados'}
          subtitle='Certificados vencidos o próximos a vencer'
          icon={<BusinessIcon />}
          actions={backButton}
        />
        <EmptyState
          icon={<TaskAltOutlined />}
          title='Certificados al día'
          hint='Todos los certificados están vigentes: no hay vencidos ni próximos a vencer.'
        />
      </Container>
    )
  }

  return (
    <Container maxWidth='xl' sx={{ py: 3 }}>
      <LmsPageHeader
        title={customerInfo?.nombre || 'Certificados'}
        subtitle='Certificados vencidos o próximos a vencer (dentro de 30 días)'
        icon={<BusinessIcon />}
        actions={
          <>
            {backButton}
            <Button
              variant='outlined'
              startIcon={<SimCardDownloadOutlined />}
              onClick={handleExportExcel}
              sx={{
                borderRadius: '10px',
                textTransform: 'none',
                fontWeight: 600,
                borderColor: '#e5e7eb',
                color: '#374151',
                bgcolor: '#fff',
                '&:hover': {
                  borderColor: '#00897B',
                  color: '#00695C',
                  bgcolor: '#E0F7F4'
                }
              }}
            >
              Exportar Excel
            </Button>
          </>
        }
      />

      {/* Los tres indicadores filtran la tabla; el activo se puede quitar con otro clic */}
      <Grid container spacing={2} sx={{ mb: 4 }}>
        <Grid item xs={12} sm={4}>
          <LmsStatCard
            label='Todos'
            value={counts.all}
            icon={<AssignmentIcon />}
            tone='teal'
            caption={
              filterType === 'all' ? 'Mostrando todos' : 'Clic para ver todos'
            }
            active={filterType === 'all'}
            onClick={() => setFilterType('all')}
          />
        </Grid>
        <Grid item xs={12} sm={4}>
          <LmsStatCard
            label='Próximos a vencer'
            value={counts.warning}
            icon={<WarningIcon />}
            tone='orange'
            caption={
              filterType === 'warning' ? 'Filtro activo' : 'Clic para filtrar'
            }
            active={filterType === 'warning'}
            onClick={() => toggleFilter('warning')}
          />
        </Grid>
        <Grid item xs={12} sm={4}>
          <LmsStatCard
            label='Vencidos'
            value={counts.expired}
            icon={<ErrorIcon />}
            tone='red'
            caption={
              filterType === 'expired' ? 'Filtro activo' : 'Clic para filtrar'
            }
            active={filterType === 'expired'}
            onClick={() => toggleFilter('expired')}
          />
        </Grid>
      </Grid>

      <DataTable<FileData>
        columns={columns}
        data={filteredData}
        itemLabel={['certificado', 'certificados']}
        searchPlaceholder='Buscar por equipo, serie o ubicación'
        enableRowActions
        initialState={{
          // Primero lo que lleva más tiempo vencido
          sorting: [{ id: 'proxima', desc: false }],
          pagination: { pageIndex: 0, pageSize: 25 }
        }}
        muiTablePaginationProps={{ rowsPerPageOptions: [10, 25, 50, 100] }}
        muiTableContainerProps={{ sx: { maxHeight: 'none' } }}
        muiTableBodyRowProps={({ row }) => ({
          onClick: () =>
            navigate(`/calibraciones/certificados/${row.original.id}`),
          sx: { cursor: 'pointer' }
        })}
        renderRowActions={({ row }) => (
          <Tooltip title='Ver certificado'>
            <IconButton
              size='small'
              aria-label={`Ver certificado de ${row.original.device?.name || 'equipo'}`}
              sx={{ color: '#00695C' }}
              onClick={(event) => {
                event.stopPropagation()
                navigate(`/calibraciones/certificados/${row.original.id}`)
              }}
            >
              <VisibilityOutlined fontSize='small' />
            </IconButton>
          </Tooltip>
        )}
        renderEmptyRowsFallback={() => (
          <EmptyState
            icon={<TaskAltOutlined />}
            title='Ningún certificado coincide'
            hint='Prueba con otra búsqueda o quita el filtro de los indicadores.'
          />
        )}
      />
    </Container>
  )
}

export default Dashboard

import * as yup from 'yup'

import { InspectionHistoryData } from './InspectionMaintenance'
import { useLocation, useNavigate, useParams } from 'react-router-dom'

import React, { useEffect, useMemo, useRef, useState } from 'react'
import { EquipmentInfo } from './InspectionMaintenanceForm'
import { notify } from 'src/utils/notify'
import { useFormik } from 'formik'
import { Box, Button, Paper } from '@mui/material'
import { Delete, Straighten } from '@mui/icons-material'
import { addMonths } from 'date-fns'
import {
  useCalibrationRecord,
  useDataSheet,
  useDeleteDataSheetRecord,
  useSaveCalibration
} from '@hooks/dataSheets/useDataSheets'
import FormPage from 'src/Components/Common/FormPage'
import FormSection from 'src/Components/Common/FormSection'
import FormikField from 'src/Components/Common/FormikField'
import FormDateField from 'src/Components/Common/FormDateField'
import FormErrorSummary from 'src/Components/Common/FormErrorSummary'
import ConfirmDialog from 'src/Components/Common/ConfirmDialog'
import {
  DetailCell,
  DetailField,
  DetailSection
} from 'src/Components/Common/DetailBlocks'

import { logger } from 'src/utils/logger'
export interface CalibrationData {
  equipmentId: string | number
  date: string
  calibrationDate: string
  nextCalibrationDate: string
  certificateNumber: string
  comments: string
  elaboratedBy: string
  calibrationCycle: string | null
}

interface CalibrationRecord extends CalibrationData {
  id: number
  verifiedBy?: string
}

interface CalibrationFormProps {
  tableData: InspectionHistoryData[]
  type: 'maintenance' | 'calibration'
  id: string | number
}

const validationSchema = yup.object().shape({
  equipmentId: yup.number().required('ID del equipo es obligatorio'),
  date: yup.date().required('Fecha es obligatoria'),
  calibrationDate: yup.date().required('Fecha de calibración es obligatoria'),
  nextCalibrationDate: yup
    .date()
    .required('Fecha de próxima calibración es obligatoria'),
  certificateNumber: yup
    .string()
    .required('Número de certificado es obligatorio'),
  comments: yup.string().nullable(),
  elaboratedBy: yup.string().required('Elaborado por es obligatorio'),
  calibrationCycle: yup
    .number()
    .typeError('El ciclo debe ser un número')
    .required('Ciclo de calibración es requerido')
    .min(1, 'El ciclo debe ser al menos 1 mes')
})

const CalibrationForm: React.FC = () => {
  const location = useLocation()
  const navigate = useNavigate()
  // El equipo sale del estado de la navegación o, si se entra por enlace directo, de la ruta
  const { id: routeId } = useParams()
  const id = (location.state as CalibrationFormProps | null)?.id ?? routeId

  const isEdit = Boolean(location.state && location.state.edit)
  const [editId, setEditId] = useState<number | null>(null)
  const [confirmDelete, setConfirmDelete] = useState(false)
  const equipoId = isEdit ? location.state.data.equipmentId : id

  const calibrationHistoryId: number | undefined =
    isEdit && location.state && location.state.data
      ? location.state.data.calibrationId
      : undefined
  const { data: calibrationData } =
    useCalibrationRecord<CalibrationRecord>(calibrationHistoryId)
  const prefilledCalibrationId = useRef<number | null>(null)
  const saveCalibrationMutation = useSaveCalibration()
  const deleteCalibrationMutation = useDeleteDataSheetRecord()

  useEffect(() => {
    if (!calibrationData) return
    // Solo precarga una vez por registro para no pisar lo que se esté editando
    if (prefilledCalibrationId.current === calibrationData.id) return
    prefilledCalibrationId.current = calibrationData.id
    const data = calibrationData
    setEditId(data.id)
    formik.setValues({
      ...data,
      equipmentId: data.equipmentId,
      date: data.date.split('T')[0],
      comments: data.comments || '',
      elaboratedBy: data.elaboratedBy || data.verifiedBy || ''
    })
  }, [calibrationData])

  // Fetch equipo: en edición usa calibrationData.equipmentId, en creación usa location.state.id
  const equipmentQueryId =
    isEdit && calibrationData && calibrationData.equipmentId
      ? calibrationData.equipmentId
      : !isEdit && id
        ? id
        : null
  const { data: equipmentData } = useDataSheet<EquipmentInfo>(
    equipmentQueryId,
    { refetchOnWindowFocus: false }
  )
  const equipmentInfo = useMemo<EquipmentInfo | null>(
    () =>
      equipmentData
        ? {
            equipmentName: equipmentData.equipmentName,
            internalCode: equipmentData.internalCode,
            brand: equipmentData.brand,
            model: equipmentData.model,
            serviceType: equipmentData.serviceType,
            serialNumber: equipmentData.serialNumber,
            calibrationCycle: equipmentData.calibrationCycle
          }
        : null,
    [equipmentData]
  )

  // Actualizar valores del formulario cuando cambia equipmentInfo
  useEffect(() => {
    if (equipmentInfo) {
      formik.setFieldValue(
        'calibrationCycle',
        equipmentInfo.calibrationCycle || ''
      )
    }
  }, [equipmentInfo])

  const formik = useFormik<CalibrationData>({
    initialValues: {
      equipmentId: id || '',
      date: '',
      calibrationDate: '',
      nextCalibrationDate: '',
      comments: '',
      elaboratedBy: '',
      certificateNumber: '',
      calibrationCycle: equipmentInfo?.calibrationCycle || ''
    },
    validationSchema: validationSchema,
    onSubmit: async (values, { resetForm }) => {
      try {
        const response = await saveCalibrationMutation.mutateAsync({
          id: isEdit && editId ? editId : null,
          payload: { ...values, name: 'Calibración' }
        })
        if (response.status >= 200 && response.status < 300) {
          notify.success(
            isEdit
              ? 'Calibración actualizada correctamente'
              : 'Calibración enviada correctamente'
          )
          resetForm()
          navigate(`/datasheets/${equipoId}/inspection-maintenance`)
        } else {
          notify.error('Error al enviar la calibración')
        }
      } catch (error) {
        notify.error('Error al enviar la calibración')
        logger.error('Error al enviar la calibración:', error)
      }
    }
  })

  const fieldLabels: { [key in keyof CalibrationData]: string } = {
    equipmentId: 'ID del equipo',
    date: 'Fecha',
    calibrationDate: 'Fecha de calibración',
    nextCalibrationDate: 'Fecha de próxima calibración',
    certificateNumber: 'Número de Certificado',
    comments: 'Comentarios',
    elaboratedBy: 'Elaborado por',
    calibrationCycle: 'Ciclo de calibración'
  }

  useEffect(() => {
    if (formik.values.calibrationDate && equipmentInfo?.calibrationCycle) {
      const parsedDate = new Date(formik.values.calibrationDate)
      if (!isNaN(parsedDate.getTime())) {
        const cycleMonths = Number(equipmentInfo.calibrationCycle)
        formik.setFieldValue(
          'nextCalibrationDate',
          addMonths(parsedDate, cycleMonths).toISOString()
        )
      }
    }
  }, [formik.values.calibrationDate, equipmentInfo?.calibrationCycle])

  const handleDelete = async () => {
    if (!editId) return
    try {
      const response = await deleteCalibrationMutation.mutateAsync(
        `/calibration/${editId}`
      )
      if (response.status === 204 || response.status === 200) {
        notify.success('Calibración eliminada correctamente')
        navigate(-1)
      } else {
        notify.error('Error al eliminar')
      }
    } catch (error) {
      notify.error('Error al eliminar')
    }
    setConfirmDelete(false)
  }

  const dateError = (name: 'date' | 'calibrationDate') =>
    formik.touched[name] && formik.errors[name]
      ? String(formik.errors[name])
      : false

  // La próxima calibración se calcula con la fecha de calibración y el ciclo del equipo
  const nextCalibrationText = formik.values.calibrationDate
    ? addMonths(
        new Date(formik.values.calibrationDate),
        Number(equipmentInfo?.calibrationCycle)
