  model: yup.string().required('Modelo es obligatorio'),
  year: yup
    .number()
    .required('Año es obligatorio')
    .min(1991, 'El año debe ser mayor a 1990'),
  currentMileage: yup
    .number()
    .required('Kilómetros es obligatorio')
    .moreThan(0, 'El kilómetros debe ser mayor a 0'),
  fuelType: yup.string().required('Tipo de Combustible es obligatorio'),
  status: yup.string().required('Estado es obligatorio'),
  transitLicense: yup.string().required('Lincencia de Transito es obligatorio'),
  displacement: yup
    .number()
    .required('Cilindraje es obligatorio')
    .moreThan(0, 'El cilindraje debe ser mayor a 0'),
  color: yup.string().required('Color es obligatorio'),
  serviceType: yup.string().required('Tipo de Servicio es obligatorio'),
  vehicleClass: yup.string().required('Clase es obligatorio'),
  bodyType: yup.string().required('Tipo de Carroceria es obligatorio'),
  capacity: yup
    .number()
    .required('Capacidad es obligatorio')
    .moreThan(0, 'La capacidad debe ser mayor a 0'),
  engineNumber: yup.string().required('Número de Motor es obligatorio'),
  chasisNumber: yup.string().required('Número de Chasis es obligatorio'),
  power: yup
    .number()
    .required('Potencia es obligatorio')
    .moreThan(0, 'La potencia debe ser mayor a 0'),
  declarationImportation: yup
    .string()
    .required('Declaración de Importación es obligatorio'),
  doors: yup
    .number()
    .required('Numero de puertas es obligatorio')
    .moreThan(0, 'Las puertas deben ser mayores a 0'),
  trafficAuthority: yup
    .string()
    .required('Autoridad de Tráfico es obligatorio'),
  importationDate: yup
    .string()
    .matches(
      /^(0[1-9]|[12][0-9]|3[01])-(0[1-9]|1[0-2])-\d{4}$/,
      'El formato debe ser dd-mm-yyyy'
    )
    .required('Fecha de Importación es obligatoria'),
  registrationDate: yup
    .string()
    .matches(
      /^(0[1-9]|[12][0-9]|3[01])-(0[1-9]|1[0-2])-\d{4}$/,
      'El formato debe ser dd-mm-yyyy'
    )
    .required('Fecha de Registro es obligatoria'),
  expeditionDate: yup
    .string()
    .matches(
      /^(0[1-9]|[12][0-9]|3[01])-(0[1-9]|1[0-2])-\d{4}$/,
      'El formato debe ser dd-mm-yyyy'
    )
    .required('Fecha de Expedición es obligatoria')
})

const Fleet = () => {
  const canManage = useCan(PERMISSIONS.FLEET_VEHICLE_MANAGE)
  const axiosPrivate = useAxiosPrivate()
  const $userStore = useStore(userStore)
  const customerId = $userStore.customer?.id || null
  const queryClient = useQueryClient()
  const { data: vehicles = [], refetch } = useVehicles({
    customerId: customerId
  })
  const [createModalOpen, setCreateModalOpen] = useState(false)
  const [validationErrors, setValidationErrors] = useState<{
    [key: string]: string | undefined
  }>({})
  const navigate = useNavigate()

  const saveRowEdits = useMutation(
    async (updatedVehicle: Vehicle) => {
      const { id, ...values } = updatedVehicle
      const { status } = await axiosPrivate.put(`/vehicles/${id}`, values, {})
      if (status !== 200) {
        throw new Error('Error al modificar la hoja de datos')
      }
    },
    {
      onSuccess: () => {
        queryClient.invalidateQueries('vehicles')
        notify.success('Hoja de Datos Modificada Exitosamente!')
      }
    }
  )

  const deleteVehicle = useMutation(
    async (id: number) => {
      const { status } = await axiosPrivate.delete(`/vehicles/${id}`, {})
      if (status !== 204) {
        throw new Error('Error al eliminar la hoja de datos')
      }
    },
    {
      onSuccess: () => {
        queryClient.invalidateQueries('vehicles')
        notify.success('Hoja de Datos Eliminada Exitosamente!')
      }
    }
  )

  const { mutate: createVehicle } = useAddVehicle()

  const handleSaveRowEdits = useCallback(
    async ({
      exitEditingMode,

      values
    }: {
      exitEditingMode: () => void
      row: MRT_Row<Vehicle>
      values: Vehicle
    }) => {
      try {
        await saveRowEdits.mutateAsync({ ...values, customerId: customerId })
        exitEditingMode()
      } catch (error) {
        logger.error('Error al guardar la edición:', error)
      }
    },
    [saveRowEdits]
  )

  const handleDeleteRow = useCallback(
    (row: MRT_Row<Vehicle>) => {
      confirmDialog({ title: `¿Está seguro que desea eliminar la hoja de datos ${row.getValue('licensePlate')}?`, text: 'No podrá recuperar esta información una vez eliminada', confirmLabel: 'Sí' }).then((result) => {
        if (result.isConfirmed) {
          deleteVehicle.mutate(row.getValue('id'))
        }
      })
    },
    [deleteVehicle]
  )

  const getCommonEditTextFieldProps = useCallback(
    ({ cell }: { cell: MRT_Cell<Vehicle> }): TextFieldProps => ({
      error: !!validationErrors[cell.id],
      helperText: validationErrors[cell.id],
      onBlur: (event) => {
        const isValid = validateRequired(event.target.value)
        if (!isValid) {
          setValidationErrors({
            ...validationErrors,
            [cell.id]: `${cell.column.columnDef.header} es obligatorio`
          })
        } else {
          const { [cell.id]: _, ...rest } = validationErrors
          setValidationErrors(rest)
        }
      }
    }),
    [validationErrors]
  )

  const validateRequired = useCallback((value: string) => !!value.length, [])

  const columns = useMemo<MRT_ColumnDef<Vehicle>[]>(
    () => [
      { accessorKey: 'id', header: 'ID', size: 10, enableEditing: false },
      {
        accessorKey: 'licensePlate',
        header: 'Número de Identificación',
        size: 150,
        muiTableBodyCellEditTextFieldProps: getCommonEditTextFieldProps
      },
      {
        accessorKey: 'make',
        header: 'Marca',
        size: 150,
        muiTableBodyCellEditTextFieldProps: getCommonEditTextFieldProps
      },
      {
        accessorKey: 'model',
        header: 'Modelo',
        size: 150,
        muiTableBodyCellEditTextFieldProps: getCommonEditTextFieldProps
      },
      {
        accessorKey: 'year',
        header: 'Año',
        size: 150,
        muiTableBodyCellEditTextFieldProps: getCommonEditTextFieldProps
      },
      {
        accessorKey: 'currentMileage',
        header: 'Kilómetros',
        size: 150,
        muiTableBodyCellEditTextFieldProps: getCommonEditTextFieldProps
      },
      {
        accessorKey: 'fuelType',
        header: 'Tipo de Combustible',
        size: 150,
        muiTableBodyCellEditTextFieldProps: getCommonEditTextFieldProps
      },
      {
        accessorKey: 'status',
        header: 'Estado',
        size: 150,
        muiTableBodyCellEditTextFieldProps: getCommonEditTextFieldProps
      }
    ],
    [getCommonEditTextFieldProps]
  )

  const handleTrip = (vehicle: Vehicle) => {
    if (vehicle && vehicle.id) {
      vehicleStore.set(vehicle)
      navigate(`${vehicle.id}/trip`)
    } else {
      notify.error('No se ha seleccionado un vehículo')
    }
  }

  const formik = useFormik<Vehicle>({
    initialValues: {
      pictureUrl: null,
      purchaseDate: '',
      vin: '',
      licensePlate: '',
      make: '',
      model: '',
      year: 0,
      currentMileage: 0,
      fuelType: '',
      status: '',
      upcomingReminders: [],
      transitLicense: '',
      displacement: 0,
      color: '',
      serviceType: '',
      vehicleClass: '',
      bodyType: '',
      capacity: 0,
      engineNumber: '',
      chasisNumber: '',
      power: 0,
      declarationImportation: '',
      doors: 0,
      trafficAuthority: '',
      importationDate: '',
      registrationDate: '',
      expeditionDate: '',
      customerId: customerId
    },
    validationSchema: validationSchema,
    onSubmit: async (values, { resetForm }) => {
      try {
        await createVehicle(
          { ...values, customerId: customerId },
          {
            onSuccess: () => {
              queryClient.invalidateQueries('vehicles')
              notify.success('Vehículo Creado Exitosamente!')
              setCreateModalOpen(false)
              refetch()
            },
            onError: (error) => {
              logger.error('Error al crear el vehículo:', error)
              notify.error('Error al crear el vehículo')
            }
          }
        )
        resetForm()
      } catch (error) {
        logger.error('Error al crear el vehículo:', error)
      }
    }
  })

  const remindersCount = vehicles.filter((v: Vehicle) => v.upcomingReminders?.length > 0).length
  const avgMileage = vehicles.length
    ? Math.round(vehicles.reduce((acc: number, v: Vehicle) => acc + (Number(v.currentMileage) || 0), 0) / vehicles.length)
    : 0

  return (
    <Container maxWidth='xl' sx={{ py: 3 }}>
      <LmsPageHeader
        title='Flota'
        subtitle='Vehículos, documentos, viajes, inspecciones y mantenimiento'
        icon={<DirectionsCar />}
        actions={
          <>
            <Button variant='outlined' startIcon={<Plumbing />} onClick={() => navigate('/fleet/interventions')} sx={{ color: '#00897B', borderColor: '#00BFA5', '&:hover': { borderColor: '#00897B', bgcolor: '#E0F7F4' } }}>
              Tipos de intervención
            </Button>
            {canManage && (
              <Button variant='contained' startIcon={<Add />} onClick={() => setCreateModalOpen(true)} sx={{ bgcolor: '#00BFA5', whiteSpace: 'nowrap', '&:hover': { bgcolor: '#00ACC1' } }}>
                Crear vehículo
              </Button>
            )}
          </>
        }
      />

      <Grid container spacing={3} sx={{ mb: 3 }}>
        <Grid item xs={12} sm={4}>
          <LmsStatCard label='Vehículos' value={vehicles.length} icon={<DirectionsCar />} tone='teal' />
        </Grid>
        <Grid item xs={12} sm={4}>
          <LmsStatCard
            label='Con documentos por vencer'
            value={remindersCount}
            icon={<WarningAmber />}
            tone={remindersCount > 0 ? 'red' : 'green'}
          />
        </Grid>
        <Grid item xs={12} sm={4}>
          <LmsStatCard
            label='Kilometraje promedio'
            value={`${avgMileage.toLocaleString('es-CO')} km`}
            icon={<Speed />}
            tone='blue'
            compact
          />
        </Grid>
      </Grid>

      <Paper elevation={2} sx={{ borderRadius: 2, overflow: 'hidden' }}>
        <MaterialReactTable
          {...purchaseTableStyle}
          columns={columns}
          data={vehicles}
          enableColumnOrdering
          editingMode='modal'
          enableEditing={canManage}
          onEditingRowSave={handleSaveRowEdits}
          onEditingRowCancel={() => setValidationErrors({})}
          enablePinning
          initialState={{ columnVisibility: { id: false }, columnPinning: { right: ['mrt-row-actions'] } }}
        renderRowActions={({ row, table }) => (
          <Box sx={{ display: 'flex', gap: '1rem' }}>
            <Tooltip arrow placement='right' title='Documentos'>
              <Link to={`${row.original.id}/documents`}>
                <IconButton>
                  <Visibility
                    sx={{
                      color:
                        row.original.upcomingReminders.length > 0 ? '#ef4444' : '#00BFA5'
                    }}
                  />
                </IconButton>
              </Link>
            </Tooltip>
            <Tooltip arrow placement='right' title='Viajes'>
              <Link to={`${row.original.id}/trip`}>
                <IconButton onClick={() => handleTrip(row.original)}>
                  <Commute />
                </IconButton>
              </Link>
            </Tooltip>
            <Tooltip arrow placement='right' title='Inspecciones'>
              <Link to={`${row.original.id}/inspections`}>
                <IconButton onClick={() => handleTrip(row.original)}>
                  <Summarize />
                </IconButton>
              </Link>
            </Tooltip>
            <Tooltip arrow placement='right' title='Intervenciones'>
              <Link to={`${row.original.id}/interventions`}>
                <IconButton>
                  <BuildCircle />
                </IconButton>
              </Link>
            </Tooltip>
  {canManage && (
  <>
            <Divider orientation='vertical' flexItem />
            <Tooltip arrow placement='right' title='Editar'>
              <IconButton color='primary' onClick={() => table.setEditingRow(row)}>
                <Edit />
              </IconButton>
            </Tooltip>
            <Tooltip arrow placement='right' title='Eliminar'>
              <IconButton color='error' onClick={() => handleDeleteRow(row)}>
                <Delete />
              </IconButton>
            </Tooltip>
  </>
  )}
          </Box>
        )}
        />
      </Paper>

      <GenericFormModal
        open={createModalOpen}
        fields={vehicleFields}
        onClose={() => {
          setCreateModalOpen(false)
          formik.resetForm()
        }}
        submitButtonText='Crear Vehículo'
        formik={formik}
      />
    </Container>
  )
}

export default Fleet

import React from 'react'
import {
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Button,
  Stack,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  TextField,
  Checkbox,
  FormControlLabel,
  FormHelperText,
  Avatar
} from '@mui/material'
import { FormikProps } from 'formik'

export interface FieldConfig {
  accessorKey: string
  header: string
  type: 'text' | 'number' | 'select' | 'checkbox' | 'image' | 'date' // Added 'image' type
  options?: string[]
}

interface GenericFormModalProps {
  open: boolean
  fields: FieldConfig[]
  onClose: () => void
  submitButtonText: string
  formik: FormikProps<any>
}

const GenericFormModal: React.FC<GenericFormModalProps> = ({
  open,
  fields,
  onClose,
  submitButtonText,
  formik
}) => {
  return (
    <Dialog open={open}>
      <form onSubmit={formik?.handleSubmit}>
        <DialogTitle textAlign='center'>Crear Vehiculo</DialogTitle>
        <DialogContent sx={{ width: '100%', padding: '1rem' }}>
          <Stack sx={{ gap: '1.5rem', width: '100%', minWidth: '300px' }}>
            {fields.map((field) => (
              <FormControl key={field.accessorKey} fullWidth>
                {field.type === 'text' || field.type === 'number' ? (
                  <TextField
                    label={field.header}
                    name={field.accessorKey}
                    type={field.type}
                    value={formik.values[field.accessorKey]}
                    onChange={formik.handleChange}
                    error={
                      formik.touched[field.accessorKey] &&
                      Boolean(formik.errors[field.accessorKey])
                    }
                    helperText={
                      formik.touched[field.accessorKey] &&
                      (formik.errors[field.accessorKey] as React.ReactNode)
                    }
                  />
                ) : field.type === 'select' ? (
                  <>
                    <InputLabel>{field.header}</InputLabel>
                    <Select
                      label={field.header}
                      name={field.accessorKey}
                      value={formik.values[field.accessorKey]}
                      onChange={formik.handleChange}
                      error={
                        formik.touched[field.accessorKey] &&
                        Boolean(formik.errors[field.accessorKey])
                      }
                    >
                      {field.options?.map((option) => (
                        <MenuItem key={option} value={option}>
                          {option}
                        </MenuItem>
                      ))}
                    </Select>
                    <FormHelperText>
                      {formik.touched[field.accessorKey] &&
                        (formik.errors[field.accessorKey] as React.ReactNode)}
                    </FormHelperText>
                  </>
                ) : field.type === 'image' ? (
                  <>
                    <div className='flex items-center justify-center mb-4'>
                      <label htmlFor='avatarInput' className='cursor-pointer'>
                        <Avatar
                          alt='Foto de perfil'
                          src={
                            formik.values[field.accessorKey]
                              ? URL.createObjectURL(
                                  formik.values[field.accessorKey]
                                )
                              : '/images/no-img.jpg'
                          } // Mostramos la foto de perfil seleccionada
                          sx={{ width: 100, height: 100, mb: 2 }}
                        />
                      </label>
                      {/* {formik.touched[field.accessorKey] &&
                        formik.errors[field.accessorKey] && (
                          <FormHelperText error>
                            {
                              formik.errors[
                                field.accessorKey
                              ] as React.ReactNode
                            }
                          </FormHelperText>
                        )} */}
                      <input
                        id='avatarInput'
                        type='file'
                        accept='image/*'
                        onChange={(event) => {
                          const file = event.currentTarget.files?.[0]

                          if (file) {
                            formik.setFieldValue(field.accessorKey, file)
                          }
                        }}
                        className='hidden'
                      />
                    </div>
                  </>
                ) : field.type === 'date' ? (
                  <TextField
                    label={field.header}
                    name={field.accessorKey}
                    type={field.type}
                    value={formik.values[field.accessorKey]}
                    onChange={formik.handleChange}
                    error={
                      formik.touched[field.accessorKey] &&
                      Boolean(formik.errors[field.accessorKey])
                    }
                    helperText={
                      formik.touched[field.accessorKey] &&
                      (formik.errors[field.accessorKey] as React.ReactNode)
                    }
                  />
                ) : (
                  <FormControlLabel
                    control={
                      <Checkbox
                        name={field.accessorKey}
                        checked={formik.values[field.accessorKey]}
                        onChange={formik.handleChange}
                      />
                    }
                    label={field.header}
                  />
                )}
              </FormControl>
            ))}
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button onClick={onClose}>Cancelar</Button>
          <Button type='submit' variant='contained' color='primary'>
            {submitButtonText}
          </Button>
        </DialogActions>
      </form>
    </Dialog>
  )
}

export default GenericFormModal

import { getApiErrorReason } from 'src/utils/apiError'
import { useState } from 'react'
import { useQuery, useMutation, useQueryClient } from 'react-query'
import {
  Card,
  CardContent,
  CardActions,
  Button,
  Typography,
  Container,
  IconButton,
  Grid
} from '@mui/material'
import { Add, Build, Edit, Delete, ArrowBack } from '@mui/icons-material'
import { useNavigate } from 'react-router-dom'
import { InterventionType } from './types'
import GenericFormModal, { FieldConfig } from './GenericFormModal'
import { useFormik } from 'formik'
import * as yup from 'yup'
import { notify } from 'src/utils/notify'
import useAxiosPrivate from '@utils/use-axios-private'
import type { AxiosInstance } from 'axios'
import { PERMISSIONS } from 'src/constants/permissions'
import { useCan } from '@utils/functions'

import LmsPageHeader from 'src/Components/lms/admin/LmsPageHeader'
import { confirmDialog } from 'src/utils/confirm'

const validationSchema = yup.object().shape({
  name: yup.string().required('Nombre es obligatorio'),
  requiresReminder: yup.boolean(),
  description: yup.string().required('Descripción es obligatoria')
})

const fetchInterventionTypes = async (
  axiosPrivate: AxiosInstance
): Promise<InterventionType[]> => {
  const { data } = await axiosPrivate.get(`/interventionType`)
  return data
}

const InterventionTypes = () => {
  const canManage = useCan(PERMISSIONS.FLEET_INTERVENTION_TYPE_MANAGE)
  const queryClient = useQueryClient()
  const navigate = useNavigate()
  const axiosPrivate = useAxiosPrivate()

  const [modalOpen, setModalOpen] = useState(false)
  const [currentType, setCurrentType] = useState<InterventionType | null>(null)

  const { data: interventionTypes = [] } = useQuery(
    'interventionType',
    () => fetchInterventionTypes(axiosPrivate)
  )

  const createOrUpdateInterventionType = useMutation(
    async (newData: InterventionType) => {
      return currentType
        ? axiosPrivate.put(`/interventionType/${currentType.id}`, newData)
        : axiosPrivate.post(`/interventionType`, newData)
    },
    {
      onSuccess: () => {
        queryClient.invalidateQueries('interventionType')
        notify.success(currentType
            ? 'Tipo de Intervención Actualizado Exitosamente!'
            : 'Tipo de Intervención Creado Exitosamente!')
        setModalOpen(false)
      },
      onError: (error: any) => {
        notify.error(`Error: ${getApiErrorReason(error) || error.message}`)
      }
    }
  )

  const deleteInterventionType = useMutation(
    async (id: number) => {
      const { status } = await axiosPrivate.delete(`/interventionType/${id}`)
      if (status !== 204)
        throw new Error('Error al eliminar el tipo de intervención')
    },
    {
      onSuccess: () => {
        queryClient.invalidateQueries('interventionType')
        notify.success('Tipo de Intervención Eliminado Exitosamente!')
      },
      onError: (error: any) => {
        notify.error(`Error: ${getApiErrorReason(error) || error.message}`)
      }
    }
  )

  const handleDelete = async (id: number) => {
    const result = await confirmDialog({ title: '¿Eliminar Tipo de Intervención?', text: 'Esta acción no se puede deshacer', confirmLabel: 'Sí, eliminar', cancelLabel: 'Cancelar', tone: 'danger' })

    if (result.isConfirmed) {
      deleteInterventionType.mutate(id)
    }
  }

  const handleEdit = (id: number) => {
    const typeToEdit = interventionTypes.find((type) => type.id === id)
    if (typeToEdit) {
      setCurrentType(typeToEdit)
      formik.setValues(typeToEdit)
      setModalOpen(true)
    }
  }

  const handleAddNew = () => {
    setCurrentType(null)
    setModalOpen(true)
  }

  const handleFormSubmit = (values: Record<string, any>) => {
    const payload: Omit<InterventionType, 'id'> = {
      name: values.name,
      requiresReminder: values.requiresReminder,
      description: values.description
    }

    if (currentType?.id !== undefined) {
      createOrUpdateInterventionType.mutate({ ...payload, id: currentType.id })
    } else {
      createOrUpdateInterventionType.mutate(payload)
    }
  }

  const formik = useFormik<InterventionType>({
    initialValues: {
      name: '',
      requiresReminder: false,
      description: ''
    },
    validationSchema: validationSchema,
    onSubmit: async (values, { resetForm }) => {
      handleFormSubmit(values)
      resetForm()
    }
  })

  const fields: FieldConfig[] = [
    { accessorKey: 'name', header: 'Nombre', type: 'text' },
    {
      accessorKey: 'requiresReminder',
      header: 'Requiere Recordatorio',
      type: 'checkbox'
    },
    {
      accessorKey: 'description',
      header: 'Descripción',
      type: 'text'
    }
  ]

  return (
    <Container maxWidth='xl' sx={{ py: 3 }}>
      <Button
        startIcon={<ArrowBack />}
        onClick={() => navigate(-1)}
        sx={{ mb: 1, color: 'text.secondary', textTransform: 'none', fontWeight: 600 }}
      >
        Volver
      </Button>

      <LmsPageHeader
        title='Tipos de Intervención'
        subtitle='Catálogo de intervenciones de mantenimiento de la flota'
        icon={<Build />}
        actions={
          canManage ? (
            <Button variant='contained' startIcon={<Add />} onClick={handleAddNew} sx={{ bgcolor: '#00BFA5', whiteSpace: 'nowrap', '&:hover': { bgcolor: '#00ACC1' } }}>
              Agregar nuevo
            </Button>
          ) : undefined
        }
      />
      <Grid container spacing={3}>
        {interventionTypes.map((type) => (
          <Grid item xs={12} sm={6} md={4} key={type.id}>
            <Card
              sx={{
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
                height: '100%'
              }}
            >
              <CardContent>
                <Typography variant='h5' gutterBottom>
                  {type.name}
                </Typography>
                <Typography variant='body2'>
                  Requiere Recordatorio: {type.requiresReminder ? 'Sí' : 'No'}
                </Typography>
              </CardContent>
{canManage && (
              <CardActions>
                <IconButton onClick={() => handleEdit(type.id as number)}>
                  <Edit />
                </IconButton>
                <IconButton
                  color='error'
                  onClick={() => handleDelete(type.id as number)}
                >
                  <Delete />
                </IconButton>
              </CardActions>
)}
            </Card>
          </Grid>
        ))}
      </Grid>

      <GenericFormModal
        open={modalOpen}
        fields={fields}
        onClose={() => setModalOpen(false)}
        formik={formik}
        submitButtonText={currentType ? 'Actualizar' : 'Crear'}
      />
