import { RangeOption } from '../types'

export const useDeviceData = (
  deviceId: number | string | null,
  selectedRange: RangeOption
) => {
  const axiosPrivate = useAxiosPrivate()
  const [visibleSeries, setVisibleSeries] = useState({
    temperature: true,
    humidity: true
  })

  const { startDateStr, endDateStr } = useMemo(() => {

    if (selectedRange.isCustom) {
      return {
        startDateStr: selectedRange.startDate?.toISOString(),
        endDateStr: selectedRange.endDate?.toISOString()
      }
    }

    const endDate = new Date()
    const startDate = new Date(
      endDate.getTime() -  (selectedRange.hours || 1) * 60 * 60 * 1000
    )

    return {
      startDateStr: startDate.toISOString(),
      endDateStr: endDate.toISOString()
    }
  }, [selectedRange])

  const {
    data: graphData,
    isLoading,
    error
  } = useQuery(
    ['deviceDataPoints', deviceId, startDateStr, endDateStr],
    async () => {
      if (!deviceId || !startDateStr || !endDateStr) return []

      const response = await axiosPrivate.get(
        `/devicesIot/dataPoints?startDate=${startDateStr}&endDate=${endDateStr}&deviceIotId=${deviceId}`
      )
      return response.data
    },
    {
      enabled: !!deviceId && !!startDateStr && !!endDateStr,
      keepPreviousData: true,
      staleTime: 60_000
    }
  )

  const combinedData = useMemo(
    () =>
      graphData?.map((dp: any) => ({
        timestamp: new Date(dp.timestamp).getTime(),
        temperature: dp.avg_temperature,
        humidity: dp.avg_humidity
      })) || [],
    [graphData]
  )

  return {
    visibleSeries,
    setVisibleSeries,
    combinedData,
    graphData,
    isLoading,
    error,
    startDateStr,
    endDateStr
  }
}

import React from 'react'
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  FormControlLabel,
  Switch,
  Box,
  FormHelperText
} from '@mui/material'
import { useFormik } from 'formik'
import * as Yup from 'yup'
import { useMutation, useQueryClient } from 'react-query'
import useAxiosPrivate from '@utils/use-axios-private'
import { notify } from 'src/utils/notify'

import { logger } from 'src/utils/logger'
// Tipos y constantes
export type DeviceAlarm = {
  id: number
  deviceId: number
  name: string
  description?: string
  metric: string
  condition: string
  threshold: number
  enabled: boolean
  active: boolean
  severity: 'info' | 'warning' | 'critical'
  createdAt: Date
  lastTriggered?: Date | null
}

const ALARM_METRICS = ['temperature', 'humidity', 'battery'] as const
const ALARM_CONDITIONS = ['above', 'below', 'equal'] as const
const ALARM_SEVERITIES = ['info', 'warning', 'critical'] as const

interface DeviceAlarmDialogProps {
  open: boolean
  onClose: () => void
  deviceId: number
  alarm: DeviceAlarm | null
}

interface AlarmFormValues {
  name: string
  description: string
  metric: (typeof ALARM_METRICS)[number]
  condition: (typeof ALARM_CONDITIONS)[number]
  threshold: number
  enabled: boolean
  severity: (typeof ALARM_SEVERITIES)[number]
}

const validationSchema = Yup.object({
  name: Yup.string().required('El nombre es obligatorio'),
  description: Yup.string(),
  metric: Yup.string()
    .oneOf([...ALARM_METRICS])
    .required('Seleccione una métrica'),
  condition: Yup.string()
    .oneOf([...ALARM_CONDITIONS])
    .required('Seleccione una condición'),
  threshold: Yup.number()
    .min(0, 'Debe ser mayor o igual a 0')
    .required('Ingrese un umbral válido')
    .typeError('Debe ser un número válido'),
  enabled: Yup.boolean(),
  severity: Yup.string()
    .oneOf([...ALARM_SEVERITIES])
    .required('Seleccione una severidad')
})

const DeviceAlarmDialog: React.FC<DeviceAlarmDialogProps> = ({
  open,
  onClose,
  deviceId,
  alarm
}) => {
  const axiosPrivate = useAxiosPrivate()
  const queryClient = useQueryClient()
  const isEditMode = !!alarm

  const isAlarmMetric = (
    value: string
  ): value is (typeof ALARM_METRICS)[number] => {
    return ALARM_METRICS.includes(value as any)
  }

  const isAlarmCondition = (
    value: string
  ): value is (typeof ALARM_CONDITIONS)[number] => {
    return ALARM_CONDITIONS.includes(value as any)
  }

  const initialValues: AlarmFormValues = {
    name: alarm?.name || '',
    description: alarm?.description || '',
    metric:
      alarm?.metric && isAlarmMetric(alarm.metric)
        ? alarm.metric
        : 'temperature',
    condition:
      alarm?.condition && isAlarmCondition(alarm.condition)
        ? alarm.condition
        : 'above',
    threshold: alarm?.threshold || 0,
    enabled: alarm?.enabled ?? true,
    severity: alarm?.severity || 'info'
  }

  const formik = useFormik({
    initialValues,
    validationSchema,
    onSubmit: async (values) => {
      try {
        const payload = {
          ...values,

          threshold: Number(values.threshold)
        }

        if (isEditMode) {
          await handleUpdate(payload)
        } else {
          await handleCreate(payload)
        }
      } catch (error) {
        logger.error('Error en el formulario:', error)
      }
    },
    enableReinitialize: true
  })

  const createMutation = useMutation({
    mutationFn: async (data: AlarmFormValues) => {
      const response = await axiosPrivate.post(
        `/devicesIot/${deviceId}/alarms`,
        data
      )

      return response.data
    }
  })

  const updateMutation = useMutation({
    mutationFn: async (data: AlarmFormValues) => {
      const response = await axiosPrivate.put(
        `/devicesIot/${alarm?.id}/alarms`,
        data
      )

      return response.data
    }
  })

  const handleCreate = async (data: AlarmFormValues) => {
    try {
      await createMutation.mutateAsync(data)
      notify.success('¡Alarma creada!', 'La alarma se ha creado exitosamente')
      invalidateQueries()
      onClose()
    } catch (error: any) {
      notify.error('Error', error.message || 'Error al crear la alarma')
    }
  }

  const handleUpdate = async (data: AlarmFormValues) => {
    try {
      await updateMutation.mutateAsync(data)
      notify.success(
        '¡Alarma actualizada!',
        'La alarma se ha actualizado exitosamente'
      )
      invalidateQueries()
      onClose()
    } catch (error: any) {
      notify.error('Error', error.message || 'Error al actualizar la alarma')
    }
  }

  const invalidateQueries = () => {
    queryClient.invalidateQueries(['/devicesIot', deviceId, 'alarms'])
    queryClient.invalidateQueries(['activeAlarms', deviceId])
  }

  const handleClose = () => {
    formik.resetForm()
    onClose()
  }

  return (
    <Dialog open={open} onClose={handleClose} maxWidth='sm' fullWidth>
      <DialogTitle>{isEditMode ? 'Editar Alarma' : 'Nueva Alarma'}</DialogTitle>

      <form onSubmit={formik.handleSubmit}>
        <DialogContent>
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3, py: 2 }}>
            {/* Nombre */}
            <TextField
              name='name'
              label='Nombre de la alarma'
              value={formik.values.name}
              onChange={formik.handleChange}
              onBlur={formik.handleBlur}
              error={formik.touched.name && Boolean(formik.errors.name)}
              helperText={formik.touched.name && formik.errors.name}
              fullWidth
              variant='outlined'
            />

            {/* Descripción */}
            <TextField
              name='description'
              label='Descripción (opcional)'
              value={formik.values.description}
              onChange={formik.handleChange}
              onBlur={formik.handleBlur}
              multiline
              rows={3}
              fullWidth
              variant='outlined'
            />

            {/* Configuración de la alarma */}
            <Box sx={{ display: 'flex', gap: 2 }}>
              {/* Métrica */}
              <FormControl
                fullWidth
                error={formik.touched.metric && Boolean(formik.errors.metric)}
              >
                <InputLabel>Métrica</InputLabel>
                <Select
                  name='metric'
                  value={formik.values.metric}
                  label='Métrica'
                  onChange={formik.handleChange}
                  onBlur={formik.handleBlur}
                >
                  {ALARM_METRICS.map((metric) => (
                    <MenuItem key={metric} value={metric}>
                      {metric.charAt(0).toUpperCase() + metric.slice(1)}
                    </MenuItem>
                  ))}
                </Select>
                {formik.touched.metric && formik.errors.metric && (
                  <FormHelperText>{formik.errors.metric}</FormHelperText>
                )}
              </FormControl>

              {/* Condición */}
              <FormControl
                fullWidth
                error={
                  formik.touched.condition && Boolean(formik.errors.condition)
                }
              >
                <InputLabel>Condición</InputLabel>
                <Select
                  name='condition'
                  value={formik.values.condition}
                  label='Condición'
                  onChange={formik.handleChange}
                  onBlur={formik.handleBlur}
                >
                  {ALARM_CONDITIONS.map((condition) => (
                    <MenuItem key={condition} value={condition}>
                      {condition === 'above'
                        ? 'Mayor que'
                        : condition === 'below'
                          ? 'Menor que'
                          : 'Igual a'}
                    </MenuItem>
                  ))}
                </Select>
                {formik.touched.condition && formik.errors.condition && (
                  <FormHelperText>{formik.errors.condition}</FormHelperText>
                )}
              </FormControl>
            </Box>

            {/* Umbral y Severidad */}
            <Box sx={{ display: 'flex', gap: 2 }}>
              {/* Umbral */}
              <TextField
                name='threshold'
                label='Valor umbral'
                type='number'
                value={formik.values.threshold}
                onChange={formik.handleChange}
                onBlur={formik.handleBlur}
                error={
                  formik.touched.threshold && Boolean(formik.errors.threshold)
                }
                helperText={formik.touched.threshold && formik.errors.threshold}
                fullWidth
                inputProps={{ min: 0, step: '0.01' }}
                variant='outlined'
              />

              {/* Severidad */}
              <FormControl
                fullWidth
                error={
                  formik.touched.severity && Boolean(formik.errors.severity)
                }
              >
                <InputLabel>Severidad</InputLabel>
                <Select
                  name='severity'
                  value={formik.values.severity}
                  label='Severidad'
                  onChange={formik.handleChange}
                  onBlur={formik.handleBlur}
                >
                  {ALARM_SEVERITIES.map((severity) => (
                    <MenuItem key={severity} value={severity}>
                      {severity.charAt(0).toUpperCase() + severity.slice(1)}
                    </MenuItem>
                  ))}
                </Select>
                {formik.touched.severity && formik.errors.severity && (
                  <FormHelperText>{formik.errors.severity}</FormHelperText>
                )}
              </FormControl>
            </Box>

            {/* Habilitar/Deshabilitar */}
            <FormControlLabel
              control={
                <Switch
                  checked={formik.values.enabled}
                  onChange={(e) =>
                    formik.setFieldValue('enabled', e.target.checked)
                  }
                  name='enabled'
                  color='primary'
                />
              }
              label='Alarma habilitada'
              labelPlacement='start'
              sx={{ justifyContent: 'space-between', ml: 0 }}
            />
          </Box>
        </DialogContent>

        <DialogActions sx={{ px: 3, pb: 2 }}>
          <Button onClick={handleClose} color='inherit' sx={{ mr: 2 }}>
            Cancelar
          </Button>
          <Button
            type='submit'
            variant='contained'
            color='primary'
            disabled={formik.isSubmitting}
          >
            {isEditMode ? 'Guardar cambios' : 'Crear alarma'}
          </Button>
        </DialogActions>
      </form>
    </Dialog>
  )
}

export default DeviceAlarmDialog

import SignalLoader from 'src/Components/Common/SignalLoader'
import React from 'react'

import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Box,
  Chip,
  Button
} from '@mui/material'
import { format } from 'date-fns'
import { Alert, AlertTitle } from '@mui/material'
import { useQuery } from 'react-query'
import useAxiosPrivate from '@utils/use-axios-private'

import { logger } from 'src/utils/logger'
interface AlarmEvent {
  id: number
  alarmId: number
  deviceId: number
  alarmName: string
  severity: string
  eventType: 'activated' | 'deactivated'
  timestamp: string
  metric: string
  condition: string
  threshold: number
  value: number
}

interface DeviceAlarmEventsTableProps {
  deviceId: number
}

const DeviceAlarmEventsTable: React.FC<DeviceAlarmEventsTableProps> = ({
  deviceId
}) => {
  // Usar fetch nativo para diagnosticar el problema
  const axiosPrivate = useAxiosPrivate()
  const {
    data: events = [],
    isLoading,
    error,
    refetch
  } = useQuery<AlarmEvent[]>({
    queryKey: [`/devicesIot/${deviceId}/alarm-events`],
    queryFn: async () => {
      try {
        // Usar fetch nativo con opciones completas
        const response = await axiosPrivate.get(
          `/devicesIot/${deviceId}/alarm-events`
        )

        // Primero verificar si la respuesta es correcta

        // Intentar parsear como JSON
        try {
          const data = await response.data
          return data as AlarmEvent[]
        } catch (parseError) {
          logger.error('Error al parsear JSON:', parseError)
          throw new Error(
            `Problema al parsear la respuesta como JSON: ${parseError}`
          )
        }
      } catch (error) {
        logger.error('Error completo al obtener eventos de alarmas:', error)
        throw error
      }
    },
    refetchInterval: 10000 // Refrescar cada 10 segundos
  })

  if (isLoading) {
    return <SignalLoader size='small' />
  }

  if (error) {
    logger.error('Error detallado:', error)
    return (
      <Alert severity='error' sx={{ m: 2 }}>
        <AlertTitle>Error</AlertTitle>
        Error al cargar el historial de eventos de alarmas.
        {error instanceof Error ? ` Detalles: ${error.message}` : ''}
        <Box sx={{ mt: 2 }}>
          <Button
            variant='contained'
            color='primary'
            size='small'
            onClick={() => refetch()}
          >
            Reintentar
          </Button>
        </Box>
      </Alert>
    )
  }

  if (!events || events.length === 0) {
    return (
      <Alert severity='info' sx={{ m: 2 }}>
        <AlertTitle>Información</AlertTitle>
        No hay eventos de alarmas registrados para este dispositivo
      </Alert>
    )
  }

  const getEventDescription = (event: AlarmEvent) => {
    const metricDisplay =
      {
        temperature: 'Temperatura',
        humidity: 'Humedad',
        battery: 'Batería'
      }[event.metric] || event.metric

    const conditionDisplay =
      {
        above: 'mayor que',
        below: 'menor que',
        equal: 'igual a'
      }[event.condition] || event.condition

    // Detect sensor error values
    const valueDisplay =
      event.value === -127 ? 'Error de sensor' : `${event.value.toFixed(1)}`

    return `${metricDisplay} ${conditionDisplay} ${event.threshold} (valor actual: ${valueDisplay})`
  }

  return (
    <TableContainer component={Paper} sx={{ mt: 2 }}>
      <Table size='small'>
        <TableHead>
          <TableRow>
            <TableCell>
              <strong>Fecha/Hora</strong>
            </TableCell>
            <TableCell>
              <strong>Nombre</strong>
            </TableCell>
            <TableCell>
              <strong>Tipo</strong>
            </TableCell>
            <TableCell>
              <strong>Severidad</strong>
            </TableCell>
            <TableCell>
              <strong>Detalles</strong>
            </TableCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {events.map((event: AlarmEvent) => (
            <TableRow key={event.id}>
              <TableCell>
                {format(new Date(event.timestamp), 'dd/MM/yyyy HH:mm:ss')}
              </TableCell>
              <TableCell>{event.alarmName}</TableCell>
              <TableCell>
                <Chip
                  size='small'
                  label={
                    event.eventType === 'activated' ? 'Activada' : 'Desactivada'
                  }
                  color={event.eventType === 'activated' ? 'error' : 'success'}
                />
              </TableCell>
              <TableCell>
                <Chip
                  size='small'
                  label={
                    {
                      info: 'Información',
                      warning: 'Advertencia',
                      critical: 'Crítica'
                    }[event.severity] || event.severity
                  }
                  color={
                    ({
                      info: 'info',
                      warning: 'warning',
                      critical: 'error'
                    }[event.severity] as any) || 'default'
                  }
                />
              </TableCell>
              <TableCell>{getEventDescription(event)}</TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </TableContainer>
  )
}

export default DeviceAlarmEventsTable

import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  ReferenceLine
} from 'recharts'
import { Box, Typography, Stack } from '@mui/material'
import { useMemo } from 'react'

interface MainChartProps {
  graphData: Array<{
    timestamp: number
    temperature: number
    humidity: number
  }>
  visibleSeries: {
    temperature: boolean
    humidity: boolean
  }
  onToggleSeries: (series: 'temperature' | 'humidity') => void
  // referenceAboveTemperature?: number
  // referenceBelowTemperature?: number
  // referenceHumidity?: number // Nueva prop
  temperatureAlarms?: {
    above?: number
    below?: number
  }
  humidityAlarms?: {
    above?: number
    below?: number
  }
}

const MainChart = ({
  graphData,
  visibleSeries,
  onToggleSeries,
  // referenceAboveTemperature,
  // referenceBelowTemperature,
  // referenceHumidity
  temperatureAlarms,
  humidityAlarms
}: MainChartProps) => {
  // Custom Tooltip
  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
      const date = new Date(label)
      return (
        <Box
          sx={{
            backgroundColor: 'white',
            border: '1px solid #ccc',
            padding: 1,
            borderRadius: 1,
            boxShadow: 1
          }}
        >
          <Stack spacing={0.5}>
            {payload.map((pl: any) => (
              <Typography
                key={pl.dataKey}
                variant='caption'
                sx={{ color: pl.color }}
              >
                {pl.dataKey === 'temperature'
                  ? `Temp: ${pl.value.toFixed(2)}°C`
                  : `Hum: ${pl.value.toFixed(2)}%`}
              </Typography>
            ))}
            <Typography variant='caption' sx={{ fontWeight: 'bold' }}>
              {`${date.getHours()}:${date.getMinutes().toString().padStart(2, '0')}`}
            </Typography>
          </Stack>
        </Box>
      )
    }
    return null
  }
  // Calcular dominios dinámicos
  const { tempDomain, humDomain, yAxisFormatter } = useMemo(() => {
    if (!graphData || graphData.length === 0) {
      return {
        tempDomain: [0, 40], // Rango default temperatura
        humDomain: [0, 100], // Rango default humedad
        yAxisFormatter: (value: number) => value.toFixed(1)
      }
    }

    const tempValues = graphData
      .map((d) => d.temperature)
      .filter((value) => !isNaN(value) && typeof value === 'number')

    const humValues = graphData
      .map((d) => d.humidity)
      .filter((value) => !isNaN(value) && typeof value === 'number')

    const safeTempDomain = [
      Math.floor(Math.min(...tempValues)),
      Math.ceil(Math.max(...tempValues))
    ]

    const safeHumDomain = [
      Math.floor(Math.min(...humValues)),
      Math.ceil(Math.max(...humValues))
    ]

    return {
      tempDomain: safeTempDomain,
      humDomain: safeHumDomain,
      yAxisFormatter: (value: number) => {
        // Convertir valores grandes a notación científica
        if (value > 1000) return value.toExponential(1)
        return value % 1 === 0 ? value.toString() : value.toFixed(1)
      }
    }
  }, [graphData])
  // Handler para clics en leyenda
  const handleLegendClick = (o: any) => {
    const { dataKey } = o
    onToggleSeries(dataKey as 'temperature' | 'humidity')
  }

  return (
    <Box sx={{ width: '100%', height: 400, mb: 4 }}>
      <ResponsiveContainer>
        <LineChart data={graphData}>
          <CartesianGrid strokeDasharray='3 3' stroke='#f0f0f0' />
          {visibleSeries.temperature && temperatureAlarms?.above && (
            <ReferenceLine
              y={temperatureAlarms.above}
              yAxisId='left'
              stroke='#F44336'
              strokeDasharray='5 5'
              label={{
                value: `Alta: ${temperatureAlarms.above}°C`,
                position: 'right',
                fill: '#F44336'
              }}
            />
          )}
          {visibleSeries.temperature && temperatureAlarms?.below && (
            <ReferenceLine
              y={temperatureAlarms.below}
              yAxisId='left'
              stroke='#F44336'
              strokeDasharray='5 5'
              label={{
                value: `Baja: ${temperatureAlarms.below}°C`,
                position: 'right',
                fill: '#F44336'
              }}
            />
          )}

          {/* Líneas de referencia para humedad */}
          {visibleSeries.humidity && humidityAlarms?.above && (
            <ReferenceLine
              y={humidityAlarms.above}
              yAxisId='right'
              stroke='#2196F3'
              strokeDasharray='5 5'
              label={{
                value: `Alta: ${humidityAlarms.above}%`,
                position: 'left',
                fill: '#2196F3'
              }}
            />
          )}
          {visibleSeries.humidity && humidityAlarms?.below && (
            <ReferenceLine
              y={humidityAlarms.below}
              yAxisId='right'
              stroke='#2196F3'
              strokeDasharray='5 5'
              label={{
                value: `Baja: ${humidityAlarms.below}%`,
                position: 'left',
                fill: '#2196F3'
              }}
            />
          )}
          <XAxis
            dataKey='timestamp'
            type='number'
            domain={['dataMin', 'dataMax']}
            tick={{ fontSize: 12 }}
            tickMargin={10}
            tickFormatter={(tick) => {
              const date = new Date(tick)
              return `${date.getHours()}:${date.getMinutes().toString().padStart(2, '0')}`
            }}
          />
          <YAxis
            yAxisId='left'
            tickCount={5}
            domain={tempDomain}
            tickFormatter={yAxisFormatter}
            label={{ value: '°C', angle: -90, position: 'insideLeft' }}
            allowDataOverflow={true}
          />
          <YAxis
            yAxisId='right'
            tickCount={5}
            domain={humDomain}
            tickFormatter={yAxisFormatter}
            orientation='right'
            label={{ value: '%', angle: 90, position: 'insideRight' }}
            allowDataOverflow={true}
          />
          <Tooltip content={<CustomTooltip />} />
          <Legend onClick={handleLegendClick} />
          <Line
            yAxisId='left'
            type='monotone'
            dataKey='temperature'
            stroke='#F44336'
            hide={!visibleSeries.temperature}
            strokeWidth={2}
            dot={false}
            activeDot={{ r: 6 }}
            strokeOpacity={visibleSeries.temperature ? 1 : 0}
          />
          <Line
            yAxisId='right'
            type='monotone'
            dataKey='humidity'
            stroke='#2196F3'
            strokeWidth={2}
            dot={false}
            activeDot={{ r: 6 }}
            hide={!visibleSeries.humidity}
            strokeOpacity={visibleSeries.humidity ? 1 : 0}
          />
        </LineChart>
      </ResponsiveContainer>
    </Box>
  )
}

export default MainChart

