// components/DeviceGraphs/GraphDrawer/tabs/HistoryTab.tsx

import SignalLoader from 'src/Components/Common/SignalLoader'
import { RANGE_OPTIONS } from 'src/Components/Iot/constants'
import { RangeSelector } from '../parts/RangeSelector'
import { StatsTable } from '../parts/StatsTable'

import { RangeOption } from '../types'
import { TextField, Typography } from '@mui/material'
import MainChart from 'src/Components/Iot/GraphDrawer/parts/MainChart'
import { useState } from 'react'
import { DatePicker } from '@mui/x-date-pickers'

interface HistoryTabProps {
  combinedData: any[]
  visibleSeries: any
  onToggleSeries: any
  temperatureAlarms: any
  humidityAlarms: any
  selectedRange: RangeOption
  onSelectRange: (range: RangeOption) => void
  aggregateStats: any
  isLoading: boolean
  error: any
}

export const HistoryTab = ({
  combinedData,
  visibleSeries,
  onToggleSeries,
  temperatureAlarms,
  humidityAlarms,
  selectedRange,
  onSelectRange,
  aggregateStats,
  isLoading,
  error
}: HistoryTabProps) => {
  const [datePickerOpen, setDatePickerOpen] = useState(false);

  const handleCustomDateSelect = (date: Date | null) => {
    if (!date) return;
    
    // Calcular rango de 24 horas (de 00:00 a 23:59)
    const startDate = new Date(date);
    startDate.setHours(0, 0, 0, 0);
    
    
    const endDate = new Date(date);
    endDate.setHours(23, 59, 59, 999);

    onSelectRange({
      label: 'Personalizado',
      isCustom: true,
      startDate,
      endDate
    });
    
    setDatePickerOpen(false);
  };

  return (
    <>
      <RangeSelector
        selectedRange={selectedRange}
        onSelect={(range) => {
          if (range.isCustom) {
            setDatePickerOpen(true);
          } else {
            onSelectRange(range);
          }
        }}
        options={RANGE_OPTIONS}
      />

{datePickerOpen && (
        <DatePicker
          open
          value={null}
          onChange={handleCustomDateSelect}
          onClose={() => setDatePickerOpen(false)}
          slotProps={{
            textField: (params) => <TextField {...params} fullWidth />
          }}
          sx={{ mt: 2, mb: 2 }}
        />
      )}

      {isLoading ? (
        <SignalLoader message='Cargando datos históricos...' />
      ) : error ? (
        <Typography color='error'>Error al cargar datos históricos</Typography>
      ) : (
        <MainChart
          graphData={combinedData}
          visibleSeries={visibleSeries}
          onToggleSeries={onToggleSeries}
          temperatureAlarms={temperatureAlarms}
          humidityAlarms={humidityAlarms}
        />
      )}

      {aggregateStats && <StatsTable stats={aggregateStats} />}
    </>
  )
}

// components/DeviceGraphs/GraphDrawer/types.ts

import { DeviceIot } from '../types'

export type SensorType = 'TEMPERATURA' | 'HUMEDAD' | 'PRESION' | 'OTRO'

export interface ModuleConfig {
  deviceIotId?: number
  sensorType: SensorType
  absoluteMin: number
  absoluteMax: number
  okMin: number
  okMax: number
  alarmThresholds: AlarmThreshold[]
  warningThresholds: WarningThreshold[]
  id?: number
  createdAt?: string
  updatedAt?: string
}

export interface AlarmThreshold {
  min?: number
  max?: number
  type: 'ABOVE' | 'BELOW'
  enabled: boolean
}

export interface WarningThreshold extends AlarmThreshold {}

export interface DeviceData {
  id: number
  deviceIotConfigs: ModuleConfig[]
  [key: string]: any
}

export interface AlarmValues {
  temperatureAlarms?: {
    above?: number
    below?: number
  }
  humidityAlarms?: {
    above?: number
    below?: number
  }
}

export interface GraphDrawerProps {
  device: DeviceIot | null
  deviceId: number | string | null
  deviceName: string
  open: boolean
  onClose: () => void
  isInAlarm?: boolean
}

export interface TabComponentProps {
  deviceId: number | string
  deviceName: string
  currentDevice?: DeviceData
  combinedData: Array<{
    timestamp: number
    temperature: number
    humidity: number
  }>
  aggregateStats: {
    avgTemp: number
    minTemp: number
    maxTemp: number
    avgHum: number
    minHum: number
    maxHum: number
  } | null
  realTimeDataFlat: any[]
  lastEntry?: any
}

export interface GaugeConfig {
  absoluteMin: number
  absoluteMax: number
  okMin: number
  okMax: number
  alarmThresholds: AlarmThreshold[]
  warningThresholds: WarningThreshold[]
  sensorType: SensorType
}

export interface RangeOption {
  label: string;
  hours?: number;
  isCustom?: boolean;
  startDate?: Date;
  endDate?: Date;
}

