import { getApiErrorReason } from 'src/utils/apiError'
import React, { useState } from 'react'
import Dialog from '@mui/material/Dialog'
import DialogTitle from '@mui/material/DialogTitle'
import DialogContent from '@mui/material/DialogContent'
import DialogActions from '@mui/material/DialogActions'
import TextField from '@mui/material/TextField'
import Button from '@mui/material/Button'
import Box from '@mui/material/Box'
import Alert from '@mui/material/Alert' // Para mostrar errores de API
import CircularProgress from '@mui/material/CircularProgress' // Indicador de carga

import { useMutation, useQueryClient } from 'react-query' // Importar useMutation y useQueryClient
import useAxiosPrivate from '@utils/use-axios-private' // Tu hook de Axios privado
import { logger } from 'src/utils/logger'

// Definir la interfaz para los datos que enviamos al backend para crear
interface CreateSensorData {
  name: string
  location?: string // Opcional al enviar
  color?: string // Opcional al enviar
}

// Definir la interfaz para la respuesta exitosa del backend (el objeto creado)
// Usamos la misma interfaz que ApiDeviceData ya que el backend devuelve el objeto completo
import { ApiDeviceData } from './LaboratoryMonitor' // Importar la interfaz desde el otro archivo

interface AddSensorModalProps {
  open: boolean
  onClose: () => void
  // Callback que se llama cuando el sensor se añade exitosamente,
  // pasando el objeto del sensor recién creado
  onSensorAdded: (newSensor: ApiDeviceData) => void
}

const AddSensorModal: React.FC<AddSensorModalProps> = ({
  open,
  onClose,
  onSensorAdded
}) => {
  const queryClient = useQueryClient() // Obtener el cliente de React Query
  const axiosPrivate = useAxiosPrivate() // Obtener la instancia de Axios
  const [formData, setFormData] = useState<CreateSensorData>({
    name: '',
    location: '',
    color: ''
  })
  const [formErrors, setFormErrors] = useState<{ name?: string }>({}) // Estado para errores de validación del formulario

  // --- Configurar la mutación con React Query ---
  const createSensorMutation = useMutation<
    ApiDeviceData,
    Error,
    CreateSensorData
  >(
    // La función de mutación que llama a la API POST
    (newSensorData) =>
      axiosPrivate
        .post('/laboratory/devices', newSensorData)
        .then((res) => res.data),
    {
      onSuccess: (newSensor) => {
        logger.log('Sensor created successfully:', newSensor)
        // 1. Llamar al callback para notificar al componente padre
        onSensorAdded(newSensor)
        // 2. Limpiar el formulario
        setFormData({ name: '', location: '', color: '' })
        setFormErrors({})
        // 3. Cerrar el modal
        onClose()

        // Opcional: Invalidar la query de lista para refetchear o actualizar manualmente la caché
        // queryClient.invalidateQueries(['laboratoryDevices']); // Opción 1: Refetch
        // Opción 2: Actualizar manualmente la caché para añadir el nuevo sensor sin refetch completo
        queryClient.setQueryData<ApiDeviceData[]>(
          ['laboratoryDevices'],
          (oldData) => {
            // Asegurarse de que oldData sea un array y añadir el nuevo sensor
            return oldData ? [...oldData, newSensor] : [newSensor]
          }
        )
      },
      onError: (error: any) => {
        // El tipo 'any' es temporal, idealmente tipar el error de Axios
        logger.error('Error creating sensor:', error)
        // Puedes intentar extraer un mensaje de error más amigable de la respuesta de Axios
        const apiErrorMessage =
          getApiErrorReason(error) ||
          error.message ||
          'Ocurrió un error al crear el sensor.'
        // Establecer un error genérico en el formulario o en un estado separado
        setFormErrors({ name: apiErrorMessage }) // Mostrarlo bajo el campo name o en otro lugar
      }
    }
  )
  // -----------------------------------------------

  // Handler para cambios en los inputs del formulario
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target
    setFormData((prev) => ({ ...prev, [name]: value }))
    // Limpiar el error de validación al escribir
    if (formErrors[name as keyof typeof formErrors]) {
      setFormErrors((prev) => ({
        ...prev,
        [name as keyof typeof formErrors]: undefined
      }))
    }
  }

  // Handler para enviar el formulario
  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault()

    // Validación básica del lado del cliente
    if (!formData.name.trim()) {
      setFormErrors({ name: 'El nombre es obligatorio.' })
      return
    }

    // Ejecutar la mutación con los datos del formulario
    createSensorMutation.mutate(formData)
  }

  // Handler para cerrar el modal y limpiar el formulario
  const handleClose = () => {
    setFormData({ name: '', location: '', color: '' }) // Limpiar al cerrar
    setFormErrors({}) // Limpiar errores al cerrar
    createSensorMutation.reset() // Resetear el estado de la mutación (errores, carga)
    onClose()
  }

  return (
    <Dialog open={open} onClose={handleClose}>
      <DialogTitle>Agregar Nuevo Sensor de Laboratorio</DialogTitle>
      <Box component='form' onSubmit={handleSubmit} noValidate>
        {' '}
        {/* Usar Box con component="form" para handleSubmit */}
        <DialogContent dividers>
          {' '}
          {/* divisors añade una línea */}
          {/* Mostrar error de API si existe */}
          {createSensorMutation.isError && formErrors.name && (
            <Alert severity='error' className='mb-4'>
              {formErrors.name}
            </Alert>
          )}
          <TextField
            autoFocus // Poner el foco en este campo al abrir el modal
            margin='dense'
            name='name'
            label='Nombre del Sensor *'
            type='text'
            fullWidth
            variant='outlined'
            value={formData.name}
            onChange={handleInputChange}
            error={!!formErrors.name} // Mostrar error si formErrors.name tiene valor
            helperText={formErrors.name} // Mostrar mensaje de error
            disabled={createSensorMutation.isLoading} // Deshabilitar inputs durante la carga
          />
          <TextField
            margin='dense'
            name='location'
            label='Ubicación'
            type='text'
            fullWidth
            variant='outlined'
            value={formData.location}
            onChange={handleInputChange}
            disabled={createSensorMutation.isLoading}
          />
          <TextField
            margin='dense'
            name='color'
            label='Color (ej: blue, red, #FF0000)'
            type='text'
            fullWidth
            variant='outlined'
            value={formData.color}
            onChange={handleInputChange}
            disabled={createSensorMutation.isLoading}
          />
        </DialogContent>
        <DialogActions>
          <Button
            onClick={handleClose}
            disabled={createSensorMutation.isLoading}
          >
            Cancelar
          </Button>
          <Button
            type='submit'
            variant='contained'
            disabled={createSensorMutation.isLoading}
          >
            {createSensorMutation.isLoading ? (
              <CircularProgress size={24} />
            ) : (
              'Guardar Sensor'
            )}
          </Button>
        </DialogActions>
      </Box>
    </Dialog>
  )
}

export default AddSensorModal

import { getApiErrorReason } from 'src/utils/apiError'
import React from 'react'
import Dialog from '@mui/material/Dialog'
import DialogTitle from '@mui/material/DialogTitle'
import DialogContent from '@mui/material/DialogContent'
import DialogContentText from '@mui/material/DialogContentText'
import DialogActions from '@mui/material/DialogActions'
import Button from '@mui/material/Button'
import Alert from '@mui/material/Alert'
import CircularProgress from '@mui/material/CircularProgress'
import Box from '@mui/material/Box' // Importar Box para centrar el spinner

import { useMutation, useQueryClient } from 'react-query'
import useAxiosPrivate from '@utils/use-axios-private' // Tu hook de Axios privado

// Importar la interfaz ApiDeviceData para la actualización de caché
import { ApiDeviceData } from './LaboratoryMonitor'
import { notify } from 'src/utils/notify'

import { logger } from 'src/utils/logger'
interface DeleteConfirmDialogProps {
  open: boolean
  onClose: () => void
  // Pasar el ID del sensor a eliminar (number según ApiDeviceData)
  sensorId: number | null
  // Callback que se llama cuando la eliminación es exitosa
  onSensorDeleted: (deletedSensorId: number) => void
  // Opcional: pasar el nombre del sensor para mostrar en el mensaje de confirmación
  sensorName?: string | null
}

const DeleteConfirmDialog: React.FC<DeleteConfirmDialogProps> = ({
  open,
  onClose,
  sensorId,
  onSensorDeleted,
  sensorName
}) => {
  const queryClient = useQueryClient()
  const axiosPrivate = useAxiosPrivate()

  // --- Configurar la mutación de eliminación con React Query ---
  // La mutación no devuelve datos en onSuccess (void), recibe el ID (number) en mutate
  const deleteSensorMutation = useMutation<void, Error, number>(
    // La función de mutación toma el ID y llama a la API DELETE
    (id) =>
      axiosPrivate.delete(`/laboratory/devices/${id}`).then((res) => res.data),
    {
      // onSuccess recibe el resultado de la mutación (void en este caso) y la variable que pasaste a mutate (el ID)
      onSuccess: (_, deletedId) => {
        logger.log(`Sensor with ID ${deletedId} deleted successfully.`)
        // 1. Llamar al callback para notificar al padre
        onSensorDeleted(deletedId)
        // 2. Cerrar el diálogo
        onClose() // Esto también limpia el estado sensorToDeleteId en el padre

        // 3. Actualizar manualmente la caché de React Query para eliminar el sensor
        queryClient.setQueryData<ApiDeviceData[]>(
          ['laboratoryDevices'],
          (oldData) => {
            // Si hay datos antiguos, filtrar la lista para remover el sensor eliminado por su ID
            return oldData
              ? oldData.filter((sensor) => sensor.id !== deletedId)
              : []
          }
        )
      },
      onError: (error: any) => {
        // El tipo 'any' es temporal
        logger.error(`Error deleting sensor with ID ${sensorId}:`, error)
        const apiErrorMessage =
          getApiErrorReason(error) ||
          error.message ||
          'Ocurrió un error al eliminar el sensor.'
        // Mostrar el error en el diálogo mismo
        // Puedes usar un estado local para mostrar este error si quieres.
        // Por ahora, lo logueamos y mostramos un aviso.
        notify.error('Error al eliminar', apiErrorMessage)
        // No cerramos automáticamente en caso de error para que el usuario vea el mensaje si se implementa en UI
      }
    }
  )
  // -------------------------------------------

  // Handler para confirmar la eliminación
  const handleConfirmDelete = () => {
    // Asegurarse de que tenemos un ID válido antes de mutar
    if (sensorId !== null) {
      // Comprobar si no es null
      deleteSensorMutation.mutate(sensorId) // Ejecutar la mutación con el ID (number)
    } else {
      logger.warn('Attempted to confirm delete with null sensorId.')
      // Opcional: mostrar un error al usuario si el ID es null
    }
  }

  // El diálogo solo debe renderizarse si open es true Y tenemos un sensorId
  if (!open || sensorId === null) return null

  return (
    // El onClose del Dialog llama al handleClose del padre, que a su vez llama a nuestro handleClose interno
    <Dialog open={open} onClose={onClose}>
      <DialogTitle>Confirmar Eliminación</DialogTitle>
      <DialogContent>
        {/* Mostrar error de API si existe */}
        {deleteSensorMutation.isError && (
          <Alert severity='error' className='mb-4'>
            Error al eliminar.
            {/* Detalles del error si los quieres mostrar: {deleteSensorMutation.error?.message} */}
          </Alert>
        )}
        <DialogContentText>
          ¿Estás seguro de que deseas eliminar el sensor
          {sensorName
            ? ` "${sensorName}" (ID: ${sensorId})`
            : ` con ID "${sensorId}"`}
          ? Esta acción no se puede deshacer.
        </DialogContentText>
        {/* Mostrar spinner durante la carga */}
        {deleteSensorMutation.isLoading && (
          <Box className='flex justify-center mt-4'>
            <CircularProgress size={24} />
          </Box>
        )}
      </DialogContent>
      <DialogActions>
        {/* El botón Cancelar llama a onClose del padre */}
        <Button onClick={onClose} disabled={deleteSensorMutation.isLoading}>
          Cancelar
        </Button>
        {/* El botón Eliminar llama a handleConfirmDelete */}
        <Button
          onClick={handleConfirmDelete}
          color='error'
          variant='contained'
          disabled={deleteSensorMutation.isLoading}
        >
          Eliminar
        </Button>
      </DialogActions>
    </Dialog>
  )
}

