      }
    })
  }

  // --- Helper para formatear valores estadísticos ---
  const formatStatValue = (value: number | null, unit: string): string => {
    if (value === null || value === undefined || isNaN(value)) {
      return 'N/A'
    }
    return `${value.toFixed(2)} ${unit}`
  }

  const handleCaptura = async () => {
    if (boxRef.current) {
      const canvas = await html2canvas(boxRef.current, { scale: 2 })
      const pdf = new jsPDF('p', 'mm', 'a4')
      const pageWidth = pdf.internal.pageSize.getWidth()
      const pageHeight = pdf.internal.pageSize.getHeight()
      const imgWidth = pageWidth
      const imgHeight = (canvas.height * imgWidth) / canvas.width
      const scale = pageHeight / imgHeight
      const height = scale < 1 ? imgHeight * scale : imgHeight

      let heightLeft = height
      let position = 0

      pdf.addImage(
        canvas.toDataURL('image/png'),
        'PNG',
        0,
        position,
        imgWidth,
        height,
        undefined,
        'FAST'
      )
      heightLeft -= pageHeight

      while (heightLeft > 0) {
        position = heightLeft - height
        pdf.addPage()
        pdf.addImage(
          canvas.toDataURL('image/png'),
          'PNG',
          0,
          position,
          imgWidth,
          height,
          undefined,
          'FAST'
        )
        heightLeft -= pageHeight
      }

      pdf.save(
        `Control de condiciones ambientales ${format(selectedDate || new Date(), 'yyyy-MM-dd')}.pdf`
      )
    } else {
      logger.error('La referencia al elemento no está disponible.')
    }
