type FilterType = 'all' | 'invoiced' | 'not_invoiced'

const MaintenanceBilling: React.FC = () => {
  const [filter, setFilter] = useState<FilterType>('not_invoiced')
  const [page, setPage] = useState(0)
  const [rowsPerPage, setRowsPerPage] = useState(20)

  const queryClient = useQueryClient()
  const canPerformActions = useCan(PERMISSIONS.MAINTENANCE_INVOICING_MANAGE)

  const axiosPrivate = useAxiosPrivate()

  // Fetch billing tickets
  const { data, isLoading, error } = useQuery<BillingResponse>({
    queryKey: ['maintenance-billing', filter, page, rowsPerPage],
    queryFn: async () => {
      const response = await axiosPrivate.get(
        `/maintenance/invoicing/tickets`,
        {
          params: {
            filter,
            page: page + 1,
            limit: rowsPerPage
          }
        }
      )
      return response.data
    },
    staleTime: 1000 * 60 * 3 // 3 minutes
  })

  // Toggle invoice status mutation
  const toggleInvoiceMutation = useMutation({
    mutationFn: async ({
      ticketId,
      isInvoiced
    }: {
      ticketId: string
      isInvoiced: boolean
    }) => {
      const response = await axiosPrivate.put(
        `/maintenance/invoicing/tickets/${ticketId}/toggle`,
        { isInvoiced }
      )
      return response.data
    },
    onSuccess: (data) => {
      notify.success(data.message)
      queryClient.invalidateQueries({ queryKey: ['maintenance-billing'] })
    },
    onError: (error: any) => {
      notify.error(
        getApiErrorReason(error) ||
          'Error al actualizar estado de facturación'
      )
    }
  })

  const handleToggleInvoice = (ticketId: string, currentStatus: boolean) => {
    toggleInvoiceMutation.mutate({
      ticketId,
      isInvoiced: !currentStatus
    })
  }

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('es-CO', {
      style: 'currency',
      currency: 'COP',
      minimumFractionDigits: 0
    }).format(value)
  }

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('es-CO', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    })
  }

  const formatWorkMinutes = (value?: number | null) => {
    const minutes = Number(value)

    if (!Number.isFinite(minutes) || minutes <= 0) {
      return 'No registrado'
    }

    const hours = Math.floor(minutes / 60)
    const remainingMinutes = minutes % 60

    if (hours <= 0) {
      return `${remainingMinutes} min`
    }

    if (remainingMinutes <= 0) {
      return `${hours} h`
    }

    return `${hours} h ${remainingMinutes} min`
  }

  const columns = useMemo<MRT_ColumnDef<BillingTicket>[]>(
    () => [
      {
        accessorKey: 'ticketCode',
        header: 'Ticket',
        size: 120,
        Cell: ({ row }) => (
          <Typography variant='body2' fontWeight={600}>
            {row.original.ticketCode}
          </Typography>
        )
      },
      {
        accessorKey: 'customerName',
        header: 'Cliente',
        size: 180,
        Cell: ({ row }) => (
          <Box sx={{ maxWidth: 170, overflowWrap: 'anywhere' }}>
            <Typography variant='body2'>{row.original.customerName}</Typography>
            <Typography variant='caption' color='text.secondary'>
              {row.original.customerEmail}
            </Typography>
          </Box>
        )
      },
      {
        accessorKey: 'equipmentType',
        header: 'Equipo',
        size: 170,
        Cell: ({ row }) => (
          <Box sx={{ maxWidth: 160, overflowWrap: 'anywhere' }}>
            <Typography variant='body2'>{row.original.equipmentType}</Typography>
            <Typography variant='caption' color='text.secondary'>
              {row.original.equipmentBrand} {row.original.equipmentModel}
            </Typography>
          </Box>
        )
      },
      {
        accessorKey: 'actualCompletionDate',
        header: 'Completado',
        size: 120,
        Cell: ({ row }) => (
          <Typography variant='body2'>
            {formatDate(row.original.actualCompletionDate)}
          </Typography>
        )
      },
      {
        accessorKey: 'totalCost',
        header: 'Total',
        size: 120,
        Cell: ({ row }) => {
          const ticket = row.original
          if (ticket.totalCost > 0) {
            return (
              <Typography variant='body2' fontWeight={700} color='#00897B'>
                {formatCurrency(ticket.totalCost)}
              </Typography>
            )
          }
          if (ticket.technicianWorkMinutes) {
            return (
              <Typography variant='caption' color='text.secondary' sx={{ fontStyle: 'italic' }}>
                Solo tiempo técnico
              </Typography>
            )
          }
          return (
            <Typography variant='body2' fontWeight={700} color='#9ca3af'>
              $0
            </Typography>
          )
        }
      },
      {
        accessorKey: 'isInvoiced',
        header: 'Estado',
        size: 170,
        Cell: ({ row }) =>
          row.original.isInvoiced ? (
            <Chip label='Facturado' color='success' size='small' variant='outlined' icon={<CheckCircle />} />
          ) : (
            <Chip label='Sin facturar' color='error' size='small' variant='outlined' icon={<Cancel />} />
          )
      }
    ],

    []
  )

  if (error) {
    return (
      <Alert severity='error' sx={{ m: 3 }}>
        Error al cargar tickets de facturación. Por favor intente nuevamente.
      </Alert>
    )
  }

  return (
    <Container maxWidth='xl' sx={{ py: 3 }}>
      <LmsPageHeader
        title='Control de Facturación'
        subtitle='Gestión y seguimiento de facturación de servicios de mantenimiento'
        icon={<Receipt />}
      />

      {data && (
        <Grid container spacing={3} sx={{ mb: 3 }}>
          <Grid item xs={12} sm={4}>
            <LmsStatCard label='Total Tickets' value={data.summary.totalTickets} icon={<Receipt />} tone='blue' />
          </Grid>
          <Grid item xs={12} sm={4}>
            <LmsStatCard label='Monto Total' value={formatCurrency(data.summary.totalAmount)} icon={<AttachMoney />} tone='green' compact />
          </Grid>
          <Grid item xs={12} sm={4}>
            <LmsStatCard
              label='Filtro Activo'
              value={filter === 'not_invoiced' ? 'Sin Facturar' : filter === 'invoiced' ? 'Facturados' : 'Todos'}
              icon={<Warning />}
              tone='orange'
              compact
            />
          </Grid>
        </Grid>
      )}

      {/* Filters */}
      <Paper sx={{ p: 2, mb: 2 }}>
        <ButtonGroup variant='outlined' fullWidth>
          <Button
            onClick={() => {
              setFilter('not_invoiced')
              setPage(0)
            }}
            variant={filter === 'not_invoiced' ? 'contained' : 'outlined'}
            sx={{
              backgroundColor:
                filter === 'not_invoiced' ? '#dc2626' : undefined,
              '&:hover': {
                backgroundColor:
                  filter === 'not_invoiced' ? '#b91c1c' : undefined
              }
            }}
          >
            Sin Facturar
          </Button>
          <Button
            onClick={() => {
              setFilter('invoiced')
              setPage(0)
            }}
            variant={filter === 'invoiced' ? 'contained' : 'outlined'}
            sx={{
              backgroundColor: filter === 'invoiced' ? '#10b981' : undefined,
              '&:hover': {
                backgroundColor: filter === 'invoiced' ? '#059669' : undefined
              }
            }}
          >
            Facturados
          </Button>
          <Button
            onClick={() => {
              setFilter('all')
              setPage(0)
            }}
            variant={filter === 'all' ? 'contained' : 'outlined'}
            sx={{
              backgroundColor: filter === 'all' ? '#3b82f6' : undefined,
              '&:hover': {
                backgroundColor: filter === 'all' ? '#2563eb' : undefined
              }
            }}
          >
            Todos
          </Button>
        </ButtonGroup>
      </Paper>

      <Paper elevation={2} sx={{ borderRadius: 2, overflow: 'hidden' }}>
        <MaterialReactTable
          {...purchaseTableStyle}
          columns={columns}
          data={data?.tickets ?? []}
          manualPagination
          rowCount={data?.pagination.totalItems ?? 0}
          state={{
            isLoading,
            pagination: { pageIndex: page, pageSize: rowsPerPage }
          }}
          onPaginationChange={(updater) => {
            const next =
              typeof updater === 'function'
                ? updater({ pageIndex: page, pageSize: rowsPerPage })
                : updater
            if (next.pageSize !== rowsPerPage) {
              setRowsPerPage(next.pageSize)
              setPage(0)
            } else {
              setPage(next.pageIndex)
            }
          }}
          muiTablePaginationProps={{ rowsPerPageOptions: [10, 20, 50, 100] }}
          enableGlobalFilter={false}
          enableColumnFilters={false}
          enableDensityToggle={false}
          enableHiding={false}
          enableSorting={false}
          enableColumnActions={false}
          enablePinning
          getRowId={(row, index) => String(row.id ?? `skeleton-${index}`)}
          initialState={{ columnPinning: { right: ['mrt-row-actions'] } }}
          enableRowActions
          displayColumnDefOptions={{
            'mrt-row-actions': { header: 'Acciones', size: 90 },
            'mrt-row-expand': { header: '', size: 50 }
          }}
          renderRowActions={({ row }) => {
            const ticket = row.original
            return (
              <Tooltip title={ticket.isInvoiced ? 'Marcar como no facturado' : 'Marcar como facturado'}>
                <span>
                  <IconButton
                    size='small'
                    onClick={() => handleToggleInvoice(ticket.id, ticket.isInvoiced)}
                    disabled={toggleInvoiceMutation.isLoading || !canPerformActions}
                    sx={{ color: ticket.isInvoiced ? 'error.main' : '#00BFA5' }}
                  >
                    {ticket.isInvoiced ? <Cancel /> : <CheckCircle />}
                  </IconButton>
                </span>
              </Tooltip>
            )
          }}
          renderDetailPanel={({ row }) => (
            <Box sx={{ py: 3, px: 2 }}>
              <Typography
                variant='h6'
                gutterBottom
                fontWeight={600}
              >
                Desglose de Costos
              </Typography>
              <Typography
                variant='body2'
                color='text.secondary'
                sx={{ mb: 1 }}
              >
                Tiempo técnico registrado:{' '}
                <strong>
                  {formatWorkMinutes(row.original.technicianWorkMinutes)}
                </strong>
              </Typography>
              <Divider sx={{ mb: 2 }} />
              {row.original.costs.length === 0 ? (
                <Alert severity='info' sx={{ mb: 2 }}>
                  Sin costos de materiales — Este servicio no registró costos de materiales. El tiempo técnico registrado queda como referencia para la facturación externa.
                </Alert>
              ) : (
                <>
              <Grid container spacing={2}>
                {row.original.costs.map((cost) => (
                  <Grid item xs={12} sm={6} md={4} key={cost.id}>
                    <Paper
                      elevation={1}
                      sx={{
                        p: 2,
                        border: '1px solid #e5e7eb',
                        borderRadius: '8px'
                      }}
                    >
                      <Typography
                        variant='subtitle2'
                        fontWeight={700}
                        gutterBottom
                      >
                        {cost.name}
                      </Typography>
                      {cost.description && (
                        <Typography
                          variant='caption'
                          color='text.secondary'
                          display='block'
                          sx={{ mb: 1 }}
                        >
                          {cost.description}
                        </Typography>
                      )}
                      <Typography
                        variant='h6'
                        fontWeight={700}
                        color='#10b981'
                      >
                        {formatCurrency(cost.amount)}
                      </Typography>
                    </Paper>
                  </Grid>
                ))}
              </Grid>
              <Box
                sx={{
                  mt: 3,
                  p: 2,
                  backgroundColor: '#10b981',
                  borderRadius: '8px',
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center'
                }}
              >
                <Typography
                  variant='h6'
                  fontWeight={700}
                  color='white'
                >
                  Total
                </Typography>
                <Typography
                  variant='h5'
                  fontWeight={700}
                  color='white'
                >
                  {formatCurrency(row.original.totalCost)}
                </Typography>
              </Box>
                </>
              )}
            </Box>
          )}
          renderEmptyRowsFallback={() => (
            <Box sx={{ py: 8, textAlign: 'center' }}>
              <Typography variant='h6' color='text.secondary'>
                No hay tickets completados para mostrar
              </Typography>
              <Typography variant='body2' color='text.secondary' sx={{ mt: 1 }}>
                {filter === 'not_invoiced'
            ? 'No hay tickets pendientes de facturar'
            : filter === 'invoiced'
              ? 'No hay tickets facturados'
              : 'No hay tickets completados'}
              </Typography>
            </Box>
          )}
        />
      </Paper>
    </Container>
  )
}

export default MaintenanceBilling

import React, { useState } from 'react'
import {
  Box,
  Typography,
  Paper,
  Avatar,
  TextField,
  Button,
  Chip,
  Divider,
  FormControlLabel,
  Checkbox,
  Tooltip,
  Alert,
  IconButton
} from '@mui/material'
import {
  Send,
  Lock,
  Public,
  AccessTime,
  Edit,
  Delete,
  Save,
  Close
} from '@mui/icons-material'
import { MaintenanceComment } from '../../types/maintenance'
import { format } from 'date-fns'
import { es } from 'date-fns/locale'

import { useCan } from '@utils/functions'
import { PERMISSIONS } from 'src/constants/permissions'
import { logger } from 'src/utils/logger'
interface MaintenanceCommentsListProps {
  comments: MaintenanceComment[]
  onAddComment: (comment: string, isInternal: boolean) => Promise<void>
  onUpdateComment: (
    commentId: string,
    content: string,
    isInternal?: boolean
  ) => Promise<void>
  onDeleteComment: (commentId: string) => Promise<void>
  currentUserRole: string
  currentUserEmail: string
  loading?: boolean
  disabled?: boolean
}

/**
 * MaintenanceCommentsList component displays and manages comments for a maintenance ticket
 *
 * @param comments - Array of comments
 * @param onAddComment - Callback when a new comment is added
 * @param currentUserRole - Current user's role to determine permissions
 * @param loading - Whether comments are loading
 * @param disabled - Whether comment input is disabled
 */
const MaintenanceCommentsList: React.FC<MaintenanceCommentsListProps> = ({
  comments,
  onAddComment,
  onUpdateComment,
  onDeleteComment,
  currentUserEmail,
  loading = false,
  disabled = false
}) => {
  const [newComment, setNewComment] = useState('')
  const [isInternal, setIsInternal] = useState(false)
  const [submitting, setSubmitting] = useState(false)
  const [editingCommentId, setEditingCommentId] = useState<string | null>(null)
  const [editingContent, setEditingContent] = useState('')
  const surfaceSx = {
    backgroundColor: '#ffffff',
    borderRadius: '12px',
    border: '1px solid #e5e7eb',
    boxShadow: '0 1px 3px rgba(15, 23, 42, 0.08)'
  }

  const canAddInternalComments = useCan(
    PERMISSIONS.MAINTENANCE_COMMENT_VIEW_INTERNAL
  )
  const isPrivilegedUser = useCan(PERMISSIONS.MAINTENANCE_COMMENT_MODERATE)

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!newComment.trim() || submitting) return

    setSubmitting(true)
    try {
      await onAddComment(newComment.trim(), isInternal)
      setNewComment('')
      setIsInternal(false)
    } catch (error) {
      logger.error('Error adding comment:', error)
    } finally {
      setSubmitting(false)
    }
  }

  const formatDate = (dateString: string) => {
    try {
      return format(new Date(dateString), 'dd/MM/yyyy HH:mm', { locale: es })
    } catch {
      return 'Fecha inválida'
    }
  }

  const getInitials = (name: string) => {
    if (!name || typeof name !== 'string') {
      return 'NN'
    }
    return name
      .split(' ')
      .map((n) => n[0])
      .join('')
      .toUpperCase()
      .slice(0, 2)
  }

  const getRoleColor = (role: string) => {
    switch (role) {
      case 'admin':
        return 'error'
      case 'mantenimiento':
      case 'technician':
        return 'primary'
      case 'client':
      case 'customer':
        return 'success'
      case 'system':
        return 'info'
      default:
        return 'default'
    }
  }

  const getRoleLabel = (role: string) => {
    switch (role) {
      case 'admin':
        return 'Administrador'
      case 'mantenimiento':
      case 'technician':
        return 'Técnico'
      case 'client':
      case 'customer':
        return 'Cliente'
      case 'system':
        return 'Sistema'
      default:
        return 'Usuario'
    }
  }

  // Filter out system events (status_update) to show only user comments
  const userComments = comments.filter(
    (comment) => comment.commentType !== 'status_update'
  )

  const sortedComments = [...userComments].sort(
    (a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime()
  )

  const canManageComment = (comment: MaintenanceComment) => {
    if (!comment.isVisible) {
      return false
    }

    if (isPrivilegedUser) {
      return true
    }

    return (
      comment.user?.email === currentUserEmail ||
      comment.technician?.email === currentUserEmail
    )
  }

  const handleStartEdit = (comment: MaintenanceComment) => {
    setEditingCommentId(comment.id)
    setEditingContent(comment.content)
  }

  const handleCancelEdit = () => {
    setEditingCommentId(null)
    setEditingContent('')
  }

  const handleSaveEdit = async (comment: MaintenanceComment) => {
    if (!editingContent.trim()) return

    try {
      await onUpdateComment(comment.id, editingContent.trim(), comment.isInternal)
      handleCancelEdit()
    } catch (error) {
      logger.error('Error updating comment:', error)
    }
  }

  const handleDelete = async (commentId: string) => {
    try {
      await onDeleteComment(commentId)
    } catch (error) {
      logger.error('Error deleting comment:', error)
    }
  }

  return (
    <Box>
      <Typography 
        variant='h6' 
        gutterBottom
        sx={{
          fontWeight: 600,
          color: '#0f172a',
          mb: 3
        }}
      >
        Comentarios ({userComments.length})
      </Typography>

      {/* Comments List */}
      <Box 
        sx={{ 
          maxHeight: 400, 
          overflowY: 'auto', 
          mb: 3,
          '&::-webkit-scrollbar': {
            width: '6px',
          },
          '&::-webkit-scrollbar-track': {
            background: '#e2e8f0',
            borderRadius: '3px',
          },
          '&::-webkit-scrollbar-thumb': {
            background: '#94a3b8',
            borderRadius: '3px',
          },
        }}
      >
        {sortedComments.length === 0 ? (
          <Alert 
            severity='info' 
            sx={{ 
              mb: 2,
              backgroundColor: '#ffffff',
              borderRadius: '12px',
              border: '1px solid rgba(33, 150, 243, 0.2)'
            }}
          >
            No hay comentarios aún. ¡Sé el primero en comentar!
          </Alert>
        ) : (
          sortedComments.map((comment, index) => (
            <Paper
              key={comment.id}
              elevation={1}
              sx={{
                ...surfaceSx,
                p: 2,
                mb: 2,
                backgroundColor: comment.isInternal ? '#fffbeb' : '#ffffff',
                border: comment.isInternal 
                  ? '1px solid #fde68a' 
                  : '1px solid #e5e7eb',
                transition: 'border-color 0.2s ease, box-shadow 0.2s ease',
                '&:hover': {
                  borderColor: comment.isInternal ? '#fcd34d' : '#cbd5e1',
                  boxShadow: comment.isInternal
                    ? '0 4px 12px rgba(245, 158, 11, 0.12)'
                    : '0 4px 12px rgba(15, 23, 42, 0.08)'
                }
              }}
            >
              {/* Comment Header */}
              <Box display='flex' alignItems='center' justifyContent='space-between' mb={1}>
                <Box display='flex' alignItems='center' gap={1}>
                  <Avatar
                    sx={{
                      width: 32,
                      height: 32,
                      fontSize: '0.875rem',
                      backgroundColor:
                        getRoleColor(comment.authorType || comment.userRole) === 'primary'
                          ? '#e8f7ef'
                          : getRoleColor(comment.authorType || comment.userRole) === 'error'
                            ? '#fef2f2'
                            : getRoleColor(comment.authorType || comment.userRole) === 'success'
                              ? '#ecfdf5'
                              : getRoleColor(comment.authorType || comment.userRole) === 'info'
                                ? '#eff6ff'
                                : '#f1f5f9',
                      color:
                        getRoleColor(comment.authorType || comment.userRole) === 'primary'
                          ? '#00A651'
                          : getRoleColor(comment.authorType || comment.userRole) === 'error'
                            ? '#dc2626'
                            : getRoleColor(comment.authorType || comment.userRole) === 'success'
                              ? '#059669'
                              : getRoleColor(comment.authorType || comment.userRole) === 'info'
                                ? '#2563eb'
                                : '#475569'
                    }}
                  >
                    {getInitials(comment.authorName || comment.userName)}
                  </Avatar>

                  <Box>
                    <Typography variant='subtitle2' fontWeight='bold'>
                      {comment.authorName || comment.userName}
                    </Typography>
                    <Box display='flex' alignItems='center' gap={0.5}>
                      <Chip
                        size='small'
                        label={getRoleLabel(
                          comment.authorType || comment.userRole
                        )}
                        sx={{
                          borderRadius: '6px',
                          fontWeight: 500,
                          background: getRoleColor(comment.authorType || comment.userRole) === 'primary' 
                            ? '#e8f7ef'
                            : undefined,
                          color: getRoleColor(comment.authorType || comment.userRole) === 'primary' 
                            ? '#00A651' 
                            : undefined,
                          border: getRoleColor(comment.authorType || comment.userRole) === 'primary' 
                            ? 'none' 
                            : undefined
                        }}
                        color={
                          getRoleColor(
                            comment.authorType || comment.userRole
                          ) as any
                        }
                        variant={getRoleColor(comment.authorType || comment.userRole) === 'primary' ? 'filled' : 'outlined'}
                      />
                      {comment.isInternal && (
                        <Tooltip title='Comentario interno - Solo visible para técnicos y administradores'>
                          <Chip
                            size='small'
                            icon={<Lock />}
                            label='Interno'
                            sx={{
                              borderRadius: '6px',
                              fontWeight: 500,
                              backgroundColor: '#fef3c7',
                              color: '#b45309',
                              border: 'none',
                              '& .MuiChip-icon': {
                                color: '#b45309'
                              }
                            }}
                          />
                        </Tooltip>
                      )}
                    </Box>
                  </Box>
                </Box>

                <Box display='flex' alignItems='center' gap={0.5}>
                  <Box
                    display='flex'
                    alignItems='center'
                    gap={0.5}
                    color='text.secondary'
                  >
                    <AccessTime fontSize='small' />
                    <Typography variant='caption'>
                      {formatDate(comment.createdAt)}
                    </Typography>
                  </Box>
                  {canManageComment(comment) && (
                    <>
                      <Tooltip title='Editar comentario'>
                        <IconButton
                          size='small'
                          onClick={() => handleStartEdit(comment)}
                          disabled={loading}
                        >
                          <Edit fontSize='small' />
                        </IconButton>
                      </Tooltip>
                      <Tooltip title='Eliminar comentario'>
                        <IconButton
                          size='small'
                          onClick={() => handleDelete(comment.id)}
                          disabled={loading}
                        >
                          <Delete fontSize='small' />
                        </IconButton>
                      </Tooltip>
                    </>
                  )}
                </Box>
              </Box>

              {/* Comment Content */}
              {editingCommentId === comment.id ? (
                <Box>
                  <TextField
                    fullWidth
                    multiline
                    rows={3}
                    value={editingContent}
                    onChange={(e) => setEditingContent(e.target.value)}
                    sx={{ mb: 1 }}
                  />
                  <Box display='flex' justifyContent='flex-end' gap={1}>
                    <Button
                      size='small'
                      startIcon={<Close />}
                      onClick={handleCancelEdit}
                    >
                      Cancelar
                    </Button>
                    <Button
                      size='small'
                      variant='contained'
                      startIcon={<Save />}
                      onClick={() => handleSaveEdit(comment)}
                      disabled={!editingContent.trim()}
                    >
                      Guardar
                    </Button>
                  </Box>
                </Box>
              ) : (
                <Typography
                  variant='body2'
                  sx={{
                    whiteSpace: 'pre-wrap',
                    wordBreak: 'break-word',
                    fontStyle: comment.isVisible === false ? 'italic' : 'normal',
                    color: comment.isVisible === false ? 'text.secondary' : 'text.primary'
                  }}
                >
                  {comment.content}
                </Typography>
              )}

              {index < sortedComments.length - 1 && <Divider sx={{ mt: 2 }} />}
            </Paper>
          ))
        )}
      </Box>

      {/* Add Comment Form */}
      {!disabled && (
        <Paper 
          sx={{ 
            ...surfaceSx,
            p: 2,
          }}
        >
          <Typography 
            variant='subtitle2' 
            gutterBottom
            sx={{
              fontWeight: 600,
              color: '#0f172a'
            }}
          >
            Agregar comentario
          </Typography>

          <form onSubmit={handleSubmit}>
            <TextField
              fullWidth
              multiline
              rows={3}
              value={newComment}
              onChange={(e) => setNewComment(e.target.value)}
              placeholder='Escribe tu comentario aquí...'
              disabled={submitting || loading}
              sx={{ 
                mb: 2,
                '& .MuiOutlinedInput-root': {
                  borderRadius: '8px',
                  '&:hover .MuiOutlinedInput-notchedOutline': {
                    borderColor: '#86c88a',
                  },
                  '&.Mui-focused .MuiOutlinedInput-notchedOutline': {
                    borderColor: '#00A651',
                  },
                },
                '& .MuiInputLabel-root.Mui-focused': {
                  color: '#00A651',
                }
              }}
            />

            <Box
              display='flex'
              justifyContent='space-between'
              alignItems='center'
            >
              <Box>
                {canAddInternalComments && (
                  <FormControlLabel
                    control={
                      <Checkbox
                        checked={isInternal}
                        onChange={(e) => setIsInternal(e.target.checked)}
                        disabled={submitting || loading}
                        icon={<Public />}
                        checkedIcon={<Lock />}
                      />
                    }
                    label={
                      <Box display='flex' alignItems='center' gap={0.5}>
                        <Typography variant='body2'>
                          {isInternal
                            ? 'Comentario interno'
                            : 'Comentario público'}
                        </Typography>
                        <Tooltip
                          title={
                            isInternal
                              ? 'Solo visible para técnicos y administradores'
                              : 'Visible para todos los usuarios'
                          }
                        >
                          <Box
                            component='span'
                            sx={{ display: 'flex', alignItems: 'center' }}
                          >
                            {isInternal ? (
                              <Lock fontSize='small' />
                            ) : (
                              <Public fontSize='small' />
                            )}
                          </Box>
                        </Tooltip>
                      </Box>
                    }
                  />
                )}
              </Box>

              <Button
                type='submit'
                variant='contained'
                endIcon={<Send />}
                disabled={!newComment.trim() || submitting || loading}
                size='small'
                sx={{
                  backgroundColor: '#00A651',
                  borderRadius: '8px',
                  '&:hover': {
                    backgroundColor: '#27672a'
                  },
                  '&:disabled': {
                    background: 'rgba(0, 0, 0, 0.12)',
                    color: 'rgba(0, 0, 0, 0.26)'
                  }
                }}
              >
                {submitting ? 'Enviando...' : 'Enviar'}
              </Button>
            </Box>
          </form>
        </Paper>
      )}
    </Box>
  )
}

export default MaintenanceCommentsList

import React, { useCallback, useState, useEffect } from 'react'
import {
  Box,
  Typography,
  IconButton,
  Chip,
  LinearProgress,
  Alert,
  Card,
  CardContent,
  Grid,
  Tooltip,
  CardMedia
} from '@mui/material'
import {
  CloudUpload,
  Delete,
  Image,
  VideoFile,
  InsertDriveFile,
  Visibility,
  Refresh
} from '@mui/icons-material'
import { useDropzone } from 'react-dropzone'
import { MaintenanceFile } from '../../types/maintenance'

import { logger } from 'src/utils/logger'
interface MaintenanceFileUploadProps {
  files: MaintenanceFile[]
  onFilesChange: (files: File[]) => void
  onFileRemove: (fileId: string) => void
  onFileView?: (file: MaintenanceFile) => void
  getFilePreviewUrl?: (file: MaintenanceFile) => Promise<string>
  onFileRetry?: (file: MaintenanceFile) => void
  maxFiles?: number
  maxSizeInMB?: number
  acceptedFileTypes?: string[]
  disabled?: boolean
  uploading?: boolean
  uploadProgress?: number
  failedFiles?: Set<string>
}

/**
 * MaintenanceFileUpload component provides drag-and-drop file upload functionality
 * with preview capabilities for images and videos
 *
 * @param files - Array of uploaded files
 * @param onFilesChange - Callback when new files are added
 * @param onFileRemove - Callback when a file is removed
 * @param onFileView - Callback when a file is viewed
 * @param maxFiles - Maximum number of files allowed
 * @param maxSizeInMB - Maximum file size in MB
 * @param acceptedFileTypes - Array of accepted file types
 * @param disabled - Whether the upload is disabled
 * @param uploading - Whether files are currently uploading
 * @param uploadProgress - Upload progress percentage
 */
const MaintenanceFileUpload: React.FC<MaintenanceFileUploadProps> = ({
  files = [],
  onFilesChange,
  onFileRemove,
  onFileView,
  getFilePreviewUrl,
  onFileRetry,
  maxFiles = 5,
  maxSizeInMB = 10,
  acceptedFileTypes = [
    'image/*',
    'video/*',
    'application/pdf',
    '.doc',
    '.docx'
  ],
  disabled = false,
  uploading = false,
  uploadProgress = 0,
  failedFiles = new Set()
}) => {
  const [dragActive, setDragActive] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [imagePreviews, setImagePreviews] = useState<Record<string, string>>({})
  const surfaceSx = {
    backgroundColor: '#ffffff',
    borderRadius: '14px',
    border: '1px solid #e5e7eb',
    boxShadow: '0 1px 3px rgba(15, 23, 42, 0.08)'
  }

  const onDrop = useCallback(
    (acceptedFiles: File[], fileRejections: any[]) => {
      setError(null)

      // Check for file rejections
      if (fileRejections.length > 0) {
        const rejection = fileRejections[0]
        if (rejection.errors[0]?.code === 'file-too-large') {
          setError(`El archivo es muy grande. Tamaño máximo: ${maxSizeInMB}MB`)
        } else if (rejection.errors[0]?.code === 'file-invalid-type') {
          setError('Tipo de archivo no permitido')
        } else {
          setError('Error al cargar el archivo')
        }
        return
      }

      // Check total file count
      if (files.length + acceptedFiles.length > maxFiles) {
        setError(`Máximo ${maxFiles} archivos permitidos`)
        return
      }

      onFilesChange(acceptedFiles)
    },
    [files.length, maxFiles, maxSizeInMB, onFilesChange]
  )

  const { getRootProps, getInputProps, isDragActive, open } = useDropzone({
    onDrop,
    maxSize: maxSizeInMB * 1024 * 1024,
    accept: acceptedFileTypes.reduce(
      (acc, type) => {
        acc[type] = []
        return acc
      },
      {} as Record<string, string[]>
    ),
    disabled: disabled || uploading,
    multiple: true,
    noClick: false,
    noKeyboard: false
  })

  // Generate image previews for uploaded files
  useEffect(() => {
    const generatePreviews = async () => {
      const newPreviews: Record<string, string> = {}

      for (const file of files) {
        if (!file.isImage || imagePreviews[file.id]) continue

        if (file.filePath) {
          newPreviews[file.id] = file.filePath
          continue
        }

        if (getFilePreviewUrl) {
          try {
            newPreviews[file.id] = await getFilePreviewUrl(file)
          } catch (previewError) {
            logger.error('Error generating image preview:', previewError)
          }
        }
      }

      if (Object.keys(newPreviews).length > 0) {
        setImagePreviews(prev => ({ ...prev, ...newPreviews }))
      }
    }

    generatePreviews()
  }, [files, imagePreviews, getFilePreviewUrl])


  const formatFileSize = (bytes: number | undefined | null) => {
    if (bytes === undefined || bytes === null) return 'Tamaño no disponible'
    if (bytes === 0) return '0 Bytes'
    const k = 1024
    const sizes = ['Bytes', 'KB', 'MB', 'GB']
    const i = Math.floor(Math.log(bytes) / Math.log(k))
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i]
  }

  const getLocalizedFileType = (file: MaintenanceFile) => {
    if (file.isImage || file.fileType === 'image') return 'Imagen'
    if (file.isVideo || file.fileType === 'video') return 'Video'
    if (file.fileType === 'audio') return 'Audio'
    if (file.fileType === 'document') return 'Documento'
    return 'Archivo'
  }

  const getFileIcon = (file: MaintenanceFile) => {
    if (file.isImage) return <Image color='primary' />
    if (file.isVideo) return <VideoFile color='secondary' />
    return <InsertDriveFile color='action' />
  }

  const getFileExtension = (file: MaintenanceFile) => {
    const fileName = file.originalName || file.fileName || ''
    const extension = fileName.split('.').pop()
    return extension ? extension.toUpperCase() : 'FILE'
  }

  const isPdfFile = (file: MaintenanceFile) => {
    const fileName = (file.originalName || file.fileName || '').toLowerCase()
    return file.fileType?.includes('pdf') || fileName.endsWith('.pdf')
  }

  const renderFilePreview = (file: MaintenanceFile) => {
    if (file.isImage && imagePreviews[file.id]) {
      return (
        <CardMedia
          component='img'
          sx={{
            height: 120,
            objectFit: 'cover',
            borderRadius: '12px 12px 0 0'
          }}
          image={imagePreviews[file.id]}
          alt={file.originalName || file.fileName || 'Vista previa'}
        />
      )
    }

    if (file.isVideo) {
      return (
        <Box
          sx={{
            height: 120,
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            gap: 1,
            borderRadius: '12px 12px 0 0',
            background: 'linear-gradient(135deg, rgba(156, 39, 176, 0.12) 0%, rgba(103, 58, 183, 0.18) 100%)'
          }}
        >
          <VideoFile sx={{ fontSize: 42, color: '#7b1fa2' }} />
          <Chip
            size='small'
            label='Vista previa en modal'
            sx={{ backgroundColor: 'rgba(255,255,255,0.85)', color: '#6a1b9a' }}
          />
        </Box>
      )
    }

    return (
      <Box
        sx={{
          height: 120,
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          gap: 1,
          borderRadius: '12px 12px 0 0',
          background: isPdfFile(file)
            ? 'linear-gradient(135deg, rgba(244, 67, 54, 0.1) 0%, rgba(229, 57, 53, 0.16) 100%)'
            : 'linear-gradient(135deg, rgba(109, 198, 98, 0.08) 0%, rgba(96, 125, 139, 0.16) 100%)'
        }}
      >
        {isPdfFile(file) ? (
          <InsertDriveFile sx={{ fontSize: 42, color: '#d32f2f' }} />
        ) : (
          <InsertDriveFile sx={{ fontSize: 42, color: '#546e7a' }} />
        )}
        <Chip
          size='small'
          label={getFileExtension(file)}
          sx={{
            backgroundColor: 'rgba(255,255,255,0.85)',
            color: isPdfFile(file) ? '#c62828' : '#455a64',
            fontWeight: 700
          }}
        />
      </Box>
    )
  }

  const handleDragEnter = () => setDragActive(true)
  const handleDragLeave = () => setDragActive(false)

  // Handle keyboard navigation
  const handleKeyDown = (event: React.KeyboardEvent) => {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault()
      open()
    }
  }

  // Handle file retry
  const handleFileRetry = (file: MaintenanceFile) => {
    if (onFileRetry) {
      onFileRetry(file)
    }
  }

  return (
    <Box>
      {/* Upload Area */}
      <Card
        {...getRootProps()}
        onDragEnter={handleDragEnter}
        onDragLeave={handleDragLeave}
        onKeyDown={handleKeyDown}
        tabIndex={disabled || uploading ? -1 : 0}
        role="button"
        aria-label="Área de carga de archivos. Presiona Enter o Espacio para seleccionar archivos"
        sx={{
          border: '2px dashed',
          borderColor: dragActive || isDragActive ? '#86c88a' : '#cbd5e1',
          backgroundColor: dragActive || isDragActive ? '#f0fdf4' : '#ffffff',
          borderRadius: '16px',
          boxShadow: '0 1px 3px rgba(15, 23, 42, 0.08)',
          cursor: disabled || uploading ? 'not-allowed' : 'pointer',
          transition: 'border-color 0.2s ease, background-color 0.2s ease',
          '&:hover': {
            borderColor: disabled || uploading ? '#cbd5e1' : '#86c88a',
            backgroundColor: disabled || uploading ? '#ffffff' : '#f8fafc'
          },
          '&:focus': {
            outline: '2px solid #00bf75',
            outlineOffset: '2px'
          }
        }}
      >
        <CardContent sx={{ textAlign: 'center', py: 4 }}>
          <input {...getInputProps()} aria-hidden="true" />
          <Box
            sx={{
              backgroundColor: disabled || uploading ? '#f1f5f9' : '#e8f7ef',
              borderRadius: '50%',
              width: 80,
              height: 80,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              margin: '0 auto 16px',
              border: '1px solid #dbe4db'
            }}
          >
            <CloudUpload
              sx={{
                fontSize: 40,
                color: disabled || uploading ? 'grey.400' : '#00A651'
              }}
            />
          </Box>
          <Typography
            variant='h6'
            gutterBottom
            sx={{
              color: disabled || uploading ? 'text.disabled' : '#0f172a',
              fontWeight: 600
            }}
          >
            {isDragActive || dragActive
              ? 'Suelta los archivos aquí'
              : 'Arrastra archivos aquí o haz clic para seleccionar'}
          </Typography>
          <Typography 
            variant='body2' 
            color='text.secondary'
            sx={{ fontWeight: 500 }}
          >
            Máximo {maxFiles} archivos, {maxSizeInMB}MB cada uno
          </Typography>
          <Typography 
            variant='caption' 
            color='text.secondary'
            sx={{ 
              mt: 1,
              backgroundColor: '#f1f5f9',
              borderRadius: '12px',
              padding: '4px 12px',
              display: 'inline-block'
            }}
          >
            Formatos soportados: Imágenes, Videos, PDF, Word
          </Typography>
        </CardContent>
      </Card>

      {/* Upload Progress */}
      {uploading && (
        <Box 
          sx={{ 
            mt: 2,
            p: 2,
            ...surfaceSx
          }}
        >
          <Typography 
            variant='body2' 
            gutterBottom
            sx={{
              color: '#0f172a',
              fontWeight: 600
            }}
          >
            Subiendo archivos... {uploadProgress}%
          </Typography>
          <LinearProgress 
            variant='determinate' 
            value={uploadProgress}
            sx={{
              height: 8,
              borderRadius: 4,
              backgroundColor: '#e2e8f0',
              '& .MuiLinearProgress-bar': {
                backgroundColor: '#00A651',
                borderRadius: 4
              }
            }}
          />
        </Box>
      )}

      {/* Error Display */}
      {error && (
        <Alert 
          severity='error' 
          sx={{ 
            mt: 2,
            backgroundColor: '#ffffff',
            borderRadius: '12px',
            border: '1px solid rgba(244, 67, 54, 0.2)'
          }} 
          onClose={() => setError(null)}
        >
          {error}
        </Alert>
      )}

      {/* File List */}
      {files.length > 0 && (
        <Box sx={{ mt: 3 }}>
          <Typography 
            variant='subtitle2' 
            gutterBottom
            sx={{
              fontWeight: 600,
              color: '#0f172a',
              mb: 2
            }}
          >
            Archivos ({files.length}/{maxFiles})
          </Typography>
          <Grid container spacing={2}>
            {files.map((file) => (
              <Grid item xs={12} sm={6} md={4} key={file.id}>
                <Card
                  sx={{
                    backgroundColor: failedFiles.has(file.id) ? '#fff7f7' : '#ffffff',
                    borderRadius: '12px',
                    boxShadow: '0 1px 3px rgba(15, 23, 42, 0.08)',
                    border: failedFiles.has(file.id)
                      ? '1px solid rgba(244, 67, 54, 0.2)'
                      : '1px solid #e5e7eb',
                    transition: 'border-color 0.2s ease, box-shadow 0.2s ease',
                    '&:hover': {
                      borderColor: failedFiles.has(file.id) ? '#fca5a5' : '#cbd5e1',
                      boxShadow: failedFiles.has(file.id)
                        ? '0 4px 12px rgba(244, 67, 54, 0.12)'
                        : '0 4px 12px rgba(15, 23, 42, 0.08)'
                    }
                  }}
                >
                  {renderFilePreview(file)}

                  <CardContent sx={{ p: 2, '&:last-child': { pb: 2 } }}>
                    <Box display='flex' alignItems='center' gap={1} mb={1}>
                      {!file.isImage && getFileIcon(file)}
                      <Typography
                        variant='body2'
                        sx={{
                          flexGrow: 1,
                          overflow: 'hidden',
                          textOverflow: 'ellipsis',
                          whiteSpace: 'nowrap',
                          color: failedFiles.has(file.id) ? 'error.main' : 'inherit'
                        }}
                      >
                        {file.originalName ||
                          file.fileName ||
                          'Archivo sin nombre'}
                      </Typography>
                      {failedFiles.has(file.id) && (
                        <Chip
                          size='small'
                          label='Error'
                          color='error'
                          variant='outlined'
                        />
                      )}
                    </Box>

                    <Typography
                      variant='caption'
                      color='text.secondary'
                      display='block'
                    >
                      {formatFileSize(file.fileSize)}
                    </Typography>

                    <Box
                      display='flex'
                      justifyContent='space-between'
                      alignItems='center'
                      mt={1}
                    >
                      <Chip
                        size='small'
                        label={getLocalizedFileType(file)}
                        sx={{
                          backgroundColor: '#e8f7ef',
                          color: '#00A651',
                          borderRadius: '6px',
                          fontWeight: 500,
                          border: 'none'
                        }}
                      />

                      <Box display='flex' gap={0.5}>
                        {failedFiles.has(file.id) && onFileRetry && (
                          <Tooltip title='Reintentar subida'>
                            <IconButton
                              size='small'
                              onClick={() => handleFileRetry(file)}
                              disabled={uploading}
                              sx={{
                                backgroundColor: '#fff7ed',
                                color: '#c2410c',
                                borderRadius: '6px',
                                '&:hover': {
                                  backgroundColor: '#fed7aa'
                                },
                                '&:disabled': {
                                  background: 'rgba(0, 0, 0, 0.12)',
                                  color: 'rgba(0, 0, 0, 0.26)'
                                }
                              }}
                            >
                              <Refresh />
                            </IconButton>
                          </Tooltip>
                        )}

                        {onFileView && (
                          <Tooltip title='Ver archivo'>
                            <IconButton
                              size='small'
                              onClick={() => onFileView(file)}
                              sx={{
                                backgroundColor: '#e8f7ef',
                                color: '#00A651',
                                borderRadius: '6px',
                                '&:hover': {
                                  backgroundColor: '#dbeedb'
                                }
                              }}
                            >
                              <Visibility />
                            </IconButton>
                          </Tooltip>
                        )}

                        <Tooltip title='Eliminar archivo'>
                          <IconButton
                            size='small'
                            onClick={() => onFileRemove(file.id)}
                            disabled={uploading}
                            sx={{
                              backgroundColor: '#fef2f2',
                              color: '#dc2626',
                              borderRadius: '6px',
                              '&:hover': {
                                backgroundColor: '#fee2e2'
                              },
                              '&:disabled': {
                                background: 'rgba(0, 0, 0, 0.12)',
                                color: 'rgba(0, 0, 0, 0.26)'
                              }
                            }}
                          >
                            <Delete />
                          </IconButton>
                        </Tooltip>
                      </Box>
                    </Box>
                  </CardContent>
                </Card>
              </Grid>
            ))}
          </Grid>
        </Box>
      )}
    </Box>
  )
}

export default MaintenanceFileUpload

import React, { useState, useEffect } from 'react'
import {
  Box,
  Card,
  Typography,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  TextField,
  Chip,
  Button,
  Grid,
  Autocomplete,
  Accordion,
  AccordionSummary,
  AccordionDetails
} from '@mui/material'
import {
  FilterList,
  Clear,
  ExpandMore,
  Search
} from '@mui/icons-material'
import { DatePicker } from '@mui/x-date-pickers/DatePicker'
import {
  MaintenanceFilters as IMaintenanceFilters,
  MaintenanceStatus,
  MaintenancePriority,
  MaintenanceTechnician
} from '../../types/maintenance'
import MaintenanceStatusBadge from './MaintenanceStatusBadge'
import MaintenancePriorityBadge from './MaintenancePriorityBadge'

interface MaintenanceFiltersProps {
  filters: IMaintenanceFilters
  onFiltersChange: (filters: IMaintenanceFilters) => void
  technicians: MaintenanceTechnician[]
  equipmentTypes: string[]
  loading?: boolean
  resultsCount?: number
}

/**
 * MaintenanceFilters component provides filtering capabilities for maintenance tickets
 *
 * @param filters - Current filter values
 * @param onFiltersChange - Callback when filters change
 * @param technicians - Array of available technicians
 * @param equipmentTypes - Array of available equipment types
 * @param loading - Whether data is loading
 * @param resultsCount - Number of results matching current filters
 */
const MaintenanceFilters: React.FC<MaintenanceFiltersProps> = ({
  filters,
  onFiltersChange,
  technicians,
  equipmentTypes,
  resultsCount
}) => {
  const [localFilters, setLocalFilters] = useState<IMaintenanceFilters>(filters)

  useEffect(() => {
    setLocalFilters(filters)
  }, [filters])

  const handleFilterChange = (key: keyof IMaintenanceFilters, value: any) => {
    const newFilters = { ...localFilters, [key]: value }
    setLocalFilters(newFilters)
    onFiltersChange(newFilters)
  }

  const handleClearFilters = () => {
    const clearedFilters: IMaintenanceFilters = {}
    setLocalFilters(clearedFilters)
    onFiltersChange(clearedFilters)
  }

  const getActiveFiltersCount = () => {
    let count = 0
    if (localFilters.status?.length) count++
    if (localFilters.priority?.length) count++
    if (localFilters.assignedTechnician?.length) count++
    if (localFilters.equipmentType?.length) count++
    if (localFilters.search) count++
    if (localFilters.customerEmail) count++
    if (localFilters.dateRange) count++
    return count
  }

  const activeFiltersCount = getActiveFiltersCount()

  const statusSummary =
    localFilters.status && localFilters.status.length > 0
      ? localFilters.status.length === 1
        ? localFilters.status[0]
        : `${localFilters.status.length} estados`
      : null

  const prioritySummary =
    localFilters.priority && localFilters.priority.length > 0
      ? localFilters.priority.length === 1
        ? localFilters.priority[0]
        : `${localFilters.priority.length} prioridades`
      : null

  return (
    <Card
      sx={{
        p: { xs: 2, md: 2.5 },
        backgroundColor: '#ffffff',
        borderRadius: '14px',
        border: '1px solid #e5e7eb',
        boxShadow: '0 1px 3px rgba(15, 23, 42, 0.08)'
      }}
    >
      {/* Header */}
      <Box
        display='flex'
        alignItems='center'
        justifyContent='space-between'
        mb={1.75}
        gap={2}
        flexWrap='wrap'
      >
        <Box display='flex' alignItems='center' gap={1}>
          <FilterList sx={{ color: '#00A651' }} />
          <Typography
            variant='h6'
            sx={{ fontSize: '1.125rem', fontWeight: 600, color: '#0f172a' }}
          >
            Filtros
          </Typography>
          {activeFiltersCount > 0 && (
            <Chip
              size='small'
              label={activeFiltersCount}
              sx={{
                height: 24,
                fontWeight: 700,
                backgroundColor: '#10b981',
                color: '#ffffff'
              }}
            />
          )}
        </Box>

        {activeFiltersCount > 0 && (
          <Button
            variant='text'
            size='small'
            onClick={handleClearFilters}
            startIcon={<Clear />}
            color='error'
            sx={{ textTransform: 'none', fontWeight: 500 }}
          >
            Limpiar
          </Button>
        )}
      </Box>

      <Grid container spacing={2} alignItems='stretch'>
        {/* Search - Full width on mobile */}
        <Grid item xs={12} md={6}>
          <TextField
            fullWidth
            size='small'
            id='quick-search-field'
            label='Búsqueda rápida'
            placeholder='Buscar tickets...'
            value={localFilters.search || ''}
            onChange={(e) => handleFilterChange('search', e.target.value)}
            InputProps={{
              startAdornment: <Search color='action' sx={{ mr: 1 }} />
            }}
            sx={{
              '& .MuiOutlinedInput-root': {
                borderRadius: '12px',
                backgroundColor: '#ffffff'
              }
            }}
          />
        </Grid>

        {/* Priority - Simplified rendering */}
        <Grid item xs={6} md={3}>
          <FormControl fullWidth size='small'>
            <InputLabel>Prioridad</InputLabel>
            <Select
              multiple
              value={localFilters.priority || []}
              onChange={(e) => handleFilterChange('priority', e.target.value)}
              label='Prioridad'
              renderValue={(selected) => {
                const items = selected as MaintenancePriority[]
                if (items.length === 0) return ''
                if (items.length === 1) {
                  return (
                    <MaintenancePriorityBadge
                      priority={items[0]}
                      size='small'
                      variant='outlined'
                    />
                  )
                }
                return `${items.length} seleccionadas`
              }}
              sx={{ borderRadius: '12px' }}
            >
              {Object.values(MaintenancePriority).map((priority) => (
