                    <MaintenanceStatusBadge
                      status={items[0]}
                      size='small'
                      variant='outlined'
                    />
                  )
                }
                return `${items.length} seleccionadas`
              }}
              sx={{ borderRadius: '12px' }}
            >
              {Object.values(MaintenanceStatus).map((status) => (
                <MenuItem key={status} value={status}>
