                }
              />
            </Grid>

            {/* Equipment Type Filter */}
            <Grid item xs={12} md={6}>
              <Autocomplete
                multiple
                size='small'
                options={equipmentTypes}
                value={localFilters.equipmentType || []}
                onChange={(_, value) => handleFilterChange('equipmentType', value)}
                renderInput={(params) => (
                  <TextField
                    {...params}
                    label='Tipo de Equipo'
                  />
                )}
                renderTags={(value, getTagProps) =>
                  value.map((option, index) => (
                    <Chip
                      {...getTagProps({ index })}
                      key={option}
                      label={option}
                      size='small'
                      variant='outlined'
                    />
                  ))
                }
              />
            </Grid>

            {/* Customer Email Filter */}
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                size='small'
                id='filter-customer-email'
                label='Email del Cliente'
                value={localFilters.customerEmail || ''}
                onChange={(e) => handleFilterChange('customerEmail', e.target.value)}
                aria-label='Filtrar por email del cliente'
                type='email'
              />
            </Grid>

            {/* Date Range Filters */}
            <Grid item xs={12} md={6}>
              <DatePicker
                label='Fecha Desde'
                value={
                  localFilters.dateRange?.from
                    ? new Date(localFilters.dateRange.from)
                    : null
                }
                onChange={(date) => {
                  const dateRange = localFilters.dateRange || {}
                  handleFilterChange('dateRange', {
                    ...dateRange,
                    from: date ? date.toISOString() : undefined
                  })
                }}
                slotProps={{
                  textField: {
                    size: 'small',
                    fullWidth: true
                  }
                }}
              />
            </Grid>

            <Grid item xs={12} md={6}>
              <DatePicker
                label='Fecha Hasta'
                value={
                  localFilters.dateRange?.to
                    ? new Date(localFilters.dateRange.to)
                    : null
                }
                onChange={(date) => {
                  const dateRange = localFilters.dateRange || {}
                  handleFilterChange('dateRange', {
                    ...dateRange,
                    to: date ? date.toISOString() : undefined
                  })
                }}
                slotProps={{
                  textField: {
                    size: 'small',
                    fullWidth: true
                  }
                }}
              />
            </Grid>
          </Grid>
        </AccordionDetails>
      </Accordion>
    </Card>
  )
}

