import React, { Dispatch, SetStateAction, useEffect, useState } from 'react'
import { TextField } from '@mui/material'

import FormDialog, { FormDialogSection } from './Common/FormDialog'
import { notify } from 'src/utils/notify'
import { useCreateCustomer } from 'src/hooks/customers/useCustomers'

import { logger } from 'src/utils/logger'
interface ModalCustomerProps {
  open: boolean
  onClose: Dispatch<SetStateAction<boolean>>
  name: string
  dataReturned: (data: any) => void
}

const FIELDS: Array<{ name: string; label: string; fullWidth?: boolean }> = [
  { name: 'nombre', label: 'Nombre', fullWidth: true },
  { name: 'email', label: 'Correo' },
  { name: 'identificacion', label: 'Identificación' },
  { name: 'direccion', label: 'Dirección' },
  { name: 'telefono', label: 'Teléfono' },
  { name: 'ciudad', label: 'Ciudad' },
  { name: 'departamento', label: 'Departamento' },
  { name: 'pais', label: 'País' }
]

const emptyValues = () =>
  FIELDS.reduce<Record<string, string>>(
    (obj, field) => ({ ...obj, [field.name]: '' }),
    {}
  )

const ModalCustomer: React.FC<ModalCustomerProps> = ({
  open,
  onClose,
  name,
  dataReturned
}) => {
  const createCustomer = useCreateCustomer<Record<string, string | boolean>>()
  const [formValues, setFormValues] =
    useState<Record<string, string>>(emptyValues)
  const [errors, setErrors] = useState<Record<string, boolean>>({})

  const handleClose = () => onClose(false)

  const handleChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const { name: field, value } = event.target
    setFormValues((prev) => ({ ...prev, [field]: value }))
    setErrors((prev) => ({ ...prev, [field]: value === '' }))
  }

  // El nombre llega del Excel; el resto lo completa quien crea el cliente
  useEffect(() => {
    setFormValues((prev) => ({ ...prev, nombre: name }))
  }, [name])

  const handleSubmit = async () => {
    const newErrors = FIELDS.reduce<Record<string, boolean>>(
      (obj, field) => ({ ...obj, [field.name]: formValues[field.name] === '' }),
      {}
    )
    setErrors(newErrors)

    if (Object.values(newErrors).some((error) => error)) {
      return
    }

    try {
      const response = await createCustomer.mutateAsync(formValues)

      if (response.status === 201) {
        notify.success('Cliente creado')
        dataReturned(response.data)
        onClose(false)
      } else {
        logger.error('Error al crear cliente')
      }
    } catch (error) {
      logger.error('Error de red:', error)
    }
  }

  return (
    <FormDialog
      open={open}
      onClose={handleClose}
      title='Crear cliente'
      subtitle='Datos del cliente que trae el Excel'
      submitLabel='Crear cliente'
      onSubmit={handleSubmit}
      loading={createCustomer.isLoading}
      maxWidth='sm'
    >
      <FormDialogSection title='Datos del cliente'>
        {FIELDS.map((field) => (
          <TextField
            key={field.name}
            name={field.name}
            label={field.label}
            value={formValues[field.name]}
            onChange={handleChange}
            error={Boolean(errors[field.name])}
            helperText={errors[field.name] ? 'Obligatorio' : undefined}
            required
            fullWidth
            sx={field.fullWidth ? { gridColumn: '1 / -1' } : undefined}
          />
        ))}
      </FormDialogSection>
    </FormDialog>
  )
}

export default ModalCustomer

import React, { Dispatch, SetStateAction, useEffect, useState } from 'react'
import { TextField } from '@mui/material'
import { notify } from 'src/utils/notify'
import { useCreateDevice } from '@hooks/devices/useDevices'
import { axiosPrivate } from '../utils/api'
import FormDialog from './Common/FormDialog'
import AsyncSelectField, { AsyncSelectOption } from './Common/AsyncSelectField'

import { logger } from 'src/utils/logger'
interface ModalDeviceProps {
  open: boolean
  onClose: Dispatch<SetStateAction<boolean>>
  name: string
  dataReturned: (data: any) => void
  resetForm: () => void
}

const formFields = ['name', 'magnitude', 'certificateTemplate']

const FIELD_LABELS: Record<string, string> = {
  name: 'Nombre',
  magnitude: 'Magnitud',
  certificateTemplate: 'Plantilla de certificado'
}

/** Crea un equipo nuevo desde el análisis de Excel. */
const ModalDevice: React.FC<ModalDeviceProps> = ({
  open,
  onClose,
  name,
  dataReturned,
  resetForm
}) => {
  const createDeviceMutation = useCreateDevice()
  const [formValues, setFormValues] = useState<
    Record<string, string | boolean | AsyncSelectOption | null>
  >(formFields.reduce((obj, field) => ({ ...obj, [field]: '' }), {}))
  const [errors, setErrors] = useState<Record<string, boolean>>(
    formFields.reduce((obj, field) => ({ ...obj, [field]: false }), {})
  )

  const handleClose = () => onClose(false)

  useEffect(() => {
    setFormValues((prev) => ({
      ...prev,
      name: name
    }))
  }, [name])

  const setField = (
    field: string,
    value: string | AsyncSelectOption | null
  ) => {
    setFormValues({ ...formValues, [field]: value })
    setErrors({ ...errors, [field]: !value })
  }

  const handleSubmit = async () => {
    const newErrors = formFields.reduce(
      (obj: Record<string, boolean>, field) => ({
        ...obj,
        [field]: !formValues[field]
      }),
      {}
    )

    setErrors(newErrors)

    if (Object.values(newErrors).some((error) => error)) {
      return
    }

    try {
      const response = await createDeviceMutation.mutateAsync(formValues)

      if (response.status === 201) {
        notify.success('Equipo creado exitosamente')
        dataReturned(response.data)
        resetForm()
        onClose(false)
      } else {
        logger.error('Error al crear equipo')
      }
    } catch (error) {
      logger.error('Error de red:', error)
    }
  }

  const searchTemplates = async (
    input: string
  ): Promise<AsyncSelectOption[]> => {
    const response = await axiosPrivate.get('/templates', {
      params: { q: input }
    })
    return response.data.map((item: { id: number; name: string }) => ({
      value: item.id,
      label: item.name
    }))
  }

  return (
    <FormDialog
      open={open}
      onClose={handleClose}
      title='Crear equipo'
      subtitle='Se agregará al catálogo de equipos'
      submitLabel='Crear equipo'
      onSubmit={() => void handleSubmit()}
      loading={createDeviceMutation.isLoading}
    >
      <TextField
        label={FIELD_LABELS.name}
        required
        fullWidth
        value={formValues.name as string}
        onChange={(event) => setField('name', event.target.value)}
        error={errors.name}
        sx={{ mb: 2 }}
      />
      <TextField
        label={FIELD_LABELS.magnitude}
        required
        fullWidth
        value={formValues.magnitude as string}
        onChange={(event) => setField('magnitude', event.target.value)}
        error={errors.magnitude}
        sx={{ mb: 2 }}
      />
      <AsyncSelectField
        label={FIELD_LABELS.certificateTemplate}
        required
        value={(formValues.certificateTemplate as AsyncSelectOption) || null}
        onChange={(option) => setField('certificateTemplate', option)}
        loadOptions={searchTemplates}
        helperText={
          errors.certificateTemplate ? 'Elige una plantilla' : undefined
        }
      />
    </FormDialog>
  )
}

export default ModalDevice

import React, { useEffect, useState } from 'react'
import {
  Alert,
  Box,
  Button,
  IconButton,
  InputAdornment,
  TextField,
  Tooltip,
  Typography
} from '@mui/material'
import axios from 'axios'
import { useMutation, useQuery } from 'react-query'
import { api } from '../config'
import { notify } from 'src/utils/notify'
import {
  AddOutlined,
  DeleteOutline,
  Visibility,
  VisibilityOff
} from '@mui/icons-material'
import FormDialog, { FormDialogSection } from './Common/FormDialog'

import { logger } from 'src/utils/logger'
const apiUrl = api()

interface ModalPasswordFormProps {
  open: boolean
  onClose: () => void
  wbPasswords: string[]
  setWbPasswords: React.Dispatch<React.SetStateAction<string[]>>
}

interface Password {
  password: string
}

const FULL_WIDTH = { gridColumn: '1 / -1' }

const ModalPasswordForm: React.FC<ModalPasswordFormProps> = ({
  open,
  onClose,
  wbPasswords,
  setWbPasswords
}) => {
  const initialPasswordData = [{ password: '' }]
  const [passwords, setPasswords] = useState<Password[]>(initialPasswordData)
  const [showPassword, setShowPassword] = useState(false)
  const [showUpdateButton, setShowUpdateButton] = useState(false)

  const authHeaders = () => ({
    headers: {
      Authorization: `Bearer ${localStorage.getItem('accessToken')}`
    }
  })

  const { data: settingsPasswords } = useQuery<string[]>(
    ['settings', 'passwords'],
    async () => {
      const response = await axios.get(`${apiUrl}/settings`, authHeaders())
      return response.data
        .filter((data: { name: string }) => data.name === 'passwords')
        .flatMap((data: { values: string[] }) => data.values)
    },
    {
      // Siempre fresco al montar, sin recargas al enfocar (no pisa ediciones locales)
      staleTime: 0,
      refetchOnWindowFocus: false,
      onError: (error) => {
        logger.error('Error fetching settings:', error)
      }
    }
  )

  const createPasswords = useMutation(
    (passwordValues: string[]) =>
      axios.post(
        `${apiUrl}/settings`,
        { passwords: passwordValues },
        authHeaders()
      ),
    { retry: false }
  )

  const updatePasswords = useMutation(
    (passwordsToSave: string[]) =>
      axios.put(
        `${apiUrl}/settings`,
        { passwords: passwordsToSave },
        authHeaders()
      ),
    { retry: false }
  )

  const handleSubmit = async () => {
    const passwordValues = passwords.map((password) => password.password)

    try {
      await createPasswords.mutateAsync(passwordValues)

      notify.success('Contraseñas creadas con éxito')
      onCloseModal()
    } catch (error) {
      logger.error('Error updating settings:', error)
    }
  }

  const onCloseModal = () => {
    setPasswords(initialPasswordData)
    onClose()
  }

  const handleAddPassword = () => {
    setPasswords([...passwords, { password: '' }])
  }

  const handleFormChange = (index: number, value: string) => {
    const newPasswords = passwords.map((password, i) =>
      i === index ? { password: value } : password
    )
    setPasswords(newPasswords)
  }

  const handleRemovePassword = (index: number) => {
    setPasswords(passwords.filter((_, i) => i !== index))
  }

  const handleRemoveFetchedPassword = (indexToRemove: number) => {
    setWbPasswords((prevPasswords) =>
      prevPasswords.filter((_, index) => index !== indexToRemove)
    )
    setShowUpdateButton(true)
  }

  const handleUpdate = async () => {
    try {
      await updatePasswords.mutateAsync(wbPasswords)

      notify.success('Contraseñas actualizadas con éxito')
      setShowUpdateButton(false)
    } catch (error) {
      logger.error('Error updating settings:', error)
    }
  }

  // Las contraseñas cargadas viven en el estado del padre (se editan localmente)
  useEffect(() => {
    if (settingsPasswords) {
      setWbPasswords(settingsPasswords)
    }
  }, [settingsPasswords])

  return (
    <FormDialog
      open={open}
      onClose={onCloseModal}
      title='Contraseñas de los libros'
      subtitle='Se prueban en orden al abrir un Excel protegido'
      submitLabel='Guardar contraseñas'
      onSubmit={handleSubmit}
      loading={createPasswords.isLoading}
      submitDisabled={passwords.every((password) => !password.password)}
    >
      <FormDialogSection title='Guardadas'>
        <Box sx={FULL_WIDTH}>
          {wbPasswords.length > 0 ? (
            <>
              {wbPasswords.map((password, index) => (
                <Box
                  key={index}
                  sx={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    py: 0.5,
                    borderBottom: '1px solid #e5e7eb'
                  }}
                >
                  <Typography sx={{ fontVariantNumeric: 'tabular-nums' }}>
                    {showPassword ? password : '••••••••'}
                  </Typography>
                  <Tooltip title='Quitar'>
                    <IconButton
                      size='small'
                      color='error'
                      aria-label='Quitar contraseña'
                      onClick={() => handleRemoveFetchedPassword(index)}
                    >
                      <DeleteOutline fontSize='small' />
                    </IconButton>
                  </Tooltip>
                </Box>
              ))}
              <Button
                size='small'
                startIcon={showPassword ? <VisibilityOff /> : <Visibility />}
                onClick={() => setShowPassword((value) => !value)}
                sx={{ mt: 1, color: '#00695C' }}
              >
                {showPassword ? 'Ocultar' : 'Mostrar'}
              </Button>
            </>
          ) : (
            <Typography variant='body2' color='text.secondary'>
              Aún no hay contraseñas guardadas.
            </Typography>
          )}
        </Box>
        {showUpdateButton ? (
          <Alert
            severity='warning'
            variant='outlined'
            sx={FULL_WIDTH}
            action={
              <Button
                color='inherit'
                size='small'
                onClick={handleUpdate}
                disabled={updatePasswords.isLoading}
              >
                Guardar cambios
              </Button>
            }
          >
            Quitaste contraseñas de la lista. Guarda los cambios para
            aplicarlos.
          </Alert>
        ) : null}
      </FormDialogSection>

      <FormDialogSection title='Agregar'>
        {passwords.map((password, index) => (
          <TextField
            key={index}
            label={`Contraseña ${index + 1}`}
            type={showPassword ? 'text' : 'password'}
            value={password.password}
            onChange={(e) => handleFormChange(index, e.target.value)}
            fullWidth
            sx={FULL_WIDTH}
            InputProps={{
              endAdornment:
                passwords.length > 1 ? (
                  <InputAdornment position='end'>
                    <IconButton
                      size='small'
                      color='error'
                      aria-label='Quitar este campo'
                      onClick={() => handleRemovePassword(index)}
                    >
                      <DeleteOutline fontSize='small' />
                    </IconButton>
                  </InputAdornment>
                ) : undefined
            }}
          />
        ))}
        <Box sx={FULL_WIDTH}>
          <Button
            size='small'
            startIcon={<AddOutlined />}
            onClick={handleAddPassword}
            sx={{ color: '#00695C' }}
          >
            Agregar otra
          </Button>
        </Box>
      </FormDialogSection>
    </FormDialog>
  )
}

export default ModalPasswordForm

