const isOn = (cell: CustomerModuleCell | null | undefined) => Boolean(cell?.isActive)
// Solo `false` explícito es inactivo: un cliente sin estado se trata como activo
const isInactive = (customer: CustomerModulesRow) => customer.isActive === false

const formatDate = (iso: string) =>
  new Date(iso).toLocaleDateString('es-CO', { day: '2-digit', month: '2-digit', year: 'numeric' })

const cellTooltip = (cell: CustomerModuleCell | null | undefined) => {
  if (!cell) return 'Nunca asignado'
  const verb = cell.isActive ? 'Activado' : 'Desactivado'
  return cell.updatedBy
    ? `${verb} por ${cell.updatedBy.nombre} el ${formatDate(cell.updatedAt)}`
    : `${verb} el ${formatDate(cell.updatedAt)}`
}

const errorMessage = (error: unknown) =>
  getApiErrorReason(error) ??
  'No se pudo actualizar el módulo'

interface PendingChange {
  customerIds: number[]
  module: LicensableModule
  isActive: boolean
  /** Nombre del cliente cuando es una sola celda. */
  customerName?: string
  /** Cuántos de los clientes afectados están inactivos. */
  inactiveCount: number
}

const CustomerModulesMatrix: React.FC = () => {
  const canAssign = useCan(PERMISSIONS.CUSTOMERS_MODULE_ASSIGN)
  const { data, isLoading, isError, refetch } = useCustomerModulesMatrix()
  const setModule = useSetCustomersModule()

  const [rowSelection, setRowSelection] = useState<MRT_RowSelectionState>({})
  const [bulkModuleId, setBulkModuleId] = useState<number | ''>('')
  const [pending, setPending] = useState<PendingChange | null>(null)
  const [showLegacy, setShowLegacy] = useState(false)
  // Por defecto solo clientes activos: los inactivos no pueden entrar, así que su licencia no da acceso
  const [showInactive, setShowInactive] = useState(false)

  const modules = useMemo(() => data?.modules ?? [], [data])
  const customers = useMemo(() => data?.customers ?? [], [data])
  const customerName = useMemo(
    () => new Map(customers.map((c) => [c.id, c.nombre])),
    [customers]
  )
  const activeCustomers = useMemo(() => customers.filter((c) => !isInactive(c)), [customers])
  const inactiveCustomers = useMemo(() => customers.filter(isInactive), [customers])
  const visibleCustomers = showInactive ? inactiveCustomers : activeCustomers
  const inactiveIds = useMemo(() => new Set(inactiveCustomers.map((c) => c.id)), [inactiveCustomers])

  const changeScope = (inactive: boolean) => {
    if (inactive === showInactive) return
    setShowInactive(inactive)
    setRowSelection({}) // la selección no se arrastra entre activos e inactivos
  }
  const selectedIds = Object.keys(rowSelection)
    .filter((id) => rowSelection[id])
    .map(Number)
  const effectiveBulkModuleId = bulkModuleId || (modules.length === 1 ? modules[0].id : '')

  const apply = async (change: PendingChange) => {
    try {
      const result = await setModule.mutateAsync({
        customerIds: change.customerIds,
        moduleId: change.module.id,
        isActive: change.isActive
      })
      const changed = result.updated + result.created
      const verb = change.isActive ? 'activado' : 'desactivado'
      notify.success(change.customerIds.length === 1
          ? `${change.module.label} ${verb}`
          : `${change.module.label} ${verb} en ${changed} cliente${changed === 1 ? '' : 's'}` +
              (result.unchanged ? ` (${result.unchanged} ya estaban así)` : ''))
      if (change.customerIds.length > 1) setRowSelection({})
    } catch (error) {
      notify.error(errorMessage(error))
    } finally {
      setPending(null)
    }
  }

  // Activar una celda es inmediato; quitar acceso o tocar varios clientes pide confirmación.
  const requestCellChange = (row: CustomerModulesRow, module: LicensableModule, isActive: boolean) => {
    const inactive = isInactive(row)
    const change = { customerIds: [row.id], module, isActive, customerName: row.nombre, inactiveCount: inactive ? 1 : 0 }
    if (isActive && !inactive) apply(change)
    else setPending(change)
  }

  const requestBulk = (isActive: boolean) => {
    const module = modules.find((m) => m.id === effectiveBulkModuleId)
    if (!module || selectedIds.length === 0) return
    setPending({
      customerIds: selectedIds,
      module,
      isActive,
      inactiveCount: selectedIds.filter((id) => inactiveIds.has(id)).length
    })
  }

  const columns = useMemo<MRT_ColumnDef<CustomerModulesRow>[]>(
    () => [
      {
        accessorKey: 'nombre',
        header: 'Cliente',
        size: 280,
        Cell: ({ row }: RowProps) => (
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
            <Avatar sx={{ width: 32, height: 32, bgcolor: '#00BFA5', fontSize: 14 }}>
              {row.original.nombre?.charAt(0) ?? '?'}
            </Avatar>
            <Box sx={{ minWidth: 0 }}>
              <Link
                component={RouterLink}
                to={`/customers/${row.original.id}`}
                underline='hover'
                sx={{ fontWeight: 600, color: 'text.primary', display: 'block' }}
              >
                {row.original.nombre}
              </Link>
              <Typography variant='caption' color='text.secondary'>
                {row.original.identificacion ? `NIT ${row.original.identificacion}` : `ID ${row.original.id}`}
              </Typography>
            </Box>
          </Box>
        )
      },
      {
        accessorKey: 'identificacion',
        header: 'NIT',
        enableHiding: true
      },
      {
        accessorKey: 'ciudad',
        header: 'Ciudad',
        size: 140,
        Cell: ({ row }: RowProps) => row.original.ciudad || '—'
      },
      {
        id: 'estado',
        header: 'Estado',
        size: 120,
        accessorFn: (row) => (row.isActive === false ? 'Inactivo' : 'Activo'),
        filterVariant: 'select',
        filterSelectOptions: ['Activo', 'Inactivo'],
        Cell: ({ row }: RowProps) => (
          <Chip
            size='small'
            variant='outlined'
            color={row.original.isActive === false ? 'default' : 'success'}
            label={row.original.isActive === false ? 'Inactivo' : 'Activo'}
          />
        )
      },
      ...modules.map<MRT_ColumnDef<CustomerModulesRow>>((module) => ({
        id: `module-${module.id}`,
        header: module.label,
        size: 150,
        accessorFn: (row) => (isOn(row.modules[module.id]) ? 'Habilitado' : 'Deshabilitado'),
        filterVariant: 'select',
        filterSelectOptions: ['Habilitado', 'Deshabilitado'],
        muiTableHeadCellProps: { align: 'center' },
        muiTableBodyCellProps: { align: 'center' },
        Cell: ({ row }: RowProps) => {
          const cell = row.original.modules[module.id]
          return (
            <Tooltip title={cellTooltip(cell)} arrow>
              <span>
                <Switch
                  checked={isOn(cell)}
                  disabled={!canAssign}
                  onChange={(event) => requestCellChange(row.original, module, event.target.checked)}
                  inputProps={{ 'aria-label': `${module.label} para ${row.original.nombre}` }}
                  sx={{
                    '& .MuiSwitch-switchBase.Mui-checked': { color: '#00BFA5' },
                    '& .MuiSwitch-switchBase.Mui-checked + .MuiSwitch-track': { backgroundColor: '#00BFA5' }
                  }}
                />
              </span>
            </Tooltip>
          )
        }
      }))
    ],
    // requestCellChange solo usa setters y apply; se recrea con los módulos y el permiso
    [modules, canAssign]
  )

  // Los totales cuentan solo clientes activos: son los únicos con acceso real
  const activeCount = (moduleId: number) =>
    activeCustomers.filter((c) => isOn(c.modules[moduleId])).length
  const legacy = data?.legacyInternal ?? []

  const pendingCount = pending?.customerIds.length ?? 0
  const pendingMessage = pending && (
    <>
      {pending.customerName ? (
        <>
          {pending.inactiveCount > 0 ? (
            <>
              <strong>{pending.customerName}</strong> quedará con <strong>{pending.module.label}</strong>{' '}
              {pending.isActive ? 'habilitado' : 'deshabilitado'}.
            </>
          ) : (
            <>
              <strong>{pending.customerName}</strong> {pending.isActive ? 'tendrá' : 'dejará de tener'} acceso a{' '}
              <strong>{pending.module.label}</strong>.
            </>
          )}
        </>
      ) : (
        <>
          Vas a {pending.isActive ? 'activar' : 'desactivar'} <strong>{pending.module.label}</strong> en{' '}
          <strong>{pendingCount} cliente{pendingCount === 1 ? '' : 's'}</strong>.
        </>
      )}
      {!pending.isActive && pending.inactiveCount < pendingCount && ' Sus usuarios dejan de ver el módulo de inmediato.'}
      {pending.inactiveCount > 0 && (
        <Alert severity='warning' sx={{ mt: 2 }}>
          {pending.customerName
            ? 'Este cliente está inactivo: sus usuarios no pueden entrar, así que el cambio aplica cuando se reactive.'
            : `${pending.inactiveCount} de ${pendingCount === pending.inactiveCount ? 'estos' : 'los'} cliente${
                pending.inactiveCount === 1 ? ' está inactivo' : 's están inactivos'
              }: el cambio les aplica cuando se reactiven.`}
        </Alert>
      )}
    </>
  )

  return (
    <>
      <Grid container spacing={3} sx={{ mb: 3 }}>
        <Grid item xs={12} sm={6} md={3}>
          <LmsStatCard variant='quiet'
            label='Clientes activos'
            value={activeCustomers.length}
            icon={<Business />}
            tone='teal'
            active={!showInactive}
            caption={showInactive ? 'Ver clientes activos' : undefined}
            onClick={() => changeScope(false)}
          />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <LmsStatCard variant='quiet'
            label='Clientes inactivos'
            value={inactiveCustomers.length}
            icon={<DomainDisabled />}
            tone='orange'
            active={showInactive}
            caption={showInactive ? 'Mostrando inactivos' : 'Ver inactivos'}
            onClick={() => changeScope(true)}
          />
        </Grid>
        {modules.map((module) => (
          <Grid item xs={12} sm={6} md={3} key={module.id}>
            <LmsStatCard variant='quiet'
              label={`Con ${module.label}`}
              value={activeCount(module.id)}
              icon={MODULE_ICONS[module.name] ?? <CheckCircle />}
              tone='teal'
              caption={`de ${activeCustomers.length} activos`}
            />
          </Grid>
        ))}
      </Grid>

      {isError && (
        <Alert
          severity='error'
          sx={{ mb: 2 }}
          action={
            <Button color='inherit' size='small' onClick={() => refetch()}>
              Reintentar
            </Button>
          }
        >
          No se pudieron cargar los módulos de los clientes.
        </Alert>
      )}

      {legacy.length > 0 && (
        <Alert
          severity='info'
          sx={{ mb: 2 }}
          action={
            <Button color='inherit' size='small' onClick={() => setShowLegacy((v) => !v)}>
              {showLegacy ? 'Ocultar' : 'Ver'}
            </Button>
          }
        >
          {legacy.length} cliente{legacy.length === 1 ? ' tiene' : 's tienen'} activo un módulo interno de una
          configuración antigua. No les da acceso, pero conviene revisarlo desde su perfil.
          <Collapse in={showLegacy}>
            <Box component='ul' sx={{ m: 0, mt: 1, pl: 2.5 }}>
              {legacy.map((item) => (
                <li key={item.customerId}>
                  <Link component={RouterLink} to={`/customers/${item.customerId}`}>
                    {customerName.get(item.customerId) ?? `Cliente ${item.customerId}`}
                  </Link>{' '}
                  — {item.modules.join(', ')}
                </li>
              ))}
            </Box>
          </Collapse>
        </Alert>
      )}

      {showInactive && (
        <Alert
          severity='warning'
          sx={{ mb: 2 }}
          action={
            <Button color='inherit' size='small' onClick={() => changeScope(false)}>
              Ver activos
            </Button>
          }
        >
          Estás viendo clientes inactivos: sus usuarios no pueden entrar. Puedes dejarles los módulos listos para cuando se
          reactiven.
        </Alert>
      )}

      <Paper elevation={2} sx={{ borderRadius: 2, overflow: 'hidden' }}>
        <MaterialReactTable
          columns={columns}
          data={visibleCustomers}
          localization={MRT_Localization_ES}
          // Mientras carga, MRT pinta filas de relleno sin id: sin clave propia React deja filas fantasma
          getRowId={(row, index) => (row?.id != null ? String(row.id) : `loading-${index}`)}
          state={{ isLoading, rowSelection, showProgressBars: setModule.isLoading }}
          enableRowSelection={canAssign}
          onRowSelectionChange={setRowSelection}
          positionToolbarAlertBanner='bottom'
          enableColumnActions={false}
          enableDensityToggle={false}
          enableFullScreenToggle={false}
          enableStickyHeader
          muiTableBodyRowProps={({ row }) => ({
            sx: isInactive(row.original) ? { opacity: 0.65 } : undefined
          })}
          initialState={{
            density: 'comfortable',
            showGlobalFilter: true,
            columnVisibility: { identificacion: false },
            pagination: { pageSize: 25, pageIndex: 0 }
          }}
          muiSearchTextFieldProps={{
            placeholder: 'Buscar cliente, NIT o ciudad…',
            sx: { minWidth: '300px' },
            variant: 'outlined',
            inputProps: { 'aria-label': 'Buscar clientes' }
          }}
          renderTopToolbarCustomActions={() =>
            canAssign && selectedIds.length > 0 ? (
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
                <Typography variant='body2' fontWeight={600} sx={{ mr: 1 }}>
                  {selectedIds.length} seleccionado{selectedIds.length === 1 ? '' : 's'}
                </Typography>
                {modules.length > 1 && (
                  <TextField
                    select
                    size='small'
                    label='Módulo'
                    value={effectiveBulkModuleId}
                    onChange={(e) => setBulkModuleId(Number(e.target.value))}
                    sx={{ minWidth: 180 }}
                  >
                    {modules.map((m) => (
                      <MenuItem key={m.id} value={m.id}>
                        {m.label}
                      </MenuItem>
                    ))}
                  </TextField>
                )}
                <Button
                  variant='contained'
                  size='small'
                  startIcon={<ToggleOn />}
                  disabled={!effectiveBulkModuleId || setModule.isLoading}
                  onClick={() => requestBulk(true)}
                  sx={{ textTransform: 'none', bgcolor: '#00BFA5', '&:hover': { bgcolor: '#00ACC1' } }}
                >
                  Activar{modules.length === 1 ? ` ${modules[0].label}` : ''}
                </Button>
                <Button
                  variant='outlined'
                  size='small'
                  color='error'
                  startIcon={<ToggleOff />}
                  disabled={!effectiveBulkModuleId || setModule.isLoading}
                  onClick={() => requestBulk(false)}
                  sx={{ textTransform: 'none' }}
                >
                  Desactivar
                </Button>
              </Box>
            ) : (
              <Typography variant='body2' color='text.secondary' sx={{ alignSelf: 'center', pl: 1 }}>
                {canAssign
                  ? 'Selecciona clientes para activar o desactivar un módulo a varios a la vez.'
                  : 'Solo lectura: no tienes permiso para asignar módulos.'}
              </Typography>
            )
          }
          muiTableProps={{
            sx: {
              '& .MuiTableHead-root .MuiTableCell-root': { backgroundColor: '#f5f5f5', fontWeight: 600 },
              '& .MuiTableBody-root .MuiTableRow-root:hover': { backgroundColor: 'rgba(0, 191, 165, 0.04)' }
            }
          }}
          muiTopToolbarProps={{ sx: { backgroundColor: '#fafafa' } }}
          muiBottomToolbarProps={{ sx: { backgroundColor: '#fafafa' } }}
        />
      </Paper>

      <ConfirmDialog
        open={Boolean(pending)}
        title={
          pending?.isActive
            ? `Activar ${pending.module.label}`
            : `Desactivar ${pending?.module.label ?? 'módulo'}`
        }
        message={pendingMessage}
        confirmLabel={pending?.isActive ? 'Activar' : 'Desactivar'}
        tone={pending?.isActive ? 'default' : 'danger'}
        loading={setModule.isLoading}
        onConfirm={() => pending && apply(pending)}
        onClose={() => setPending(null)}
      />
    </>
  )
}

export default CustomerModulesMatrix

import { getApiErrorReason } from 'src/utils/apiError'
import React from 'react'
import { useFormik } from 'formik'
import * as Yup from 'yup'
import {
  Button,
  TextField,
  Container,
  Box,
  Typography,
  Paper
} from '@mui/material'
import { IModule, ModuleFormProps } from '../types/moduleTypes'
import useAxiosPrivate from '@utils/use-axios-private'

const validationSchema = Yup.object({
  name: Yup.string().required('Nombre es requerido'),
  label: Yup.string().required('Label es requerido'),
  description: Yup.string().max(500, 'Descripción muy larga')
})

const ModuleForm: React.FC<ModuleFormProps> = ({
  onSuccess,
  initialData,
  onCancel
}) => {
  const axiosPrivate = useAxiosPrivate()

  const formik = useFormik<Omit<IModule, 'id'>>({
    initialValues: initialData || {
      name: '',
      label: '',
      description: ''
    },
    validationSchema,
    onSubmit: async (values, { setSubmitting, setStatus }) => {
      try {
        const endpoint = initialData ? `/modules/${initialData.id}` : '/modules'
        const method = initialData ? 'patch' : 'post'

        await axiosPrivate[method](endpoint, values)

        setStatus({ success: true })
        onSuccess?.()
      } catch (error: any) {
        const errorMessage =
          getApiErrorReason(error) || 'Error al procesar el módulo'
        setStatus({ success: false, error: errorMessage })
      } finally {
        setSubmitting(false)
      }
    }
  })

  return (
    <Container maxWidth='sm'>
      <Paper elevation={3} sx={{ p: 4, mt: 4 }}>
        <Typography variant='h5' gutterBottom>
          {initialData ? 'Editar Módulo' : 'Crear Nuevo Módulo'}
        </Typography>

        <Box component='form' onSubmit={formik.handleSubmit} sx={{ mt: 2 }}>
          <TextField
            fullWidth
            margin='normal'
            id='name'
            name='name'
            label='Nombre del módulo'
            value={formik.values.name}
            onChange={formik.handleChange}
            error={formik.touched.name && Boolean(formik.errors.name)}
            helperText={formik.touched.name && formik.errors.name}
          />

          <TextField
            fullWidth
            margin='normal'
            id='label'
            name='label'
            label='Label'
            value={formik.values.label}
            onChange={formik.handleChange}
            error={formik.touched.label && Boolean(formik.errors.label)}
            helperText={formik.touched.label && formik.errors.label}
          />

          <TextField
            fullWidth
            margin='normal'
            id='description'
            name='description'
            label='Descripción'
            multiline
            rows={4}
            value={formik.values.description}
            onChange={formik.handleChange}
            error={
              formik.touched.description && Boolean(formik.errors.description)
            }
            helperText={formik.touched.description && formik.errors.description}
          />

          <Box
            sx={{ display: 'flex', justifyContent: 'flex-end', gap: 2, mt: 3 }}
          >
            {onCancel && (
              <Button
                variant='outlined'
                onClick={onCancel}
                disabled={formik.isSubmitting}
              >
                Cancelar
              </Button>
            )}

            <Button
              type='submit'
              variant='contained'
              color='primary'
              disabled={formik.isSubmitting}
            >
              {formik.isSubmitting
                ? 'Procesando...'
                : initialData
                  ? 'Actualizar'
                  : 'Crear'}
            </Button>
          </Box>

          {formik.status?.error && (
            <Typography color='error' sx={{ mt: 2 }}>
              {formik.status.error}
            </Typography>
          )}
        </Box>
      </Paper>
    </Container>
  )
}

export default ModuleForm

import { NumericFormat, NumericFormatProps } from 'react-number-format'
import { IMaskInput } from 'react-imask'

import * as React from 'react'
interface CustomProps {
  onChange: (event: { target: { name: string; value: string } }) => void
  name: string
}

export const TextMaskCustom = React.forwardRef<HTMLInputElement, CustomProps>(
  function TextMaskCustom(props, ref) {
    const { onChange, ...other } = props

    return (
      <IMaskInput
        {...other}
        // mask="(#00) 000-0000"
        // definitions={{
        //   "#": /[1-9]/,
        // }}
        inputRef={ref}
        onAccept={(value: any) =>
          onChange({ target: { name: props.name, value } })
        }
        overwrite
      />
    )
  }
)

export const NumericFormatCustom = React.forwardRef<
  NumericFormatProps,
  CustomProps
>(function NumericFormatCustom(props, ref) {
  const { onChange, ...other } = props

  return (
    <NumericFormat
      {...other}
      getInputRef={ref}
      onValueChange={(values) => {
        onChange?.({
          target: {
            name: props.name,
            value: values.value
          }
        })
      }}
      thousandSeparator='.'
      decimalSeparator=','
      valueIsNumericString
      suffix={props.name?.includes('Ratio') ? '%' : ''} // Agregar sufijo %
    />
  )
})

// src/Components/Purchases/GenerateOrderModal.tsx
import { useState, useEffect, FC, ChangeEvent } from 'react'
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  TextField,
  Table,
  TableHead,
  TableRow,
  TableCell,
  TableBody,
  Typography,
  MenuItem,
  Checkbox,
  Grid,
  Box,
  CircularProgress,
  Alert,
  IconButton,
  Tooltip,
  Divider
} from '@mui/material'
import { Close, DeleteOutline } from '@mui/icons-material'
import { PURCHASE_TEAL, PURCHASE_TEAL_HOVER } from './purchaseTableStyle'
import {
  useCreatePurchaseOrder,
  useFiscalSettings
} from 'src/hooks/purchases/usePurchaseOrders'
import {
  PurchaseRequestItem,
  Supplier,
  PurchaseRequest,
  PurchaseOrder
} from 'src/pages/Purchases/Types' // Asegúrate que estas rutas sean correctas
import { NumericFormat } from 'react-number-format'
import { notify } from 'src/utils/notify'

import { logger } from 'src/utils/logger'
interface AssignedItem {
  purchaseRequestItemId: string
  description: string
  quantity: number
  unitValue: string // Se mantiene como string por NumericFormat, se parsea para cálculos
  total: number // quantity * unitValue (subtotal original del ítem)
  itemType: 'service' | 'purchase'
  applyIVA: boolean
  ivaPercentageForItem: string // Se mantiene como string, se parsea para cálculos
}

interface GenerateOrderModalProps {
  open: boolean
  onClose: () => void
  purchaseRequest: PurchaseRequest
  onSuccess: () => void
}


const GenerateOrderModal: FC<GenerateOrderModalProps> = ({
  open,
  onClose,
  purchaseRequest,
  onSuccess
}) => {
  const [orderData, setOrderData] = useState<
    Omit<PurchaseOrder, 'purchaseRequestId' | 'purchaseRequest'>
  >({
    code: '',
    requestDate: new Date().toISOString().slice(0, 10),
    deliveryDate: new Date().toISOString().slice(0, 10),
    deliveryPlace: 'Calle 35 No. 13 - 46 Barrio, Guadalupe',
    paymentMethod: 'Contado',
    installments: 'N/A',
    freight: 'Asume Metromedics',
    observations: '',
    totalBeforeVAT: 0, // Suma de item.total (subtotal bruto de la orden)
    vat: 0,
    retefuente: 0,
    retecree: 0,
    discount: 0, // Valor del descuento (calculado a partir de discountPercentage)
    total: 0,
    requirements: purchaseRequest.requirements || ['No hay requerimientos']
  })
  const [selectedSupplier, setSelectedSupplier] = useState<string>('')
  const [selectedSupplierFull, setSelectedSupplierFull] =
    useState<Supplier | null>(null)
  const [assignedItems, setAssignedItems] = useState<AssignedItem[]>([])
  const [removedItems, setRemovedItems] = useState<string[]>([])
  const [_pendingItems, setPendingItems] = useState<PurchaseRequestItem[]>([])
  const [discountPercentage, setDiscountPercentage] = useState<number>(0) // Porcentaje de descuento ingresado por el usuario

  const {
    data: fiscalSettings,
    isLoading: isLoadingFiscalSettings,
    error: fiscalSettingsError
  } = useFiscalSettings()
  const createOrder = useCreatePurchaseOrder()

  const handleSubmitOrder = async () => {
    if (!selectedSupplier) {
      notify.warning('Advertencia', 'Por favor, seleccione un proveedor.')
      return
    }
    if (assignedItems.length === 0) {
      notify.warning('Advertencia', 'No hay ítems asignados para este proveedor.')
      return
    }
    if (isLoadingFiscalSettings) {
      notify.info('Info', 'Cargando configuración fiscal, por favor espere.')
      return
    }
    if (fiscalSettingsError || !fiscalSettings) {
      notify.error('Error', 'No se pudo cargar la configuración fiscal necesaria.')
      return
    }

    // El orderData.discount ya es el valor calculado, no el porcentaje
    // El orderData.total ya está calculado con el descuento comercial aplicado
    const payload = {
      purchaseRequestId: purchaseRequest.id,
      supplierId: selectedSupplier,
      orderData: {
        ...orderData, // Contiene todos los valores calculados, incluyendo el total final
        requirements: purchaseRequest.requirements || [],
        // Asegurar que los valores numéricos se envíen como números
        totalBeforeVAT: Number(orderData.totalBeforeVAT) || 0,
        vat: Number(orderData.vat) || 0,
        retefuente: Number(orderData.retefuente) || 0,
        retecree: Number(orderData.retecree) || 0,
        discount: Number(orderData.discount) || 0, // Este es el valor del descuento
        total: Number(orderData.total) || 0
      },
      items: assignedItems.map((item) => ({
        purchaseRequestItemId: item.purchaseRequestItemId,
        unitValue:
          parseFloat(String(item.unitValue).replace(/[^0-9.-]+/g, '')) || 0,
        quantity: item.quantity,
        total: item.total, // Subtotal original del ítem (cantidad * valor unitario)
        itemType: item.itemType,
        applyIVA: item.applyIVA,
        ivaPercentageForItem: parseFloat(item.ivaPercentageForItem) || 0
      }))
    }

    try {
      await createOrder.mutateAsync(payload)
      notify.success('Éxito', 'La orden de compra ha sido generada.')
      const processedIds = assignedItems.map(
        (item) => item.purchaseRequestItemId
      )
      setPendingItems((prev) =>
        prev.filter((item) => !processedIds.includes(item.id.toString()))
      )
      onSuccess()
      onClose()
    } catch (error) {
      logger.error('Error generating purchase order:', error)
      notify.error('Error', 'No se pudo generar la orden de compra.')
    }
  }

  const availableSuppliers: Supplier[] = Array.from(
    new Set(
      (purchaseRequest.items ?? [])
        .filter((item) => !item.procesed)
        .flatMap((item) =>
          item.suppliers ? item.suppliers.map((s) => s.id.toString()) : []
        )
    )
  )
    .map((supplierId: string) => {
      const itemWithSupplier = (purchaseRequest.items ?? []).find(
        (item) =>
          !item.procesed &&
          item.suppliers?.some((s) => s.id.toString() === supplierId)
      )
      return (
        itemWithSupplier?.suppliers?.find(
          (s) => s.id.toString() === supplierId
        ) || null
      )
    })
    .filter((s): s is Supplier => s !== null)

  useEffect(() => {
    if (selectedSupplier) {
      const supplierDetails = availableSuppliers.find(
        (s) => s.id.toString() === selectedSupplier
      )
      setSelectedSupplierFull(supplierDetails || null)
      const itemsForSupplier: AssignedItem[] = (purchaseRequest.items ?? [])
        .filter(
          (item) =>
            !item.procesed &&
            item.suppliers?.some((s) => s.id.toString() === selectedSupplier) &&
            !removedItems.includes(item.id.toString())
        )
        .map((item) => ({
          purchaseRequestItemId: item.id.toString(),
          description: item.description,
          quantity: item.quantity,
          unitValue: '',
          total: 0,
          itemType: 'purchase',
          applyIVA: true,
          ivaPercentageForItem:
            fiscalSettings?.IVA_GENERAL_RATE_PERCENTAGE?.toString() || '19'
        }))
      setAssignedItems(itemsForSupplier)
    } else {
      setSelectedSupplierFull(null)
      setAssignedItems([])
    }
  }, [selectedSupplier, removedItems, purchaseRequest.items, fiscalSettings])

  const handleOrderChange = (e: ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target
    setOrderData((prev) => ({ ...prev, [name]: value }))
  }

  const handleSupplierChange = (e: ChangeEvent<HTMLInputElement>) => {
    setSelectedSupplier(e.target.value)
    setRemovedItems([])
  }

  const handleItemChange = (
    index: number,
    field: keyof AssignedItem,
    value: string | boolean | number
  ) => {
    setAssignedItems((prevItems) => {
      const newItems = [...prevItems]
      ;(newItems[index] as any)[field] = value
      if (field === 'unitValue' || field === 'quantity') {
        const quantity = Number(newItems[index].quantity) || 0
        const unitValue =
          parseFloat(
            String(newItems[index].unitValue).replace(/[^0-9.-]+/g, '')
          ) || 0
        newItems[index].total = unitValue * quantity
      }
      return newItems
    })
  }

  const handleRemoveItem = (itemId: string) => {
    setRemovedItems((prev) => [...prev, itemId])
  }

  // 1. Calcular Total Bruto Antes de IVA y Descuento (Subtotal Original)
  useEffect(() => {
    const grossSubtotal = assignedItems.reduce(
      (sum, item) => sum + item.total,
      0
    )
    setOrderData((prev) => ({ ...prev, totalBeforeVAT: grossSubtotal }))
  }, [assignedItems])

  // 2. Calcular el Valor del Descuento
  useEffect(() => {
    const grossSubtotal = Number(orderData.totalBeforeVAT) || 0
    const percentage = Number(discountPercentage) || 0
    const validPercentage = Math.max(0, percentage) // Evitar descuento negativo
    const calculatedDiscountAmount = (grossSubtotal * validPercentage) / 100
    setOrderData((prev) => ({
      ...prev,
      discount: parseFloat(calculatedDiscountAmount.toFixed(2))
    }))
  }, [discountPercentage, orderData.totalBeforeVAT])

  // 3. Calcular IVA Total (sobre la base después del descuento)
  useEffect(() => {
    const grossSubtotal = Number(orderData.totalBeforeVAT) || 0
    const discountAmount = Number(orderData.discount) || 0
    let totalVAT = 0

    if (grossSubtotal > 0) {
      assignedItems.forEach((item) => {
        if (item.applyIVA) {
          const itemOriginalSubtotal = item.total // Subtotal original del ítem
          const itemProportion = itemOriginalSubtotal / grossSubtotal
          const itemDiscount = discountAmount * itemProportion
          const itemTaxableBase = itemOriginalSubtotal - itemDiscount
          const itemIVAPerc = parseFloat(item.ivaPercentageForItem) / 100 || 0
          totalVAT += itemTaxableBase * itemIVAPerc
        }
      })
    } else {
      // Si grossSubtotal es 0, pero algún ítem podría tener IVA (caso raro, ej. ítem de $0 con IVA)
      assignedItems.forEach((item) => {
        if (item.applyIVA && item.total === 0) {
          const itemIVAPerc = parseFloat(item.ivaPercentageForItem) / 100 || 0
          totalVAT += 0 * itemIVAPerc // Explicitly 0
        }
      })
    }
    setOrderData((prev) => ({ ...prev, vat: parseFloat(totalVAT.toFixed(2)) }))
  }, [assignedItems, orderData.totalBeforeVAT, orderData.discount])

  // 4. Calcular Retefuente (sobre la base después del descuento)
  useEffect(() => {
    if (
      !selectedSupplierFull ||
      !selectedSupplierFull.applyRetention ||
      isLoadingFiscalSettings ||
      !fiscalSettings
    ) {
      setOrderData((prev) => ({ ...prev, retefuente: 0 }))
      return
    }

    const {
      PURCHASE_RETENTION_RATE = 0,
      SERVICE_RETENTION_RATE = 0,
      PURCHASE_MINIMUM_BASE = 0,
      SERVICE_MINIMUM_BASE = 0
    } = fiscalSettings

    const grossSubtotal = Number(orderData.totalBeforeVAT) || 0
    const discountAmount = Number(orderData.discount) || 0

    let discountedPurchasesBase = 0
    let discountedServicesBase = 0

    if (grossSubtotal > 0) {
      assignedItems.forEach((item) => {
        const itemOriginalSubtotal = item.total
        const itemProportion = itemOriginalSubtotal / grossSubtotal
        const itemDiscount = discountAmount * itemProportion
        const itemTaxableBase = itemOriginalSubtotal - itemDiscount

        if (item.itemType === 'purchase') {
          discountedPurchasesBase += itemTaxableBase
        } else if (item.itemType === 'service') {
          discountedServicesBase += itemTaxableBase
        }
      })
    }

    let calculatedRetefuente = 0
    if (discountedPurchasesBase >= PURCHASE_MINIMUM_BASE) {
      calculatedRetefuente += discountedPurchasesBase * PURCHASE_RETENTION_RATE
    }
    if (discountedServicesBase >= SERVICE_MINIMUM_BASE) {
      calculatedRetefuente += discountedServicesBase * SERVICE_RETENTION_RATE
    }
    setOrderData((prev) => ({
      ...prev,
      retefuente: parseFloat(calculatedRetefuente.toFixed(2))
    }))
  }, [
    assignedItems,
    selectedSupplierFull,
    fiscalSettings,
    isLoadingFiscalSettings,
    orderData.totalBeforeVAT,
    orderData.discount
  ])

  // 5. Calcular Total Final
  useEffect(() => {
    const subtotalOriginal = Number(orderData.totalBeforeVAT) || 0
    const discountVal = Number(orderData.discount) || 0
    const vatVal = Number(orderData.vat) || 0
    const retefuenteVal = Number(orderData.retefuente) || 0
    const retecreeVal = Number(orderData.retecree) || 0 // Asumimos que este es un valor, no un %

    const subtotalAfterDiscount = subtotalOriginal - discountVal

    const finalTotal =
      subtotalAfterDiscount + vatVal - retefuenteVal - retecreeVal

    setOrderData((prev) => ({
      ...prev,
      total: parseFloat(finalTotal.toFixed(2))
    }))
  }, [
    orderData.totalBeforeVAT,
    orderData.vat,
    orderData.retefuente,
    orderData.retecree,
    orderData.discount
  ])

  const formatCOP = (value: number | string) =>
    new Intl.NumberFormat('es-CO', {
      style: 'currency',
      currency: 'COP',
      minimumFractionDigits: 0,
      maximumFractionDigits: 0
    }).format(Number(value) || 0)

  const blockedReason = isLoadingFiscalSettings
    ? 'Cargando configuración fiscal...'
    : !selectedSupplier
      ? 'Elige un proveedor para continuar'
      : assignedItems.length === 0
        ? 'Este proveedor no tiene ítems pendientes de orden'
        : ''

  const sectionTitle = (text: string) => (
    <Typography variant='subtitle1' fontWeight={700} sx={{ mb: 1.5 }}>
      {text}
    </Typography>
  )

  const summaryRow = (label: string, value: number | string, bold = false) => (
    <Box
      sx={{
        display: 'flex',
        justifyContent: 'space-between',
        py: 0.5,
        fontWeight: bold ? 700 : 400
      }}
    >
      <Typography variant='body2' color='text.secondary'>
        {label}
      </Typography>
      <Typography variant='body2' fontWeight='inherit'>
        {formatCOP(value)}
      </Typography>
    </Box>
  )

  return (
    <Dialog open={open} onClose={onClose} maxWidth='lg' fullWidth>
      <DialogTitle
        sx={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center'
        }}
      >
        <Box>
          <Typography variant='h6' component='span' fontWeight={700}>
            Generar orden · {purchaseRequest.purchaseCode}
          </Typography>
          <Typography variant='body2' color='text.secondary'>
            {[
              purchaseRequest.applicantName,
              purchaseRequest.purchaseType
                ? `Tipo ${purchaseRequest.purchaseType}`
                : null
            ]
              .filter(Boolean)
              .join(' · ')}
          </Typography>
        </Box>
        <IconButton onClick={onClose} aria-label='Cerrar'>
          <Close />
        </IconButton>
      </DialogTitle>

      <DialogContent dividers>
        {isLoadingFiscalSettings && (
          <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
            <CircularProgress size={20} sx={{ mr: 1 }} />
            <Typography variant='body2'>
              Cargando configuración fiscal...
            </Typography>
          </Box>
        )}
        {fiscalSettingsError && (
          <Alert severity='error' sx={{ mb: 2 }}>
            Error al cargar la configuración fiscal:{' '}
            {fiscalSettingsError.message}. Los cálculos pueden ser incorrectos.
          </Alert>
        )}

        {sectionTitle('Proveedor')}
        <Grid container spacing={2} sx={{ mb: 3 }}>
          <Grid item xs={12} md={6}>
            <TextField
              select
              label='Proveedor'
              value={selectedSupplier}
              onChange={handleSupplierChange}
              fullWidth
              required
              disabled={isLoadingFiscalSettings}
            >
              {availableSuppliers.map((supplier) => (
                <MenuItem key={supplier.id} value={supplier.id.toString()}>
                  {supplier.name}
                </MenuItem>
              ))}
            </TextField>
          </Grid>
          <Grid item xs={12} md={6}>
            <TextField
              label='Código de la orden (opcional)'
              name='code'
              fullWidth
              value={orderData.code}
              onChange={handleOrderChange}
              disabled={isLoadingFiscalSettings}
            />
          </Grid>
        </Grid>

        {sectionTitle('Entrega y pago')}
        <Grid container spacing={2} sx={{ mb: 3 }}>
          <Grid item xs={12} sm={6} md={3}>
            <TextField
              label='Fecha de solicitud'
              name='requestDate'
              type='date'
              fullWidth
              InputLabelProps={{ shrink: true }}
              value={orderData.requestDate}
              onChange={handleOrderChange}
              disabled={isLoadingFiscalSettings}
            />
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <TextField
              label='Fecha de entrega'
              name='deliveryDate'
              type='date'
              fullWidth
              InputLabelProps={{ shrink: true }}
              value={orderData.deliveryDate}
              onChange={handleOrderChange}
              disabled={isLoadingFiscalSettings}
            />
          </Grid>
          <Grid item xs={12} md={6}>
            <TextField
              label='Lugar de entrega'
              name='deliveryPlace'
              fullWidth
              value={orderData.deliveryPlace}
              onChange={handleOrderChange}
              disabled={isLoadingFiscalSettings}
            />
          </Grid>
          <Grid item xs={12} sm={4}>
            <TextField
              label='Método de pago'
              name='paymentMethod'
              fullWidth
              value={orderData.paymentMethod}
              onChange={handleOrderChange}
              disabled={isLoadingFiscalSettings}
            />
          </Grid>
          <Grid item xs={12} sm={4}>
            <TextField
              label='Cuotas'
              name='installments'
              fullWidth
              value={orderData.installments}
              onChange={handleOrderChange}
              disabled={isLoadingFiscalSettings}
            />
          </Grid>
          <Grid item xs={12} sm={4}>
            <TextField
              label='Flete'
              name='freight'
              fullWidth
              value={orderData.freight}
              onChange={handleOrderChange}
              disabled={isLoadingFiscalSettings}
            />
          </Grid>
        </Grid>

        {selectedSupplier && assignedItems.length > 0 && (
          <>
            <Divider sx={{ mb: 2 }} />
            {sectionTitle(
              `Ítems de ${selectedSupplierFull?.name || 'el proveedor'}`
            )}
            <Box sx={{ overflowX: 'auto', mb: 3 }}>
              <Table size='small'>
                <TableHead>
                  <TableRow sx={{ '& th': { bgcolor: '#f5f5f5', fontWeight: 600 } }}>
                    <TableCell>Descripción</TableCell>
                    <TableCell sx={{ minWidth: 120 }}>Tipo</TableCell>
                    <TableCell>Cant.</TableCell>
                    <TableCell sx={{ minWidth: 140 }}>Valor unitario</TableCell>
                    <TableCell align='right' sx={{ minWidth: 120 }}>
                      Total
                    </TableCell>
                    <TableCell sx={{ minWidth: 90 }}>IVA %</TableCell>
                    <TableCell>Aplica IVA</TableCell>
                    <TableCell />
                  </TableRow>
                </TableHead>
                <TableBody>
                  {assignedItems.map((item, index) => (
                    <TableRow key={item.purchaseRequestItemId}>
                      <TableCell>{item.description}</TableCell>
                      <TableCell>
                        <TextField
                          select
                          value={item.itemType}
                          onChange={(e) =>
                            handleItemChange(
                              index,
                              'itemType',
                              e.target.value as 'service' | 'purchase'
                            )
                          }
                          size='small'
                          sx={{ minWidth: 100 }}
                          disabled={isLoadingFiscalSettings}
                        >
                          <MenuItem value='purchase'>Compra</MenuItem>
                          <MenuItem value='service'>Servicio</MenuItem>
                        </TextField>
                      </TableCell>
                      <TableCell>{item.quantity}</TableCell>
                      <TableCell>
                        <NumericFormat
                          value={item.unitValue}
                          thousandSeparator=','
                          decimalSeparator='.'
                          prefix={'$ '}
                          customInput={TextField}
                          size='small'
                          onValueChange={(values) =>
                            handleItemChange(index, 'unitValue', values.value)
                          }
                          sx={{ minWidth: 120 }}
                          disabled={isLoadingFiscalSettings}
                        />
                      </TableCell>
                      <TableCell align='right'>
                        <Typography variant='body2' fontWeight={600}>
                          {formatCOP(item.total)}
                        </Typography>
                      </TableCell>
                      <TableCell>
                        <NumericFormat
                          value={item.ivaPercentageForItem}
                          customInput={TextField}
                          suffix={'%'}
                          size='small'
                          onValueChange={(values) =>
                            handleItemChange(
                              index,
                              'ivaPercentageForItem',
                              values.value
                            )
                          }
                          sx={{ minWidth: 80 }}
                          disabled={isLoadingFiscalSettings || !item.applyIVA}
                        />
                      </TableCell>
                      <TableCell>
                        <Checkbox
                          checked={item.applyIVA}
                          onChange={(e) =>
                            handleItemChange(
                              index,
                              'applyIVA',
                              e.target.checked
                            )
                          }
                          size='small'
                          sx={{
                            color: PURCHASE_TEAL,
                            '&.Mui-checked': { color: PURCHASE_TEAL }
                          }}
                          disabled={isLoadingFiscalSettings}
                        />
                      </TableCell>
                      <TableCell>
                        <Tooltip title='Quitar de la orden'>
                          <span>
                            <IconButton
                              size='small'
                              color='error'
                              onClick={() =>
                                handleRemoveItem(item.purchaseRequestItemId)
                              }
                              disabled={isLoadingFiscalSettings}
                              aria-label='Quitar de la orden'
                            >
                              <DeleteOutline />
                            </IconButton>
                          </span>
                        </Tooltip>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </Box>
          </>
        )}

        {selectedSupplier && (
          <Grid container spacing={3}>
            <Grid item xs={12} md={7}>
              {sectionTitle('Observaciones')}
              <TextField
                multiline
                minRows={4}
                maxRows={8}
                label='Observaciones'
                name='observations'
                fullWidth
                value={orderData.observations}
                onChange={handleOrderChange}
                disabled={isLoadingFiscalSettings}
              />
            </Grid>
            <Grid item xs={12} md={5}>
              {sectionTitle('Resumen')}
              <Box
                sx={{
                  border: '1px solid #e5e7eb',
                  borderRadius: 2,
                  p: 2
                }}
              >
                {summaryRow('Total antes de IVA', orderData.totalBeforeVAT)}
                <Box
                  sx={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    py: 0.5,
                    gap: 1
                  }}
                >
                  <Typography variant='body2' color='text.secondary'>
                    Descuento
                  </Typography>
                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <NumericFormat
                      value={discountPercentage}
                      suffix={'%'}
                      customInput={TextField}
                      size='small'
                      onValueChange={(values) => {
                        setDiscountPercentage(Number(values.value) || 0)
                      }}
                      decimalScale={2}
                      allowNegative={false}
                      sx={{ width: 90 }}
                      inputProps={{ 'aria-label': 'Descuento en porcentaje' }}
                      disabled={
                        isLoadingFiscalSettings ||
                        orderData.totalBeforeVAT === 0
                      }
                    />
                    <Typography variant='body2' sx={{ minWidth: 80 }} align='right'>
                      {formatCOP(orderData.discount)}
                    </Typography>
                  </Box>
                </Box>
                {summaryRow('IVA', orderData.vat)}
                {summaryRow('ReteFuente', orderData.retefuente)}
                <Box
                  sx={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    py: 0.5,
                    gap: 1
                  }}
                >
                  <Typography variant='body2' color='text.secondary'>
                    ReteICA / otros
                  </Typography>
                  <NumericFormat
                    value={orderData.retecree}
                    thousandSeparator=','
                    decimalSeparator='.'
                    prefix={'$ '}
                    customInput={TextField}
                    size='small'
                    onValueChange={(values) => {
                      setOrderData((prev) => ({
                        ...prev,
                        retecree: Number(values.value) || 0
                      }))
                    }}
                    sx={{ width: 150 }}
                    inputProps={{ 'aria-label': 'ReteICA u otros' }}
                    disabled={isLoadingFiscalSettings}
                  />
                </Box>
                <Divider sx={{ my: 1 }} />
                <Box
                  sx={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'baseline'
                  }}
                >
                  <Typography variant='subtitle1' fontWeight={700}>
                    Total final
                  </Typography>
                  <Typography variant='h6' fontWeight={700}>
                    {formatCOP(orderData.total)}
                  </Typography>
                </Box>
              </Box>
            </Grid>
          </Grid>
        )}
      </DialogContent>

      <DialogActions sx={{ px: 3, py: 2 }}>
        {blockedReason && (
          <Typography variant='body2' color='text.secondary' sx={{ mr: 'auto' }}>
            {blockedReason}
          </Typography>
        )}
        <Button onClick={onClose} color='inherit'>
          Cancelar
        </Button>
        <Button
          variant='contained'
          onClick={handleSubmitOrder}
          disabled={!!blockedReason}
          sx={{
            bgcolor: PURCHASE_TEAL,
            '&:hover': { bgcolor: PURCHASE_TEAL_HOVER }
          }}
        >
          Generar orden
        </Button>
      </DialogActions>
    </Dialog>
  )
}

export default GenerateOrderModal

