import {
  AddShoppingCart,
  Edit,
  MoreVert,
  NextPlanOutlined,
  RequestQuote,
  ThumbUpOutlined,
  Visibility
} from '@mui/icons-material'
import {
  Button,
  IconButton,
  ListItemIcon,
  ListItemText,
  Menu,
  MenuItem,
  Tooltip,
  Stack
} from '@mui/material'
import { useStore } from '@nanostores/react'
import useAxiosPrivate from '@utils/use-axios-private'
import { QueryClient, useMutation } from 'react-query'
import { Link } from 'react-router-dom'
import { PurchaseRequestStatus } from 'src/pages/Purchases/Enums'
import { userStore } from 'src/store/userStore'
import GenerateOrderModal from './GenerateOrderModal'

import { PurchaseRequest, PurchaseRequestItem } from 'src/pages/Purchases/Types'
import { useCan } from '@utils/functions'
import UploadQuotationModal from './UploadQuotationModal'
import { useState } from 'react'

import { PERMISSIONS } from 'src/constants/permissions'
import { notify } from 'src/utils/notify'
import { confirmDialog } from 'src/utils/confirm'
import { promptDialog } from 'src/utils/confirm'
type RenderRowActionsProps = {
  row: { original: PurchaseRequest }
  queryClient: QueryClient
  onEdit: () => void
}

const RenderRowActions = ({
  row,
  queryClient,
  onEdit
}: RenderRowActionsProps) => {
  const axiosPrivate = useAxiosPrivate()
  const $userStore = useStore(userStore)

  const status = row.original.status as PurchaseRequestStatus
  const allowActions = {
    creationOrder: useCan(PERMISSIONS.PURCHASES_ORDER_CREATE),
    // pre-aprobar, aprobar y rechazar
    approval: useCan(PERMISSIONS.PURCHASES_REQUEST_DECIDE)
  }

  const [orderModalOpen, setOrderModalOpen] = useState(false)
  const [uploadModalOpen, setUploadModalOpen] = useState(false)
  const [menuAnchor, setMenuAnchor] = useState<null | HTMLElement>(null)

  const handleOpenOrderModal = () => {
    setOrderModalOpen(true)
  }

  const handleManageQuotations = () => {
    setUploadModalOpen(true)
  }

  const mutation = useMutation(
    async ({
      id,
      action,
      payload
    }: {
      id: number
      action: string
      payload: any
    }) => {
      return await axiosPrivate.patch(
        `/purchaseRequests/${id}/${action}`,
        payload
      )
    },
    {
      onSuccess: () => {
        queryClient.invalidateQueries('purchaseRequests')
      }
    }
  )

  const handleAction = async (
    id: number,
    action: 'pre-approve' | 'approve' | 'reject'
  ) => {
    let message = ''
    let payload: any = { userId: $userStore.email }

    // Si la acción es "reject", solicitamos el motivo
    if (action === 'reject') {
      const { value: reason } = await promptDialog({
        title: 'Motivo de rechazo',
        label: 'Ingrese el motivo de rechazo',
        placeholder: 'Motivo de rechazo...',
        confirmLabel: 'Rechazar'
      })

      if (!reason) return
      payload = { ...payload, rejectionReason: reason }
      message = '¿Está seguro de que desea rechazar esta solicitud?'
    } else if (action === 'pre-approve') {
      message = '¿Está seguro de que desea preaprobar esta solicitud?'
    } else if (action === 'approve') {
      message = '¿Está seguro de que desea aprobar esta solicitud?'
    }

    const result = await confirmDialog({
      title: 'Confirmación',
      text: message,
      confirmLabel: 'Sí, continuar',
      cancelLabel: 'Cancelar',
      tone: 'danger'
    })

    if (result.isConfirmed) {
      try {
        await mutation.mutateAsync({ id, action, payload })
        notify.success('Éxito', 'La acción se realizó correctamente.')
      } catch (error) {
        notify.error('Error', 'No se pudo completar la acción.')
      }
    }
  }

  const isAllowed =
    row.original.approved &&
    row.original.preApproved &&
    row.original.quotations.some((quotation) => quotation.accepted)

  const items: PurchaseRequestItem[] = row.original.items || []

  const allProcessed = items.length > 0 && items.every((item) => item.procesed)
  const allUnprocessed =
    items.length > 0 && items.every((item) => !item.procesed)
  const mixedState = items.length > 0 && !allProcessed && !allUnprocessed

  const canApprove =
    allowActions.approval && status !== PurchaseRequestStatus.Rejected
  const canGenerate = allowActions.creationOrder

  // Por qué no se puede generar la orden (se muestra en el menú)
  const orderBlockedReason = !isAllowed
    ? 'Falta la cotización aceptada y la aprobación'
    : allProcessed
      ? 'Ya se generó la orden de todos los ítems'
      : ''

  // Acción principal: lo siguiente que toca hacer con esta solicitud
  let primary: {
    label: string
    icon: JSX.Element
    onClick: () => void
  } | null = null
  if (canApprove && status === PurchaseRequestStatus.Pending) {
    primary = {
      label: 'Preaprobar',
      icon: <NextPlanOutlined />,
      onClick: () => handleAction(row.original.id, 'pre-approve')
    }
  } else if (canApprove && status === PurchaseRequestStatus.PreApproved) {
    primary = {
      label: 'Aprobar',
      icon: <ThumbUpOutlined />,
      onClick: () => handleAction(row.original.id, 'approve')
    }
  } else if (canGenerate && !orderBlockedReason) {
    primary = {
      label: mixedState ? 'Completar orden' : 'Generar orden',
      icon: <AddShoppingCart />,
      onClick: handleOpenOrderModal
    }
  }

  const closeMenu = () => setMenuAnchor(null)

  return (
    <Stack direction='row' spacing={0.5} alignItems='center'>
      <Tooltip title='Ver'>
        <IconButton
          component={Link}
          to={`${row.original.id}`}
          size='small'
          aria-label={`Ver solicitud ${row.original.purchaseCode}`}
          sx={{ color: '#00695C' }}
        >
          <Visibility />
        </IconButton>
      </Tooltip>
      <Tooltip
        title={
          row.original.status === 'aprobado' && row.original.hasOrder
            ? 'Ya tiene orden, no se puede editar'
            : 'Editar solicitud'
        }
      >
        <span>
          <IconButton
            size='small'
            aria-label={`Editar solicitud ${row.original.purchaseCode}`}
            sx={{ color: '#2563eb' }}
            onClick={onEdit}
            disabled={
              row.original.status === 'aprobado' && row.original.hasOrder
            }
          >
            <Edit />
          </IconButton>
        </span>
      </Tooltip>
      {primary && (
        <Button
          size='small'
          variant='contained'
          startIcon={primary.icon}
          onClick={primary.onClick}
          sx={{
            bgcolor: '#00BFA5',
            whiteSpace: 'nowrap',
            '&:hover': { bgcolor: '#00ACC1' }
          }}
        >
          {primary.label}
        </Button>
      )}
      <Tooltip title='Más acciones'>
        <IconButton
          size='small'
          aria-label='Más acciones'
          onClick={(e) => setMenuAnchor(e.currentTarget)}
        >
          <MoreVert />
        </IconButton>
      </Tooltip>
      <Menu anchorEl={menuAnchor} open={!!menuAnchor} onClose={closeMenu}>
        <MenuItem
          onClick={() => {
            closeMenu()
            handleManageQuotations()
          }}
        >
          <ListItemIcon>
            <RequestQuote
              fontSize='small'
              color={row.original.quotations.length > 0 ? 'primary' : 'inherit'}
            />
          </ListItemIcon>
          <ListItemText
            primary='Gestionar cotizaciones'
            secondary={
              row.original.quotations.length > 0
                ? `${row.original.quotations.length} cargada(s)`
                : 'Sin cotizaciones'
            }
          />
        </MenuItem>
        {canGenerate && (
          <MenuItem
            disabled={!!orderBlockedReason}
            onClick={() => {
              closeMenu()
              handleOpenOrderModal()
            }}
          >
            <ListItemIcon>
              <AddShoppingCart fontSize='small' />
            </ListItemIcon>
            <ListItemText
              primary='Generar orden'
              secondary={orderBlockedReason || undefined}
            />
          </MenuItem>
        )}
      </Menu>

      <UploadQuotationModal
        open={uploadModalOpen}
        onClose={() => setUploadModalOpen(false)}
        purchaseRequest={row.original}
        onSuccess={() => queryClient.invalidateQueries('purchaseRequests')}
      />
      <GenerateOrderModal
        open={orderModalOpen}
        onClose={() => setOrderModalOpen(false)}
        purchaseRequest={row.original}
        onSuccess={() => queryClient.invalidateQueries('purchaseRequests')}
      />
    </Stack>
  )
}

export default RenderRowActions

// src/components/Purchases/SupplierEvaluationForm.tsx

import { getApiErrorReason } from 'src/utils/apiError'
import { useState, useEffect, FC, FormEvent, ChangeEvent } from 'react'
import {
  Box,
  Button,
  Grid,
  TextField,
  Typography,
  Paper,
  CircularProgress,
  Alert,
  MenuItem
} from '@mui/material'
import { Save, Cancel } from '@mui/icons-material'
import { useMutation, useQueryClient } from 'react-query'
import useAxiosPrivate from '@utils/use-axios-private' // Ajusta la ruta
import { isAxiosError } from 'axios' // Importar AxiosResponse
import { SelectChangeEvent } from '@mui/material/Select'
import { notify } from 'src/utils/notify'

import { logger } from 'src/utils/logger'
// Asumiendo que estos tipos están en 'src/pages/Purchases/Types'
// o en un archivo central de tipos.
interface ISupplier {
  id: number
  name: string
  taxId: string
  // Otros campos de ISupplier que puedas necesitar
}

export interface SupplierEvaluationData {
  id?: number // Opcional, solo presente si se edita una evaluación existente
  supplierId: number // Se asigna desde la prop 'supplier'
  evaluationDate: string // Formato YYYY-MM-DD
  qualityScore: number
  deliveryScore: number
  supportScore: number
  warrantyScore: number
  nonConformityScore: number
  invoiceScore: number
  comments?: string
  documentReference?: string
  preparedBy?: string
  approvedBy?: string
  totalScore?: number // Calculado en UI para feedback, y en backend para persistencia
  finalCondition?: string // Calculado en UI para feedback, y en backend para persistencia
  supplier?: Pick<ISupplier, 'id' | 'name' | 'taxId'> // Para mostrar info del proveedor si la data viene así
}

interface SupplierEvaluationFormProps {
  supplier: ISupplier // Información del proveedor que se está evaluando
  existingEvaluation?: SupplierEvaluationData | null // Para modo edición
  onSuccess: (evaluation: SupplierEvaluationData) => void // Callback tras éxito
  onCancel: () => void
}

// Límites y opciones para los puntajes de los criterios
const SCORE_MIN = 0
const SCORE_MAX = 15 // El puntaje máximo para "Excelente"

const scoreOptions = [
  // Es importante que el valor por defecto (0) tenga una opción visible si quieres que el Select muestre algo.
  { value: 0, label: 'No Calificado / No Aplica (0 pts)' },
  { value: 2, label: 'Regular (2 pts)' },
  { value: 10, label: 'Bueno (10 pts)' },
  { value: 15, label: 'Excelente (15 pts)' }
]

const evaluatorOptions = [
  { value: 'Jessica Cardona Garcia', label: 'Jessica Cardona Garcia' },
  { value: 'Daniel Alberto Paredes', label: 'Daniel Alberto Paredes' }
]

const approverOptions = [
  {
    value: 'Andres Felipe Bernal Meneses',
    label: 'Andres Felipe Bernal Meneses'
  }
]

// Función para calcular la condición final basada en el puntaje total
const calculateFinalCondition = (totalScore: number): string => {
  if (totalScore >= 76 && totalScore <= 90) return 'EXCELENTE'
  if (totalScore >= 56 && totalScore <= 75) return 'BUENO'
  if (totalScore >= 36 && totalScore <= 55) return 'APROBADO CON RESERVA'
  if (totalScore >= 0 && totalScore <= 35) return 'NO APROBADO'
  return 'INDETERMINADO' // Para puntajes fuera de rango o inicial
}

// Tipo para las claves de los campos de puntaje en formData
type ScoreFieldName =
  | 'qualityScore'
  | 'deliveryScore'
  | 'supportScore'
  | 'warrantyScore'
  | 'nonConformityScore'
  | 'invoiceScore'

// Tipo para la parte del estado formData que maneja este formulario
type EvaluationFormData = Omit<
  SupplierEvaluationData,
  'id' | 'supplierId' | 'totalScore' | 'finalCondition' | 'supplier'
>

const SupplierEvaluationForm: FC<SupplierEvaluationFormProps> = ({
  supplier,
  existingEvaluation,
  onSuccess,
  onCancel
}) => {
  const axiosPrivate = useAxiosPrivate()
  const queryClient = useQueryClient()

  const initialFormData: EvaluationFormData = {
    evaluationDate: new Date().toISOString().split('T')[0],
    qualityScore: 0, // Default a 0 para 'No Calificado'
    deliveryScore: 0,
    supportScore: 0,
    warrantyScore: 0,
    nonConformityScore: 0,
    invoiceScore: 0,
    comments: '',
    documentReference: 'FOGC-MMCS-15 V03', // Default del formato
    preparedBy: 'Jessica Cardona Garcia',
    approvedBy: 'Andres Felipe Bernal Meneses'
  }

  const [formData, setFormData] = useState<EvaluationFormData>(initialFormData)
  const [calculatedTotal, setCalculatedTotal] = useState<number>(0)
  const [calculatedCondition, setCalculatedCondition] = useState<string>('')
  const [errors, setErrors] = useState<Record<string, string>>({})

  useEffect(() => {
    if (existingEvaluation) {
      setFormData({
        evaluationDate:
          existingEvaluation.evaluationDate ||
          new Date().toISOString().split('T')[0],
        qualityScore: existingEvaluation.qualityScore ?? 0,
        deliveryScore: existingEvaluation.deliveryScore ?? 0,
        supportScore: existingEvaluation.supportScore ?? 0,
        warrantyScore: existingEvaluation.warrantyScore ?? 0,
        nonConformityScore: existingEvaluation.nonConformityScore ?? 0,
        invoiceScore: existingEvaluation.invoiceScore ?? 0,
        comments: existingEvaluation.comments || '',
        documentReference:
          existingEvaluation.documentReference || 'FOGC-MMCS-15 V03',
        preparedBy: existingEvaluation.preparedBy || 'Jessica Cardona Garcia',
        approvedBy:
          existingEvaluation.approvedBy || 'Andres Felipe Bernal Meneses'
      })
    } else {
      // Resetear a valores por defecto si no hay existingEvaluation (ej. al cambiar de editar a crear, o al abrir para crear)
      setFormData(initialFormData)
    }
  }, [existingEvaluation]) // Dependencia clave

  useEffect(() => {
    const scores: number[] = [
      Number(formData.qualityScore),
      Number(formData.deliveryScore),
      Number(formData.supportScore),
      Number(formData.warrantyScore),
      Number(formData.nonConformityScore),
      Number(formData.invoiceScore)
    ]
    const total = scores.reduce((sum, score) => sum + (score || 0), 0)
    setCalculatedTotal(total)
    setCalculatedCondition(calculateFinalCondition(total))
  }, [formData])

  const handleChange = (
    event:
      | ChangeEvent<HTMLInputElement | HTMLTextAreaElement>
      | SelectChangeEvent<number> // Acepta ambos tipos de evento
  ) => {
    const { name, value } = event.target
    let processedValue: string | number = value

    // Para los campos de puntaje, el valor del Select ya es el número (o un string que representa el número)
    if (name.endsWith('Score')) {
      processedValue = Number(value) // Convertir a número. Si es "" del Select, será 0.
      if (isNaN(processedValue)) processedValue = 0 // Fallback si no es un número
      // El clamping no es estrictamente necesario si las opciones del Select son la única fuente,
      // pero lo mantenemos por si acaso.
      processedValue = Math.max(SCORE_MIN, Math.min(SCORE_MAX, processedValue))
    }

    setFormData((prev) => ({ ...prev, [name]: processedValue }))
    if (errors[name]) {
      setErrors((prev) => ({ ...prev, [name]: '' }))
    }
  }

  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {}
    if (!formData.evaluationDate) {
      newErrors.evaluationDate = 'La fecha es requerida.'
    }

    const scoreFields: ScoreFieldName[] = [
      'qualityScore',
      'deliveryScore',
      'supportScore',
      'warrantyScore',
      'nonConformityScore',
      'invoiceScore'
    ]

    scoreFields.forEach((field) => {
      const value = formData[field] // Ya es un número en formData
      if (
        typeof value !== 'number' ||
        !scoreOptions.some((opt) => opt.value === value)
      ) {
        newErrors[field] = `Seleccione una calificación válida.`
      }
    })
    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const mutationFn = async (dataToSubmitForBackend: EvaluationFormData) => {
    // El backend espera supplierId y los scores numéricos.
    // totalScore y finalCondition se calculan en backend por el hook del modelo.
    const payload: Omit<
      SupplierEvaluationData,
      'id' | 'totalScore' | 'finalCondition' | 'supplier'
    > = {
      ...dataToSubmitForBackend,
      supplierId: supplier.id
    }

    if (existingEvaluation?.id) {
      const { data } = await axiosPrivate.put<SupplierEvaluationData>(
        `/supplier-evaluations/${existingEvaluation.id}`,
        payload
      )
      return data
    } else {
      const { data } = await axiosPrivate.post<SupplierEvaluationData>(
        `/supplier-evaluations/${supplier.id}`,
        payload
      )
      return data
    }
  }

  const {
    mutate,
    isLoading,
    error: mutationError
  } = useMutation<SupplierEvaluationData, Error, EvaluationFormData>(
    mutationFn,
    {
      onSuccess: (responseData) => {
        // responseData es SupplierEvaluationData devuelta por el backend
        notify.success(
          'Éxito',
          `Evaluación ${existingEvaluation ? 'actualizada' : 'guardada'} correctamente.`
        )
        queryClient.invalidateQueries([
          'supplierEvaluations',
          supplier.id.toString()
        ])
        queryClient.invalidateQueries('allSupplierEvaluations') // Si tienes una lista global de evaluaciones
        onSuccess(responseData) // Pasar la data completa recibida del backend
      },
      onError: (err) => {
        logger.error('Error guardando evaluación:', err)
        let message = `Error al ${existingEvaluation ? 'actualizar' : 'guardar'} la evaluación.`
        if (isAxiosError(err) && getApiErrorReason(err)) {
          message = getApiErrorReason(err) ?? message
        } else if (err instanceof Error) {
          message = err.message
        }
        notify.error('Error', message)
      }
    }
  )

  const handleSubmit = (event: FormEvent) => {
    event.preventDefault()
    if (!validateForm()) {
      notify.warning(
        'Atención',
        'Por favor corrige los errores en el formulario.'
      )
      return
    }
    mutate(formData) // formData ya tiene la estructura correcta Omit<...>
  }

  // Definición de criterios para el renderizado del formulario
  const criteria: { label: string; name: ScoreFieldName }[] = [
    { label: 'Calidad de los productos y / o servicios', name: 'qualityScore' },
    { label: 'Cumplimiento en la entrega', name: 'deliveryScore' },
    { label: 'Soporte Técnico o asesoramiento', name: 'supportScore' },
    { label: 'Garantía Ofrecida', name: 'warrantyScore' },
    { label: 'No conformidades presentadas', name: 'nonConformityScore' },
    { label: 'Entrega de Facturas', name: 'invoiceScore' }
  ]

  return (
    // Si este Paper está dentro de un DialogContent con dividers, la elevación puede ser 0 o baja.
    <Paper elevation={0} sx={{ p: { xs: 0, sm: 1, md: 2 } }}>
      <Typography variant='h6' gutterBottom component='div'>
        {' '}
        {/* Cambiado a h6 si está en un Dialog */}
        Evaluación para Proveedor: <strong>{supplier.name}</strong> (NIT:{' '}
        {supplier.taxId})
      </Typography>
      <Typography
        variant='body2'
        color='text.secondary'
        gutterBottom
        sx={{ mb: 2 }}
      >
        Referencia Documento: {formData.documentReference}
      </Typography>
      <Box component='form' onSubmit={handleSubmit} noValidate>
        <Grid container spacing={2}>
          <Grid item xs={12} sm={6} md={4}>
            <TextField
              label='Fecha de Evaluación'
              name='evaluationDate'
              type='date'
              value={formData.evaluationDate}
              onChange={handleChange}
              error={!!errors.evaluationDate}
              helperText={errors.evaluationDate}
              InputLabelProps={{ shrink: true }}
              fullWidth
              required
            />
          </Grid>

          {/* --- Renderizado de Criterios con Select --- */}
          {criteria.map((criterion) => (
            <Grid item xs={12} sm={6} md={4} key={criterion.name}>
              <TextField
                select
                fullWidth
                required
                label={criterion.label}
                name={criterion.name}
                value={formData[criterion.name]} // El valor es un número (0, 2, 10, 15)
                onChange={handleChange as any} // Cast a 'any' para simplificar el tipo de evento del Select
                error={!!errors[criterion.name]}
                helperText={errors[criterion.name]}
                // SelectProps={{ displayEmpty: true }} // Si quieres un placeholder visible
              >
                {/* <MenuItem value="" disabled><em>-- Calificar --</em></MenuItem> */}
                {scoreOptions.map((option) => (
                  <MenuItem key={option.value} value={option.value}>
                    {option.label}
                  </MenuItem>
                ))}
              </TextField>
            </Grid>
          ))}

          <Grid item xs={12} sx={{ mt: 1 }}>
            {' '}
            {/* Añadido margen superior */}
            <TextField
              label='Comentarios Adicionales'
              name='comments'
              multiline
              rows={3}
              value={formData.comments}
              onChange={handleChange}
              fullWidth
            />
          </Grid>

          <Grid item xs={12} sm={6} md={4}>
            <TextField
              select
              label='Evaluado por (Elaboró)'
              name='preparedBy'
              value={formData.preparedBy}
              onChange={handleChange as any}
              fullWidth
              required
            >
              {evaluatorOptions.map((option) => (
                <MenuItem key={option.value} value={option.value}>
                  {option.label}
                </MenuItem>
              ))}
            </TextField>
          </Grid>

          <Grid item xs={12} sm={6} md={4}>
            <TextField
              select
              label='Aprobado por'
              name='approvedBy'
              value={formData.approvedBy}
              onChange={handleChange as any}
              fullWidth
              required
            >
              {approverOptions.map((option) => (
                <MenuItem key={option.value} value={option.value}>
                  {option.label}
                </MenuItem>
              ))}
            </TextField>
          </Grid>

          <Grid item xs={12} sx={{ mt: 1 }}>
            <Box
              display='flex'
              flexDirection={{ xs: 'column', md: 'row' }}
              gap={4}
              alignItems='center'
            >
              <Box>
                <Typography variant='body1' component='div' fontWeight='medium'>
                  Puntaje Total Obtenido:
                </Typography>
                <Typography variant='h5' color='primary.main' fontWeight='bold'>
                  {calculatedTotal} / 90
                </Typography>
              </Box>

              <Box>
                <Typography variant='body1' component='div' fontWeight='medium'>
                  Condición Final:
                </Typography>
                <Typography
                  variant='h5'
                  fontWeight='bold' // @ts-ignore
                  color={
                    calculatedCondition === 'NO APROBADO' ||
                    calculatedCondition === 'INDETERMINADO'
                      ? 'error.main'
                      : calculatedCondition === 'EXCELENTE' ||
                          calculatedCondition === 'BUENO'
                        ? 'success.main'
                        : 'warning.main'
                  }
                >
                  {calculatedCondition}
                </Typography>
              </Box>
            </Box>
          </Grid>

          {mutationError && (
            <Grid item xs={12} sx={{ mt: 1 }}>
              <Alert severity='error'>
                Error al guardar: {(mutationError as Error).message}
              </Alert>
            </Grid>
          )}

          <Grid
            item
            xs={12}
            sx={{ mt: 2, display: 'flex', justifyContent: 'flex-end', gap: 2 }}
          >
            <Button
              onClick={onCancel}
              startIcon={<Cancel />}
              color='inherit'
              disabled={isLoading}
            >
              Cancelar
            </Button>
            <Button
              type='submit'
              variant='contained'
              startIcon={
                isLoading ? (
                  <CircularProgress size={20} color='inherit' />
                ) : (
                  <Save />
                )
              }
              disabled={isLoading}
            >
              {isLoading
                ? existingEvaluation
                  ? 'Actualizando...'
                  : 'Guardando...'
                : existingEvaluation
                  ? 'Actualizar Evaluación'
                  : 'Guardar Evaluación'}
            </Button>
          </Grid>
        </Grid>
      </Box>
    </Paper>
  )
}

export default SupplierEvaluationForm

// src/components/Purchases/SupplierPurchaseHistoryTable.tsx
import { getApiErrorReason } from 'src/utils/apiError'
import SignalLoader from 'src/Components/Common/SignalLoader'
import React, { useMemo } from 'react'
import {
  Box,
  Typography,
  Alert,
  Chip,
  Link
} from '@mui/material'
import {
  type MRT_Cell,
  type MRT_ColumnDef,
  type MRT_Row
} from 'material-react-table'
import { useQuery } from 'react-query'
import useAxiosPrivate from '@utils/use-axios-private' // Ajusta la ruta
import DataTable from 'src/Components/Common/DataTable'
import { useNavigate } from 'react-router-dom'
import { CheckCircleOutline, HighlightOff } from '@mui/icons-material' // Icono para ver detalle de orden

// Importar el tipo desde tu archivo central de tipos
import { PurchaseHistoryEntry } from 'src/pages/Purchases/Types' // Ajusta la ruta
import { isAxiosError } from 'axios'
import { notify } from 'src/utils/notify'
import { busyDialog } from 'src/utils/confirm'

import { logger } from 'src/utils/logger'
import { headerText } from 'src/utils/responseHeaders'
interface SupplierPurchaseHistoryTableProps {
  supplierId: string | number
}

const SupplierPurchaseHistoryTable: React.FC<
  SupplierPurchaseHistoryTableProps
> = ({ supplierId }) => {
  const axiosPrivate = useAxiosPrivate()
  const navigate = useNavigate()

  const {
    data: purchaseHistory = [], // Valor por defecto es un array vacío
    isLoading,
    isError,
    error,
    isFetching // Para la barra de progreso en refetches
  } = useQuery<PurchaseHistoryEntry[], Error>(
    ['supplierPurchaseHistory', supplierId], // Query key incluye supplierId
    async () => {
      const response = await axiosPrivate.get<PurchaseHistoryEntry[]>(
        `/purchaseOrders/${supplierId}/purchase-history`
      )
      return response.data
    },
    {
      enabled: !!supplierId // Solo ejecutar si supplierId está presente
    }
  )

  const handleViewOrderReportPDF = async (
    purchaseOrderId: number | string,
    orderCode: string
  ) => {
    try {
      busyDialog.show(
        'Generando Reporte...',
        `Por favor espera mientras se genera el PDF para la orden ${orderCode}.`
      )

      // El endpoint que mencionaste, ajusta la ruta base si es necesario (ej. si api() da /api)
      const reportUrl = `/reports/fog-mmcs-13/${purchaseOrderId}`

      const response = await axiosPrivate.get(reportUrl, {
        responseType: 'blob' // Importante para manejar la respuesta como archivo
      })

      busyDialog.hide()

      const effectiveMimeType =
        headerText(response.headers, 'content-type') || 'application/pdf'
      const blob = new Blob([response.data], { type: effectiveMimeType })
      const fileURL = URL.createObjectURL(blob)

      const newWindow = window.open(fileURL, '_blank')
      if (newWindow) {
        newWindow.focus()
        setTimeout(() => {
          // Dar tiempo a que la pestaña cargue antes de intentar cambiar el título
          try {
            newWindow.document.title = `Orden ${orderCode} - FOGC-MMCS-13`
          } catch (e) {
            logger.warn('No se pudo cambiar el título de la pestaña.')
          }
        }, 500)
      } else {
        notify.warning(
          'Error de Navegador',
          'Tu navegador bloqueó la apertura de una nueva pestaña. Por favor, permite pop-ups para este sitio.'
        )
      }
    } catch (err) {
      busyDialog.hide()
      logger.error(
        `Error obteniendo el reporte PDF para la orden ID ${purchaseOrderId}:`,
        err
      )
      let errorMessage =
        'No se pudo generar o mostrar el reporte PDF de la orden de compra.'
      if (isAxiosError(err)) {
        if (err.response?.status === 404) {
          errorMessage =
            'Reporte o datos para la orden de compra no encontrados.'
        } else if (getApiErrorReason(err)) {
          errorMessage = getApiErrorReason(err) ?? errorMessage
        } else if (err.message) {
          errorMessage = err.message
        }
      } else if (err instanceof Error) {
        errorMessage = err.message
      }
      notify.error('Error', errorMessage)
    }
  }

  const columns = useMemo<MRT_ColumnDef<PurchaseHistoryEntry>[]>(
    () => [
      {
        accessorKey: 'code',
        header: 'Orden',
        size: 160,
        Cell: ({
          cell,
          row
        }: {
          cell: MRT_Cell<PurchaseHistoryEntry>
          row: MRT_Row<PurchaseHistoryEntry>
        }) => (
          <Link
            component='button'
            type='button'
            variant='body2'
            underline='hover'
            aria-label={`Abrir el PDF de la orden ${row.original.code}`}
            onClick={() =>
              handleViewOrderReportPDF(row.original.id, row.original.code)
            }
            sx={{ color: '#00695C', fontWeight: 600, textAlign: 'left' }}
          >
            {cell.getValue<string>()}
          </Link>
        )
      },
      {
        accessorKey: 'requestDate', // Asegúrate que este sea el nombre del campo
        header: 'Fecha de la orden',
        size: 150,
        Cell: ({ cell }: { cell: MRT_Cell<PurchaseHistoryEntry> }) => {
          const dateValue = cell.getValue<string>()
          if (!dateValue) return <span />
          return (
            <span style={{ whiteSpace: 'nowrap' }}>
              {new Date(dateValue).toLocaleDateString('es-CO', {
                year: 'numeric',
                month: 'short',
                day: 'numeric',
                // Interpreta la fecha como UTC para mostrar el día correcto
                timeZone: 'UTC'
              })}
            </span>
          )
        }
      },
      {
        accessorKey: 'total', // O el nombre de campo de total que uses
        header: 'Total',
        size: 150,
        Cell: ({ cell }: { cell: MRT_Cell<PurchaseHistoryEntry> }) => (
          <span>
            {new Intl.NumberFormat('es-CO', {
              style: 'currency',
              currency: 'COP',
              minimumFractionDigits: 0,
              maximumFractionDigits: 0
            }).format(cell.getValue<number>())}
          </span>
        ),
        muiTableBodyCellProps: { align: 'right' },
        muiTableHeadCellProps: { align: 'right' }
      },
      {
        // --- COLUMNA MODIFICADA ---
        accessorKey: 'verified', // Cambiado de 'status'
        header: 'Verificado', // Nuevo encabezado
        size: 100,
        Cell: ({ cell }: { cell: MRT_Cell<PurchaseHistoryEntry> }) => {
          const isVerified = cell.getValue<boolean>()
          return isVerified ? (
            <Chip
              icon={<CheckCircleOutline />}
              label='Sí'
              color='success'
              size='small'
              variant='outlined'
            />
          ) : (
            <Chip
              icon={<HighlightOff />}
              label='No'
              color='default'
              size='small'
              variant='outlined'
            />
          )
          // Alternativa simple con texto:
          // return isVerified ? <Typography color="success.main">Sí</Typography> : <Typography color="text.secondary">No</Typography>;
        }
      }
    ],
    [navigate]
  )

  if (isLoading && !purchaseHistory.length) {
    // Mostrar solo si es la carga inicial y no hay datos cacheados
    return (
      <Box
        sx={{
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          my: 3,
          p: 2
        }}
      >
        <SignalLoader size='small' message='Cargando historial de compras...' />
      </Box>
    )
  }

  // No mostrar error si hay datos cacheados y solo está refetching en background
  if (isError && !purchaseHistory.length) {
    return (
      <Alert severity='error' sx={{ my: 2 }}>
        Error al cargar el historial de compras: {error?.message}
      </Alert>
    )
  }

  return (
    <Box sx={{ mt: 3 }}>
      <Typography variant='h6' fontWeight={700} sx={{ mb: 1.5 }}>
        Historial de compras
      </Typography>
      {!isLoading && purchaseHistory.length === 0 && !isError && (
        <Typography sx={{ color: 'text.secondary' }}>
          No se encontraron compras para este proveedor.
        </Typography>
      )}
      {purchaseHistory.length > 0 && (
        <DataTable
          columns={columns}
          data={purchaseHistory}
          itemLabel={['compra', 'compras']}
          searchPlaceholder='Buscar compras'
          enableColumnFilters
          enablePagination
          enableSorting
          enableHiding={false}
          muiTableContainerProps={{ sx: { maxHeight: '400px' } }} // Ajusta la altura máxima
          muiToolbarAlertBannerProps={
            isError && isFetching
              ? {
                  // Mostrar solo si hay error Y está intentando recargar
                  color: 'error',
                  children: `Error actualizando historial: ${error?.message}`
                }
              : undefined
          }
          initialState={{
            density: 'compact',
            pagination: { pageSize: 5, pageIndex: 0 },
            sorting: [{ id: 'requestDate', desc: true }] // Ordenar por fecha más reciente
            // showGlobalFilter: true, // Habilitar si quieres búsqueda global
          }}
          state={{
            showProgressBars: isFetching // Barra de progreso para recargas
          }}
        />
      )}
    </Box>
  )
}

export default SupplierPurchaseHistoryTable

// components/SupplierSelectionModal.tsx
import { getApiErrorReason } from 'src/utils/apiError'
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  CircularProgress,
  Box,
  Paper,
  Typography,
  Divider,
  FormGroup,
  Grid,
  TextField,
  MenuItem,
  InputLabel,
  FormControl,
  Alert,
  Select,
  RadioGroup,
  FormControlLabel,
  Radio,
  Checkbox,
  IconButton
} from '@mui/material'

import { ChangeEvent, useEffect, useState } from 'react'
import { useSaveSupplierSelection } from 'src/hooks/purchases/useSuppliers'
import {
  FormState,
  Criterion,
  SelectionSupplier
} from 'src/pages/Purchases/Types'
import { isAxiosError } from 'axios'
import { Close } from '@mui/icons-material'
import { notify } from 'src/utils/notify'

import { logger } from 'src/utils/logger'
interface SupplierSelectionModalProps {
  open: boolean
  onClose: () => void
  onSuccess: () => void
  criteria: Criterion[]
  categories: string[]
  existingSelectionData?: SelectionSupplier | null
}

const initialSupplierData = {
  name: '',
  taxId: '',
  phone: '',
  mobile: '',
  email: '',
  address: '',
  city: '',
  accountType: '',
  accountNumber: '',
  bankName: '',
  product: '',
  purchaseType: 1,
  contactName: '',
  position: ''
}

const initialFormState: FormState = {
  supplierData: initialSupplierData,
  providerType: '', // 'Juridical' o 'Natural'
  selections: {},
  scores: {},
  totalScore: 0,
  whichAnswers: {}
}

const SupplierSelectionModal = ({
  open,
  onClose,
  onSuccess,
  criteria,
  categories,
  existingSelectionData
}: SupplierSelectionModalProps) => {
  const saveSelection = useSaveSupplierSelection()
  const isSubmitting = saveSelection.isLoading
  const [formState, setFormState] = useState<FormState>(initialFormState)
  const [error, setError] = useState<string>('')

  useEffect(() => {
    if (open) {
      if (existingSelectionData && existingSelectionData.supplier) {
        // --- MODO EDICIÓN ---
        const newSelections: Record<string, number[]> = {}
        const newScores: Record<string, number> = {}
        const newWhichAnswers: Record<string, string> = {}
        let newTotalScore = 0

        // Reconstruir selections, scores, y whichAnswers a partir de existingSelectionData.details
        // Asumiendo que existingSelectionData.details es Array<SelectionSupplierDetail>
        ;(existingSelectionData.details || []).forEach((detail: any) => {
          const criterion = criteria.find(
            (c) => c.id === detail.selectionSupplierSubItemId
          )
          if (criterion) {
            if (!newSelections[criterion.category]) {
              newSelections[criterion.category] = []
            }
            newSelections[criterion.category].push(criterion.id)

            if (detail.which) {
              newWhichAnswers[criterion.id] = detail.which
            }
            // Sumar al score de la categoría y al total
            newScores[criterion.category] =
              (newScores[criterion.category] || 0) + (criterion.baseScore || 0)
            newTotalScore += criterion.baseScore || 0
          }
        })

        setFormState({
          supplierData: {
            // Asegurar que todos los campos de initialSupplierData estén presentes
            name: existingSelectionData.supplier.name || '',
            taxId: existingSelectionData.supplier.taxId || '',
            phone: existingSelectionData.supplier.phone || '',
            mobile: existingSelectionData.supplier.mobile || '',
            email: existingSelectionData.supplier.email || '',
            address: existingSelectionData.supplier.address || '',
            city: existingSelectionData.supplier.city || '',
            accountType: existingSelectionData.supplier.accountType || '',
            accountNumber: existingSelectionData.supplier.accountNumber || '',
            bankName: existingSelectionData.supplier.bankName || '',
            product: existingSelectionData.product || '', // 'product' viene de SelectionSupplier
            purchaseType: existingSelectionData.supplier.purchaseType || 1,
            contactName: existingSelectionData.supplier.contactName || '',
            position: existingSelectionData.supplier.position || ''
          },
          providerType:
            existingSelectionData.supplier.typePerson === 1
              ? 'Natural'
              : 'Juridical',
          selections: newSelections,
          scores: newScores,
          totalScore: newTotalScore,
          whichAnswers: newWhichAnswers
        })
      } else {
        // --- MODO CREACIÓN ---
        setFormState(initialFormState)
      }
      setError('') // Limpiar errores al abrir/cambiar modo
    }
  }, [open, existingSelectionData, criteria])

  const groupedCriteria = criteria.reduce(
    (acc, criterion) => {
      const key = criterion.category
      if (!acc[key]) acc[key] = []
      acc[key].push(criterion)
      return acc
    },
    {} as Record<string, Criterion[]>
  )

  const handleSupplierInputChange = (
    e: ChangeEvent<HTMLInputElement | { name?: string; value: unknown }>
  ) => {
    // Ajustar tipo para Select
    const target = e.target as HTMLInputElement // Asumir HTMLInputElement para simplicidad o castear select
    setFormState((prev) => ({
      ...prev,
      supplierData: { ...prev.supplierData, [target.name]: target.value }
    }))
  }

  const handleSelectionChange = (
    category: string,
    criterion: Criterion,
    isChecked: boolean
  ) => {
    setError('')
    const newSelections = { ...formState.selections }
    const newWhichAnswers = { ...formState.whichAnswers }

    // // Manejar campo which
    // if (category === 'CALIDAD' && criterion.requiresWhich) {
    //   setFormState((prev) => ({ ...prev, showWhich: isChecked }))
    //   if (!isChecked) setFormState((prev) => ({ ...prev, which: undefined }))
    // }

    const isSingleSelect = [
      'PRECIO',
      'TIEMPO DE ENTREGA',
      'GARANTIA',
      'EXPERIENCIA',
      'RÉGIMEN TRIBUTARIO',
      'CONDICIONES DE PAGO'
    ].includes(category)

    if (isSingleSelect) {
      // Radio Button: Reemplazar selección anterior
      newSelections[category] = isChecked ? [criterion.id] : []
    } else {
      // Checkbox: Manejar múltiples selecciones
      newSelections[category] = newSelections[category] || []
      if (isChecked) {
        if (!newSelections[category].includes(criterion.id)) {
          newSelections[category].push(criterion.id)
        }
      } else {
        newSelections[category] = newSelections[category].filter(
          (id) => id !== criterion.id
        )
      }
    }

    if (criterion.requiresWhich && !isChecked) {
      newWhichAnswers[criterion.id] = ''
    }

    // Calcular puntuación
    const newScores: Record<string, number> = {}
    let total = 0

    Object.entries(newSelections).forEach(([cat, ids]) => {
      const categoryScore = ids.reduce((sum, id) => {
        const c = criteria.find((c) => c.id === id)
        return sum + (c?.baseScore || 0)
      }, 0)
      newScores[cat] = categoryScore
      total += categoryScore
    })

    setFormState((prev) => ({
      ...prev,
      selections: newSelections,
      scores: newScores,
      totalScore: total,
      whichAnswers: newWhichAnswers
    }))
  }

  const handleWhichChange = (criterionId: number, value: string) => {
    setFormState((prev) => ({
      ...prev,
      whichAnswers: {
        ...prev.whichAnswers,
        [criterionId]: value
      }
    }))
  }

  const validateForm = () => {
    const { supplierData, providerType, selections, whichAnswers } = formState
    const requiredFields = [
      supplierData.name,
      supplierData.taxId,
      supplierData.email,
      supplierData.address,
      providerType
    ]

    if (requiredFields.some((field) => !field)) {
      setError('Todos los campos básicos del proveedor son requeridos')
      return false
    }

    // Verificar que si un criterio de CALIDAD requiereWhich fue seleccionado,
    // entonces su "cual" no esté vacío.
    // (Si quisieras hacerlo global, no solo en CALIDAD, puedes quitar el `if (c.category === 'CALIDAD')`)
    for (const c of criteria) {
      if (c.category === 'CALIDAD' && c.requiresWhich) {
        // Si este criterio está seleccionado
        const isSelected = (selections[c.category] || []).includes(c.id)
        if (isSelected) {
          // Debe haber un "whichAnswers[c.id]"
          if (!whichAnswers[c.id] || whichAnswers[c.id].trim() === '') {
            setError(`Debe especificar el "Cuál" para: ${c.name}`)
            return false
          }
        }
      }
    }

    return true
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!validateForm()) return

    // Preparamos los detalles de evaluación a partir de las selecciones
    const details = Object.values(formState.selections)
      .flat()
      .map((id) => {
        const foundCriterion = criteria.find((c) => c.id === id)
        return {
          selectionSupplierSubItemId: id,
          answer: true,
          which: formState.whichAnswers[id] || null,
          actualScore: foundCriterion?.baseScore || 0
        }
      })

    /* 
        Armamos el payload:
        - Si el puntaje es >= 61, se envían los datos del proveedor (para que se cree).
        - Si no se cumple, se envía supplierData como null y se crea solo la evaluación.
        - evaluationData incluye la fecha y la decisión final según el puntaje.
        - details es el arreglo de detalles de evaluación.
      */
    const { product, ...supplierDataWithoutProduct } = formState.supplierData

    const payload = {
      supplierData: {
        ...supplierDataWithoutProduct,
        typePerson: formState.providerType === 'Natural' ? 1 : 0
      },

      evaluationData: {
        // Si se crea el proveedor, el backend usará el ID del proveedor recién creado.
        // Si no se crea, puedes enviar null o forzarlo a null.
        supplierId: formState.totalScore < 61 ? null : undefined,
        selectionSupplierDate: new Date().toISOString(),
        product,
        finalDecision:
          formState.totalScore >= 81
            ? 'APPROVED'
            : formState.totalScore >= 61
              ? 'APPROVED WITH RESERVE'
              : 'NOT APPROVED',
        id: existingSelectionData?.id
      },
      details
    }
    try {
      const isEdit = Boolean(existingSelectionData?.id)
      // Edición: PUT /suppliers/selection-suppliers/:supplierId
      // Creación: POST /suppliers (una transacción en el backend)
      await saveSelection.mutateAsync({
        isEdit,
        supplierId: existingSelectionData?.supplierId,
        payload
      })
      if (isEdit) {
        notify.success('Selección de proveedor actualizada')
      } else {
        const finalDecision = payload.evaluationData.finalDecision
        if (
        finalDecision === 'APPROVED' ||
        finalDecision === 'APPROVED WITH RESERVE'
      ) {
        notify.success('Proveedor aprobado')
      } else {
        notify.error('Proveedor no aprobado')
      }
      }
      setFormState(initialFormState)
      onSuccess()
      onClose()
    } catch (error) {
      logger.log(error)
      let message = 'Error guardando la información.'
      if (isAxiosError(error) && getApiErrorReason(error)) {
        message = getApiErrorReason(error) ?? message
      }
      setError(message)
    }
  }

  const handleClose = () => {
    // Resetear el estado al cerrar
    setFormState({
      supplierData: initialSupplierData,
      providerType: '',
      selections: {},
      scores: {},
      totalScore: 0,
      whichAnswers: {}
    })
    onClose()
  }

  return (
    <Dialog
      open={open}
      onClose={handleClose}
      maxWidth='lg'
      fullWidth
      scroll='paper'
    >
      <DialogTitle
        sx={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center'
        }}
      >
        {existingSelectionData
          ? 'Editar Selección/Evaluación de Proveedor'
          : 'Evaluar Nuevo Proveedor'}
        <IconButton aria-label='close' onClick={handleClose}>
          <Close />
        </IconButton>
      </DialogTitle>
      <DialogContent dividers>
        <Box component='form' onSubmit={handleSubmit} sx={{ p: 3 }}>
          <Paper elevation={3} sx={{ p: 3, mb: 3 }}>
            {error && (
              <Alert severity='error' sx={{ mb: 3 }}>
                {error}
              </Alert>
            )}

            {/* 1) Selector de tipo de proveedor */}
            <FormControl fullWidth sx={{ mb: 3 }}>
              <InputLabel>Tipo de Proveedor *</InputLabel>
              <Select
                value={formState.providerType}
                onChange={(e) =>
                  setFormState((prev) => ({
                    ...prev,
                    providerType: e.target.value as any,
                    selections: {},
                    scores: {},
                    totalScore: 0
                  }))
                }
                required
              >
                <MenuItem value='Juridical'>Jurídico</MenuItem>
                <MenuItem value='Natural'>Natural</MenuItem>
              </Select>
            </FormControl>

            {/* 2) Renderiza los campos SOLO si hay un tipo seleccionado */}
            {formState.providerType && (
              <>
                {/* Sección de datos del proveedor */}
                <Paper sx={{ p: 2, mb: 3 }}>
                  <Typography variant='h6' gutterBottom>
                    Información Básica
                  </Typography>

                  <Grid container spacing={2}>
                    {formState.providerType === 'Juridical' && (
                      <>
                        {/* Ejemplo de campos para Jurídico */}
                        <Grid item xs={12} md={6}>
                          <TextField
                            fullWidth
                            label='Razón Social'
                            name='name'
                            value={formState.supplierData.name}
                            onChange={handleSupplierInputChange}
                            required
                          />
                        </Grid>
                        <Grid item xs={12} md={6}>
                          <TextField
                            fullWidth
                            label='NIT'
                            name='taxId'
                            value={formState.supplierData.taxId}
                            onChange={handleSupplierInputChange}
                            required
                          />
                        </Grid>
                        <Grid item xs={12} md={6}>
                          <TextField
                            fullWidth
                            label='Celular'
                            name='mobile'
                            value={formState.supplierData.mobile || ''}
                            onChange={handleSupplierInputChange}
                          />
                        </Grid>
                        <Grid item xs={12} md={6}>
                          <TextField
                            fullWidth
                            label='Contacto'
                            name='contactName'
                            value={formState.supplierData.contactName || ''}
                            onChange={handleSupplierInputChange}
                          />
                        </Grid>
                        <Grid item xs={12} md={6}>
                          <TextField
                            fullWidth
                            label='Cargo'
                            name='position'
                            value={formState.supplierData.position || ''}
                            onChange={handleSupplierInputChange}
                          />
                        </Grid>
                        <Grid item xs={12} md={6}>
                          <TextField
                            fullWidth
                            label='Dirección'
                            name='address'
                            value={formState.supplierData.address}
                            onChange={handleSupplierInputChange}
                            required
                          />
                        </Grid>
                        <Grid item xs={12} md={6}>
                          <TextField
                            fullWidth
                            label='Ciudad'
                            name='city'
                            value={formState.supplierData.city}
                            onChange={handleSupplierInputChange}
                            required
                          />
                        </Grid>
                        <Grid item xs={12} md={6}>
                          <TextField
                            fullWidth
                            label='Teléfono'
                            name='phone'
                            value={formState.supplierData.phone}
                            onChange={handleSupplierInputChange}
                          />
                        </Grid>
                        <Grid item xs={12} md={6}>
                          <TextField
                            fullWidth
                            label='Email'
                            name='email'
                            value={formState.supplierData.email}
                            onChange={handleSupplierInputChange}
                            required
                          />
                        </Grid>
                        <Grid item xs={12} md={6}>
                          <TextField
                            fullWidth
                            label='Compra Tipo'
                            name='purchaseType'
                            value={formState.supplierData.purchaseType}
                            onChange={handleSupplierInputChange}
                            select
                            required
                          >
                            <MenuItem value={1}>1</MenuItem>
                            <MenuItem value={2}>2</MenuItem>
                          </TextField>
                        </Grid>
                        <Grid item xs={12} md={6}>
                          <TextField
                            fullWidth
                            label='Banco'
                            name='bankName'
                            value={formState.supplierData.bankName}
                            onChange={handleSupplierInputChange}
                            required
                          />
                        </Grid>
                        <Grid item xs={12} md={6}>
                          <TextField
                            fullWidth
                            label='Tipo de cuenta'
                            name='accountType'
                            value={formState.supplierData.accountType}
                            onChange={handleSupplierInputChange}
                            select
                            required
                          >
                            <MenuItem value='Ahorros'>Ahorros</MenuItem>
                            <MenuItem value='Corriente'>Corriente</MenuItem>
                          </TextField>
                        </Grid>
                        <Grid item xs={12} md={6}>
                          <TextField
                            fullWidth
                            label='Numero de cuenta'
                            name='accountNumber'
                            value={formState.supplierData.accountNumber}
                            onChange={handleSupplierInputChange}
                            required
                          />
                        </Grid>
                        <Grid item xs={12} md={6}>
                          <TextField
                            fullWidth
                            label='Producto que ofrece'
                            name='product'
                            value={formState.supplierData.product}
                            onChange={handleSupplierInputChange}
                            required
                          />
                        </Grid>
                      </>
                    )}

                    {formState.providerType === 'Natural' && (
                      <>
                        {/* Ejemplo de campos para Natural */}
                        <Grid item xs={12} md={6}>
                          <TextField
                            fullWidth
                            label='Nombre'
                            name='name'
                            value={formState.supplierData.name}
                            onChange={handleSupplierInputChange}
                            required
                          />
                        </Grid>
                        <Grid item xs={12} md={6}>
                          <TextField
                            fullWidth
                            label='C.C.'
                            name='taxId'
                            value={formState.supplierData.taxId}
                            onChange={handleSupplierInputChange}
                            required
                          />
                        </Grid>
                        <Grid item xs={12} md={6}>
                          <TextField
                            fullWidth
                            label='Profesión'
                            name='position'
                            value={formState.supplierData.position || ''}
                            onChange={handleSupplierInputChange}
                          />
                        </Grid>
                        <Grid item xs={12} md={6}>
                          <TextField
                            fullWidth
                            label='Ciudad / País'
                            name='city'
                            value={formState.supplierData.city}
                            onChange={handleSupplierInputChange}
                            required
                          />
                        </Grid>
                        <Grid item xs={12} md={6}>
                          <TextField
                            fullWidth
                            label='Departamento'
                            name='state'
                            value={formState.supplierData.state || ''}
                            onChange={handleSupplierInputChange}
                          />
                        </Grid>
                        <Grid item xs={12} md={6}>
                          <TextField
                            fullWidth
                            label='Dirección'
                            name='address'
                            value={formState.supplierData.address}
                            onChange={handleSupplierInputChange}
                            required
                          />
                        </Grid>
                        <Grid item xs={12} md={6}>
                          <TextField
                            fullWidth
                            label='Teléfono'
                            name='phone'
                            value={formState.supplierData.phone}
                            onChange={handleSupplierInputChange}
                          />
                        </Grid>
                        <Grid item xs={12} md={6}>
                          <TextField
                            fullWidth
                            label='Email'
                            name='email'
                            value={formState.supplierData.email}
                            onChange={handleSupplierInputChange}
                            required
                          />
                        </Grid>
                        <Grid item xs={12} md={6}>
                          <TextField
                            fullWidth
                            label='Compra Tipo'
                            name='purchaseType'
                            value={formState.supplierData.purchaseType}
                            onChange={handleSupplierInputChange}
                            select
                            required
                          >
                            <MenuItem value={1}>1</MenuItem>
                            <MenuItem value={2}>2</MenuItem>
                          </TextField>
                        </Grid>
                        <Grid item xs={12} md={6}>
                          <TextField
                            fullWidth
                            label='Banco'
                            name='bankName'
                            value={formState.supplierData.bankName}
                            onChange={handleSupplierInputChange}
                            required
                          />
                        </Grid>
                        <Grid item xs={12} md={6}>
                          <TextField
                            fullWidth
                            label='Tipo de cuenta'
                            name='accountType'
                            value={formState.supplierData.accountType}
                            onChange={handleSupplierInputChange}
                            select
                            required
                          >
                            <MenuItem value='Ahorros'>Ahorros</MenuItem>
                            <MenuItem value='Corriente'>Corriente</MenuItem>
                          </TextField>
                        </Grid>
                        <Grid item xs={12} md={6}>
                          <TextField
                            fullWidth
                            label='Numero de cuenta'
                            name='accountNumber'
                            value={formState.supplierData.accountNumber}
                            onChange={handleSupplierInputChange}
                            required
                          />
                        </Grid>
                        <Grid item xs={12} md={6}>
                          <TextField
                            fullWidth
                            label='Servicio que ofrece'
                            name='product'
                            value={formState.supplierData.product}
                            onChange={handleSupplierInputChange}
                            required
                          />
                        </Grid>
                      </>
                    )}
                  </Grid>
                </Paper>

                {/* Sección de criterios */}
                {categories.map((category) => (
                  <Paper key={category} sx={{ p: 2, mb: 3 }}>
                    <Typography variant='h6'>{category}</Typography>
                    <Divider sx={{ mb: 2 }} />

                    <FormGroup>
                      {(groupedCriteria[category] || [])
                        .filter(
                          (c) =>
                            c.type === 'Both' ||
                            c.type === formState.providerType
                        )
                        .map((criterion) => {
                          const isSelected = (
                            formState.selections[category] || []
                          ).includes(criterion.id)

                          const shouldShowWhich =
                            criterion.requiresWhich &&
                            category === 'CALIDAD' &&
                            isSelected

                          return (
                            <Box key={criterion.id} sx={{ mb: 1 }}>
                              {[
                                'PRECIO',
                                'TIEMPO DE ENTREGA',
                                'GARANTIA',
                                'EXPERIENCIA',
                                'RÉGIMEN TRIBUTARIO',
                                'CONDICIONES DE PAGO'
                              ].includes(category) ? (
                                <RadioGroup
                                  value={
                                    formState.selections[category]?.[0] || ''
                                  }
                                  onChange={(e) =>
                                    handleSelectionChange(
                                      category,
                                      criterion,
                                      e.target.checked
                                    )
                                  }
                                >
                                  <FormControlLabel
                                    value={criterion.id}
                                    control={<Radio />}
                                    label={`${criterion.name} (${criterion.baseScore} pts)`}
                                  />
                                </RadioGroup>
                              ) : (
                                <FormControlLabel
                                  control={
                                    <Checkbox
                                      checked={isSelected}
                                      onChange={(e) =>
                                        handleSelectionChange(
                                          category,
                                          criterion,
                                          e.target.checked
                                        )
                                      }
                                    />
                                  }
                                  label={`${criterion.name} (${criterion.baseScore} pts)`}
                                />
                              )}

                              {/* Si está en CALIDAD, requiereWhich y está seleccionado, renderiza "Cuál" */}
                              {shouldShowWhich && (
                                <TextField
                                  sx={{ ml: 4, mt: 1 }} // pequeño margen para que se vea debajo/del lado
                                  label='¿Cuál?'
                                  value={
                                    formState.whichAnswers[criterion.id] || ''
                                  }
                                  onChange={(e) =>
                                    handleWhichChange(
                                      criterion.id,
                                      e.target.value
                                    )
                                  }
                                  size='small'
                                  required
                                />
                              )}
                            </Box>
                          )
                        })}
                    </FormGroup>

                    <Typography sx={{ mt: 2 }}>
                      Puntuación {category}: {formState.scores[category] || 0}{' '}
                      pts
                    </Typography>
                  </Paper>
                ))}

                {/* Resumen y botón de envío */}
                <Paper sx={{ p: 2, mt: 3 }}>
                  <Typography variant='h5'>
                    Puntuación Total: {formState.totalScore} pts
                  </Typography>
                  <Typography color='text.secondary' sx={{ mb: 2 }}>
                    {formState.totalScore >= 81
                      ? 'EXCELLENT'
                      : formState.totalScore >= 61
                        ? 'APPROVED'
                        : 'NO APROBADO'}
                  </Typography>
                </Paper>
              </>
            )}
          </Paper>
        </Box>
      </DialogContent>
      <DialogActions>
        <Button onClick={handleClose}>Cancelar</Button>
        <Button
          onClick={handleSubmit}
          variant='contained'
          disabled={isSubmitting}
        >
          {isSubmitting ? (
            <CircularProgress size={24} />
          ) : existingSelectionData ? (
            'Guardar Cambios'
          ) : (
            'Evaluar y Guardar'
          )}
        </Button>
      </DialogActions>
    </Dialog>
  )
}

export default SupplierSelectionModal

// src/Components/Purchases/UploadQuotationModal.tsx
import { getApiErrorReason } from 'src/utils/apiError'
import React, { useEffect, useState, useCallback, FC, ChangeEvent } from 'react'
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Typography,
  Box,
  CircularProgress,
  Alert,
  Divider,
  Autocomplete,
  TextField,
  Paper,
  IconButton,
  Chip
} from '@mui/material'
import {
  CloudUpload,
  Visibility,
  CheckCircle,
  ErrorOutline,
  Add
} from '@mui/icons-material'
import CloseIcon from '@mui/icons-material/Close' // Icono para cerrar el modal
import { PictureAsPdf } from '@mui/icons-material'
import { format } from 'date-fns'
import {
  PURCHASE_TEAL,
  PURCHASE_TEAL_HOVER
} from './purchaseTableStyle'

const tealButton = {
  bgcolor: PURCHASE_TEAL,
  '&:hover': { bgcolor: PURCHASE_TEAL_HOVER }
}
import useAxiosPrivate from '@utils/use-axios-private'
import { useMutation, useQueryClient } from 'react-query'
import { useSupplierSearch } from 'src/hooks/purchases/useSuppliers'
import { isAxiosError } from 'axios' // Importar AxiosResponse
import {
  PurchaseRequest as IPurchaseRequest, // Renombrado para evitar conflicto con el componente
  PurchaseRequestItem as IPurchaseRequestItem,
  Supplier as ISupplier
  // PurchaseOrder, // No se usa directamente en este modal más que para tipos internos
} from 'src/pages/Purchases/Types' // Asegúrate que estas rutas sean correctas
import debounce from 'lodash/debounce'
import { notify } from 'src/utils/notify'
import { confirmDialog } from 'src/utils/confirm'

import { logger } from 'src/utils/logger'
// Definir localmente si no está en Types.ts, pero idealmente debería estar allí
interface Quotation {
  id: string | number
  supplierId: number | string // Debe coincidir con ISupplier['id']
  filePath?: string
  originalFileName?: string
  fileName?: string
  createdAt?: string
  accepted?: boolean
}

// Actualizar PurchaseRequest para incluir quotations
interface PurchaseRequestWithQuotations extends IPurchaseRequest {
  quotations: Quotation[]
  items?: IPurchaseRequestItemWithSuppliers[] // Items con sus proveedores
}

interface IPurchaseRequestItemWithSuppliers extends IPurchaseRequestItem {
  suppliers?: ISupplier[]
}

interface UploadQuotationModalProps {
  open: boolean
  onClose: () => void
  purchaseRequest: PurchaseRequestWithQuotations // Usar el tipo actualizado
  onSuccess: () => void
}

// Helper para obtener la lista inicial de proveedores únicos desde los ítems
const getInitialSuppliersFromItems = (
  pr: PurchaseRequestWithQuotations
): ISupplier[] => {
  const allSuppliersFromItems = (pr.items ?? []).flatMap(
    (item) => item.suppliers || []
  )
  const uniqueSuppliersMap = new Map<string | number, ISupplier>()
  allSuppliersFromItems.forEach((supplier) => {
    if (supplier && !uniqueSuppliersMap.has(supplier.id)) {
      uniqueSuppliersMap.set(supplier.id, supplier)
    }
  })
  return Array.from(uniqueSuppliersMap.values())
}

const UploadQuotationModal: FC<UploadQuotationModalProps> = ({
  open,
  onClose,
  purchaseRequest,
  onSuccess
}) => {
  const axiosPrivate = useAxiosPrivate()
  const queryClient = useQueryClient()

  const [selectedFiles, setSelectedFiles] = useState<{
    [key: string]: File | null
  }>({})
  const [actionStates, setActionStates] = useState<{
    [key: string]: {
      uploading?: boolean
      accepting?: boolean
      error?: string
      pdfLoading?: boolean
      pdfUrl?: string | null
    }
  }>({})

  const [displayedSuppliers, setDisplayedSuppliers] = useState<ISupplier[]>([])
  const [showAddSupplierSection, setShowAddSupplierSection] = useState(false)
  const [autocompleteInputValue, setAutocompleteInputValue] = useState('') // Para el input directo del Autocomplete
  const [debouncedSearchTerm, setDebouncedSearchTerm] = useState('') // Para la query de React Query
  const [selectedNewSuppliers, setSelectedNewSuppliers] = useState<ISupplier[]>(
    []
  )

  // Efecto para inicializar/resetear estados
  useEffect(() => {
    if (open) {
      const initialSuppliers = getInitialSuppliersFromItems(purchaseRequest)
      setDisplayedSuppliers(initialSuppliers)

      setSelectedFiles({})
      setShowAddSupplierSection(false)
      setSelectedNewSuppliers([])
      setAutocompleteInputValue('')
      setDebouncedSearchTerm('')

      const initialActionStates: typeof actionStates = {}
      initialSuppliers.forEach((supplier) => {
        initialActionStates[supplier.id.toString()] = { pdfUrl: null }
      })
      setActionStates(initialActionStates)
    }
  }, [open, purchaseRequest])

  const debouncedSetSearch = useCallback(
    debounce((value: string) => {
      setDebouncedSearchTerm(value)
    }, 500),
    []
  )

  useEffect(() => {
    debouncedSetSearch(autocompleteInputValue)
  }, [autocompleteInputValue, debouncedSetSearch])

  const {
    data: searchedSuppliersList = [],
    isLoading: isLoadingSearchedSuppliers
  } = useSupplierSearch<ISupplier>(
    debouncedSearchTerm,
    purchaseRequest.purchaseType
  )

  const handleFileChange = (
    event: ChangeEvent<HTMLInputElement>,
    supplierId: string
  ) => {
    const selectedFile = event.target.files?.[0]
    setActionStates((prev) => ({
      ...prev,
      [supplierId]: { ...prev[supplierId], error: undefined }
    }))
    if (selectedFile) {
      if (selectedFile.type !== 'application/pdf') {
        setActionStates((prev) => ({
          ...prev,
          [supplierId]: {
            ...prev[supplierId],
            error: 'Solo se permiten archivos PDF.'
          }
        }))
        setSelectedFiles((prev) => ({ ...prev, [supplierId]: null }))
        event.target.value = '' // Limpiar el input de archivo
      } else {
        setSelectedFiles((prev) => ({ ...prev, [supplierId]: selectedFile }))
      }
    }
  }

  // --- MUTACIONES ---
  const commonMutationOptions = {
    onSuccessInvalidatePR: () => {
      queryClient.invalidateQueries([
        'purchaseRequestDetails',
        purchaseRequest.id.toString()
      ])
      onSuccess() // Llama al onSuccess general (ej. para refrescar lista de PRs)
    },
    onErrorDisplay: (error: unknown, defaultMessage: string) => {
      logger.error(`Error: ${defaultMessage}`, error)
      let userMessage = defaultMessage
      if (isAxiosError(error) && getApiErrorReason(error)) {
        userMessage = getApiErrorReason(error) ?? userMessage
      } else if (error instanceof Error) {
        userMessage = error.message
      }
      notify.error('Error', userMessage)
    }
  }

  const uploadMutation = useMutation(
    async (vars: { supplierId: string; file: File; supplierName?: string }) => {
      const { supplierId, file, supplierName } = vars
      setActionStates((prev) => ({
        ...prev,
        [supplierId]: { ...prev[supplierId], uploading: true, error: undefined }
      }))
      const formData = new FormData()
      formData.append('file', file)
      formData.append('supplierId', supplierId)
      formData.append('purchaseRequestId', purchaseRequest.id.toString())
      formData.append('purchaseRequestCode', purchaseRequest.purchaseCode || '')
      formData.append('supplierName', supplierName || 'Desconocido')
      for (const [key, value] of formData.entries()) {
  logger.log(key, value);
}

      return axiosPrivate.post('/purchaseQuotations', formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      })
    },
    {
      onSuccess: (_data, variables) => {
        notify.success('Éxito', 'La cotización ha sido subida correctamente.')
        setSelectedFiles((prev) => ({ ...prev, [variables.supplierId]: null }))
        commonMutationOptions.onSuccessInvalidatePR()
      },
      onError: (error, variables) => {
        setActionStates((prev) => ({
          ...prev,
          [variables.supplierId]: {
            ...prev[variables.supplierId],
            error: 'Error al subir la cotización.'
          }
        }))
        commonMutationOptions.onErrorDisplay(
          error,
          'No se pudo subir la cotización.'
        )
      },
      onSettled: (_data, _error, variables) => {
        setActionStates((prev) => ({
          ...prev,
          [variables.supplierId]: {
            ...prev[variables.supplierId],
            uploading: false
          }
        }))
      }
    }
  )

  const fetchPdfForView = async (supplierId: string) => {
    const currentPdfUrl = actionStates[supplierId]?.pdfUrl
    if (currentPdfUrl) {
      URL.revokeObjectURL(currentPdfUrl) // Limpiar URL de objeto anterior
      setActionStates((prev) => ({
        ...prev,
        [supplierId]: { ...prev[supplierId], pdfUrl: null }
      }))
      return
    }
    setActionStates((prev) => ({
      ...prev,
      [supplierId]: {
        ...prev[supplierId],
        pdfLoading: true,
        error: undefined,
        pdfUrl: null
      }
    }))
    try {
      const quotation = purchaseRequest.quotations.find(
        (q) => q.supplierId.toString() === supplierId
      )
      if (!quotation || (!quotation.filePath && !quotation.id)) {
        // Asumimos que necesitamos filePath o un ID de cotización
        throw new Error('Datos de cotización insuficientes para visualización.')
      }
      // Ejemplo: Si filePath es una URL directa y pública
      // if (quotation.filePath?.startsWith('http')) {
      //   window.open(quotation.filePath, '_blank');
      //   setActionStates(prev => ({ ...prev, [supplierId]: { ...prev[supplierId], pdfLoading: false } }));
      //   return;
      // }
      // O si necesitas un endpoint para obtener el blob por ID de cotización (más seguro)
      const response = await axiosPrivate.get(
        // Ajusta este endpoint: puede ser por ID de cotización o PR_ID + Supplier_ID
        `/purchaseQuotations?purchaseRequestId=${purchaseRequest.id}&supplierId=${supplierId}`,

        { responseType: 'blob' }
      )
      if (response.headers['content-type'] !== 'application/pdf')
        throw new Error('El archivo no es un PDF.')
      const url = URL.createObjectURL(
        new Blob([response.data], { type: 'application/pdf' })
      )
      setActionStates((prev) => ({
        ...prev,
        [supplierId]: { ...prev[supplierId], pdfUrl: url, pdfLoading: false }
      }))
    } catch (error) {
      logger.error('Error fetching PDF:', error)
      setActionStates((prev) => ({
        ...prev,
        [supplierId]: {
          ...prev[supplierId],
          error: 'Error al cargar PDF.',
          pdfLoading: false
        }
      }))
    }
  }

  const acceptQuotationMutation = useMutation(
    async (supplierId: string) => {
      setActionStates((prev) => ({
        ...prev,
        [supplierId]: { ...prev[supplierId], accepting: true, error: undefined }
      }))
      return axiosPrivate.post('/purchaseQuotations/accept', {
        purchaseRequestId: purchaseRequest.id,
        supplierId
      })
    },
    {
      onSuccess: () => {
        notify.success('Aceptado', 'La cotización ha sido aceptada.')
        commonMutationOptions.onSuccessInvalidatePR()
      },
      onError: (error, supplierId) => {
        setActionStates((prev) => ({
          ...prev,
          [supplierId]: { ...prev[supplierId], error: 'Error al aceptar.' }
        }))
        commonMutationOptions.onErrorDisplay(
          error,
          'Ocurrió un error al aceptar la cotización.'
        )
      },
      onSettled: (_data, _error, supplierId) => {
        setActionStates((prev) => ({
          ...prev,
          [supplierId]: { ...prev[supplierId], accepting: false }
        }))
      }
    }
  )

  const associateSuppliersToPRItemsMutation = useMutation(
    async (newSupplierIds: (string | number)[]) => {
      if (newSupplierIds.length === 0) return
      const numericSupplierIds = newSupplierIds.map((id) => Number(id))
      return axiosPrivate.post(
        `/purchaseRequests/${purchaseRequest.id}/suppliers`,
        { supplierIds: numericSupplierIds }
      )
    },
    {
      onSuccess: () => {
        notify.success('Proveedores Asociados', 'Los nuevos proveedores se han vinculado a los ítems de la solicitud.')
        commonMutationOptions.onSuccessInvalidatePR() // Esto refrescará purchaseRequest y el useEffect actualizará displayedSuppliers
      },
      onError: (error) => {
        commonMutationOptions.onErrorDisplay(
          error,
          'No se pudo asociar los proveedores a los ítems de la Solicitud de Compra.'
        )
      }
    }
  )

  const handleUpload = (supplierId: string) => {
    const fileToUpload = selectedFiles[supplierId]
    const supplier = displayedSuppliers.find(
      (s) => s.id.toString() === supplierId
    )
    if (!fileToUpload || !supplier) return
    uploadMutation.mutate({
      supplierId,
      file: fileToUpload,
      supplierName: supplier.name
    })
  }

  const handleAcceptQuotation = async (supplierId: string) => {
    const result = await confirmDialog({ title: '¿Estás seguro?', text: '¿Deseas aceptar esta cotización?', confirmLabel: 'Sí, aceptar', cancelLabel: 'Cancelar', tone: 'danger' })
    if (result.isConfirmed) acceptQuotationMutation.mutate(supplierId)
  }

  const handleAddSelectedSuppliers = () => {
    const newlyAddedToUIDisplay = selectedNewSuppliers.filter(
      (newSup) =>
        !displayedSuppliers.some((dispSup) => dispSup.id === newSup.id)
    )

    if (newlyAddedToUIDisplay.length > 0) {
      // Actualizar UI localmente primero para respuesta rápida
      setDisplayedSuppliers((prev) => {
        const existingIds = new Set(prev.map((s) => s.id))
        const trulyNewForDisplay = newlyAddedToUIDisplay.filter(
          (s) => !existingIds.has(s.id)
        )
        return [...prev, ...trulyNewForDisplay]
      })

      const newActionStatesToAdd: typeof actionStates = {}
      newlyAddedToUIDisplay.forEach((sup) => {
        newActionStatesToAdd[sup.id.toString()] = { pdfUrl: null }
      })
      setActionStates((prev) => ({ ...prev, ...newActionStatesToAdd }))
      setSelectedFiles((prev) => {
        // Asegurar que no haya archivos seleccionados para estos nuevos
        const updated = { ...prev }
        newlyAddedToUIDisplay.forEach((sup) => {
          updated[sup.id.toString()] = null
        })
        return updated
      })

      const idsToAssociateBackend = newlyAddedToUIDisplay.map((s) => s.id)
      associateSuppliersToPRItemsMutation.mutate(idsToAssociateBackend)
    }
    setSelectedNewSuppliers([])
    setShowAddSupplierSection(false)
  }

  return (
    <Dialog open={open} onClose={onClose} maxWidth='lg' fullWidth>
      {' '}
      {/* Aumentado a lg para más espacio */}
      <DialogTitle
        sx={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center'
        }}
      >
        <Box>
          <Typography variant='h6' component='span' fontWeight={700}>
            Cotizaciones · {purchaseRequest.purchaseCode}
          </Typography>
          <Typography variant='body2' color='text.secondary'>
            {[
              purchaseRequest.applicantName,
              purchaseRequest.purchaseType
                ? `Tipo ${purchaseRequest.purchaseType}`
                : null
            ]
              .filter(Boolean)
              .join(' · ')}
          </Typography>
        </Box>
        <IconButton onClick={onClose} aria-label='Cerrar'>
          <CloseIcon />
        </IconButton>
      </DialogTitle>
      <DialogContent dividers>
        {' '}
        {/* dividers para mejor separación */}
        <Box
          sx={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            mb: 2
          }}
        >
          <Typography variant='body2' color='text.secondary'>
            {displayedSuppliers.length}{' '}
            {displayedSuppliers.length === 1 ? 'proveedor' : 'proveedores'} ·{' '}
            {purchaseRequest.quotations.length}{' '}
            {purchaseRequest.quotations.length === 1
              ? 'cotización'
              : 'cotizaciones'}
          </Typography>
          <Button
            variant={showAddSupplierSection ? 'outlined' : 'contained'}
            startIcon={<Add />}
            onClick={() => setShowAddSupplierSection(!showAddSupplierSection)}
            size='small'
            sx={
              showAddSupplierSection
                ? { color: PURCHASE_TEAL, borderColor: PURCHASE_TEAL }
                : tealButton
            }
          >
            {showAddSupplierSection ? 'Cancelar' : 'Añadir proveedor'}
          </Button>
        </Box>
        {showAddSupplierSection && (
          <Paper elevation={1} sx={{ p: 2, mb: 3, mt: 1 }}>
            <Typography variant='subtitle1' gutterBottom>
              Buscar y seleccionar proveedores adicionales
            </Typography>
            <Autocomplete
              multiple
              filterSelectedOptions
              options={searchedSuppliersList}
              value={selectedNewSuppliers}
              onInputChange={(_event, newInputValue) =>
                setAutocompleteInputValue(newInputValue)
              }
              onChange={(_event, newValue) => setSelectedNewSuppliers(newValue)}
              getOptionLabel={(option) => `${option.name} (${option.taxId})`}
              isOptionEqualToValue={(option, value) => option.id === value.id}
              loading={isLoadingSearchedSuppliers}
              loadingText='Buscando...'
              noOptionsText={
                autocompleteInputValue.length < 2
                  ? 'Escribe al menos 2 caracteres...'
                  : 'No se encontraron proveedores'
              }
              renderInput={(params) => (
                <TextField
                  {...params}
                  label='Buscar Proveedores'
                  placeholder='Nombre o NIT/CC'
                  InputProps={{
                    ...params.InputProps,
                    endAdornment: (
                      <>
                        {isLoadingSearchedSuppliers ? (
                          <CircularProgress color='inherit' size={20} />
                        ) : null}
                        {params.InputProps.endAdornment}
                      </>
                    )
                  }}
                />
              )}
              sx={{ mb: 1 }}
            />
            <Button
              variant='contained'
              onClick={handleAddSelectedSuppliers}
              disabled={selectedNewSuppliers.length === 0}
              size='small'
              sx={tealButton}
            >
              Añadir seleccionados
            </Button>
          </Paper>
        )}
        {displayedSuppliers.length === 0 && !showAddSupplierSection && (
          <Box sx={{ textAlign: 'center', py: 5 }}>
            <Typography variant='subtitle1' fontWeight={600}>
              Aún no hay proveedores en esta solicitud
            </Typography>
            <Typography variant='body2' color='text.secondary'>
              Añade un proveedor para cargar su cotización.
            </Typography>
          </Box>
        )}
        {displayedSuppliers.map((supplier, index) => {
          if (!supplier) return null
          const supplierIdStr = supplier.id.toString()
          const existingQuotation = purchaseRequest.quotations.find(
            (q) => q.supplierId.toString() === supplierIdStr
          )
          const currentActionState = actionStates[supplierIdStr] || {}

          return (
            <React.Fragment key={supplier.id}>
              <Paper
                variant='outlined'
                sx={{ mb: 2, p: 2, borderRadius: 2 }}
              >
                <Box
                  sx={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    gap: 1,
                    mb: 1.5
                  }}
                >
                  <Typography variant='subtitle1' fontWeight={600}>
                    {supplier.name}
                    {supplier.taxId && (
                      <Typography
                        component='span'
                        variant='body2'
                        color='text.secondary'
                      >
                        {' '}
                        · {supplier.taxId}
                      </Typography>
                    )}
                  </Typography>
                  {existingQuotation?.accepted ? (
                    <Chip
                      icon={<CheckCircle />}
                      label='Aceptada'
                      color='success'
                      size='small'
                    />
                  ) : existingQuotation ? (
                    <Chip label='Subida' color='info' variant='outlined' size='small' />
                  ) : (
                    <Chip
                      label='Pendiente'
                      color='warning'
                      variant='outlined'
                      size='small'
                    />
                  )}
                </Box>

                {existingQuotation && (
                  <Box
                    sx={{
                      display: 'flex',
                      alignItems: 'center',
                      gap: 1.5,
                      mb: 1.5
                    }}
                  >
                    <PictureAsPdf color='error' />
                    <Box sx={{ minWidth: 0 }}>
                      <Typography variant='body2' noWrap>
                        {existingQuotation.fileName ||
                          existingQuotation.originalFileName ||
                          `Cotización de ${supplier.name}`}
                      </Typography>
                      {existingQuotation.createdAt && (
                        <Typography variant='caption' color='text.secondary'>
                          Subida el{' '}
                          {format(
                            new Date(existingQuotation.createdAt),
                            'dd/MM/yyyy'
                          )}
                        </Typography>
                      )}
                    </Box>
                  </Box>
                )}

                <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
                  {existingQuotation && (
                    <Button
                      variant='outlined'
                      onClick={() => fetchPdfForView(supplierIdStr)}
                      startIcon={
                        currentActionState.pdfLoading ? (
                          <CircularProgress size={20} />
                        ) : (
                          <Visibility />
                        )
                      }
                      disabled={
                        currentActionState.pdfLoading ||
                        currentActionState.accepting
                      }
                      size='small'
                      sx={{ color: PURCHASE_TEAL, borderColor: PURCHASE_TEAL }}
                    >
                      {currentActionState.pdfUrl ? 'Ocultar PDF' : 'Ver cotización'}
                    </Button>
                  )}
                  {existingQuotation && !existingQuotation.accepted && (
                    <Button
                      variant='contained'
                      onClick={() => handleAcceptQuotation(supplierIdStr)}
                      startIcon={
                        currentActionState.accepting ||
                        (acceptQuotationMutation.isLoading &&
