import { logger } from 'src/utils/logger'
export interface FileData {
  name: string
  title: string
  description: string
  version: string
  date: Date
  path: string
}

export interface RepositoryData extends FileData {
  id: number
  created_at: Date
}

const Repository = () => {
  const canManage = useCan(PERMISSIONS.REPOSITORIES_REPOSITORY_MANAGE)
  const { data: repositoriesData, isLoading: loading } =
    useRepositories<RepositoryData>()
  const tableData = useMemo(() => repositoriesData ?? [], [repositoriesData])
  const createRepositoryMutation = useCreateRepository()
  const deleteRepositoryMutation = useDeleteRepository()
  const [createModalOpen, setCreateModalOpen] = useState(false)

  const columns = useMemo<MRT_ColumnDef<RepositoryData>[]>(
    () => [
      {
        accessorKey: 'id',
        header: 'Id',
        size: 80
      },
      {
        accessorKey: 'name',
        header: 'Nombre',
        size: 100
      },
      {
        accessorKey: 'title',
        header: 'Título',
        size: 100
      },

      {
        accessorKey: 'version',
        header: 'Versión',
        size: 50
      },
      {
        accessorKey: 'date',
        header: 'Fecha',
        size: 50,
        Cell: ({ row }) => format(new Date(row.original.date), 'yyyy-MM-dd')
      },
      {
        accessorKey: 'description',
        header: 'Descripción',
        size: 100
      },
      {
        accessorKey: 'path',
        header: 'Ruta',
        size: 100
      }
    ],
    [] // No hay dependencias específicas aquí
  )

  const handleCreateNewRow = (values: FileData) => {
    onCreateRepository(values)
    setCreateModalOpen(false)
  }

  const onCreateRepository = async (repostoryData: FileData) => {
    try {
      const response = await createRepositoryMutation.mutateAsync(repostoryData)

      if (response.status >= 200 && response.status < 300) {
        toast.success('Archivo subido Exitosamente!', {
          duration: 4000,
          position: 'top-center'
        })
      } else {
        toast.error('Error al subir archivo', {
          duration: 4000,
          position: 'top-center'
        })
      }
    } catch (error) {
      logger.error('Error de red:', error)
    }
  }

  const downloadFileFromMinio = async (file: string) => {
    try {
      const blob = await fetchMinioObjectBlob('repositories', file)

      const url = URL.createObjectURL(blob)

      const a = document.createElement('a')
      a.href = url
      a.download = file
      document.body.appendChild(a)
      a.click()

      document.body.removeChild(a)
      URL.revokeObjectURL(url)
    } catch (error) {
      logger.error('Error downloading file from Minio:', error)
    }
  }

  const openExcelViewerFromMinio = async (file: string): Promise<string> => {
    try {
      const blob = await fetchMinioObjectBlob('repositories', file)

      return URL.createObjectURL(blob)
    } catch (error) {
      logger.error('Error opening Excel file in viewer:', error)
      throw error
    }
  }

  const handleClick = async (
    e: React.MouseEvent<HTMLButtonElement>,
    file: string
  ) => {
    e.preventDefault()
    try {
      const fileURL = await openExcelViewerFromMinio(file)

      window.open(fileURL, '_blank')
    } catch (error) {
      // Manejar el error, si es necesario
    }
  }

  const handleDelete = async (id: number) => {
    try {
      const { isConfirmed: shouldDelete } = await confirmDialog({
        title: 'Eliminar archivo',
        text: 'Esta acción no se puede deshacer.',
        confirmLabel: 'Eliminar',
        tone: 'danger'
      })

      if (shouldDelete) {
        const response = await deleteRepositoryMutation.mutateAsync(id)

        if (response.status >= 200 && response.status < 300) {
          toast.success('Archivo eliminado Exitosamente!', {
            duration: 4000,
            position: 'top-center'
          })
          } else {
          toast.error('Error al eliminar archivo', {
            duration: 4000,
            position: 'top-center'
          })
        }
      }
    } catch (error) {
      logger.error('Error de red:', error)
    }
  }

  return (
    <>
      <Loader loading={loading} />
      <MaterialReactTable
        columns={columns}
        data={tableData}
        localization={MRT_Localization_ES}
        enableRowActions={true}
        renderTopToolbarCustomActions={() =>
          canManage ? (
            <button
              className='bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded '
              onClick={() => setCreateModalOpen(true)}
            >
              Subir Nuevo Archivo
            </button>
          ) : null
        }
        renderRowActions={({ row }) => {
          return (
            <Box
              sx={{
                display: 'flex',
                gap: '1rem',
                // width: 20,
                justifyContent: 'center'
              }}
            >
              {/* <Tooltip arrow placement="right" title="Ver">
                  <Link to={`${row.original.id}`}>
                    <Visibility />
                  </Link>
                </Tooltip> */}

              <Tooltip arrow placement='right' title='descargar'>
                <Button
                  onClick={() => downloadFileFromMinio(row.original.path)}
                >
                  <Download />
                </Button>
              </Tooltip>
              <Button onClick={(e) => handleClick(e, row.original.path)}>
                <Visibility />
              </Button>
{canManage && (
              <Button onClick={() => handleDelete(row.original.id)}>
                <Delete />
              </Button>
)}
            </Box>
          )
        }}
      />
      <CreateNewRepositoryModal
        columns={columns}
        open={createModalOpen}
        onClose={() => setCreateModalOpen(false)}
        onSubmit={handleCreateNewRow}
      />
    </>
  )
}

interface CreateModalProps {
  columns: MRT_ColumnDef<RepositoryData>[]
  onClose: () => void
  onSubmit: (values: FileData) => void
  open: boolean
}

export const CreateNewRepositoryModal = ({
  open,
  columns,
  onClose,
  onSubmit
}: CreateModalProps) => {
  const [file, setFile] = useState<File | null>(null)
  const [selectedFileName, setSelectedFileName] = useState<string | null>(null)
  const [values, setValues] = useState<any>(() =>
    columns.reduce((acc, column) => {
      acc[column.accessorKey ?? ''] = ''
      return acc
    }, {} as any)
  )

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = event.target.files?.[0]
    if (selectedFile) {
      setFile(selectedFile)
      setSelectedFileName(selectedFile.name)
    }
  }

  const handleSubmit = () => {
    const formData = new FormData()
    formData.append('file', file as File)
    formData.append('name', values.name)
    formData.append('title', values.title)
    formData.append('version', values.version)
    formData.append('description', values.description)
    formData.append('date', values.date)
    //@ts-ignore
    onSubmit(formData)
    onClose()
  }

  return (
    <Dialog open={open}>
      <DialogTitle textAlign='center'>Subir Nuevo Archivo</DialogTitle>
      <DialogContent>
        <form onSubmit={(e) => e.preventDefault()}>
          <Stack
            sx={{
              width: '100%',
              minWidth: { xs: '300px', sm: '360px', md: '400px' },
              gap: '1.5rem'
            }}
          >
            {columns.map((column) => (
              <React.Fragment key={column.accessorKey}>
                {column.accessorKey !== 'id' && (
                  <>
                    {column.accessorKey === 'date' ? (
                      <TextField
                        label={column.header}
                        type='date'
                        name={column.accessorKey}
                        onChange={(e: React.ChangeEvent<HTMLInputElement>) =>
                          setValues({
                            ...values,
                            [e.target.name]: e.target.value
                          })
                        }
                      />
                    ) : column.accessorKey === 'path' ? (
                      <Button
                        component='label'
                        variant='contained'
                        startIcon={<CloudUpload />}
                        htmlFor='file-upload'
                        style={{
                          textTransform: 'none'
                        }}
                      >
                        {selectedFileName ? selectedFileName : 'Cargar Archivo'}
                        <input
                          id='file-upload'
                          type='file'
                          accept='.xlsx'
                          onChange={handleFileChange}
                          style={{ display: 'none' }}
                        />
                      </Button>
                    ) : (
                      <TextField
                        label={column.header}
                        name={column.accessorKey}
                        onChange={(e: React.ChangeEvent<HTMLInputElement>) =>
                          setValues({
                            ...values,
                            [e.target.name]: e.target.value
                          })
                        }
                      />
                    )}
                  </>
                )}
              </React.Fragment>
            ))}
          </Stack>
        </form>
      </DialogContent>
      <DialogActions sx={{ p: '1.25rem' }}>
        <Button
          variant='contained'
          onClick={onClose}
          sx={{ backgroundColor: '#ccc', marginRight: '10px' }}
        >
          Cancelar
        </Button>
        <Button variant='contained' color='primary' onClick={handleSubmit}>
          Subir Archivo
        </Button>
      </DialogActions>
    </Dialog>
  )
}

