      //         )
      //       }
      //       onChange={(selectedOption: any) => setFormat(selectedOption) as any}
      //       styles={styles(false)}
      //     />
      //   )
      // }
    ],
    [getCommonEditTextFieldProps]
  )

  return (
    <Container maxWidth='xl' sx={{ py: 3 }}>
      <LmsPageHeader
        title='Equipos'
        subtitle='Catálogo de equipos, magnitudes y plantillas de certificado'
        icon={<Build />}
        actions={
          canManageDevices ? (
            <Button variant='contained' startIcon={<Add />} onClick={() => setCreateModalOpen(true)} sx={{ bgcolor: '#00BFA5', whiteSpace: 'nowrap', '&:hover': { bgcolor: '#00ACC1' } }}>
              Crear equipo
            </Button>
          ) : undefined
        }
      />

      <Grid container spacing={3} sx={{ mb: 3 }}>
        <Grid item xs={12} sm={4}>
          <LmsStatCard variant='quiet'
            label='Total equipos'
            value={devicesCount ?? devicesPage?.totalItems ?? 0}
            icon={<Build />}
            tone='teal'
          />
        </Grid>
      </Grid>

      <DataTable<DeviceData>
        columns={columns}
        data={tableData}
        itemLabel={['equipo', 'equipos']}
        searchPlaceholder='Buscar por nombre'
        {...server.tableProps}
        rowCount={devicesPage?.totalItems ?? 0}
        state={{
          ...server.tableState,
          isLoading,
          showProgressBars: isFetching && !isLoading
        }}
        editingMode='modal' //default
        enableEditing={canManageDevices}
        enableRowActions={canManageDevices}
        onEditingRowSave={handleSaveRowEdits}
        onEditingRowCancel={handleCancelRowEdits}
        initialState={{ columnVisibility: { id: false } }}
        renderRowActions={({ row, table }) => (
          <Box sx={{ display: 'flex', gap: 0.5 }}>
          <Tooltip arrow placement='top' title='Editar'>
            <IconButton
