                  </Tooltip>
                  <Tooltip title='Reenviar correo de activación'>
                    <IconButton
                      size='small'
                      aria-label={`Reenviar activación a ${user.nombre}`}
                      sx={{ color: '#00695C' }}
                      onClick={() => handleResendActivation(user)}
