            </Box>
          )
        }}
        displayColumnDefOptions={{
          'mrt-row-actions': { header: 'Acciones', size: 190 }
        }}
        renderEmptyRowsFallback={() => (
          <EmptyState
            icon={<PersonOutline />}
            title='No hay usuarios registrados'
            hint='Crea el primer usuario para que el cliente pueda entrar.'
