import { notify } from 'src/utils/notify'

import { logger } from 'src/utils/logger'
interface PreviewData {
  totalAffected: number
  sourceDevice: { name: string }
  targetDevice: { name: string }
  sampleCertificates?: Array<{
    id: number
    customerName: string
    serie?: string | null
  }>
