// API functions
const maintenanceAPI = {
  // Public endpoints (no auth required)
  createTicket: async (data: MaintenanceCreateRequest): Promise<any> => {
    const formData = new FormData()

    // Add text fields
    Object.entries(data).forEach(([key, value]) => {
      if (key !== 'files' && value !== undefined) {
        formData.append(key, String(value))
      }
    })

    // Add files
    if (data.files) {
      data.files.forEach((file) => {
        formData.append('files', file)
      })
    }

    const response = await axiosPublic.post<any>(
      `/public/maintenance/tickets`,
      formData
    )
    return response.data
  },

  trackTicket: async (
    ticketNumber: string
  ): Promise<MaintenanceTrackingResponse> => {
    try {
      const response = await axiosPublic.get<any>(
        `public/maintenance/tickets/${ticketNumber}`
      )

      // Map backend timeline format to frontend format
      const mappedTimeline =
        response.data.timeline?.map((entry: any) => ({
          id: entry.id,
          ticketId: response.data.id,
          action: mapBackendTypeToAction(entry.type),
          description: entry.description || entry.title,
          performedBy: entry.author || 'Sistema',
          performedAt: entry.timestamp || entry.createdAt,
          metadata: {
            title: entry.title,
            icon: entry.icon,
            authorType: entry.authorType
          }
        })) || []

      const ticket: MaintenanceTicket = {
        ...response.data,
        timeline: mappedTimeline
      }

      return {
        ticket,
        found: true,
        message: 'Ticket encontrado'
      }
    } catch (error: any) {
      if (error.response?.status === 404) {
        return {
          ticket: null,
          found: false,
          message: 'Ticket no encontrado'
        }
      }
      throw error
    }
  },

  // Private endpoints (auth required)
  getTickets: async (
    filters?: MaintenanceFilters,
    page = 1,
    limit = 10
  ): Promise<MaintenanceResponse> => {
    const params = new URLSearchParams({
      page: page.toString(),
      limit: limit.toString()
    })

    if (filters) {
      Object.entries(filters).forEach(([key, value]) => {
        if (value !== undefined && value !== null) {
          if (Array.isArray(value)) {
            value.forEach((v) => params.append(key, String(v)))
          } else if (typeof value === 'object' && value.from && value.to) {
            params.append('dateFrom', value.from)
            params.append('dateTo', value.to)
          } else {
            params.append(key, String(value))
          }
        }
      })
    }

    const response = await axiosPrivate.get<MaintenanceResponse>(
      `/maintenance/tickets?${params.toString()}`
    )
    return response.data
  },

  getTicketById: async (id: string): Promise<MaintenanceTicket> => {
    const response = await axiosPrivate.get<MaintenanceTicket>(
      `/maintenance/tickets/${id}`
    )
    return response.data
  },

  updateTicket: async (
    id: string,
    data: MaintenanceUpdateRequest
  ): Promise<MaintenanceTicket> => {
    // Map frontend field names to backend field names
    const requestData: Record<string, any> = {
      ...data
    }

    // Map assignedTechnician to assignedTechnicianId only when explicitly provided
    if (Object.prototype.hasOwnProperty.call(data, 'assignedTechnician')) {
      requestData.assignedTechnicianId = data.assignedTechnician
        ? parseInt(data.assignedTechnician)
        : null
    }

    // Remove the frontend field name to avoid conflicts
    delete requestData.assignedTechnician

    const response = await axiosPrivate.put<MaintenanceTicket>(
      `/maintenance/tickets/${id}`,
      requestData
    )
    return response.data
  },

  deleteTicket: async (ticketId: string): Promise<void> => {
    await axiosPrivate.delete(`/maintenance/tickets/${ticketId}`)
  },

  getStats: async (
    technicianEmail?: string | null
  ): Promise<MaintenanceStats> => {
    const params = technicianEmail ? { technicianEmail } : {}
    const response = await axiosPrivate.get<MaintenanceStats>(
      `/maintenance/stats`,
      { params }
    )
    return response.data
  },

  getAnalytics: async (
    filters?: MaintenanceAnalyticsFilters
  ): Promise<MaintenanceAnalyticsResponse> => {
    const params = new URLSearchParams()

    if (filters?.startDate) {
      params.append('startDate', filters.startDate)
    }
    if (filters?.endDate) {
      params.append('endDate', filters.endDate)
    }
    if (filters?.technicianId) {
      params.append('technicianId', filters.technicianId)
    }

    const response = await axiosPrivate.get<MaintenanceAnalyticsResponse>(
      `/maintenance/analytics?${params.toString()}`
    )
    return response.data
  },

  // Comments
  addComment: async (
    ticketId: string,
