  lastUpdated: string
  updateFrequency: number
  metrics: {
    totalActive: number
    pending: number
    assigned: number
    inProgress: number
    pendingTechnicalReport: number
    completedToday: number
    urgent: number
    overdue: number
    techniciansAvailable: string
    averageWorkload: number
    avgResolutionTimeHours: number
    completedLast30Days: number
