  }
}

// Public API functions for TV display (no auth required)
const maintenancePublicAPI = {
  // Get TV display data - single endpoint with all data
  getTVDisplayData: async (): Promise<TVDisplayData> => {
    const response = await axiosPublic.get<TVDisplayData>(
      `/public/maintenance/tv-display`,
      {
        // This endpoint is intentionally public and must not send auth cookies,
        // otherwise browsers reject wildcard/public CORS responses.
        withCredentials: false
      }
    )
    return response.data
  }
}

// WebSocket hook for TV display with real-time updates
export const useTVDisplayDataWithWebSocket = () => {
  const queryClient = useQueryClient()
  const wsRef = useRef<WebSocket | null>(null)
  const reconnectTimeoutRef = useRef<NodeJS.Timeout | null>(null)
  const reconnectAttempts = useRef(0)
  const maxReconnectAttempts = 5
  const [isWebSocketConnected, setIsWebSocketConnected] = useState(false)
  const [isSocketConnecting, setIsSocketConnecting] = useState(true)
  const [retryCount, setRetryCount] = useState(0)

  // Initial data fetch
  const queryResult = useQuery({
    queryKey: ['tv-display-data'],
    queryFn: maintenancePublicAPI.getTVDisplayData,
    staleTime: isWebSocketConnected ? Infinity : 10000,
    refetchOnWindowFocus: false,
    refetchInterval: isWebSocketConnected ? false : 30000,
    retryDelay: 1000
  })

  const connectWebSocket = useCallback(() => {
    const wsUrl = import.meta.env.VITE_WS_URL || 'ws://localhost:5050'
    const wsWithChannel = `${wsUrl}?channel=tv-display&public=true`

    try {
      setIsSocketConnecting(true)
      wsRef.current = new WebSocket(wsWithChannel)

      wsRef.current.onopen = () => {
        logger.log('TV Display WebSocket connected')
        reconnectAttempts.current = 0
        setRetryCount(0)
        setIsWebSocketConnected(true)
        setIsSocketConnecting(false)

        // Send subscription message for TV display updates
        wsRef.current?.send(
          JSON.stringify({
            type: 'subscribe',
            channel: 'tv-display',
            timestamp: new Date().toISOString()
          })
        )
      }

      wsRef.current.onmessage = (event) => {
        try {
          const message = JSON.parse(event.data)
          handleWebSocketMessage(message)
        } catch (error) {
          logger.error('Error parsing TV Display WebSocket message:', error)
        }
      }

      wsRef.current.onclose = (event) => {
        logger.log(
          'TV Display WebSocket connection closed:',
          event.code,
          event.reason
        )
        setIsWebSocketConnected(false)
        setIsSocketConnecting(false)

        // Only attempt to reconnect if it wasn't a manual close
        if (
          event.code !== 1000 &&
          reconnectAttempts.current < maxReconnectAttempts
        ) {
          const delay = Math.min(
            1000 * Math.pow(2, reconnectAttempts.current),
            30000
          )
          reconnectAttempts.current++

          logger.log(
            `Reconnecting TV Display WebSocket in ${delay}ms (attempt ${reconnectAttempts.current}/${maxReconnectAttempts})`
          )
          setRetryCount(reconnectAttempts.current)
          queryClient.invalidateQueries({ queryKey: ['tv-display-data'] })

          reconnectTimeoutRef.current = setTimeout(() => {
            connectWebSocket()
          }, delay)
        }
      }

      wsRef.current.onerror = (error) => {
        logger.error('TV Display WebSocket error:', error)
        setIsWebSocketConnected(false)
      }
    } catch (error) {
      logger.error('Error creating TV Display WebSocket connection:', error)
      setIsWebSocketConnected(false)
      setIsSocketConnecting(false)
    }
  }, [queryClient])

  const handleWebSocketMessage = useCallback(
    (message: any) => {
      switch (message.type) {
        case 'tv_display_update':
          // Update the cache with new data
          queryClient.setQueryData(['tv-display-data'], message.data)
          break
        case 'ticket_updated':
        case 'ticket_created':
        case 'ticket_assigned':
        case 'ticket_status_changed':
          // Invalidate and refetch when tickets change
          queryClient.invalidateQueries({ queryKey: ['tv-display-data'] })
          break
        default:
          logger.log(
            'Unknown TV Display WebSocket message type:',
            message.type
          )
      }
    },
    [queryClient]
  )

  const disconnect = useCallback(() => {
    if (reconnectTimeoutRef.current) {
      clearTimeout(reconnectTimeoutRef.current)
      reconnectTimeoutRef.current = null
    }

    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
      wsRef.current.close(1000, 'Manual disconnect')
    }

    wsRef.current = null
    reconnectAttempts.current = 0
    setIsWebSocketConnected(false)
    setIsSocketConnecting(false)
    setRetryCount(0)
  }, [])

  // Connect WebSocket on mount
  useEffect(() => {
    connectWebSocket()
    return () => {
      disconnect()
    }
  }, [connectWebSocket, disconnect])

  return {
    ...queryResult,
    isWebSocketConnected,
    isSocketConnecting,
    retryCount
  }
}

