import { useEffect, useCallback, useRef } from 'react'
import { useQueryClient } from 'react-query'
import {
  MaintenanceTicket,
  MaintenanceNotification
} from '../types/maintenance'

import { logger } from 'src/utils/logger'
interface MaintenanceWebSocketMessage {
  type: 'ticket_updated' | 'notification' | 'technician_status_changed'
  data: any
  timestamp: string
}

interface UseMaintenanceWebSocketProps {
  onNotification?: (notification: MaintenanceNotification) => void
  onTicketUpdate?: (ticket: MaintenanceTicket) => void
  enabled?: boolean
}

/**
 * Custom hook for handling real-time maintenance updates via WebSocket
 *
 * @param onNotification - Callback for new notifications
 * @param onTicketUpdate - Callback for ticket updates
 * @param enabled - Whether the WebSocket connection should be active
 */
export const useMaintenanceWebSocket = ({
  onNotification,
  onTicketUpdate,
  enabled = true
}: UseMaintenanceWebSocketProps = {}) => {
  const queryClient = useQueryClient()
  const wsRef = useRef<WebSocket | null>(null)
  const reconnectTimeoutRef = useRef<NodeJS.Timeout | null>(null)
  const reconnectAttempts = useRef(0)
  const maxReconnectAttempts = 5

  const connect = useCallback(() => {
    if (!enabled) return

    const token = localStorage.getItem('token')
    if (!token) {
      logger.warn('No token found, skipping WebSocket connection')
      return
    }

    const wsUrl = import.meta.env.VITE_WS_URL || 'ws://localhost:5050'
    const wsWithToken = `${wsUrl}?token=${token}&channel=maintenance`

    try {
      wsRef.current = new WebSocket(wsWithToken)

      wsRef.current.onopen = () => {
        logger.log('Maintenance WebSocket connected')
        reconnectAttempts.current = 0

        // Send ping to confirm connection
        wsRef.current?.send(
          JSON.stringify({
            type: 'ping',
            timestamp: new Date().toISOString()
          })
        )
      }

      wsRef.current.onmessage = (event) => {
        try {
          const message: MaintenanceWebSocketMessage = JSON.parse(event.data)
          handleWebSocketMessage(message)
        } catch (error) {
          logger.error('Error parsing WebSocket message:', error)
        }
      }

      wsRef.current.onclose = (event) => {
        logger.log(
          'Maintenance WebSocket connection closed:',
          event.code,
          event.reason
        )

        // Only attempt to reconnect if it wasn't a manual close
        if (
          enabled &&
          event.code !== 1000 &&
          reconnectAttempts.current < maxReconnectAttempts
        ) {
          const delay = Math.min(
            1000 * Math.pow(2, reconnectAttempts.current),
            30000
          )
          reconnectAttempts.current++

          logger.log(
            `Attempting to reconnect in ${delay}ms (attempt ${reconnectAttempts.current}/${maxReconnectAttempts})`
          )

          reconnectTimeoutRef.current = setTimeout(() => {
            connect()
          }, delay)
        }
      }

      wsRef.current.onerror = (error) => {
        logger.error('Maintenance WebSocket error:', error)
      }
    } catch (error) {
      logger.error('Error creating WebSocket connection:', error)
    }
  }, [enabled])

  const handleWebSocketMessage = useCallback(
    (message: MaintenanceWebSocketMessage) => {
      switch (message.type) {
        case 'ticket_updated':
          handleTicketUpdate(message.data)
          break

        case 'notification':
          handleNotification(message.data)
          break

        case 'technician_status_changed':
          handleTechnicianStatusChange(message.data)
          break

        default:
          logger.log('Unknown WebSocket message type:', message.type)
      }
    },
    [onNotification, onTicketUpdate, queryClient]
  )

  const handleTicketUpdate = useCallback(
    (ticket: MaintenanceTicket) => {
      // Update React Query cache
      queryClient.setQueryData(['maintenance-ticket', ticket.id], ticket)

      // Invalidate related queries
      queryClient.invalidateQueries({ queryKey: ['maintenance-tickets'] })
      queryClient.invalidateQueries({ queryKey: ['maintenance-stats'] })

      // Call custom callback
      onTicketUpdate?.(ticket)
    },
    [queryClient, onTicketUpdate]
  )

  const handleNotification = useCallback(
    (notification: MaintenanceNotification) => {
      // Show notification to user
      onNotification?.(notification)

      // Update cache if needed
      queryClient.invalidateQueries({ queryKey: ['maintenance-notifications'] })
    },
    [queryClient, onNotification]
  )

  const handleTechnicianStatusChange = useCallback(
    (_data: any) => {
      // Invalidate technicians query to get updated status
      queryClient.invalidateQueries({ queryKey: ['maintenance-technicians'] })
    },
    [queryClient]
  )

  const disconnect = useCallback(() => {
    if (reconnectTimeoutRef.current) {
      clearTimeout(reconnectTimeoutRef.current)
      reconnectTimeoutRef.current = null
    }

    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
      wsRef.current.close(1000, 'Manual disconnect')
    }

    wsRef.current = null
    reconnectAttempts.current = 0
  }, [])

  const sendMessage = useCallback((message: any) => {
    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
      wsRef.current.send(
        JSON.stringify({
          ...message,
          timestamp: new Date().toISOString()
        })
      )
    }
  }, [])

  // Connection management
  useEffect(() => {
    if (enabled) {
      connect()
    } else {
      disconnect()
    }

    return () => {
      disconnect()
    }
  }, [enabled, connect, disconnect])

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      disconnect()
    }
  }, [disconnect])

  // Return connection status and methods
  const isConnected = wsRef.current?.readyState === WebSocket.OPEN
  const isConnecting = wsRef.current?.readyState === WebSocket.CONNECTING

  return {
    isConnected,
    isConnecting,
    connect,
    disconnect,
    sendMessage
  }
}

export default useMaintenanceWebSocket

import { useCallback, useRef, useState } from 'react'
import {
  MRT_ColumnFiltersState,
  MRT_PaginationState,
  MRT_SortingState,
  MRT_VisibilityState,
  MRT_DensityState
} from 'material-react-table'

import { logger } from 'src/utils/logger'
// Complete table state interface
export interface TableState {
  columnFilters: MRT_ColumnFiltersState
  sorting: MRT_SortingState
  pagination: MRT_PaginationState
  columnVisibility?: MRT_VisibilityState
  density?: MRT_DensityState
}

// Configuration options for the hook
export interface UsePersistentTableStateOptions {
  tableId: string
  persistedProperties?: Array<keyof TableState>
  useBackendApi?: boolean
  debounceMs?: number
  defaultState?: Partial<TableState>
}

// Default table state
const DEFAULT_TABLE_STATE: TableState = {
  columnFilters: [],
  sorting: [],
  pagination: {
    pageIndex: 0,
    pageSize: 10
  },
  columnVisibility: {},
  density: 'comfortable'
}

// Debounce utility function
const useDebounce = (callback: (...args: any[]) => void, delay: number) => {
  const timeoutRef = useRef<NodeJS.Timeout>()

  return useCallback(
    (...args: any[]) => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current)
      }
      timeoutRef.current = setTimeout(() => callback(...args), delay)
    },
    [callback, delay]
  )
}

// Validate table state structure
const validateState = (state: any): state is Partial<TableState> => {
  if (!state || typeof state !== 'object') return false

  const validKeys: Array<keyof TableState> = [
    'columnFilters',
    'sorting',
    'pagination',
    'columnVisibility',
    'density'
  ]
  const stateKeys = Object.keys(state)

  return stateKeys.every((key) => validKeys.includes(key as keyof TableState))
}

// Load state from localStorage
const loadStateFromStorage = (
  tableId: string,
  defaultState: TableState
): TableState => {
  try {
    const savedState = localStorage.getItem(`table-state-${tableId}`)
    if (!savedState) return defaultState

    const parsedState = JSON.parse(savedState)
    if (!validateState(parsedState)) {
      logger.warn(`Invalid table state for ${tableId}, using default`)
      return defaultState
    }

    return { ...defaultState, ...parsedState }
  } catch (error) {
    logger.error(`Error loading table state for ${tableId}:`, error)
    return defaultState
  }
}

// Save state to localStorage
const saveStateToStorage = (
  tableId: string,
  state: Partial<TableState>,
  persistedProperties: Array<keyof TableState>
) => {
  try {
    const stateToSave: Partial<TableState> = {}
    persistedProperties.forEach((prop) => {
      if (state[prop] !== undefined) {
        ;(stateToSave as any)[prop] = state[prop]
      }
    })

    localStorage.setItem(`table-state-${tableId}`, JSON.stringify(stateToSave))
  } catch (error) {
    logger.error(`Error saving table state for ${tableId}:`, error)
  }
}

/**
 * Generic hook for persistent table state across all MaterialReactTable components
 *
 * @param options Configuration options for the hook
 * @returns Table state and handlers for MaterialReactTable
 */
export const usePersistentTableState = (
  options: UsePersistentTableStateOptions
) => {
  const {
    tableId,
    persistedProperties = ['columnFilters', 'sorting', 'pagination'],
    useBackendApi = false,
    debounceMs = 300,
    defaultState = {}
  } = options

  // Merge default state with provided default state
  const mergedDefaultState: TableState = {
    ...DEFAULT_TABLE_STATE,
    ...defaultState
  }

  // Initialize state
  const [tableState, setTableState] = useState<TableState>(() =>
    loadStateFromStorage(tableId, mergedDefaultState)
  )

  // Debounced save function
  const debouncedSave = useDebounce((state: TableState) => {
    saveStateToStorage(tableId, state, persistedProperties)

    // TODO: Add backend API call here if useBackendApi is true
    if (useBackendApi) {
      // Future implementation for backend persistence
      logger.log(`Would save to backend API for table ${tableId}:`, state)
    }
  }, debounceMs)

  // Generic state update function
  const updateTableState = useCallback(
    (updates: Partial<TableState>) => {
      setTableState((prevState) => {
        const newState = { ...prevState, ...updates }
        debouncedSave(newState)
        return newState
      })
    },
    [debouncedSave]
  )

  // Individual state handlers
  const handleColumnFiltersChange = useCallback(
    (updater: any) => {
      const newFilters =
        typeof updater === 'function'
          ? updater(tableState.columnFilters)
          : updater
      updateTableState({ columnFilters: newFilters })
    },
    [tableState.columnFilters, updateTableState]
  )

  const handleSortingChange = useCallback(
    (updater: any) => {
      const newSorting =
        typeof updater === 'function' ? updater(tableState.sorting) : updater
      updateTableState({ sorting: newSorting })
    },
    [tableState.sorting, updateTableState]
  )

  const handlePaginationChange = useCallback(
    (updater: any) => {
      const newPagination =
        typeof updater === 'function' ? updater(tableState.pagination) : updater
      updateTableState({ pagination: newPagination })
    },
    [tableState.pagination, updateTableState]
  )

  const handleColumnVisibilityChange = useCallback(
    (updater: any) => {
      const newVisibility =
        typeof updater === 'function'
          ? updater(tableState.columnVisibility || {})
          : updater
      updateTableState({ columnVisibility: newVisibility })
    },
    [tableState.columnVisibility, updateTableState]
  )

  const handleDensityChange = useCallback(
    (updater: any) => {
      const newDensity =
        typeof updater === 'function'
          ? updater(tableState.density || 'comfortable')
          : updater
      updateTableState({ density: newDensity })
    },
    [tableState.density, updateTableState]
  )

  // Clear state function
  const clearState = useCallback(() => {
    localStorage.removeItem(`table-state-${tableId}`)
    setTableState(mergedDefaultState)
  }, [tableId, mergedDefaultState])

  // Clear only filters function (keep pagination/other settings)
  const clearFilters = useCallback(() => {
    const clearedState = {
      ...tableState,
      columnFilters: [],
      sorting: [],
      pagination: {
        pageIndex: 0,
        pageSize: tableState.pagination.pageSize // Keep current page size
      }
    }
    setTableState(clearedState)
    debouncedSave(clearedState)
  }, [tableState, debouncedSave])

  // Load state function (for manual refresh)
  const loadState = useCallback(() => {
    const loadedState = loadStateFromStorage(tableId, mergedDefaultState)
    setTableState(loadedState)
  }, [tableId, mergedDefaultState])

  return {
    // Current state
    tableState,

    // Individual state properties for easy access
    columnFilters: tableState.columnFilters,
    sorting: tableState.sorting,
    pagination: tableState.pagination,
    columnVisibility: tableState.columnVisibility,
    density: tableState.density,

    // Event handlers for MaterialReactTable
    onColumnFiltersChange: handleColumnFiltersChange,
    onSortingChange: handleSortingChange,
    onPaginationChange: handlePaginationChange,
    onColumnVisibilityChange: handleColumnVisibilityChange,
    onDensityChange: handleDensityChange,

    // Utility functions
    updateTableState,
    clearState,
    clearFilters,
    loadState
  }
}

import { useState, useEffect, useMemo } from 'react'
import { formatDistanceToNow, parseISO, format } from 'date-fns'
import { es } from 'date-fns/locale'

interface UseRelativeTimeOptions {
  updateInterval?: number // in milliseconds
  showSeconds?: boolean
  addSuffix?: boolean
}

export const useRelativeTime = (
  dateString: string | null | undefined,
  options: UseRelativeTimeOptions = {}
) => {
  const {
    updateInterval = 60000, // Update every minute by default
    showSeconds = false,
    addSuffix = true
  } = options

  const [, forceUpdate] = useState({})

  // Parse the date once and memoize it
  const date = useMemo(() => {
    if (!dateString) return null
    try {
      return parseISO(dateString)
    } catch {
      return null
    }
  }, [dateString])

  // Force re-renders to keep the relative time updated
  useEffect(() => {
    if (!date) return

    const interval = setInterval(() => {
      forceUpdate({})
    }, updateInterval)

    return () => clearInterval(interval)
  }, [date, updateInterval])

  const relativeTime = useMemo(() => {
    if (!date) return null

    try {
      return formatDistanceToNow(date, {
        addSuffix,
        locale: es,
        includeSeconds: showSeconds
      })
    } catch {
      return null
    }
  }, [date, addSuffix, showSeconds, forceUpdate])

  const absoluteTime = useMemo(() => {
    if (!date) return null

    try {
      return format(date, 'PPpp', { locale: es })
    } catch {
      return null
    }
  }, [date])

  const shortAbsoluteTime = useMemo(() => {
    if (!date) return null

    try {
      return format(date, 'dd/MM/yyyy HH:mm', { locale: es })
    } catch {
      return null
    }
  }, [date])

  return {
    relativeTime,
    absoluteTime,
    shortAbsoluteTime,
    date,
    isValid: date !== null
  }
}

export default useRelativeTime

