        return date ? format(new Date(date), 'dd/MM/yyyy') : 'N/A'
      }
    },
    {
      accessorKey: 'supplier.name',
      header: 'Proveedor',
      size: 220,
      Cell: ({ cell, row }) => (
        <Stack>
          <Typography variant='body2'>{cell.getValue<string>()}</Typography>
          <Typography variant='caption' color='text.secondary'>
            {row.original.supplier?.phone}
          </Typography>
        </Stack>
      )
    },
    {
      id: 'sent',
      header: 'Enviada',
      size: 170,
      enableSorting: false,
      Cell: ({ row }) => {
        const order = row.original
        return (
          <Stack direction='row' alignItems='center' spacing={0.5}>
            <Tooltip
              title={
                order.sentAt
                  ? `Enviada el ${format(new Date(order.sentAt), 'dd/MM/yyyy')}. Clic para desmarcar`
                  : 'Marcar como enviada al proveedor'
              }
            >
              <Checkbox
                size='small'
                checked={!!order.sentAt}
                disabled={markSent.isLoading}
                onChange={(e) =>
                  markSent.mutate({ id: order.id, sent: e.target.checked })
                }
              />
            </Tooltip>
            {order.sendOverdue && (
              <Chip
                size='small'
                color='error'
                variant='outlined'
                label={`Sin enviar · venció ${format(new Date(order.sendDeadline as string), 'dd/MM')}`}
              />
            )}
          </Stack>
        )
      }
    },
    {
      accessorKey: 'purchaseRequest.purchaseType',
      header: 'Tipo',
      size: 80,
      filterVariant: 'select',
      filterSelectOptions: ['I', 'II'],
      Cell: ({ cell }) => (
        <Chip
          label={cell.getValue<string>()}
          size='small'
          variant='outlined'
          sx={{ minWidth: 36, fontWeight: 600 }}
        />
      )
    },
    {
      id: 'verification',
      header: 'Verificación',
      size: 150,
      accessorFn: (row) => (row.verified ? 'Verificada' : 'Por verificar'),
      Cell: ({ row }) => (
        <Chip
          size='small'
          variant='outlined'
          color={row.original.verified ? 'success' : 'warning'}
          label={row.original.verified ? 'Verificada' : 'Por verificar'}
        />
      )
    },
    {
      accessorKey: 'total',
      header: 'Total',
      size: 130,
      Cell: ({ cell }) => {
        const total = cell.getValue() as number
        return total
          ? new Intl.NumberFormat('es-CO', {
              style: 'currency',
              currency: 'COP'
            }).format(total)
          : 'N/A'
      }
    }
  ]

  // Función para abrir el modal con la orden seleccionada
  const openVerificationModal = (purchaseOrder: IPurchaseOrder) => {
    setSelectedPurchaseOrder(purchaseOrder)
    setModalOpen(true)
  }

  // Manejo del éxito en la creación de la verificación
  const handleVerificationSuccess = () => {
    // Aquí podrías refrescar los datos o mostrar una notificación
    queryClient.invalidateQueries('purchaseOrders')
    setModalOpen(false)
    setSelectedPurchaseOrder(null)
  }

  return (
    <>
      <PurchasesPage
        title='Órdenes de compra'
        subtitle='Controla que cada orden salga al proveedor y se verifique al recibirla'
        icon={<ReceiptLong />}
        stats={
          <Grid container spacing={2} sx={{ mb: 3 }}>
            {/* Cada tarjeta filtra la tabla; un segundo clic quita el filtro */}
            <Grid item xs={12} sm={4}>
              <LmsStatCard
                variant='quiet'
                label='Sin enviar'
                value={unsentCount}
                icon={<SendOutlined />}
                tone='orange'
                active={quickFilter === 'unsent'}
                onClick={() => toggleQuick('unsent')}
              />
            </Grid>
            <Grid item xs={12} sm={4}>
              <LmsStatCard
                variant='quiet'
                label='Envío vencido (3 días hábiles)'
                value={overdueCount}
                icon={<ScheduleSend />}
                tone='red'
                active={quickFilter === 'overdue'}
                onClick={() => toggleQuick('overdue')}
              />
            </Grid>
            <Grid item xs={12} sm={4}>
              <LmsStatCard
                variant='quiet'
                label='Sin verificar'
                value={unverifiedCount}
                icon={<FactCheck />}
                tone='blue'
                active={quickFilter === 'unverified'}
                onClick={() => toggleQuick('unverified')}
              />
            </Grid>
          </Grid>
        }
      >
        <DataTable
          columns={columns}
          data={filteredOrders}
          itemLabel={['orden', 'órdenes']}
          searchPlaceholder='Buscar órdenes'
          state={{ isLoading }}
          enableRowActions
          initialState={{ density: 'compact' }}
          // PurchasesPage ya pone el marco de la tabla
          muiTablePaperProps={{ elevation: 0 }}
          renderRowActions={({ row }) => (
            <RenderRowActions
              row={row}
              openVerificationModal={openVerificationModal}
            />
          )}
          muiTableBodyRowProps={({ row }) => {
            const { verified, requestDate, sendOverdue } = row.original

            if (sendOverdue) {
              return {
                sx: {
                  backgroundColor: 'rgba(244, 67, 54, 0.10)',
                  '&:hover': { backgroundColor: 'rgba(244, 67, 54, 0.18)' }
                }
              }
            }

            if (verified) return {}

            const daysPast = differenceInDays(new Date(), new Date(requestDate))
            if (daysPast > 20) {
              return {
                sx: {
                  backgroundColor: 'rgba(255, 165, 0, 0.15)',
                  '&:hover': { backgroundColor: 'rgba(255, 165, 0, 0.25)' }
                }
              }
            }
            return {}
          }}
        />
      </PurchasesPage>

      {selectedPurchaseOrder && (
        <CreatePurchaseVerificationModal
          open={modalOpen}
          onClose={() => {
            setModalOpen(false)
            setSelectedPurchaseOrder(null)
          }}
          onSuccess={handleVerificationSuccess}
          purchaseOrder={selectedPurchaseOrder}
        />
      )}
    </>
  )
}

export default PurchaseOrders

interface RenderRowActionsProps {
  row: any
  openVerificationModal: (purchaseOrder: IPurchaseOrder) => void
}

const RenderRowActions: React.FC<RenderRowActionsProps> = ({
  row,
  openVerificationModal
}) => {
  const isVerified = row.original.verified
  return (
    <Stack direction='row' spacing={0.5} alignItems='center'>
      <Tooltip title='Ver'>
        <IconButton
          component={Link}
          to={`${row.original.id}`}
          size='small'
          aria-label={`Ver ${row.original.code}`}
          sx={{ color: '#00695C' }}
        >
          <Visibility />
        </IconButton>
      </Tooltip>
      {!isVerified && (
        <Button
          size='small'
          variant='contained'
          startIcon={<FactCheck />}
          onClick={() => openVerificationModal(row.original)}
          sx={{
            bgcolor: '#00BFA5',
            whiteSpace: 'nowrap',
            '&:hover': { bgcolor: '#00ACC1' }
          }}
        >
          Verificar
        </Button>
      )}
    </Stack>
  )
}

import React, { useEffect, useMemo, useState } from 'react'
import { MRT_ColumnDef } from 'material-react-table'
import {
  Avatar,
  Box,
  Button,
  Chip,
  Grid,
  IconButton,
  Tooltip,
  Typography
} from '@mui/material'
import {
  AccessTime,
  Add,
  Cancel,
  CheckCircle,
  ErrorOutline,
  ListAlt,
  ShoppingCart,
  ShoppingCartCheckout
} from '@mui/icons-material'
import { PurchaseRequest as IPurchaseRequest } from './Types'
import { PurchaseRequestStatus } from './Enums'
import { differenceInDays, format } from 'date-fns'

import RenderRowActions from 'src/Components/Purchases/RenderRowActions'
import { useQueryClient } from 'react-query'
import {
  PURCHASE_REQUEST_EXACT_FILTERS,
  PURCHASE_REQUEST_SORTABLE_FIELDS,
  useApprovedPurchaseRequests,
  usePurchaseRequestCounts,
  usePurchaseRequestsPaginated,
  useSetInitialPurchaseRequestId
} from 'src/hooks/purchases/usePurchaseRequests'
import {
  useKeepPageInRange,
  useServerTableState
} from 'src/hooks/useServerTable'
import { useSuppliers } from 'src/hooks/purchases/useSuppliers'
import { useCan } from '@utils/functions'
import { PurchaseRequestModal } from 'src/Components/Purchases/purchase-request-modal'
import { useNavigate } from 'react-router-dom'
import { FaUser } from 'react-icons/fa'

// Import the new generic solution
import { usePersistentTableState } from '../../hooks/usePersistentTableState'
import {
  createTableStateHandlers,
  generateTableId,
  getModuleTableConfig
} from '../../utils/tableStateUtils'
import ActiveFiltersIndicator from '../../Components/Table/ActiveFiltersIndicator'
import PurchasesPage from 'src/Components/Purchases/PurchasesPage'
import LmsStatCard from 'src/Components/lms/admin/LmsStatCard'
import DataTable from 'src/Components/Common/DataTable'
import {
  PURCHASE_TEAL,
  PURCHASE_TEAL_HOVER
} from 'src/Components/Purchases/purchaseTableStyle'

type QuickFilter = 'all' | 'pending' | 'toOrder' | 'late'

import { PERMISSIONS } from 'src/constants/permissions'
import { notify } from 'src/utils/notify'
import { promptDialog } from 'src/utils/confirm'

const PurchaseRequest: React.FC = () => {
  const navigate = useNavigate()
  const queryClient = useQueryClient()
  const allowCreationRequest = useCan(PERMISSIONS.PURCHASES_REQUEST_CREATE)

  // Use the new generic persistent table state
  const tableConfig = getModuleTableConfig('purchases')
  const persistentTableState = usePersistentTableState({
    tableId: generateTableId('purchases', 'purchase-requests'),
    persistedProperties: tableConfig.persistedProperties,
    defaultState: {
      pagination: {
        pageIndex: 0,
        pageSize: tableConfig.defaultPageSize
      }
    }
  })

  // Create standardized event handlers
  const tableHandlers = createTableStateHandlers(persistentTableState)
  const [quickFilter, setQuickFilter] = useState<QuickFilter>('all')

  // Filtros guardados de versiones anteriores sobre columnas que ya no se
  // filtran (la tabla filtra en el servidor): se descartan.
  const { columnFilters: savedFilters, onColumnFiltersChange } =
    persistentTableState
  useEffect(() => {
    const allowed = savedFilters.filter((filter) =>
      (PURCHASE_REQUEST_EXACT_FILTERS as readonly string[]).includes(filter.id)
    )
    if (allowed.length !== savedFilters.length) onColumnFiltersChange(allowed)
  }, [savedFilters, onColumnFiltersChange])

  // "Todas" y "Pendientes" se paginan en el servidor; "Por generar orden" y
  // "Sin orden" se filtran en el cliente sobre las solicitudes aprobadas
  // (el endpoint no sabe filtrar por "sin orden de compra").
  const serverMode = quickFilter === 'all' || quickFilter === 'pending'
  const server = useServerTableState({
    sortableFields: PURCHASE_REQUEST_SORTABLE_FIELDS,
    exactFilters: PURCHASE_REQUEST_EXACT_FILTERS,
    pagination: persistentTableState.pagination,
    onPaginationChange: persistentTableState.onPaginationChange,
    sorting: persistentTableState.sorting,
    onSortingChange: persistentTableState.onSortingChange,
    columnFilters: persistentTableState.columnFilters,
    onColumnFiltersChange: persistentTableState.onColumnFiltersChange
  })
  const pageParams = useMemo(
    () =>
      quickFilter === 'pending'
        ? { ...server.params, status: PurchaseRequestStatus.Pending }
        : server.params,
    [server.params, quickFilter]
  )
  const {
    data: requestsPage,
    isLoading: pageLoading,
    isFetching: pageFetching
  } = usePurchaseRequestsPaginated(pageParams, { enabled: serverMode })
  useKeepPageInRange(
    serverMode ? requestsPage?.totalPages : undefined,
    server.pagination.pageIndex,
    server.setPagination
  )
  const { data: requestCounts } = usePurchaseRequestCounts()
  const { data: approvedRequests = [], isLoading: approvedLoading } =
    useApprovedPurchaseRequests()
  // Precarga el listado de proveedores (caché compartida con /suppliers)
  useSuppliers()
  const setInitialId = useSetInitialPurchaseRequestId()

  const totalRecords = requestCounts?.total ?? 0
  const isLoading = serverMode ? pageLoading : approvedLoading

  // Aprobadas (o pre-aprobadas) que todavía no tienen orden de compra
  const needsOrder = (r: IPurchaseRequest) =>
    (r.status === PurchaseRequestStatus.PreApproved ||
      r.status === PurchaseRequestStatus.Accepted) &&
    !r.hasOrder
  const isLate = (r: IPurchaseRequest) =>
    needsOrder(r) && differenceInDays(new Date(), new Date(r.createdAt)) > 7

  const counts = useMemo(
    () => ({
      pending: requestCounts?.pending ?? 0,
      toOrder: approvedRequests.filter(needsOrder).length,
      late: approvedRequests.filter(isLate).length
    }),
    [approvedRequests, requestCounts]
  )

  const purchaseRequests = useMemo(() => {
    switch (quickFilter) {
      case 'toOrder':
        return approvedRequests.filter(needsOrder)
      case 'late':
        return approvedRequests.filter(isLate)
      default:
        return requestsPage?.items ?? []
    }
  }, [approvedRequests, requestsPage, quickFilter])

  const changeQuickFilter = (value: QuickFilter) => {
    setQuickFilter(value)
    server.goToFirstPage()
  }
  const toggleQuick = (value: QuickFilter) =>
    changeQuickFilter(quickFilter === value ? 'all' : value)

  const [modalOpen, setModalOpen] = useState(false)
  const [editModalOpen, setEditModalOpen] = useState(false)
  const [selectedPREdit, setSelectedPREdit] = useState<IPurchaseRequest | null>(
    null
  )

  const handleOpenEditModal = (purchaseRequest: IPurchaseRequest) => {
    setSelectedPREdit(purchaseRequest)
    setEditModalOpen(true)
  }

  const handleCloseEditModal = () => {
    setSelectedPREdit(null)
    setEditModalOpen(false)
  }

  const handleEditSuccess = () => {
    queryClient.invalidateQueries('purchaseRequests')
    // No necesitas llamar a handleCloseEditModal aquí si el modal se cierra solo
    // o si onSuccess en el modal ya lo hace (que es el caso).
  }

  const handleSuccess = () => {
    queryClient.invalidateQueries('purchaseRequests')
  }

  // Función para mostrar el popup de configuración del número inicial
  const showInitialSetupPopup = async () => {
    const { value: initialId } = await promptDialog({
      title: 'Configurar número inicial',
      type: 'number',
      min: 1,
      placeholder: 'Ingrese el número inicial (ej. 1000)',
      confirmLabel: 'Guardar'
    })

    if (initialId) {
      try {
        await setInitialId.mutateAsync(initialId)
        notify.success('¡Configurado!', 'El número inicial ha sido establecido.')
        // La mutación invalida 'purchaseRequests' para refrescar el count
        // Abre el modal para crear la solicitud
        setModalOpen(true)
      } catch (error) {
        notify.error('Error', 'No se pudo establecer el número inicial.')
      }
    }
  }

  // Función para manejar la apertura del modal
  const handleOpenModal = () => {
    if (totalRecords === 0) {
      // Si no hay registros, se solicita configurar el número inicial
      showInitialSetupPopup()
    } else {
      // Si ya existen registros, abre el modal normalmente
      setModalOpen(true)
    }
  }

  // Definir las columnas de la tabla
  const columns: MRT_ColumnDef<IPurchaseRequest>[] = [
    {
      accessorKey: 'purchaseCode',
      header: 'Código',
      size: 150,
      enableColumnFilter: false,
      Cell: ({ cell }) => (
        <Typography variant='body2' fontWeight={600} noWrap>
          {cell.getValue<string>()}
        </Typography>
      )
    },
    {
      accessorKey: 'elaborationDate',
      header: 'Elaborada el',
      size: 120,
      enableColumnFilter: false,
      Cell: ({ cell }) => {
        const date = cell.getValue<string>()
        return date ? format(new Date(date), 'dd/MM/yyyy') : 'N/A'
      }
    },
    {
      accessorKey: 'applicantName',
      header: 'Solicitante',
      size: 230,
      // La búsqueda global ya busca por solicitante en el servidor.
      enableSorting: false,
      enableColumnFilter: false,
      Cell: ({ cell }) => {
        const name = cell.getValue<string>() ?? ''
        const initials = name
          .split(' ')
          .filter(Boolean)
          .slice(0, 2)
          .map((word) => word[0])
          .join('')
          .toUpperCase()
        return (
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
            <Avatar
              sx={{
                bgcolor: PURCHASE_TEAL,
                width: 28,
                height: 28,
                fontSize: 12
              }}
            >
              {initials}
            </Avatar>
            <Typography variant='body2' noWrap>
              {name}
            </Typography>
          </Box>
        )
      }
    },
    {
      accessorKey: 'purchaseType',
      header: 'Tipo',
      size: 80,
      enableSorting: false,
      filterVariant: 'select',
      filterSelectOptions: ['I', 'II'],
      Cell: ({ cell }) => (
        <Chip
          label={cell.getValue<string>()}
          size='small'
          variant='outlined'
          sx={{ minWidth: 36, fontWeight: 600 }}
        />
      )
    },
    // En tu archivo de columnas
    {
      accessorKey: 'status',
      header: 'Estado',
      size: 230,
      filterVariant: 'select',
      filterSelectOptions: [
        { text: 'Pendiente', value: PurchaseRequestStatus.Pending },
        { text: 'Pre-aprobado', value: PurchaseRequestStatus.PreApproved },
        { text: 'Aprobado', value: PurchaseRequestStatus.Accepted },
        { text: 'Rechazado', value: PurchaseRequestStatus.Rejected }
      ],
      Cell: ({ cell }) => {
        const status = cell.getValue() as PurchaseRequestStatus
        let color: 'warning' | 'success' | 'error'
        let estilo

        switch (status) {
          case PurchaseRequestStatus.Pending:
            color = 'warning'
            estilo = {
              backgroundColor: '#fff3e0',
              color: '#ef6c00',
              fontWeight: 600,
              borderRadius: '12px',
              padding: '4px 12px'
            }
            break
          case PurchaseRequestStatus.PreApproved:
            color = 'success'
            estilo = {
              backgroundColor: '#e8f5e9',
              color: '#2e7d32',
              fontWeight: 600,
              borderRadius: '12px',
              padding: '4px 12px'
            }
            break
          case PurchaseRequestStatus.Accepted:
            color = 'success'
            estilo = {
              backgroundColor: '#e8f5e9',
              color: '#2e7d32',
              fontWeight: 600,
              borderRadius: '12px',
              padding: '4px 12px'
            }
            break
          case PurchaseRequestStatus.Rejected:
            color = 'error'
            estilo = {
              backgroundColor: '#ffebee',
              color: '#c62828',
              fontWeight: 600,
              borderRadius: '12px',
              padding: '4px 12px'
            }
            break
          default:
            throw new Error(`Estado desconocido: ${status}`)
        }

        const chipElement = (
          <Chip
            label={status.charAt(0).toUpperCase() + status.slice(1)}
            color={color}
            variant='outlined'
            sx={{ ...estilo, backgroundColor: 'transparent' }}
            size='small'
            icon={
              {
                [PurchaseRequestStatus.Pending]: (
                  <AccessTime fontSize='small' />
                ),
                [PurchaseRequestStatus.Accepted]: (
                  <CheckCircle fontSize='small' />
                ),
                [PurchaseRequestStatus.PreApproved]: (
                  <CheckCircle fontSize='small' />
                ),
                [PurchaseRequestStatus.Rejected]: <Cancel fontSize='small' />
              }[status]
            }
          />
        )

        if (status === PurchaseRequestStatus.Rejected) {
          const rejectionReason = cell.row.original.rejectionReason
          return (
            <Tooltip arrow title={rejectionReason || 'Sin motivo de rechazo'}>
              {chipElement}
            </Tooltip>
          )
        }

        const request = cell.row.original
        if (isLate(request)) {
          const days = differenceInDays(new Date(), new Date(request.createdAt))
          return (
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
              {chipElement}
              <Chip
                label={`Sin orden · ${days} días`}
                size='small'
                color='warning'
                variant='outlined'
              />
            </Box>
          )
        }

        return chipElement
      }
    },
    {
      accessorKey: 'approvalDate',
      header: 'Aprobada el',
      size: 120,
      enableSorting: false,
      enableColumnFilter: false,
      Cell: ({ cell }) => {
        const date = cell.getValue() as string
        return date ? format(new Date(date), 'dd/MM/yyyy') : 'N/A'
      }
    }
    // {
    //   accessorKey: 'approver.nombre',
    //   header: 'Aprobado por',
    //   Cell: ({ cell }) => {
    //     const approver = cell.row.original.approver
    //     const approverName =
    //       approver && approver.nombre ? approver.nombre : 'N/A'
    //     return approverName
    //   }
    // }
  ]

  return (
    <>
      <PurchasesPage
        title='Solicitudes de compra'
        subtitle='Pide, aprueba y haz seguimiento de lo que necesita cada área'
        icon={<ShoppingCart />}
        actions={
          allowCreationRequest && (
            <>
              <Tooltip title='Crear personal de compras'>
                <IconButton
                  onClick={() => navigate('/purchases/personnel-management')}
                  sx={{ color: PURCHASE_TEAL }}
                >
                  <FaUser />
                </IconButton>
              </Tooltip>
              <Button
                variant='contained'
                onClick={handleOpenModal}
                startIcon={<Add />}
                sx={{
                  bgcolor: PURCHASE_TEAL,
                  '&:hover': { bgcolor: PURCHASE_TEAL_HOVER }
                }}
              >
                Nueva solicitud
              </Button>
            </>
          )
        }
        stats={
          <Grid container spacing={3} sx={{ mb: 3 }}>
            <Grid item xs={6} md={3}>
              <LmsStatCard variant='quiet'
                label='Todas'
                value={totalRecords}
                icon={<ListAlt />}
                tone='teal'
                active={quickFilter === 'all'}
                onClick={() => changeQuickFilter('all')}
              />
            </Grid>
            <Grid item xs={6} md={3}>
              <LmsStatCard variant='quiet'
                label='Pendientes de aprobar'
                value={counts.pending}
                icon={<AccessTime />}
                tone='orange'
                active={quickFilter === 'pending'}
                onClick={() => toggleQuick('pending')}
              />
            </Grid>
            <Grid item xs={6} md={3}>
              <LmsStatCard variant='quiet'
                label='Por generar orden'
                value={counts.toOrder}
                icon={<ShoppingCartCheckout />}
                tone='blue'
                active={quickFilter === 'toOrder'}
                onClick={() => toggleQuick('toOrder')}
              />
            </Grid>
            <Grid item xs={6} md={3}>
              <LmsStatCard variant='quiet'
                label='Sin orden hace más de 7 días'
                value={counts.late}
                icon={<ErrorOutline />}
                tone='red'
                active={quickFilter === 'late'}
                onClick={() => toggleQuick('late')}
              />
            </Grid>
          </Grid>
        }
      >
        <ActiveFiltersIndicator
          tableState={persistentTableState.tableState}
          onClearFilters={persistentTableState.clearFilters}
          showDetails={true}
        />

        <DataTable
          columns={columns}
          data={purchaseRequests}
          {...(serverMode
            ? { ...server.tableProps, rowCount: requestsPage?.totalItems ?? 0 }
            : {
                onColumnFiltersChange: server.setColumnFilters,
                onSortingChange: server.setSorting,
                onPaginationChange: server.setPagination,
                onGlobalFilterChange: server.setGlobalFilter
              })}
          state={{
            ...tableHandlers.state,
            ...server.tableState,
            isLoading,
            showProgressBars: serverMode && pageFetching && !pageLoading
          }}
          itemLabel={['solicitud', 'solicitudes']}
          searchPlaceholder='Buscar solicitudes'
          enableRowActions
          initialState={{ density: 'compact' }}
          // Ver, editar, la acción principal y el menú caben en una fila
          displayColumnDefOptions={{
            'mrt-row-actions': {
              header: 'Acciones',
              size: 270,
              muiTableHeadCellProps: {
                align: 'left',
                sx: { backgroundColor: '#f3f4f6', opacity: 1 }
              },
              muiTableBodyCellProps: {
                align: 'left',
                sx: { backgroundColor: '#fff', boxShadow: '-1px 0 0 #e5e7eb' }
              }
            }
          }}
          // PurchasesPage ya pone el marco de la tabla
          muiTablePaperProps={{ elevation: 0 }}
          renderRowActions={({ row }) => (
            <RenderRowActions
              row={row}
              queryClient={queryClient}
              onEdit={() => handleOpenEditModal(row.original)}
            />
          )}
          muiTableBodyRowProps={({ row }) =>
            isLate(row.original)
              ? {
                sx: {
                  backgroundColor: 'rgba(255, 193, 7, 0.15)',
                  '&:hover': { backgroundColor: 'rgba(255, 193, 7, 0.25)' }
                }
              }
              : {}
          }
          renderTopToolbarCustomActions={() => (
            <ActiveFiltersIndicator
              tableState={persistentTableState.tableState}
              onClearFilters={persistentTableState.clearFilters}
              compact={true}
            />
          )}
        />
      </PurchasesPage>

      <PurchaseRequestModal
        open={modalOpen}
        onClose={() => setModalOpen(false)}
        onSuccess={handleSuccess}
        //providers={providers}
      />
      {selectedPREdit && ( // Solo renderiza si hay una PR seleccionada para editar
        <PurchaseRequestModal
          open={editModalOpen}
          onClose={handleCloseEditModal}
          onSuccess={handleEditSuccess}
          existingRequest={selectedPREdit}
        />
      )}
    </>
  )
}

export default PurchaseRequest

import { getApiErrorReason } from 'src/utils/apiError'
import SignalLoader from 'src/Components/Common/SignalLoader'
import { useState } from 'react'
import {
  Bar,
  Line,
  ComposedChart,
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  Legend, 
  ResponsiveContainer 
} from 'recharts'
import { Container, Grid, Box, Alert, Button, Card, CardContent, LinearProgress, Paper, ToggleButton, ToggleButtonGroup, Typography } from '@mui/material'
import { BarChart as BarChart, DateRange, ErrorOutline, FactCheck, HourglassEmpty, ListAlt, ReceiptLong, RemoveShoppingCart } from '@mui/icons-material'
import LmsPageHeader from 'src/Components/lms/admin/LmsPageHeader'
import LmsStatCard from 'src/Components/lms/admin/LmsStatCard'
import { DatePicker } from '@mui/x-date-pickers/DatePicker'
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider'
import { AdapterDateFns } from '@mui/x-date-pickers/AdapterDateFns'
import useAxiosPrivate from '@utils/use-axios-private'
import { usePurchaseStatistics } from 'src/hooks/purchases/usePurchaseStatistics'
import { format, subDays } from 'date-fns'
import { es } from 'date-fns/locale'

import { logger } from 'src/utils/logger'
interface PurchaseStatistics {
  overview: {
    totalRequests: number
    totalOrders: number
    totalVerifications: number
    requestsWithoutOrders: number
    ordersWithoutVerification: number
    pendingVerifications: number
  }
  requestsByStatus: Array<{
    status: string
    count: number
  }>
  timeSeriesData: {
    daily: Array<{
      date: string
      orderCount: number
      totalAmount: number
    }>
    monthly: Array<{
      month: string
      orderCount: number
      totalAmount: number
    }>
    yearly: Array<{
      year: string
      orderCount: number
      totalAmount: number
    }>
  }
}

// const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884D8']

const PurchaseStatistics = () => {
  const [timeRange, setTimeRange] = useState<'daily' | 'monthly' | 'yearly'>('monthly')
  const [dateFilter, setDateFilter] = useState({
    startDate: subDays(new Date(), 30),
    endDate: new Date()
  })
  const [customDateRange, setCustomDateRange] = useState(false)
  // Estado de la consulta por rango (se dispara a mano y por ahora solo se registra)
  const [rangeLoading, setRangeLoading] = useState(false)
  const [rangeError, setRangeError] = useState<string | null>(null)

  const axiosPrivate = useAxiosPrivate()

  const {
    data: statistics,
    isLoading: statisticsLoading,
    error: statisticsError,
    refetch: refetchStatistics
  } = usePurchaseStatistics<PurchaseStatistics>({
    onError: (err) => logger.error('Error fetching purchase statistics:', err)
  })

  const loading = statisticsLoading || rangeLoading
  const error: string | null = statisticsError
    ? getApiErrorReason(statisticsError) ||
      'Error al cargar las estadísticas'
    : rangeError

  const fetchStatistics = () => {
    setRangeError(null)
    refetchStatistics()
  }

  const fetchStatisticsByDateRange = async () => {
    try {
      setRangeLoading(true)
      setRangeError(null)

      const params = {
        startDate: format(dateFilter.startDate, 'yyyy-MM-dd'),
        endDate: format(dateFilter.endDate, 'yyyy-MM-dd')
      }

      const response = await axiosPrivate.get('/purchase-statistics/date-range', { params })
      // Handle date range specific response here if needed
      logger.log('Date range statistics:', response.data)

    } catch (err: any) {
      logger.error('Error fetching date range statistics:', err)
      setRangeError(getApiErrorReason(err) || 'Error al cargar las estadísticas por fecha')
    } finally {
      setRangeLoading(false)
    }
  }

  const handleDateRangeFilter = () => {
    fetchStatisticsByDateRange()
  }

  const getStatusColor = (status: string) => {
    const statusColors: { [key: string]: string } = {
      'pendiente': '#f59e0b',
      'pre-aprobado': '#3b82f6',
      'aprobado': '#00BFA5',
      'aceptada': '#00BFA5',
      'rechazado': '#ef4444'
    }
    return statusColors[String(status).toLowerCase()] || '#9ca3af'
  }

  const formatCurrency = (value: number) => {
    if (!value || isNaN(value)) return '$0';

    return new Intl.NumberFormat('es-CO', {
      style: 'currency',
      currency: 'COP',
      minimumFractionDigits: 0,
      maximumFractionDigits: 0
    }).format(value)
  }

  const formatDate = (dateString: string) => {
    if (!dateString) return '';
    try {
      return format(new Date(dateString), 'MMM dd', { locale: es });
    } catch (error) {
      return dateString;
    }
  }

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="400px">
        <SignalLoader />
      </Box>
    )
  }

  if (error) {
    return (
      <Box p={3}>
        <Alert severity="error" action={
          <Button color="inherit" size="small" onClick={fetchStatistics}>
            Reintentar
          </Button>
        }>
          {error}
        </Alert>
      </Box>
    )
  }

  if (!statistics) {
    return (
      <Box p={3}>
        <Alert severity="info">No hay datos disponibles</Alert>
      </Box>
    )
  }

  const timeSeriesData = statistics.timeSeriesData[timeRange].map(item => {
    let formattedDate = '';
    try {
      if (timeRange === 'yearly') {
        const dateValue = 'date' in item ? item.date : 'year' in item ? item.year : '';
        formattedDate = format(new Date(dateValue), 'yyyy');
      } else if (timeRange === 'monthly') {
        const dateValue = 'date' in item ? item.date : 'month' in item ? item.month : '';
        formattedDate = format(new Date(dateValue), 'MMM yyyy', { locale: es });
      } else {
        const dateValue = 'date' in item ? item.date : '';
        formattedDate = formatDate(dateValue);
      }
    } catch (error) {
      const fallbackDate = 'date' in item ? item.date : 'month' in item ? item.month : 'year' in item ? item.year : '';
      formattedDate = fallbackDate;
    }

    return {
      ...item,
      date: formattedDate
    };
  })

  const compactCurrency = (value: number) => {
    if (value >= 1000000) return `${(value / 1000000).toFixed(1)}M`
    if (value >= 1000) return `${(value / 1000).toFixed(0)}K`
    return `${value}`
  }

  const { totalRequests, totalOrders, totalVerifications, requestsWithoutOrders, ordersWithoutVerification } = statistics.overview
  const percentOf = (part: number, whole: number) => (whole ? Math.round((part / whole) * 1000) / 10 : 0)
  const funnel = [
    { label: 'Solicitudes', value: totalRequests, rate: null as number | null, color: '#3b82f6' },
    { label: 'Órdenes de compra', value: totalOrders, rate: percentOf(totalOrders, totalRequests), color: '#00BFA5' },
    { label: 'Verificaciones', value: totalVerifications, rate: percentOf(totalVerifications, totalOrders), color: '#00695C' }
  ]
  const funnelMax = Math.max(...funnel.map((step) => step.value), 0)
  const stuckTotal = requestsWithoutOrders + ordersWithoutVerification
  const statusTotal = statistics.requestsByStatus.reduce((acc, entry) => acc + entry.count, 0)

  const chartPaperSx = { p: { xs: 2, md: 3 }, borderRadius: 2 }
  const toggleSx = {
    '& .MuiToggleButton-root': { textTransform: 'none', fontWeight: 600, px: 2 },
    '& .Mui-selected': { bgcolor: '#E0F7F4 !important', color: '#00695C' }
  }

  return (
    <Container maxWidth='xl' sx={{ py: 3 }} className='space-y-6'>
      <LmsPageHeader
        title='Estadísticas de Compras'
        subtitle='Solicitudes, órdenes y verificaciones del módulo de compras'
        icon={<BarChart />}
        actions={
          <Button
            variant={customDateRange ? 'outlined' : 'contained'}
            startIcon={<DateRange />}
            onClick={() => setCustomDateRange(!customDateRange)}
            sx={
              customDateRange
                ? { color: '#00897B', borderColor: '#00BFA5', '&:hover': { borderColor: '#00897B', bgcolor: '#E0F7F4' } }
                : { bgcolor: '#00BFA5', whiteSpace: 'nowrap', '&:hover': { bgcolor: '#00ACC1' } }
            }
          >
            {customDateRange ? 'Ocultar filtros' : 'Filtro por fechas'}
          </Button>
        }
      />

      {/* Custom Date Range Filter */}
      {customDateRange && (
        <Card>
          <CardContent>
            <LocalizationProvider dateAdapter={AdapterDateFns} adapterLocale={es}>
              <div className="flex gap-4 items-center">
                <DatePicker
                  label="Fecha Inicio"
                  value={dateFilter.startDate}
                  onChange={(date) => date && setDateFilter(prev => ({ ...prev, startDate: date }))}
                  slotProps={{ textField: { size: 'small' } }}
                />
                <DatePicker
                  label="Fecha Fin"
                  value={dateFilter.endDate}
                  onChange={(date) => date && setDateFilter(prev => ({ ...prev, endDate: date }))}
                  slotProps={{ textField: { size: 'small' } }}
                />
                <Button variant="contained" onClick={handleDateRangeFilter}>
                  Aplicar Filtro
                </Button>
              </div>
            </LocalizationProvider>
          </CardContent>
        </Card>
      )}

      {/* Overview Cards */}
      <Grid container spacing={3}>
        <Grid item xs={6} sm={4} lg={2}>
          <LmsStatCard variant='quiet' label='Total solicitudes' value={statistics.overview.totalRequests} icon={<ListAlt />} tone='blue' />
        </Grid>
        <Grid item xs={6} sm={4} lg={2}>
          <LmsStatCard variant='quiet' label='Total órdenes' value={statistics.overview.totalOrders} icon={<ReceiptLong />} tone='teal' />
        </Grid>
        <Grid item xs={6} sm={4} lg={2}>
          <LmsStatCard variant='quiet' label='Verificaciones' value={statistics.overview.totalVerifications} icon={<FactCheck />} tone='green' />
        </Grid>
        <Grid item xs={6} sm={4} lg={2}>
          <LmsStatCard variant='quiet' label='Sin orden' value={statistics.overview.requestsWithoutOrders} icon={<RemoveShoppingCart />} tone='orange' />
        </Grid>
        <Grid item xs={6} sm={4} lg={2}>
          <LmsStatCard variant='quiet' label='Sin verificar' value={statistics.overview.ordersWithoutVerification} icon={<ErrorOutline />} tone='red' />
        </Grid>
        <Grid item xs={6} sm={4} lg={2}>
          <LmsStatCard variant='quiet' label='Pendientes' value={statistics.overview.pendingVerifications} icon={<HourglassEmpty />} tone='orange' />
        </Grid>
      </Grid>

      {/* Tendencia y proceso */}
      <Grid container spacing={3}>
        <Grid item xs={12} lg={8}>
          <Paper elevation={2} sx={{ ...chartPaperSx, height: '100%' }}>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 2, flexWrap: 'wrap', mb: 2 }}>
              <Box>
                <Typography variant='h6' fontWeight={700}>
                  Órdenes y monto comprado
                </Typography>
                <Typography variant='body2' color='text.secondary'>
                  Las barras son órdenes emitidas; la línea es el monto en pesos.
                </Typography>
              </Box>
              <ToggleButtonGroup
                size='small'
                exclusive
                value={timeRange}
                onChange={(_, value) => value && setTimeRange(value)}
                aria-label='Período de la gráfica'
                sx={toggleSx}
              >
                <ToggleButton value='daily'>Diario</ToggleButton>
                <ToggleButton value='monthly'>Mensual</ToggleButton>
                <ToggleButton value='yearly'>Anual</ToggleButton>
              </ToggleButtonGroup>
            </Box>
            {timeSeriesData.length === 0 ? (
              <Box sx={{ py: 8, textAlign: 'center', color: 'text.secondary' }}>
                No hay órdenes en este período. Cambia el rango para ver otras fechas.
              </Box>
            ) : (
              <ResponsiveContainer width='100%' height={320}>
                <ComposedChart data={timeSeriesData} margin={{ top: 8, right: 8, left: 0, bottom: 0 }}>
                  <CartesianGrid vertical={false} stroke='#e5e7eb' />
                  <XAxis dataKey='date' tickLine={false} axisLine={false} tick={{ fill: '#6b7280', fontSize: 12 }} />
                  <YAxis yAxisId='left' allowDecimals={false} tickLine={false} axisLine={false} tick={{ fill: '#6b7280', fontSize: 12 }} width={32} />
                  <YAxis
                    yAxisId='right'
                    orientation='right'
                    tickLine={false}
                    axisLine={false}
                    tick={{ fill: '#6b7280', fontSize: 12 }}
                    width={56}
                    tickFormatter={compactCurrency}
                  />
                  <Tooltip
                    cursor={{ fill: 'rgba(0, 191, 165, 0.06)' }}
                    contentStyle={{ borderRadius: 12, border: '1px solid #e5e7eb', boxShadow: '0 4px 12px rgba(0,0,0,0.08)' }}
                    formatter={(value: number, name: string) => [
                      name === 'Monto' ? formatCurrency(value) : `${value} órdenes`,
                      name
                    ]}
                  />
                  <Legend iconType='circle' wrapperStyle={{ fontSize: 13 }} />
                  <Bar yAxisId='left' dataKey='orderCount' name='Órdenes' fill='#00BFA5' radius={[6, 6, 0, 0]} maxBarSize={36} />
                  <Line yAxisId='right' dataKey='totalAmount' name='Monto' stroke='#00695C' strokeWidth={2.5} dot={{ r: 3, fill: '#00695C' }} activeDot={{ r: 5 }} />
                </ComposedChart>
              </ResponsiveContainer>
            )}
          </Paper>
        </Grid>

        <Grid item xs={12} lg={4}>
          <Paper elevation={2} sx={{ ...chartPaperSx, height: '100%' }}>
            <Typography variant='h6' fontWeight={700}>
              Del pedido a la verificación
            </Typography>
            <Typography variant='body2' color='text.secondary' sx={{ mb: 3 }}>
              Cuántas solicitudes llegan a orden y cuántas órdenes se verifican.
            </Typography>
            {funnel.map((step, index) => (
              <Box key={step.label} sx={{ mb: index === funnel.length - 1 ? 0 : 2.5 }}>
                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', mb: 0.75 }}>
                  <Typography variant='body2' fontWeight={600}>
                    {step.label}
                  </Typography>
                  <Typography variant='body2' fontWeight={700}>
                    {step.value}
                  </Typography>
                </Box>
                <LinearProgress
                  variant='determinate'
                  value={funnelMax ? (step.value / funnelMax) * 100 : 0}
                  sx={{ height: 12, borderRadius: 6, bgcolor: '#E0F7F4', '& .MuiLinearProgress-bar': { borderRadius: 6, bgcolor: step.color } }}
                />
                {step.rate !== null && (
                  <Typography variant='caption' color='text.secondary'>
                    {step.rate}% de la etapa anterior
                  </Typography>
                )}
              </Box>
            ))}
            <Box sx={{ mt: 3, p: 2, borderRadius: 2, bgcolor: stuckTotal > 0 ? '#fff7ed' : '#E0F7F4' }}>
              <Typography variant='body2' fontWeight={600}>
                {stuckTotal > 0
                  ? `${stuckTotal} pendientes por atender`
                  : 'No hay pendientes por atender'}
              </Typography>
              <Typography variant='body2' color='text.secondary'>
                {stuckTotal > 0
                  ? `${statistics.overview.requestsWithoutOrders} solicitudes sin orden y ${statistics.overview.ordersWithoutVerification} órdenes sin verificar.`
                  : 'Todas las solicitudes tienen orden y todas las órdenes están verificadas.'}
              </Typography>
            </Box>
          </Paper>
        </Grid>

        <Grid item xs={12}>
          <Paper elevation={2} sx={chartPaperSx}>
            <Typography variant='h6' fontWeight={700}>
              Estado de las solicitudes
            </Typography>
            <Typography variant='body2' color='text.secondary' sx={{ mb: 2.5 }}>
              {statusTotal} solicitudes en total.
            </Typography>
            {statusTotal === 0 ? (
              <Box sx={{ py: 4, textAlign: 'center', color: 'text.secondary' }}>Aún no hay solicitudes registradas.</Box>
            ) : (
              <>
                <Box sx={{ display: 'flex', height: 14, borderRadius: 7, overflow: 'hidden', mb: 2.5 }} role='img' aria-label='Reparto de solicitudes por estado'>
                  {statistics.requestsByStatus.map((entry) => (
                    <Box key={entry.status} title={`${entry.status}: ${entry.count}`} sx={{ width: `${(entry.count / statusTotal) * 100}%`, bgcolor: getStatusColor(entry.status) }} />
                  ))}
                </Box>
                <Grid container spacing={2}>
                  {statistics.requestsByStatus.map((entry) => (
                    <Grid item xs={12} sm={6} md={4} key={entry.status}>
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
                        <Box sx={{ width: 12, height: 12, borderRadius: '50%', bgcolor: getStatusColor(entry.status), flexShrink: 0 }} />
                        <Typography variant='body2' sx={{ textTransform: 'capitalize', flexGrow: 1 }}>
                          {entry.status}
                        </Typography>
                        <Typography variant='body2' fontWeight={700}>
                          {entry.count}
                        </Typography>
                        <Typography variant='body2' color='text.secondary' sx={{ minWidth: 44, textAlign: 'right' }}>
                          {Math.round((entry.count / statusTotal) * 100)}%
                        </Typography>
                      </Box>
                    </Grid>
                  ))}
                </Grid>
              </>
            )}
          </Paper>
        </Grid>
      </Grid>
    </Container>
  )
}

