      options={getSuggestedValues(key)}
      value={assetForm[key]}
      onChange={(_, value) => updateField(key, value || '')}
      onInputChange={(_, value) => updateField(key, value)}
      fullWidth
      renderInput={(params) => (
        <TextField
          {...params}
