                <Download fontSize='small' />
              </IconButton>
            </Tooltip>
            {canManage && (
              <Tooltip title='Eliminar'>
                <IconButton
                  size='small'
                  aria-label={`Eliminar ${row.original.assetCode}`}
                  color='error'
                  onClick={() => setAssetPendingDelete(row.original)}
