            height: { xs: 'calc(100% - 64px)', md: 'calc(100% - 72px)' },
            width: { xs: '100vw', sm: 480, md: 560 },
            maxWidth: '100%',
            borderTopLeftRadius: { sm: '16px' },
            borderBottomLeftRadius: { sm: '16px' }
          }
        }}
      >
        <Box
          sx={{
            display: 'flex',
            flexDirection: 'column',
            height: '100%',
            // Mismo foco turquesa que los demás formularios
            '& .MuiOutlinedInput-root.Mui-focused .MuiOutlinedInput-notchedOutline':
              { borderColor: '#00897B' }
          }}
        >
          <Box
            sx={{
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'flex-start',
              gap: 1,
              px: 3,
              pt: 2.5,
              pb: 2,
              borderBottom: '1px solid #e5e7eb'
            }}
          >
            <Stack
              direction='row'
              spacing={1.5}
              alignItems='center'
              sx={{ minWidth: 0 }}
            >
              {assetImageUrl && (
                <Avatar
                  variant='rounded'
                  src={assetImageUrl}
                  alt={`Foto de ${selectedAsset?.name ?? 'activo'}`}
                  sx={{
                    width: 56,
                    height: 56,
                    borderRadius: '12px',
                    border: '1px solid #e5e7eb',
                    bgcolor: '#f3f4f6'
                  }}
                />
