                <Typography
                  variant='h6'
                  component='h2'
                  fontWeight={700}
                  sx={{ lineHeight: 1.2 }}
                >
                  {selectedAsset?.name}
                </Typography>
                <Stack
                  direction='row'
                  spacing={1}
                  alignItems='center'
                  sx={{ mt: 0.75, flexWrap: 'wrap', rowGap: 0.5 }}
                >
                  <Typography variant='body2' color='text.secondary'>
                    {[selectedAsset?.assetCode, selectedAsset?.assetType]
                      .filter(Boolean)
                      .join(' · ') || 'Sin código'}
                  </Typography>
                  <Chip
                    size='small'
                    variant='outlined'
                    color={
                      selectedAsset?.status === 'active'
