            }), 'Movimiento registrado', () => { setShowTrace(false); setTraceContact(''); setTraceLocation('') })} disabled={actionLoading === 'trace'}>Guardar</Button>
          </DialogActions>
        </Dialog>

        {/* Adjustment Dialog */}
