                  <MenuItem value='quantity_less'>Cantidad menor</MenuItem>
                  <MenuItem value='extra_item'>Ítem extra</MenuItem>
                  <MenuItem value='not_received'>No recibido</MenuItem>
                  <MenuItem value='scope_change'>Cambio de alcance</MenuItem>
