  course: {
    id: number
    title: string
    description: string
    is_mandatory: boolean
    audience: string
  }
  assignment_type?: string
  user_ids?: number[]
  department?: string
  all_employees: boolean
  role?: string
  deadline: string | null
  is_manual?: boolean
  managed_by_plan?: boolean
  plan_origins?: PlanOrigin[]
  created_by: number
  creator?: {
