          title: quiz.title,
          instructions: quiz.instructions,
          passingPercentage: quiz.passing_percentage,
          maxAttempts: quiz.max_attempts,
          cooldownMinutes: quiz.cooldown_minutes,
          showCorrectAnswers: quiz.show_correct_answers,
          randomizeQuestions: quiz.randomize_questions,
          shuffleAnswers: quiz.shuffle_answers,
          hasTimeLimit: quiz.time_limit_minutes !== null,
          timeLimitMinutes: quiz.time_limit_minutes,
          allowReview: true,
          showProgressBar: true,
          questions: quiz.questions.map(q => ({
            id: q.id,
            type: q.type,
            question: q.question,
            options: q.options,
            correct_answers: q.correct_answers,
            points: q.points,
            explanation: q.explanation || undefined,
            source: 'quiz'
          }))
        })
      },
      onError: (error: any) => {
        logger.error('❌ Error loading quiz:', error)
      }
    }
  )

  // Load quiz statistics for analytics tab
  const {
    data: quizStats,
    isLoading: isLoadingStats,
    error: statsLoadError
  } = useQuery(
    ['quiz-stats', initialQuizId],
    () => quizService.getQuizStatistics(initialQuizId!),
    {
      enabled: !!initialQuizId && activeTab === 3,
      retry: (failureCount, error) =>
        (error as AxiosError | undefined)?.response?.status !== 429 && failureCount < 1,
      refetchInterval: 30000, // Refresh every 30 seconds when on analytics tab
      onError: (error: any) => {
        logger.error('❌ Error loading quiz stats:', error)
      }
    }
  )

  // Save quiz mutation (create or update)
  const saveQuizMutation = useMutation(
    async () => {
      let targetLessonId = lessonId
      if (!targetLessonId) {
        if (!moduleId) {
          throw new Error('Lesson ID is required')
        }

        const lessonsResponse = await axiosPrivate.get(`/lms/content/modules/${moduleId}/lessons`)
        const lessons = lessonsResponse.data.data || lessonsResponse.data || []

        if (lessons.length === 0) {
          throw new Error('Este módulo no tiene lecciones. Por favor, crea una lección primero.')
        }

        targetLessonId = lessons[0].id
      }

      if (!targetLessonId) {
        throw new Error('No se pudo resolver la lección del quiz.')
      }

      // Build quiz DTO
      const quizDTO = quizService.buildQuizDTO(quizConfig, quizConfig.questions)

      // Create or Update
      if (initialQuizId) {
        return await quizService.updateQuiz(initialQuizId, quizDTO)
      } else {
        return await quizService.createQuiz(targetLessonId, quizDTO)
      }
    },
    {
      onSuccess: (quiz) => {
        logger.log('✅ Quiz saved successfully:', quiz)

        // Invalidate queries
        queryClient.invalidateQueries(['quiz', quiz.id])
        queryClient.invalidateQueries(['lms-course', courseId])

        // Callback to parent component
        if (onQuizSaved) {
          onQuizSaved(quiz.id)
        }
      },
      onError: (error: any) => {
        logger.error('❌ Error saving quiz:', error)
      }
    }
  )

  // ============================================================================
  // Question Bank API Integration
  // ============================================================================

  // Fetch question bank from API
  const { data: questionBankData } = useQuery(
    ['questionBank', searchTerm, filterCategory, filterDifficulty],
    async () => {
      const params = new URLSearchParams()
      if (filterDifficulty) params.append('difficulty', filterDifficulty)
      if (filterCategory) params.append('category', filterCategory)
      if (searchTerm) params.append('search', searchTerm)

      const response = await axiosPrivate.get(`/lms/question-bank?${params.toString()}`)
      return response.data
    },
    {
      staleTime: 3 * 60 * 1000, // 3 minutes
      refetchOnMount: 'always', // <--- fuerza re-fetch cada vez que el componente monta
      onSuccess: (data) => {
        logger.log('✅ Question bank loaded from API:', data)
        setQuestionBank(data.data || [])
      },
      onError: (error: any) => {
        logger.error('❌ Error loading question bank:', error)
        appNotify.error('Error', 'Error al cargar el banco de preguntas')
      }
    }
  )

  // Sync questionBankData with questionBank state
  useEffect(() => {
    if (questionBankData?.data) {
      logger.log('🔄 Syncing question bank data:', questionBankData.data)
      setQuestionBank(questionBankData.data)
    }
  }, [questionBankData])

   useEffect(() => {
    if (!loadedQuiz) return

    const quiz = loadedQuiz
    logger.log('✅ Quiz (effect) loaded:', quiz)

    setQuizConfig({
      id: quiz.id,
      title: quiz.title,
      instructions: quiz.instructions,
      passingPercentage: quiz.passing_percentage,
      maxAttempts: quiz.max_attempts,
      cooldownMinutes: quiz.cooldown_minutes,
      showCorrectAnswers: quiz.show_correct_answers,
      randomizeQuestions: quiz.randomize_questions,
      shuffleAnswers: quiz.shuffle_answers,
      hasTimeLimit: quiz.time_limit_minutes !== null,
      timeLimitMinutes: quiz.time_limit_minutes,
      allowReview: true,
      showProgressBar: true,
      questions: quiz.questions.map((q: any) => ({
        id: q.id,
        type: q.type,
        question: q.question,
        options: q.options,
        correct_answers: q.correct_answers,
        points: q.points,
        explanation: q.explanation || undefined
      }))
    })
  }, [loadedQuiz])

  // Create question mutation
  const createQuestionMutation = useMutation(
    async ({
      questionData
    }: {
      questionData: Partial<QuizQuestion>
      addToQuiz?: boolean
    }) => {
      const response = await axiosPrivate.post('/lms/question-bank', questionData)
      return response.data
    },
    {
      onSuccess: (data, variables) => {
        logger.log('✅ Question created:', data)
        const createdQuestion = data.data

        if (variables.addToQuiz && createdQuestion) {
          setQuizConfig(prev => ({
            ...prev,
            questions: [
              ...prev.questions,
              {
                id: createdQuestion.id,
                question: createdQuestion.question,
                type: createdQuestion.type,
                options: createdQuestion.options,
                correct_answers: createdQuestion.correct_answers,
                points: createdQuestion.points,
                explanation: createdQuestion.explanation || undefined,
                difficulty: createdQuestion.difficulty,
                category: createdQuestion.category,
                tags: createdQuestion.tags,
                source: 'quiz',
                bankQuestionId: createdQuestion.id
              }
            ]
          }))
        }

        appNotify.success('Éxito', variables.addToQuiz
            ? 'Pregunta creada y agregada al quiz'
            : 'Pregunta creada en el banco exitosamente')
        queryClient.invalidateQueries(['questionBank'])
        // Close modal and reset form after successful creation
        setQuestionEditorMode('quiz')
        setSaveQuestionToBank(false)
        resetQuestionForm()
        setOpenQuestionDialog(false)
      },
      onError: (error: any) => {
        logger.error('❌ Error creating question:', error)
        appNotify.error('Error', getApiErrorReason(error) || 'Error al crear la pregunta')
      }
    }
  )

  // Update question mutation
  const updateQuestionMutation = useMutation(
    async ({ id, data, updateQuiz }: { id: number; data: Partial<QuizQuestion>; updateQuiz?: { isInQuiz: boolean; updatedQuestion: QuizQuestion } }) => {
      const response = await axiosPrivate.put(`/lms/question-bank/${id}`, data)
      return { response: response.data, updateQuiz }
    },
    {
      onSuccess: ({ response, updateQuiz }) => {
        logger.log('✅ Question updated:', response)
        appNotify.success('Éxito', 'Pregunta actualizada exitosamente')
        queryClient.invalidateQueries(['questionBank'])

        // Update quiz questions if this question is in the quiz
        if (updateQuiz?.isInQuiz && updateQuiz.updatedQuestion) {
          setQuizConfig(prev => ({
            ...prev,
            questions: prev.questions.map(q => q.id === updateQuiz.updatedQuestion.id ? updateQuiz.updatedQuestion : q)
          }))
        }

        // Close modal and reset form after successful update
        setEditingQuestion(null)
        resetQuestionForm()
        setOpenQuestionDialog(false)
      },
      onError: (error: any) => {
        logger.error('❌ Error updating question:', error)
        appNotify.error('Error', getApiErrorReason(error) || 'Error al actualizar la pregunta')
      }
    }
  )

  // Delete question mutation
  const deleteQuestionMutation = useMutation(
    async (id: number) => {
      const response = await axiosPrivate.delete(`/lms/question-bank/${id}`)
      return response.data
    },
    {
      onSuccess: () => {
        logger.log('✅ Question deleted')
        appNotify.success('Éxito', 'Pregunta eliminada exitosamente')
        queryClient.invalidateQueries(['questionBank'])
      },
      onError: (error: any) => {
        logger.error('❌ Error deleting question:', error)
        appNotify.error('Error', getApiErrorReason(error) || 'Error al eliminar la pregunta')
      }
    }
  )

  const handleTabChange = (_event: React.SyntheticEvent, newValue: number) => {
    setActiveTab(newValue)
  }

  const handleQuizConfigChange = (field: keyof QuizConfiguration, value: any) => {
    setQuizConfig(prev => ({ ...prev, [field]: value }))
  }

  const buildQuestionPayload = () => ({
    question: newQuestion.question?.trim() || '',
    type: newQuestion.type || 'single',
    options: newQuestion.options?.filter(opt => opt.trim() !== '') || [],
    correct_answers: newQuestion.correct_answers || [0],
    explanation: newQuestion.explanation,
    points: newQuestion.points || 1,
    difficulty: newQuestion.difficulty || 'medium',
    category: newQuestion.category || '',
    tags: newQuestion.tags || []
  })

  const createLocalQuizQuestion = (questionData: ReturnType<typeof buildQuestionPayload>): QuizQuestion => ({
    id: -Date.now(),
    ...questionData,
    source: 'quiz'
  })

  const openNewQuizQuestionDialog = () => {
    setEditingQuestion(null)
    setQuestionEditorMode('quiz')
    setSaveQuestionToBank(false)
    resetQuestionForm()
    setOpenQuestionDialog(true)
  }

  const openBankQuestionDialog = () => {
    setEditingQuestion(null)
    setQuestionEditorMode('bank')
    setSaveQuestionToBank(true)
    resetQuestionForm()
    setOpenQuestionDialog(true)
  }

  const handleAddQuestion = () => {
    if (!newQuestion.question?.trim()) return

    const questionData = buildQuestionPayload()

    if (questionEditorMode === 'quiz' && !saveQuestionToBank) {
      setQuizConfig(prev => ({
        ...prev,
        questions: [...prev.questions, createLocalQuizQuestion(questionData)]
      }))
      appNotify.success('Éxito', 'Pregunta agregada al quiz')
      resetQuestionForm()
      setOpenQuestionDialog(false)
      return
    }

    createQuestionMutation.mutate({
      questionData,
      addToQuiz: questionEditorMode === 'quiz'
    })
  }

  const handleEditQuestion = (question: QuizQuestion, mode: 'quiz' | 'bank' = 'quiz') => {
    setEditingQuestion(question)
    setQuestionEditorMode(mode)
    setSaveQuestionToBank(mode === 'bank' || Boolean(question.bankQuestionId))
    setNewQuestion({
      question: question.question,
      type: question.type,
      options: [...question.options],
      correct_answers: question.correct_answers,
      explanation: question.explanation,
      points: question.points,
      difficulty: question.difficulty,
      category: question.category,
      tags: question.tags
    })
    setOpenQuestionDialog(true)
  }

  const handleUpdateQuestion = () => {
    if (!editingQuestion || !newQuestion.question?.trim()) return

    const questionData = {
      ...buildQuestionPayload(),
      type: newQuestion.type || editingQuestion.type,
      options: newQuestion.options?.filter(opt => opt.trim() !== '') || editingQuestion.options,
      correct_answers: newQuestion.correct_answers || editingQuestion.correct_answers,
      points: newQuestion.points || editingQuestion.points,
      difficulty: newQuestion.difficulty || editingQuestion.difficulty,
      category: newQuestion.category || editingQuestion.category,
      tags: newQuestion.tags || editingQuestion.tags
    }

    if (questionEditorMode === 'quiz') {
      const updatedQuestion: QuizQuestion = {
        ...editingQuestion,
        ...questionData,
        source: 'quiz'
      }

      setQuizConfig(prev => ({
        ...prev,
        questions: prev.questions.map(q => q.id === editingQuestion.id ? updatedQuestion : q)
      }))
      appNotify.success('Éxito', 'Pregunta del quiz actualizada')
      setEditingQuestion(null)
      setQuestionEditorMode('quiz')
      setSaveQuestionToBank(false)
      resetQuestionForm()
      setOpenQuestionDialog(false)
      return
    }

    // Check if this question is in the quiz
    const isInQuiz = quizConfig.questions.some(q => q.id === editingQuestion.id)
    const updatedQuestion: QuizQuestion = {
      ...editingQuestion,
      ...questionData,
      correct_answers: questionData.correct_answers
    }

    updateQuestionMutation.mutate({
      id: editingQuestion.id,
      data: questionData,
      updateQuiz: isInQuiz ? { isInQuiz, updatedQuestion } : undefined
    })
  }

  const handleDeleteQuestion = async (questionId: number) => {
    const { isConfirmed } = await confirmDialog({
      title: 'Eliminar pregunta',
      text: 'Esta acción no se puede deshacer.',
      confirmLabel: 'Eliminar',
      tone: 'danger'
    })
    if (isConfirmed) {
      await deleteQuestionMutation.mutateAsync(questionId)

      // Also remove from quiz if present
      setQuizConfig(prev => ({
        ...prev,
        questions: prev.questions.filter(q => q.id !== questionId)
      }))
    }
  }

  const handleAddQuestionsToQuiz = () => {
    const questionsToAdd = questionBank
      .filter(q => selectedQuestions.includes(q.id))
      .map((question, index) => ({
        ...question,
        id: -(Date.now() + index),
        source: 'quiz' as const,
        bankQuestionId: question.id
      }))

    setQuizConfig(prev => ({
      ...prev,
      questions: [
        ...prev.questions,
        ...questionsToAdd.filter(q => !prev.questions.find(existing => existing.bankQuestionId === q.bankQuestionId))
      ]
    }))
    setSelectedQuestions([])
    appNotify.success('Éxito', 'Preguntas agregadas al quiz')
  }

  const handleRemoveQuestionFromQuiz = (questionId: number) => {
    setQuizConfig(prev => ({
      ...prev,
      questions: prev.questions.filter(q => q.id !== questionId)
    }))
  }

  const resetQuestionForm = () => {
    setNewQuestion({
      question: '',
      type: 'single',
      options: ['', '', '', ''],
      correct_answers: [0],
      explanation: '',
      points: 1,
      difficulty: 'medium',
      category: '',
      tags: []
    })
  }

  const getFilteredQuestions = () => {
    return questionBank.filter(question => {
      const matchesSearch = question.question.toLowerCase().includes(searchTerm.toLowerCase()) ||
                           question.category?.toLowerCase().includes(searchTerm.toLowerCase()) ||
                           question.tags?.some(tag => tag.toLowerCase().includes(searchTerm.toLowerCase()))
      const matchesCategory = !filterCategory || question.category === filterCategory
      const matchesDifficulty = !filterDifficulty || question.difficulty === filterDifficulty

      return matchesSearch && matchesCategory && matchesDifficulty
    })
  }

  const getQuestionTypeIcon = (type: string) => {
    switch (type) {
      case 'true-false': return <ToggleIcon />
      case 'single-choice': return <RadioIcon />
      case 'multiple-choice': return <CheckboxIcon />
      default: return <HelpIcon />
    }
  }

  const getDifficultyColor = (difficulty?: string) => {
    switch (difficulty) {
      case 'easy': return 'success'
      case 'medium': return 'warning'
      case 'hard': return 'error'
      default: return 'default'
    }
  }

  const validateQuizConfig = () => {
    const errors: string[] = []

    if (!quizConfig.title.trim()) errors.push('El título es requerido')
    if (quizConfig.questions.length === 0) errors.push('Debe agregar al menos una pregunta')
    if (quizConfig.passingPercentage < 1 || quizConfig.passingPercentage > 100) {
      errors.push('El porcentaje de aprobación debe estar entre 1 y 100')
    }
    if (quizConfig.maxAttempts < 1 || quizConfig.maxAttempts > 10) {
      errors.push('Los intentos máximos deben estar entre 1 y 10')
    }

    return errors
  }

  const applyQuestionCategorySuggestion = (value: string) => {
    setNewQuestion((prev) => ({ ...prev, category: value }))
  }

  const quizValidationErrors = validateQuizConfig()
  const totalPoints = quizConfig.questions.reduce((sum, q) => sum + q.points, 0)
  const pointsToPass = Math.ceil((totalPoints * quizConfig.passingPercentage) / 100)
  const hasBasicSetup = Boolean(quizConfig.title.trim())
  const hasQuestions = quizConfig.questions.length > 0
  const canPreviewQuiz = hasBasicSetup && hasQuestions
  const canReviewAnalytics = Boolean(initialQuizId)

  const guidedSteps = [
    {
      label: 'Configura el quiz',
      description: hasBasicSetup
        ? 'El título ya está listo; puedes afinar reglas e instrucciones.'
        : 'Define al menos el título y las reglas básicas.',
      complete: hasBasicSetup,
      tab: 0
    },
    {
      label: 'Agrega preguntas',
      description: hasQuestions
        ? `${quizConfig.questions.length} pregunta(s) agregada(s).`
        : 'Crea preguntas para este quiz o reutiliza algunas del banco.',
      complete: hasQuestions,
      tab: 1
    },
    {
      label: 'Prueba la experiencia',
      description: canPreviewQuiz
        ? 'Ya puedes ejecutar una vista previa del quiz.'
        : 'Necesitas configuración básica y al menos una pregunta.',
      complete: previewMode || false,
      tab: 2
    },
    {
      label: 'Guarda y mide resultados',
      description: canReviewAnalytics
        ? 'El quiz ya existe y puede mostrar métricas reales.'
        : 'Primero guarda el quiz para habilitar analíticas.',
      complete: canReviewAnalytics,
      tab: 3
    }
  ]

  const firstIncompleteStep = guidedSteps.find((step) => !step.complete)
  const activeGuidedStep = firstIncompleteStep ? guidedSteps.indexOf(firstIncompleteStep) : guidedSteps.length - 1

  const handleSaveQuiz = () => {
    if (quizValidationErrors.length > 0) {
      notify.error('Errores de validación', quizValidationErrors.join('. '))
      return
    }

    if (quizConfig.questions.length === 0) {
      notify.error('Debes agregar al menos una pregunta al quiz antes de guardar')
      return
    }

    // Trigger save mutation
    saveQuizMutation.mutate()
  }

  // ============================================================================
  // Loading States
  // ============================================================================
  if (isLoadingQuiz) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', p: 8 }}>
        <SignalLoader message='Cargando quiz...' />
      </Box>
    )
  }

  // Abierto directo por su ruta (sin curso ni lección), no hay un quiz que editar
  if (!courseId && !lessonId && !initialQuizId) {
    return (
      <Container maxWidth='xl' sx={{ py: 3 }}>
        <LmsPageHeader
          title='Quizzes'
          subtitle='Evaluaciones de las lecciones de cada curso'
          icon={<Quiz />}
        />
        <Card variant='outlined' sx={{ maxWidth: 560, mx: 'auto', mt: 3, borderRadius: 3, textAlign: 'center' }}>
          <CardContent sx={{ p: 4 }}>
            <Typography variant='h5' sx={{ fontWeight: 600, mb: 1 }}>
              Los quizzes se editan desde cada curso
            </Typography>
            <Typography variant='body2' color='text.secondary' sx={{ mb: 3 }}>
              Abre el contenido de un curso, elige una lección de tipo quiz y configura aquí sus preguntas.
            </Typography>
            <Button variant='contained' onClick={() => navigate('/lms/admin/courses')}>
              Ir a gestión de cursos
            </Button>
          </CardContent>
        </Card>
      </Container>
    )
  }

  return (
    <Box sx={{ width: '100%' }}>
      {/* Error Messages */}
      {quizLoadError && (
        <Alert severity="error" sx={{ mb: 2 }}>
          Error al cargar el quiz. Por favor, inténtalo de nuevo.
        </Alert>
      )}

      {saveQuizMutation.isError && (
        <Alert severity="error" sx={{ mb: 2 }}>
          Error al guardar el quiz: {(saveQuizMutation.error as any)?.message || 'Error desconocido'}
        </Alert>
      )}

      {saveQuizMutation.isSuccess && (
        <Alert severity="success" sx={{ mb: 2 }}>
          ✅ Quiz guardado exitosamente
        </Alert>
      )}

      <Card sx={{ mb: 3, borderRadius: 3, border: '1px solid', borderColor: 'divider' }}>
        <CardContent>
          <Stack spacing={2.5}>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', gap: 2, flexWrap: 'wrap' }}>
              <Box>
                <Typography variant="h5" sx={{ fontWeight: 700, mb: 0.5 }}>
                  Constructor de Quiz
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  Sigue este flujo: configura, agrega preguntas, prueba la experiencia y luego guarda para medir resultados.
                </Typography>
              </Box>
              <Chip
                color={quizValidationErrors.length === 0 && hasQuestions ? 'success' : 'warning'}
                icon={quizValidationErrors.length === 0 && hasQuestions ? <CheckCircleIcon /> : <WarningIcon />}
                label={
                  quizValidationErrors.length === 0 && hasQuestions
                    ? 'Listo para guardar'
                    : 'Configuración incompleta'
                }
              />
            </Box>

            <Stepper activeStep={activeGuidedStep} alternativeLabel>
              {guidedSteps.map((step) => (
                <Step key={step.label} completed={step.complete}>
                  <StepLabel>{step.label}</StepLabel>
                </Step>
              ))}
            </Stepper>

            <Grid container spacing={2}>
              {guidedSteps.map((step, index) => (
                <Grid item xs={12} md={6} key={step.label}>
                  <Paper
                    variant="outlined"
                    sx={{
                      p: 2,
                      borderRadius: 2,
                      height: '100%',
                      borderColor: index === activeGuidedStep ? 'primary.main' : 'divider',
                      bgcolor: step.complete ? 'success.50' : 'background.paper'
                    }}
                  >
                    <Box sx={{ display: 'flex', justifyContent: 'space-between', gap: 2, mb: 1 }}>
                      <Typography variant="subtitle1" sx={{ fontWeight: 600 }}>
                        {step.label}
                      </Typography>
                      <Chip
                        size="small"
                        color={step.complete ? 'success' : index === activeGuidedStep ? 'primary' : 'default'}
                        label={step.complete ? 'Hecho' : index === activeGuidedStep ? 'Siguiente' : 'Pendiente'}
                      />
                    </Box>
                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                      {step.description}
                    </Typography>
                    <Button
                      size="small"
                      variant={index === activeGuidedStep ? 'contained' : 'outlined'}
                      onClick={() => setActiveTab(step.tab)}
                    >
                      Ir a este paso
                    </Button>
                  </Paper>
                </Grid>
              ))}
            </Grid>

          </Stack>
        </CardContent>
      </Card>

      <Box sx={{ borderBottom: 1, borderColor: 'divider', mb: 3 }}>
        <Tabs value={activeTab} onChange={handleTabChange}>
          <Tab label="Configuración" icon={<AssessmentIcon />} />
          <Tab label="Preguntas" icon={<QuestionIcon />} />
          <Tab label="Vista Previa" icon={<PreviewIcon />} />
          <Tab label="Analíticas" icon={<AnalyticsIcon />} />
        </Tabs>
      </Box>

      {/* Tab 1: Quiz Configuration */}
      <TabPanel value={activeTab} index={0}>
        <Grid container spacing={3}>
          <Grid item xs={12} md={8}>
            <Card>
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  Configuración General del Quiz
                </Typography>
                <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                  Paso 1 de 4. Define las reglas mínimas para que el quiz quede claro y evaluable.
                </Typography>

                <Grid container spacing={2}>
                  <Grid item xs={12}>
                    <TextField
                      fullWidth
                      label="Título del Quiz"
                      value={quizConfig.title}
                      onChange={(e) => handleQuizConfigChange('title', e.target.value)}
                      required
                    />
                  </Grid>

                  <Grid item xs={12}>
                    <TextField
                      fullWidth
                      multiline
                      rows={3}
                      label="Instrucciones"
                      value={quizConfig.instructions}
                      onChange={(e) => handleQuizConfigChange('instructions', e.target.value)}
                      helperText="Instrucciones que verán los estudiantes antes de comenzar"
                    />
                  </Grid>

                  <Grid item xs={12} sm={6}>
                    <TextField
                      fullWidth
                      type="number"
                      label="Porcentaje de Aprobación (%)"
                      value={quizConfig.passingPercentage}
                      onChange={(e) => handleQuizConfigChange('passingPercentage', parseInt(e.target.value))}
                      inputProps={{ min: 1, max: 100 }}
                    />
                  </Grid>

                  <Grid item xs={12} sm={6}>
                    <TextField
                      fullWidth
                      type="number"
                      label="Intentos Máximos"
                      value={quizConfig.maxAttempts}
                      onChange={(e) => handleQuizConfigChange('maxAttempts', parseInt(e.target.value))}
                      inputProps={{ min: 1, max: 10 }}
                    />
                  </Grid>

                  <Grid item xs={12} sm={6}>
                    <TextField
                      fullWidth
                      type="number"
                      label="Tiempo de Espera (minutos)"
                      value={quizConfig.cooldownMinutes}
                      onChange={(e) => handleQuizConfigChange('cooldownMinutes', parseInt(e.target.value))}
                      inputProps={{ min: 0 }}
                      helperText="Tiempo de espera entre intentos"
                    />
                  </Grid>

                  <Grid item xs={12} sm={6}>
                    <TextField
                      fullWidth
                      type="number"
                      label="Límite de Tiempo (minutos)"
                      value={quizConfig.timeLimitMinutes || ''}
                      onChange={(e) => handleQuizConfigChange('timeLimitMinutes', e.target.value ? parseInt(e.target.value) : undefined)}
                      inputProps={{ min: 1 }}
                      helperText="Opcional - Dejar vacío para sin límite"
                    />
                  </Grid>
                </Grid>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} md={4}>
            <Card>
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  Opciones Avanzadas
                </Typography>

                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                  <FormControlLabel
                    control={
                      <Switch
                        checked={quizConfig.showCorrectAnswers}
                        onChange={(e) => handleQuizConfigChange('showCorrectAnswers', e.target.checked)}
                      />
                    }
                    label="Mostrar respuestas correctas"
                  />

                  <FormControlLabel
                    control={
                      <Switch
                        checked={quizConfig.randomizeQuestions}
                        onChange={(e) => handleQuizConfigChange('randomizeQuestions', e.target.checked)}
                      />
                    }
                    label="Aleatorizar preguntas"
                  />

                  <FormControlLabel
                    control={
                      <Switch
                        checked={quizConfig.shuffleAnswers}
                        onChange={(e) => handleQuizConfigChange('shuffleAnswers', e.target.checked)}
                      />
                    }
                    label="Mezclar opciones de respuesta"
                  />

                  <FormControlLabel
                    control={
                      <Switch
                        checked={quizConfig.allowReview}
                        onChange={(e) => handleQuizConfigChange('allowReview', e.target.checked)}
                      />
                    }
                    label="Permitir revisar respuestas"
                  />

                  <FormControlLabel
                    control={
                      <Switch
                        checked={quizConfig.showProgressBar}
                        onChange={(e) => handleQuizConfigChange('showProgressBar', e.target.checked)}
                      />
                    }
                    label="Mostrar barra de progreso"
                  />
                </Box>
              </CardContent>
            </Card>

            <Card sx={{ mt: 2 }}>
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  Resumen del Quiz
                </Typography>

                <Alert severity={quizValidationErrors.length === 0 ? 'success' : 'warning'} sx={{ mb: 2 }}>
                  {quizValidationErrors.length === 0
                    ? 'La configuración actual es válida.'
                    : `Faltan ${quizValidationErrors.length} ajuste(s) para poder guardar.`}
                </Alert>

                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                  <Typography variant="body2">
                    <strong>Preguntas:</strong> {quizConfig.questions.length}
                  </Typography>
                  <Typography variant="body2">
                    <strong>Puntos totales:</strong> {totalPoints}
                  </Typography>
                  <Typography variant="body2">
                    <strong>Puntos para aprobar:</strong> {pointsToPass}
                  </Typography>
                </Box>

                {quizValidationErrors.length > 0 && (
                  <>
                    <Divider sx={{ my: 2 }} />
                    <Stack spacing={1}>
                      {quizValidationErrors.map((error) => (
                        <Typography key={error} variant="body2" color="warning.main">
                          • {error}
                        </Typography>
                      ))}
                    </Stack>
                  </>
                )}

                <Button
                  fullWidth
                  variant="contained"
                  startIcon={saveQuizMutation.isLoading ? <CircularProgress size={20} color="inherit" /> : <SaveIcon />}
                  onClick={handleSaveQuiz}
                  sx={{ mt: 2 }}
                  disabled={quizValidationErrors.length > 0 || saveQuizMutation.isLoading}
                >
                  {saveQuizMutation.isLoading ? 'Guardando...' : (initialQuizId ? 'Actualizar Quiz' : 'Guardar Quiz')}
                </Button>
              </CardContent>
            </Card>
          </Grid>

          {/* Current Quiz Questions */}
          <Grid item xs={12}>
            <Card>
              <CardContent>
                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                  <Typography variant="h6">
                    Preguntas del Quiz ({quizConfig.questions.length})
                  </Typography>
                  <Stack direction='row' spacing={1}>
                    <Button
                      variant="contained"
                      startIcon={<AddIcon />}
                      onClick={openNewQuizQuestionDialog}
                    >
                      Nueva pregunta
                    </Button>
                    <Button
                      variant="outlined"
                      startIcon={<QuestionIcon />}
                      onClick={() => setActiveTab(1)}
                    >
                      Usar banco
                    </Button>
                  </Stack>
                </Box>

                {quizConfig.questions.length === 0 ? (
                  <Alert severity="info">
                    Este quiz todavía no tiene preguntas. Lo más rápido es crear una aquí misma. El banco queda disponible si quieres reutilizar preguntas existentes.
                  </Alert>
                ) : (
                  <List>
                    {quizConfig.questions.map((question, index) => (
                      <Card key={question.id} sx={{ mb: 2 }}>
                        <CardContent>
                          <Box sx={{ display: 'flex', alignItems: 'flex-start', gap: 2 }}>
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, minWidth: 120 }}>
                              <DragIcon sx={{ color: 'text.disabled' }} />
                              <Typography variant="caption" color="text.secondary">
                                Pregunta {index + 1}
                              </Typography>
                            </Box>

                            <Box sx={{ flex: 1 }}>
                              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                                {getQuestionTypeIcon(question.type)}
                                <Chip label={question.type} size="small" color="primary" />
                                <Chip label={`${question.points} pts`} size="small" variant="outlined" />
                                {question.difficulty && (
                                  <Chip 
                                    label={question.difficulty} 
                                    size="small" 
                                    color={getDifficultyColor(question.difficulty) as any}
                                  />
                                )}
                              </Box>

                              <Typography variant="body1" sx={{ mb: 1 }}>
                                {question.question}
                              </Typography>

                              {question.category && (
                                <Chip label={question.category} size="small" variant="outlined" sx={{ mr: 1 }} />
                              )}
                            </Box>

                            <Box sx={{ display: 'flex', gap: 1 }}>
                              <IconButton size="small" onClick={() => handleEditQuestion(question, 'quiz')}>
                                <EditIcon />
                              </IconButton>
                              <IconButton 
                                size="small" 
                                color="error" 
                                onClick={() => handleRemoveQuestionFromQuiz(question.id)}
                              >
                                <DeleteIcon />
                              </IconButton>
                            </Box>
                          </Box>
                        </CardContent>
                      </Card>
                    ))}
                  </List>
                )}
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      </TabPanel>

      {/* Tab 2: Question Bank */}
      <TabPanel value={activeTab} index={1}>
        <Grid container spacing={3}>
          <Grid item xs={12}>
            <Card>
              <CardContent>
                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 2, flexWrap: 'wrap', mb: 2 }}>
                  <Typography variant="h6">Preguntas del Quiz</Typography>
                  <Stack direction='row' spacing={1}>
                    <Button
                      variant="contained"
                      startIcon={<AddIcon />}
                      onClick={openNewQuizQuestionDialog}
                    >
                      Nueva pregunta para este quiz
                    </Button>
                    <Button
                      variant="outlined"
                      startIcon={<QuestionIcon />}
                      onClick={openBankQuestionDialog}
                    >
                      Crear solo en banco
                    </Button>
                  </Stack>
                </Box>
                <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                  Paso 2 de 4. Crea primero las preguntas propias de este quiz. Si ya tienes preguntas reutilizables, puedes agregarlas desde el banco en la parte inferior.
                </Typography>
                <Alert severity="info" sx={{ mb: 2 }}>
                  El banco de preguntas es opcional. Úsalo cuando quieras reutilizar preguntas en varios quizzes; no hace falta alimentarlo para poder crear uno nuevo.
                </Alert>

                <Divider sx={{ my: 3 }} />
                <Typography variant="subtitle1" sx={{ fontWeight: 600, mb: 1 }}>
                  Reutilizar desde el banco de preguntas
                </Typography>
                <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                  Selecciona preguntas existentes y agrégalas al quiz como copia editable. Cambiarlas aquí no modifica el banco global.
                </Typography>

                {/* Filters */}
                <Grid container spacing={2} sx={{ mb: 2 }}>
                  <Grid item xs={12} sm={4}>
                    <TextField
                      fullWidth
                      label="Buscar preguntas"
                      value={searchTerm}
                      onChange={(e) => setSearchTerm(e.target.value)}
                      size="small"
                    />
                  </Grid>
                  <Grid item xs={12} sm={4}>
                    <FormControl fullWidth size="small">
                      <InputLabel>Categoría</InputLabel>
                      <Select
                        value={filterCategory}
                        label="Categoría"
                        onChange={(e) => setFilterCategory(e.target.value)}
                      >
                        <MenuItem value="">Todas</MenuItem>
                        <MenuItem value="Geografía">Geografía</MenuItem>
                        <MenuItem value="Programación">Programación</MenuItem>
                        <MenuItem value="Historia">Historia</MenuItem>
                      </Select>
                    </FormControl>
                  </Grid>
                  <Grid item xs={12} sm={4}>
                    <FormControl fullWidth size="small">
                      <InputLabel>Dificultad</InputLabel>
                      <Select
                        value={filterDifficulty}
                        label="Dificultad"
                        onChange={(e) => setFilterDifficulty(e.target.value)}
                      >
                        <MenuItem value="">Todas</MenuItem>
                        <MenuItem value="easy">Fácil</MenuItem>
                        <MenuItem value="medium">Medio</MenuItem>
                        <MenuItem value="hard">Difícil</MenuItem>
                      </Select>
                    </FormControl>
                  </Grid>
                </Grid>

                {selectedQuestions.length > 0 && (
                  <Box sx={{ mb: 2 }}>
                    <Alert severity="info" sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                      <Typography>
                        {selectedQuestions.length} pregunta(s) seleccionada(s)
                      </Typography>
                      <Button
                        variant="contained"
                        size="small"
                        onClick={handleAddQuestionsToQuiz}
                      >
                        Agregar al Quiz
                      </Button>
                    </Alert>
                  </Box>
                )}

                {/* Question List */}
                <List>
                  {getFilteredQuestions().map((question) => (
                    <Card key={question.id} sx={{ mb: 2 }}>
                      <CardContent>
                        <Box sx={{ display: 'flex', alignItems: 'flex-start', gap: 2 }}>
                          <FormControlLabel
                            control={
                              <Switch
                                checked={selectedQuestions.includes(question.id)}
                                onChange={(e) => {
                                  if (e.target.checked) {
                                    setSelectedQuestions(prev => [...prev, question.id])
                                  } else {
                                    setSelectedQuestions(prev => prev.filter(id => id !== question.id))
                                  }
                                }}
                              />
                            }
                            label=""
                          />

                          <Box sx={{ flex: 1 }}>
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                              {getQuestionTypeIcon(question.type)}
                              <Chip label={question.type} size="small" color="primary" />
                              <Chip label={`${question.points} pts`} size="small" variant="outlined" />
                              {question.difficulty && (
                                <Chip 
                                  label={question.difficulty} 
                                  size="small" 
                                  color={getDifficultyColor(question.difficulty) as any}
                                />
                              )}
                              {question.usageCount !== undefined && (
                                <Chip label={`Usado ${question.usageCount} veces`} size="small" variant="outlined" />
                              )}
                              {question.successRate !== undefined && (
                                <Chip 
                                  label={`${question.successRate}% éxito`} 
                                  size="small" 
                                  color={question.successRate >= 70 ? 'success' : question.successRate >= 50 ? 'warning' : 'error'}
                                />
                              )}
                            </Box>

                            <Typography variant="body1" sx={{ mb: 1 }}>
                              {question.question}
                            </Typography>

                            <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
                              {question.category && (
                                <Chip label={question.category} size="small" variant="outlined" />
                              )}
                              {question.tags?.map((tag, index) => (
                                <Chip key={index} label={tag} size="small" variant="outlined" />
                              ))}
                            </Box>
                          </Box>

                            <Box sx={{ display: 'flex', gap: 1 }}>
                            <IconButton size="small" onClick={() => handleEditQuestion(question, 'bank')}>
                                <EditIcon />
                              </IconButton>
                            <IconButton 
                              size="small" 
                              color="error" 
                              onClick={() => handleDeleteQuestion(question.id)}
                            >
                              <DeleteIcon />
                            </IconButton>
                          </Box>
                        </Box>
                      </CardContent>
                    </Card>
                  ))}
                </List>
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      </TabPanel>

      {/* Tab 3: Preview */}
      <TabPanel value={activeTab} index={2}>
        <Card>
          <CardContent>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
              <Typography variant="h6">Vista Previa del Quiz</Typography>
              <Button
                variant="outlined"
                startIcon={<PreviewIcon />}
                onClick={() => setPreviewMode(!previewMode)}
              >
                {previewMode ? 'Salir de Vista Previa' : 'Iniciar Vista Previa'}
              </Button>
            </Box>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
              Paso 3 de 4. Usa esta vista para validar el orden, las preguntas y la dificultad antes de guardar.
            </Typography>

            {quizConfig.questions.length === 0 ? (
              <Alert severity="warning">
                No hay preguntas en el quiz para mostrar la vista previa.
              </Alert>
            ) : previewMode ? (
              <LmsQuizComponent
                questions={quizConfig.questions.map(q => ({
                  ...q,
                  type: q.type === 'single' ? 'single-choice' : q.type === 'multiple' ? 'multiple-choice' : 'true-false',
                  correctAnswer: q.type === 'single' || q.type === 'boolean' ? q.correct_answers[0] : q.correct_answers
                }))}
                isPreview={true}
                onComplete={(score, totalPoints) => {
                  notify.info(`Vista previa completada: ${score}/${totalPoints} puntos (${Math.round((score/totalPoints)*100)}%)`)
                  setPreviewMode(false)
                }}
              />
            ) : (
              <Box>
                <Typography variant="h6" gutterBottom>
                  {quizConfig.title || 'Quiz sin título'}
                </Typography>

                {quizConfig.instructions && (
                  <Typography variant="body1" sx={{ mb: 2 }}>
                    {quizConfig.instructions}
                  </Typography>
                )}

                <Grid container spacing={2} sx={{ mb: 3 }}>
                  <Grid item xs={12} sm={6} md={3}>
                    <Paper sx={{ p: 2, textAlign: 'center' }}>
                      <Typography variant="h4" color="primary">
                        {quizConfig.questions.length}
                      </Typography>
                      <Typography variant="body2">Preguntas</Typography>
                    </Paper>
                  </Grid>
                  <Grid item xs={12} sm={6} md={3}>
                    <Paper sx={{ p: 2, textAlign: 'center' }}>
                      <Typography variant="h4" color="primary">
                        {quizConfig.questions.reduce((sum, q) => sum + q.points, 0)}
                      </Typography>
                      <Typography variant="body2">Puntos Totales</Typography>
                    </Paper>
                  </Grid>
                  <Grid item xs={12} sm={6} md={3}>
                    <Paper sx={{ p: 2, textAlign: 'center' }}>
                      <Typography variant="h4" color="primary">
                        {quizConfig.passingPercentage}%
                      </Typography>
                      <Typography variant="body2">Para Aprobar</Typography>
                    </Paper>
                  </Grid>
                  <Grid item xs={12} sm={6} md={3}>
                    <Paper sx={{ p: 2, textAlign: 'center' }}>
                      <Typography variant="h4" color="primary">
                        {quizConfig.maxAttempts}
                      </Typography>
                      <Typography variant="body2">Intentos Máx.</Typography>
                    </Paper>
                  </Grid>
                </Grid>

                <Alert severity="info">
                  Haz clic en "Iniciar Vista Previa" para probar el quiz como lo verían los estudiantes.
                </Alert>
              </Box>
            )}
          </CardContent>
        </Card>
      </TabPanel>

      {/* Tab 4: Analytics */}
      <TabPanel value={activeTab} index={3}>
        <Grid container spacing={3}>
          <Grid item xs={12}>
            <Typography variant="h6" gutterBottom>
              Analíticas del Quiz
            </Typography>
            <Typography variant="body2" color="text.secondary">
              Paso 4 de 4. Esta pestaña muestra resultados reales una vez que el quiz ya fue guardado y usado por estudiantes.
            </Typography>
          </Grid>

          {/* No quiz saved yet */}
          {!initialQuizId && (
            <Grid item xs={12}>
              <Alert severity="info">
                Debes guardar el quiz primero para ver las analíticas de intentos
              </Alert>
            </Grid>
          )}

          {/* Loading stats */}
          {isLoadingStats && (
            <Grid item xs={12}>
              <Box sx={{ display: 'flex', justifyContent: 'center', p: 4 }}>
                <SignalLoader message='Cargando estadísticas...' />
              </Box>
            </Grid>
          )}

          {/* Error loading stats */}
          {statsLoadError && (
            <Grid item xs={12}>
              <Alert severity="warning">
                No se pudieron cargar las estadísticas. Puede que aún no haya intentos registrados.
              </Alert>
            </Grid>
          )}

          {/* Stats loaded and available */}
          {quizStats && !isLoadingStats && (
            <>
              {/* Main Stats Cards */}
              <Grid item xs={12} sm={6} md={3}>
                <Card>
                  <CardContent sx={{ textAlign: 'center' }}>
                    <Typography variant="h4" color="primary">
                      {quizStats.totalAttempts}
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      Total de Intentos
                    </Typography>
                  </CardContent>
                </Card>
              </Grid>

              <Grid item xs={12} sm={6} md={3}>
                <Card>
                  <CardContent sx={{ textAlign: 'center' }}>
                    <Typography variant="h4" color="success.main">
                      {quizStats.averageScore}%
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      Puntuación Promedio
                    </Typography>
                  </CardContent>
                </Card>
              </Grid>

              <Grid item xs={12} sm={6} md={3}>
                <Card>
                  <CardContent sx={{ textAlign: 'center' }}>
                    <Typography variant="h4" color="info.main">
                      {quizStats.passRate}%
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      Tasa de Aprobación
                    </Typography>
                  </CardContent>
                </Card>
              </Grid>

              <Grid item xs={12} sm={6} md={3}>
                <Card>
                  <CardContent sx={{ textAlign: 'center' }}>
                    <Typography variant="h4" color="warning.main">
                      {quizStats.averageTimeMinutes.toFixed(1)}
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      Tiempo Promedio (min)
                    </Typography>
                  </CardContent>
                </Card>
              </Grid>

              {/* Additional Stats */}
              <Grid item xs={12} sm={6}>
                <Card>
                  <CardContent sx={{ textAlign: 'center' }}>
                    <Typography variant="h4" color="secondary">
                      {quizStats.uniqueUsers}
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      Usuarios Únicos
                    </Typography>
                  </CardContent>
                </Card>
              </Grid>

              <Grid item xs={12} sm={6}>
                <Card>
                  <CardContent sx={{ textAlign: 'center' }}>
                    <Typography variant="h4" color={quizStats.suspiciousAttempts > 0 ? "error" : "success.main"}>
                      {quizStats.suspiciousAttempts}
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      Intentos Sospechosos
                    </Typography>
                    {quizStats.suspiciousAttempts > 0 && (
                      <Typography variant="caption" color="error" sx={{ mt: 1, display: 'block' }}>
                        <WarningIcon fontSize="small" sx={{ verticalAlign: 'middle', mr: 0.5 }} />
                        Completados demasiado rápido
                      </Typography>
                    )}
                  </CardContent>
                </Card>
              </Grid>

              {/* No attempts yet */}
              {quizStats.totalAttempts === 0 && (
                <Grid item xs={12}>
                  <Alert severity="info">
                    Aún no hay intentos registrados para este quiz. Las estadísticas aparecerán cuando los usuarios comiencen a tomar el quiz.
                  </Alert>
                </Grid>
              )}
            </>
          )}
        </Grid>
      </TabPanel>

      {/* Question Dialog */}
      <Dialog
        open={openQuestionDialog}
        onClose={() => {
          setOpenQuestionDialog(false)
          setEditingQuestion(null)
          setQuestionEditorMode('quiz')
          setSaveQuestionToBank(false)
          resetQuestionForm()
        }}
        maxWidth="md"
        fullWidth
      >
        <DialogTitle>
          {editingQuestion
            ? questionEditorMode === 'bank'
              ? 'Editar pregunta del banco'
              : 'Editar pregunta del quiz'
            : questionEditorMode === 'bank'
              ? 'Nueva pregunta para el banco'
              : 'Nueva pregunta para este quiz'}
        </DialogTitle>
        <DialogContent>
          <Grid container spacing={2} sx={{ mt: 1 }}>
            <Grid item xs={12}>
              {!editingQuestion && questionEditorMode === 'quiz' && (
                <Alert severity="info" sx={{ mb: 2 }}>
                  Esta pregunta se agregará directamente al quiz. Si quieres reutilizarla más adelante, también puedes guardarla en el banco.
                </Alert>
              )}

              {!editingQuestion && questionEditorMode === 'bank' && (
                <Alert severity="info" sx={{ mb: 2 }}>
                  Esta pantalla crea una pregunta reusable en el banco global para futuros quizzes.
                </Alert>
              )}

              <TextField
                fullWidth
                multiline
                rows={3}
                label="Pregunta"
                value={newQuestion.question || ''}
                onChange={(e) => setNewQuestion(prev => ({ ...prev, question: e.target.value }))}
                required
              />
            </Grid>

            <Grid item xs={12} sm={6}>
              <FormControl fullWidth>
                <InputLabel>Tipo de pregunta</InputLabel>
                <Select
                  value={newQuestion.type || 'single'}
                  label="Tipo de pregunta"
                  onChange={(e) => {
                    const type = e.target.value as 'single' | 'multiple' | 'boolean'
                    setNewQuestion(prev => ({
                      ...prev,
                      type,
                      options: type === 'boolean' ? ['Falso', 'Verdadero'] : ['', '', '', ''],
                      correct_answers: type === 'multiple' ? [] : [0]
                    }))
                  }}
                >
                  <MenuItem value="boolean">Verdadero/Falso</MenuItem>
                  <MenuItem value="single">Selección Única</MenuItem>
                  <MenuItem value="multiple">Selección Múltiple</MenuItem>
                </Select>
              </FormControl>
            </Grid>

            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                type="number"
                label="Puntos"
                value={newQuestion.points || 1}
                onChange={(e) => setNewQuestion(prev => ({ ...prev, points: parseInt(e.target.value) || 1 }))}
                inputProps={{ min: 1, max: 10 }}
              />
            </Grid>

            <Grid item xs={12} sm={6}>
              <FormControl fullWidth>
                <InputLabel>Dificultad</InputLabel>
                <Select
                  value={newQuestion.difficulty || 'medium'}
                  label="Dificultad"
                  onChange={(e) => setNewQuestion(prev => ({ ...prev, difficulty: e.target.value as 'easy' | 'medium' | 'hard' }))}
                >
                  <MenuItem value="easy">Fácil</MenuItem>
                  <MenuItem value="medium">Medio</MenuItem>
                  <MenuItem value="hard">Difícil</MenuItem>
                </Select>
              </FormControl>
            </Grid>

            <Grid item xs={12} sm={6}>
              <FormControl fullWidth>
                <InputLabel>Categoría</InputLabel>
                <Select
                  value={newQuestion.category || ''}
                  label="Categoría"
                  onChange={(e) => applyQuestionCategorySuggestion(e.target.value)}
                >
                  <MenuItem value=''>
                    <em>Sin categoría</em>
                  </MenuItem>
                  {questionCategorySuggestions.map((category) => (
                    <MenuItem key={category} value={category}>
                      {category}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>

            {newQuestion.type !== 'boolean' && (
              <Grid item xs={12}>
                <Alert severity="info" sx={{ mb: 2 }}>
                  Completa primero las opciones que realmente usarás. Las vacías no se enviarán al backend.
                </Alert>
                <Typography variant="subtitle2" gutterBottom>
                  Opciones:
                </Typography>
                {(newQuestion.options || ['', '', '', '']).map((option, index) => (
                  <TextField
                    key={index}
                    fullWidth
                    label={`Opción ${index + 1}`}
                    value={option}
                    onChange={(e) => {
                      const newOptions = [...(newQuestion.options || ['', '', '', ''])]
                      newOptions[index] = e.target.value
                      setNewQuestion(prev => ({ ...prev, options: newOptions }))
                    }}
                    sx={{ mb: 1 }}
                  />
                ))}
              </Grid>
            )}

            {/* Correct Answer Selection */}
            <Grid item xs={12}>
              <Typography variant="subtitle2" gutterBottom sx={{ color: 'primary.main', fontWeight: 600 }}>
                Respuesta(s) Correcta(s):
              </Typography>

              {newQuestion.type === 'boolean' && (
                <RadioGroup
                  value={newQuestion.correct_answers?.[0] ?? 0}
                  onChange={(e) => setNewQuestion(prev => ({ ...prev, correct_answers: [parseInt(e.target.value)] }))}
                >
                  <FormControlLabel
                    value={0}
                    control={<Radio />}
                    label="Falso"
                  />
                  <FormControlLabel
                    value={1}
                    control={<Radio />}
                    label="Verdadero"
                  />
                </RadioGroup>
              )}

              {newQuestion.type === 'single' && (
                <RadioGroup
                  value={newQuestion.correct_answers?.[0] ?? 0}
                  onChange={(e) => setNewQuestion(prev => ({ ...prev, correct_answers: [parseInt(e.target.value)] }))}
                >
                  {(newQuestion.options || ['', '', '', '']).map((option, index) => (
                    <FormControlLabel
                      key={index}
                      value={index}
                      control={<Radio />}
                      label={option || `Opción ${index + 1}`}
                      disabled={!option?.trim()}
                    />
                  ))}
                </RadioGroup>
              )}

              {newQuestion.type === 'multiple' && (
                <Box>
                  {(newQuestion.options || ['', '', '', '']).map((option, index) => (
                    <FormControlLabel
                      key={index}
                      control={
                        <Checkbox
                          checked={newQuestion.correct_answers?.includes(index) || false}
                          onChange={(e) => {
                            const currentCorrect = newQuestion.correct_answers || []
                            const newCorrect = e.target.checked
                              ? [...currentCorrect, index]
                              : currentCorrect.filter(i => i !== index)
                            setNewQuestion(prev => ({ ...prev, correct_answers: newCorrect }))
                          }}
                          disabled={!option?.trim()}
                        />
                      }
                      label={option || `Opción ${index + 1}`}
                    />
                  ))}
                </Box>
              )}

              {newQuestion.type === 'multiple' && (!newQuestion.correct_answers || newQuestion.correct_answers.length === 0) && (
                <Alert severity="warning" sx={{ mt: 1 }}>
                  Debe seleccionar al menos una respuesta correcta
                </Alert>
              )}
            </Grid>

            <Grid item xs={12}>
              <TextField
                fullWidth
                multiline
                rows={2}
                label="Explicación (opcional)"
                value={newQuestion.explanation || ''}
                onChange={(e) => setNewQuestion(prev => ({ ...prev, explanation: e.target.value }))}
                helperText="Explicación que se mostrará después de responder"
              />
            </Grid>

            {!editingQuestion && questionEditorMode === 'quiz' && (
              <Grid item xs={12}>
                <FormControlLabel
                  control={
                    <Checkbox
                      checked={saveQuestionToBank}
                      onChange={(e) => setSaveQuestionToBank(e.target.checked)}
                    />
                  }
                  label="Guardar también esta pregunta en el banco para reutilizarla después"
                />
              </Grid>
            )}
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button
            onClick={() => {
              setOpenQuestionDialog(false)
              setEditingQuestion(null)
              setQuestionEditorMode('quiz')
              setSaveQuestionToBank(false)
              resetQuestionForm()
            }}
          >
            Cancelar
          </Button>
          <Button
            onClick={editingQuestion ? handleUpdateQuestion : handleAddQuestion}
            variant="contained"
            disabled={!newQuestion.question?.trim()}
          >
            {editingQuestion
              ? 'Actualizar'
              : questionEditorMode === 'bank'
                ? 'Guardar en banco'
                : saveQuestionToBank
                  ? 'Agregar y guardar en banco'
                  : 'Agregar al quiz'}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  )
}

export default LmsQuizManagement

import { getApiErrorReason } from 'src/utils/apiError'
import React, { useMemo, useState } from 'react'
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  Grid,
  IconButton,
  InputLabel,
  List,
  ListItem,
  ListItemText,
  MenuItem,
  Select,
  Stack,
  Tab,
  Tabs,
  TextField,
  Typography
} from '@mui/material'
import {
  Add as AddIcon,
  Delete as DeleteIcon,
  Download as DownloadIcon,
  Edit as EditIcon,
  PlayArrow as GenerateIcon,
  Schedule as ScheduleIcon,
  Summarize as SummarizeIcon
} from '@mui/icons-material'
import { useNavigate } from 'react-router-dom'
import { useMutation, useQuery, useQueryClient } from 'react-query'
import useAxiosPrivate from '@utils/use-axios-private'
import { notify } from 'src/utils/notify'
import LmsPageHeader from 'src/Components/lms/admin/LmsPageHeader'

import { headerText } from 'src/utils/responseHeaders'
type ReportType = 'user_progress' | 'course_analytics' | 'compliance' | 'quiz_performance' | 'custom'
type ReportFormat = 'csv' | 'pdf' | 'xlsx'
type ReportFrequency = 'daily' | 'weekly' | 'monthly'

interface ReportTemplate {
  id: number
  name: string
  description?: string
  type: ReportType
  columns: string[]
  filters?: Record<string, unknown>
  created_at: string
  updated_at: string
}

interface ScheduledReport {
  id: number
  template_id: number
  name: string
  frequency: ReportFrequency
  time: string
  format: ReportFormat
  recipients: string[]
  enabled: boolean
  next_run?: string
  template?: {
    name: string
    type: ReportType
  }
}

interface GeneratedReport {
  id: number
  name: string
  format: ReportFormat
  status: 'generating' | 'completed' | 'failed'
  record_count?: number
  created_at: string
  completed_at?: string
  template?: {
    name: string
    type: ReportType
  }
}

interface ReportingMetadata {
  byType: Record<string, { supported: string[]; recommended: string[] }>
  custom: { supported: string[]; recommended: string[] }
}

const templateColumnsPresets: Record<ReportType, string[]> = {
  user_progress: ['usuario', 'email', 'rol', 'cursosInscritos', 'cursosCompletados', 'porcentajeProgreso'],
  course_analytics: ['curso', 'categoria', 'inscritos', 'completados', 'porcentajeCompletacion', 'estado'],
  compliance: ['rol', 'usuario', 'cursoObligatorio', 'estado', 'fechaLimite', 'fechaCompletado'],
  quiz_performance: ['curso', 'usuario', 'intentoNumero', 'porcentaje', 'aprobado', 'fechaIntento'],
  custom: []
}

const reportTypeLabels: Record<ReportType, string> = {
  user_progress: 'Progreso de usuarios',
  course_analytics: 'Analítica de cursos',
  compliance: 'Cumplimiento',
  quiz_performance: 'Rendimiento de quizzes',
  custom: 'Personalizado'
}

const reportTypeOptions: Array<{ value: ReportType; label: string; helper: string }> = [
  {
    value: 'user_progress',
    label: reportTypeLabels.user_progress,
    helper: 'Úsalo para seguimiento general de avance por persona.'
  },
  {
    value: 'course_analytics',
    label: reportTypeLabels.course_analytics,
    helper: 'Sirve para comparar cursos por inscritos, completados y tasa de cierre.'
  },
  {
    value: 'compliance',
    label: reportTypeLabels.compliance,
    helper: 'Es el reporte más útil para cursos obligatorios y vencimientos.'
  },
  {
    value: 'quiz_performance',
    label: reportTypeLabels.quiz_performance,
    helper: 'Ayuda a revisar aprobación e intentos en evaluaciones.'
  },
  {
    value: 'custom',
    label: reportTypeLabels.custom,
    helper: 'Déjalo para casos puntuales donde ninguna plantilla estándar cubra la necesidad.'
  }
]

const knownCustomColumns = Array.from(
  new Set(
    Object.entries(templateColumnsPresets)
      .filter(([type]) => type !== 'custom')
      .flatMap(([, columns]) => columns)
  )
)

const emptyTemplateForm = {
  name: '',
  description: '',
  type: 'user_progress' as ReportType,
  columns: [...templateColumnsPresets.user_progress]
}

const emptyScheduleForm = {
  templateId: '',
  name: '',
  frequency: 'weekly' as ReportFrequency,
  time: '09:00',
  format: 'csv' as ReportFormat,
  recipients: [] as string[]
}

const getApiMessage = (error: any, fallback: string) =>
  getApiErrorReason(error)
  || error?.message
  || fallback

const getReportStatusLabel = (status: GeneratedReport['status']) => {
  if (status === 'completed') return 'Completado'
  if (status === 'failed') return 'Fallido'
  return 'Generando'
}

const LmsReporting: React.FC = () => {
  const navigate = useNavigate()
  const axiosPrivate = useAxiosPrivate()
  const queryClient = useQueryClient()
  const [activeTab, setActiveTab] = useState(0)
  const [templateDialogOpen, setTemplateDialogOpen] = useState(false)
  const [scheduleDialogOpen, setScheduleDialogOpen] = useState(false)
  const [editingTemplate, setEditingTemplate] = useState<ReportTemplate | null>(null)
  const [editingSchedule, setEditingSchedule] = useState<ScheduledReport | null>(null)
  const [templateForm, setTemplateForm] = useState(emptyTemplateForm)
  const [scheduleForm, setScheduleForm] = useState(emptyScheduleForm)
  const [customColumnInput, setCustomColumnInput] = useState('')
  const [recipientInput, setRecipientInput] = useState('')
  const isCustomTemplate = templateForm.type === 'custom'

  const metadataQuery = useQuery(['lms-reporting', 'metadata'], async () => {
    const response = await axiosPrivate.get('/lms/reporting/metadata')
    return response.data.data as ReportingMetadata
  })

  const metadata = metadataQuery.data
  const availableColumns = metadata?.byType?.[templateForm.type]?.recommended
    || metadata?.byType?.[templateForm.type]?.supported
    || templateColumnsPresets[templateForm.type]
  const availableCustomColumns = metadata?.custom?.supported || knownCustomColumns

  const templatesQuery = useQuery(['lms-reporting', 'templates'], async () => {
    const response = await axiosPrivate.get('/lms/reporting/templates')
    return response.data.data as ReportTemplate[]
  })

  const recentReportsQuery = useQuery(['lms-reporting', 'recent'], async () => {
    const response = await axiosPrivate.get('/lms/reporting/recent', {
      params: { limit: 10 }
    })
    return response.data.data as GeneratedReport[]
  })

  const scheduledReportsQuery = useQuery(['lms-reporting', 'scheduled'], async () => {
    const response = await axiosPrivate.get('/lms/reporting/scheduled')
    return response.data.data as ScheduledReport[]
  })

  const invalidateReporting = () => {
    queryClient.invalidateQueries(['lms-reporting', 'templates'])
    queryClient.invalidateQueries(['lms-reporting', 'recent'])
    queryClient.invalidateQueries(['lms-reporting', 'scheduled'])
  }

  const saveTemplateMutation = useMutation(
    async () => {
      const payload = {
        name: templateForm.name.trim(),
        description: templateForm.description.trim(),
        type: templateForm.type,
        columns: templateForm.columns
          .map((item) => item.trim())
          .filter(Boolean),
        filters: {}
      }

      if (editingTemplate) {
        const response = await axiosPrivate.put(`/lms/reporting/templates/${editingTemplate.id}`, payload)
        return response.data.data
      }

      const response = await axiosPrivate.post('/lms/reporting/templates', payload)
      return response.data.data
    },
    {
      onSuccess: () => {
        invalidateReporting()
        setTemplateDialogOpen(false)
        setEditingTemplate(null)
        setTemplateForm(emptyTemplateForm)
        setCustomColumnInput('')
        notify.success(editingTemplate ? 'Plantilla actualizada' : 'Plantilla creada', editingTemplate
            ? 'La plantilla quedó lista para seguir generando o programando reportes.'
            : 'La plantilla ya puede usarse para generar o programar reportes.')
      },
      onError: (error: any) => {
        notify.error('Error al guardar plantilla', getApiMessage(error, 'No se pudo guardar la plantilla.'))
      }
    }
  )

  const deleteTemplateMutation = useMutation(
    async (id: number) => axiosPrivate.delete(`/lms/reporting/templates/${id}`),
    {
      onSuccess: () => {
        invalidateReporting()
        notify.success('Plantilla eliminada', 'La plantilla ya no aparecerá en generación ni programación.')
      },
      onError: (error: any) => {
        notify.error('Error al eliminar plantilla', getApiMessage(error, 'No se pudo eliminar la plantilla.'))
      }
    }
  )

  const generateReportMutation = useMutation(
    async ({ templateId, format }: { templateId: number; format: ReportFormat }) => {
      const response = await axiosPrivate.post('/lms/reporting/generate', {
        templateId,
        format,
        filters: {}
      })
      return response.data.data as GeneratedReport
    },
    {
      onSuccess: () => {
        invalidateReporting()
        notify.success('Reporte generado', 'Quedó registrado en reportes recientes y podrás descargarlo cuando termine.')
      },
      onError: (error: any) => {
        notify.error('Error al generar reporte', getApiMessage(error, 'No se pudo generar el reporte.'))
      }
    }
  )

  const saveScheduleMutation = useMutation(
    async () => {
      const payload = {
        templateId: Number(scheduleForm.templateId),
        name: scheduleForm.name.trim(),
        frequency: scheduleForm.frequency,
        time: scheduleForm.time,
        format: scheduleForm.format,
        recipients: scheduleForm.recipients,
        filters: {}
      }

      if (editingSchedule) {
        const response = await axiosPrivate.put(`/lms/reporting/scheduled/${editingSchedule.id}`, payload)
        return response.data.data
      }

      const response = await axiosPrivate.post('/lms/reporting/schedule', payload)
      return response.data.data
    },
    {
      onSuccess: () => {
        invalidateReporting()
        setScheduleDialogOpen(false)
        setEditingSchedule(null)
        setScheduleForm(emptyScheduleForm)
        setRecipientInput('')
        notify.success(editingSchedule ? 'Programación actualizada' : 'Reporte programado', editingSchedule
            ? 'La programación quedó ajustada con los nuevos datos.'
            : 'La programación quedó activa para futuros envíos.')
      },
      onError: (error: any) => {
        notify.error('Error al guardar programación', getApiMessage(error, 'No se pudo guardar la programación.'))
      }
    }
  )

  const deleteScheduleMutation = useMutation(
    async (id: number) => axiosPrivate.delete(`/lms/reporting/scheduled/${id}`),
    {
      onSuccess: () => {
        invalidateReporting()
        notify.success('Programación eliminada', 'Ese envío ya no se ejecutará automáticamente.')
      },
      onError: (error: any) => {
        notify.error('Error al eliminar programación', getApiMessage(error, 'No se pudo eliminar la programación.'))
      }
    }
  )

  const templates = templatesQuery.data || []
  const recentReports = recentReportsQuery.data || []
  const scheduledReports = scheduledReportsQuery.data || []
  const complianceTemplate = templates.find((template) => template.type === 'compliance') || null

  const summary = useMemo(
    () => ({
      templates: templates.length,
      scheduled: scheduledReports.length,
      recent: recentReports.length
    }),
    [templates, scheduledReports, recentReports]
  )
  const reportingTabGuidance = [
    'Empieza por plantillas. Aquí defines la estructura base de cada reporte.',
    'Programa envíos solo cuando la plantilla ya esté clara y tenga destinatarios reales.',
    'Usa el histórico para validar qué sí generó el backend y qué sigue pendiente.'
  ]

  const handleCreateTemplate = () => {
    setEditingTemplate(null)
    setTemplateForm(emptyTemplateForm)
    setCustomColumnInput('')
    setTemplateDialogOpen(true)
  }

  const handleCreateComplianceTemplate = () => {
    setEditingTemplate(null)
    setTemplateForm({
      ...emptyTemplateForm,
      type: 'compliance',
      columns: [...templateColumnsPresets.compliance]
    })
    setCustomColumnInput('')
    setTemplateDialogOpen(true)
  }

  const handleEditTemplate = (template: ReportTemplate) => {
    setEditingTemplate(template)
    setTemplateForm({
      name: template.name,
      description: template.description || '',
      type: template.type,
      columns: template.columns || []
    })
    setCustomColumnInput('')
    setTemplateDialogOpen(true)
  }

  const toggleTemplateColumn = (column: string) => {
    setTemplateForm((prev) => {
      const nextColumns = prev.columns.includes(column)
        ? prev.columns.filter((item) => item !== column)
        : [...prev.columns, column]

      return {
        ...prev,
        columns: nextColumns
      }
    })
  }

  const addCustomColumns = () => {
    const incomingColumns = customColumnInput
      .split(',')
      .map((item) => item.trim())
      .filter(Boolean)

    if (incomingColumns.length === 0) return

    setTemplateForm((prev) => ({
      ...prev,
      columns: Array.from(new Set([...prev.columns, ...incomingColumns]))
    }))
    setCustomColumnInput('')
  }

  const removeTemplateColumn = (column: string) => {
    setTemplateForm((prev) => ({
      ...prev,
      columns: prev.columns.filter((item) => item !== column)
    }))
  }

  const addRecipients = () => {
    const incomingRecipients = recipientInput
      .split(',')
      .map((item) => item.trim())
      .filter(Boolean)

    if (incomingRecipients.length === 0) return

    setScheduleForm((prev) => ({
      ...prev,
      recipients: Array.from(new Set([...prev.recipients, ...incomingRecipients]))
    }))
    setRecipientInput('')
  }

  const removeRecipient = (recipient: string) => {
    setScheduleForm((prev) => ({
      ...prev,
      recipients: prev.recipients.filter((item) => item !== recipient)
    }))
  }

  const handleCreateSchedule = () => {
    setEditingSchedule(null)
    setScheduleForm(emptyScheduleForm)
    setRecipientInput('')
    setScheduleDialogOpen(true)
  }

  const handleCreateScheduleFromTemplate = (template: ReportTemplate) => {
    setEditingSchedule(null)
    setScheduleForm({
      ...emptyScheduleForm,
      templateId: String(template.id),
      name: `${template.name} programado`
    })
    setRecipientInput('')
    setScheduleDialogOpen(true)
  }

  const handleEditSchedule = (schedule: ScheduledReport) => {
    setEditingSchedule(schedule)
    setScheduleForm({
      templateId: String(schedule.template_id),
      name: schedule.name,
      frequency: schedule.frequency,
      time: schedule.time.slice(0, 5),
      format: schedule.format,
      recipients: schedule.recipients || []
    })
    setRecipientInput('')
    setScheduleDialogOpen(true)
  }

  const handleDownloadReport = async (report: GeneratedReport) => {
    try {
      const response = await axiosPrivate.get(`/lms/reporting/download/${report.id}`, {
        responseType: 'blob'
      })

      const blob = new Blob([response.data], {
        type:
          headerText(response.headers, 'content-type') ||
          'application/octet-stream'
      })
      const url = window.URL.createObjectURL(blob)
      const link = document.createElement('a')
      const extension = report.format
      link.href = url
      link.download = `${report.name}.${extension}`
      document.body.appendChild(link)
      link.click()
      link.remove()
      window.URL.revokeObjectURL(url)
    } catch (error: any) {
      notify.error('Error al descargar reporte', getApiMessage(error, 'No se pudo descargar el reporte.'))
    }
  }

  return (
    <Box sx={{ p: 3, maxWidth: 1536, mx: 'auto' }}>
      <Stack spacing={3}>
        <LmsPageHeader
          title='Reportes LMS'
          subtitle='Crea plantillas, programa reportes y descarga los que ya se generaron'
          icon={<SummarizeIcon />}
          actions={
            <Button variant='outlined' onClick={() => navigate('/lms/admin/analytics')}>
              Ver analíticas
            </Button>
          }
        />

        {!complianceTemplate && (
          <Button
            variant='outlined'
            startIcon={<AddIcon />}
            onClick={handleCreateComplianceTemplate}
            sx={{ alignSelf: 'flex-start' }}
          >
            Crear plantilla de cumplimiento
          </Button>
        )}

        <Grid container spacing={2}>
          <Grid item xs={12} md={4}>
            <Card>
              <CardContent>
                <Typography variant='subtitle2' color='text.secondary'>
                  Plantillas
                </Typography>
                <Typography variant='h4'>{summary.templates}</Typography>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={12} md={4}>
            <Card>
              <CardContent>
                <Typography variant='subtitle2' color='text.secondary'>
                  Programados activos
                </Typography>
                <Typography variant='h4'>{summary.scheduled}</Typography>
              </CardContent>
            </Card>
          </Grid>
          <Grid item xs={12} md={4}>
            <Card>
              <CardContent>
                <Typography variant='subtitle2' color='text.secondary'>
                  Reportes recientes
                </Typography>
                <Typography variant='h4'>{summary.recent}</Typography>
              </CardContent>
            </Card>
          </Grid>
        </Grid>

        <Tabs value={activeTab} onChange={(_, value) => setActiveTab(value)}>
          <Tab label='Plantillas' />
          <Tab label='Programados' />
          <Tab label='Recientes' />
        </Tabs>

        <Alert severity='info' sx={{ mt: 2 }}>
          {reportingTabGuidance[activeTab]}
        </Alert>

          {activeTab === 0 && (
          <Card>
            <CardContent>
              <Stack direction='row' justifyContent='space-between' alignItems='center' sx={{ mb: 2 }}>
                <Typography variant='h6'>Plantillas Reales</Typography>
                <Stack direction='row' spacing={1}>
                  {complianceTemplate && (
                    <Button
                      variant='outlined'
                      startIcon={<GenerateIcon />}
                      onClick={() =>
                        generateReportMutation.mutate({
                          templateId: complianceTemplate.id,
                          format: 'csv'
                        })
                      }
                    >
                      Generar cumplimiento
                    </Button>
                  )}
                  {!complianceTemplate && (
                    <Button
                      variant='outlined'
                      startIcon={<AddIcon />}
                      onClick={handleCreateComplianceTemplate}
                    >
                      Crear cumplimiento
                    </Button>
                  )}
                  <Button startIcon={<AddIcon />} variant='contained' onClick={handleCreateTemplate}>
                    Nueva plantilla
                  </Button>
                </Stack>
              </Stack>
              {templates.length === 0 ? (
                <Alert severity='warning'>Aún no tienes plantillas de reportes creadas.</Alert>
              ) : (
                <List>
                  {templates.map((template) => (
                    <ListItem
                      key={template.id}
                      secondaryAction={
                        <Stack direction='row' spacing={1} flexWrap='wrap' useFlexGap>
                          <Button
                            size='small'
                            variant='outlined'
                            startIcon={<GenerateIcon />}
                            onClick={() => generateReportMutation.mutate({ templateId: template.id, format: 'csv' })}
                          >
                            Generar
                          </Button>
                          <Button
                            size='small'
                            variant='outlined'
                            startIcon={<ScheduleIcon />}
                            onClick={() => handleCreateScheduleFromTemplate(template)}
                          >
                            Programar
                          </Button>
                          <IconButton onClick={() => handleEditTemplate(template)} title='Editar plantilla'>
                            <EditIcon />
                          </IconButton>
                          <IconButton onClick={() => deleteTemplateMutation.mutate(template.id)} title='Eliminar plantilla'>
                            <DeleteIcon />
                          </IconButton>
                        </Stack>
                      }
                    >
                      <ListItemText
                        primary={template.name}
                        secondary={
                          <Stack direction='row' spacing={1} flexWrap='wrap' useFlexGap sx={{ mt: 0.5 }}>
                            <Chip
                              icon={<SummarizeIcon />}
                              label={reportTypeLabels[template.type]}
                              size='small'
                            />
                            <Chip
                              label={`${template.columns.length} columnas`}
                              size='small'
                              variant='outlined'
                            />
                            <Chip
                              label='Generación rápida en CSV'
                              size='small'
                              variant='outlined'
                            />
                          </Stack>
                        }
                      />
                    </ListItem>
                  ))}
                </List>
              )}
            </CardContent>
          </Card>
        )}

        {activeTab === 1 && (
          <Card>
            <CardContent>
              <Stack direction='row' justifyContent='space-between' alignItems='center' sx={{ mb: 2 }}>
                <Typography variant='h6'>Programaciones Activas</Typography>
                <Button
                  startIcon={<ScheduleIcon />}
                  variant='contained'
                  onClick={handleCreateSchedule}
                  disabled={templates.length === 0}
                >
                  Programar reporte
                </Button>
              </Stack>
              {templates.length === 0 && (
                <Alert severity='warning' sx={{ mb: 2 }}>
                  Primero necesitas al menos una plantilla real para programar reportes.
                </Alert>
              )}
              {scheduledReports.length === 0 ? (
                <Stack spacing={2}>
                  <Alert severity='info'>No hay reportes programados activos.</Alert>
                  {templates.length > 0 && (
                    <Button
                      variant='outlined'
                      startIcon={<ScheduleIcon />}
                      onClick={() => handleCreateScheduleFromTemplate(templates[0])}
                      sx={{ alignSelf: 'flex-start' }}
                    >
                      Programar desde la primera plantilla disponible
                    </Button>
                  )}
                </Stack>
              ) : (
                <List>
                  {scheduledReports.map((schedule) => (
                    <ListItem
                      key={schedule.id}
                      secondaryAction={
                        <Stack direction='row' spacing={1}>
                          <IconButton onClick={() => handleEditSchedule(schedule)}>
                            <EditIcon />
                          </IconButton>
                          <IconButton onClick={() => deleteScheduleMutation.mutate(schedule.id)}>
                            <DeleteIcon />
                          </IconButton>
                        </Stack>
                      }
                    >
                      <ListItemText
                        primary={schedule.name}
                        secondary={
                          <Stack direction='row' spacing={1} flexWrap='wrap' useFlexGap sx={{ mt: 0.5 }}>
                            <Chip label={schedule.template?.name || `Template ${schedule.template_id}`} size='small' />
                            <Chip label={schedule.frequency} size='small' variant='outlined' />
                            <Chip label={`${schedule.time.slice(0, 5)} · ${schedule.format.toUpperCase()}`} size='small' variant='outlined' />
                            {schedule.next_run && (
                              <Chip label={`Siguiente: ${new Date(schedule.next_run).toLocaleString()}`} size='small' variant='outlined' />
                            )}
                          </Stack>
                        }
                      />
                    </ListItem>
                  ))}
                </List>
              )}
            </CardContent>
          </Card>
        )}

        {activeTab === 2 && (
          <Card>
            <CardContent>
              <Typography variant='h6' sx={{ mb: 2 }}>
                Reportes Recientes
              </Typography>
              {recentReports.length === 0 ? (
                <Alert severity='info'>
                  Todavía no hay reportes generados desde esta cuenta.
                </Alert>
              ) : (
                <List>
                  {recentReports.map((report) => (
                    <ListItem
                      key={report.id}
                      secondaryAction={
                        report.status === 'completed' ? (
                          <IconButton onClick={() => handleDownloadReport(report)}>
                            <DownloadIcon />
                          </IconButton>
                        ) : undefined
                      }
                    >
                      <ListItemText
                        primary={report.name}
                        secondary={
                          <Stack direction='row' spacing={1} flexWrap='wrap' useFlexGap sx={{ mt: 0.5 }}>
                            <Chip label={report.template?.name || 'Sin plantilla'} size='small' />
                            <Chip label={report.format.toUpperCase()} size='small' variant='outlined' />
                            <Chip label={getReportStatusLabel(report.status)} size='small' color={report.status === 'completed' ? 'success' : report.status === 'failed' ? 'error' : 'warning'} />
                            {report.record_count !== undefined && (
                              <Chip label={`${report.record_count} registros`} size='small' variant='outlined' />
                            )}
                            {report.completed_at && (
                              <Chip
                                label={`Completado: ${new Date(report.completed_at).toLocaleString('es-CO')}`}
                                size='small'
                                variant='outlined'
                              />
                            )}
                          </Stack>
                        }
                      />
                    </ListItem>
                  ))}
                </List>
              )}
            </CardContent>
          </Card>
        )}
      </Stack>

      <Dialog open={templateDialogOpen} onClose={() => setTemplateDialogOpen(false)} maxWidth='sm' fullWidth>
        <DialogTitle>{editingTemplate ? 'Editar plantilla' : 'Nueva plantilla'}</DialogTitle>
        <DialogContent>
          <Stack spacing={2} sx={{ mt: 1 }}>
            <TextField
              label='Nombre'
              value={templateForm.name}
              onChange={(event) => setTemplateForm((prev) => ({ ...prev, name: event.target.value }))}
              fullWidth
            />
            <TextField
              label='Descripción'
              value={templateForm.description}
              onChange={(event) => setTemplateForm((prev) => ({ ...prev, description: event.target.value }))}
              multiline
              minRows={2}
              fullWidth
            />
            <FormControl fullWidth>
              <InputLabel>Tipo</InputLabel>
              <Select
                label='Tipo'
                value={templateForm.type}
                  onChange={(event) => {
                    const nextType = event.target.value as ReportType
                    setTemplateForm((prev) => ({
                      ...prev,
                      type: nextType,
                      columns: [...templateColumnsPresets[nextType]]
                    }))
                  }}
                >
                {reportTypeOptions.map((option) => (
                  <MenuItem key={option.value} value={option.value}>
                    <Box>
                      <Typography variant='body2' sx={{ fontWeight: 600 }}>
                        {option.label}
                      </Typography>
                      <Typography variant='caption' color='text.secondary'>
                        {option.helper}
                      </Typography>
                    </Box>
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
            <Alert severity={isCustomTemplate ? 'warning' : 'info'}>
              {reportTypeOptions.find((option) => option.value === templateForm.type)?.helper}
            </Alert>
              {isCustomTemplate ? (
                <Stack spacing={2}>
                  <Box>
                    <Typography variant='subtitle2' sx={{ mb: 1 }}>
                      Columnas conocidas
                    </Typography>
                    <Typography variant='body2' color='text.secondary' sx={{ mb: 2 }}>
                      Puedes seleccionar columnas conocidas del LMS y, si hace falta, agregar extras manualmente.
                    </Typography>
                    <Stack direction='row' spacing={1} flexWrap='wrap' useFlexGap>
                      {availableCustomColumns.map((column) => {
                        const selected = templateForm.columns.includes(column)
                        return (
                          <Chip
                            key={column}
                            label={column}
                            clickable
                            color={selected ? 'primary' : 'default'}
                            variant={selected ? 'filled' : 'outlined'}
                            onClick={() => toggleTemplateColumn(column)}
                          />
                        )
                      })}
                    </Stack>
                  </Box>

                  <Box>
                    <Typography variant='subtitle2' sx={{ mb: 1 }}>
                      Columnas extra
                    </Typography>
                    <TextField
                      label='Agregar columnas manuales'
                      helperText='Escribe columnas extra separadas por coma y luego agrégalas.'
                      value={customColumnInput}
                      onChange={(event) => setCustomColumnInput(event.target.value)}
                      fullWidth
                    />
                    <Button sx={{ mt: 1.5 }} variant='outlined' onClick={addCustomColumns} disabled={!customColumnInput.trim()}>
                      Agregar columnas manuales
                    </Button>
                  </Box>

                  <Box>
                    <Typography variant='subtitle2' sx={{ mb: 1 }}>
                      Selección actual
                    </Typography>
                    {templateForm.columns.length === 0 ? (
                      <Alert severity='warning'>Todavía no has seleccionado columnas para este reporte.</Alert>
                    ) : (
                      <Stack direction='row' spacing={1} flexWrap='wrap' useFlexGap>
                        {templateForm.columns.map((column) => (
                          <Chip
                            key={column}
                            label={column}
                            onDelete={() => removeTemplateColumn(column)}
                            color='primary'
                            variant='outlined'
                          />
                        ))}
                      </Stack>
                    )}
                  </Box>
                </Stack>
              ) : (
                <Box>
                  <Typography variant='subtitle2' sx={{ mb: 1 }}>
                    Columnas disponibles
                  </Typography>
                  <Typography variant='body2' color='text.secondary' sx={{ mb: 2 }}>
                    Selecciona las columnas que quieres incluir. Ya no necesitas escribir los nombres manualmente.
                  </Typography>
                  <Stack direction='row' spacing={1} flexWrap='wrap' useFlexGap>
                    {availableColumns.map((column) => {
                      const selected = templateForm.columns.includes(column)
                      return (
                        <Chip
                          key={column}
                          label={column}
                          clickable
                          color={selected ? 'primary' : 'default'}
                          variant={selected ? 'filled' : 'outlined'}
                          onClick={() => toggleTemplateColumn(column)}
                        />
                      )
                    })}
                  </Stack>
                  <Typography variant='caption' color='text.secondary' sx={{ mt: 1.5, display: 'block' }}>
                    {templateForm.columns.length} columna(s) seleccionada(s)
                  </Typography>
                </Box>
              )}
            </Stack>
          </DialogContent>
        <DialogActions>
          <Button onClick={() => setTemplateDialogOpen(false)}>Cancelar</Button>
          <Button variant='contained' onClick={() => saveTemplateMutation.mutate()}>
            Guardar
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog open={scheduleDialogOpen} onClose={() => setScheduleDialogOpen(false)} maxWidth='sm' fullWidth>
        <DialogTitle>{editingSchedule ? 'Editar programación' : 'Programar reporte'}</DialogTitle>
        <DialogContent>
          <Stack spacing={2} sx={{ mt: 1 }}>
            <FormControl fullWidth>
              <InputLabel>Plantilla</InputLabel>
              <Select
                label='Plantilla'
                value={scheduleForm.templateId}
                onChange={(event) => setScheduleForm((prev) => ({ ...prev, templateId: event.target.value }))}
              >
                {templates.map((template) => (
                  <MenuItem key={template.id} value={String(template.id)}>
                    {template.name}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
            <TextField
              label='Nombre de la programación'
              value={scheduleForm.name}
              onChange={(event) => setScheduleForm((prev) => ({ ...prev, name: event.target.value }))}
              fullWidth
            />
            <Grid container spacing={2}>
              <Grid item xs={12} md={4}>
                <FormControl fullWidth>
                  <InputLabel>Frecuencia</InputLabel>
                  <Select
                    label='Frecuencia'
                    value={scheduleForm.frequency}
                    onChange={(event) => setScheduleForm((prev) => ({ ...prev, frequency: event.target.value as ReportFrequency }))}
                  >
                    <MenuItem value='daily'>Diario</MenuItem>
                    <MenuItem value='weekly'>Semanal</MenuItem>
                    <MenuItem value='monthly'>Mensual</MenuItem>
                  </Select>
                </FormControl>
              </Grid>
              <Grid item xs={12} md={4}>
                <TextField
                  label='Hora'
                  type='time'
                  value={scheduleForm.time}
                  onChange={(event) => setScheduleForm((prev) => ({ ...prev, time: event.target.value }))}
                  InputLabelProps={{ shrink: true }}
                  fullWidth
                />
              </Grid>
              <Grid item xs={12} md={4}>
                <FormControl fullWidth>
                  <InputLabel>Formato</InputLabel>
                  <Select
                    label='Formato'
                    value={scheduleForm.format}
                    onChange={(event) => setScheduleForm((prev) => ({ ...prev, format: event.target.value as ReportFormat }))}
                  >
                    <MenuItem value='csv'>CSV</MenuItem>
                    <MenuItem value='pdf'>PDF</MenuItem>
                    <MenuItem value='xlsx'>XLSX</MenuItem>
                  </Select>
                </FormControl>
              </Grid>
            </Grid>
            <Box>
              <TextField
                label='Agregar destinatarios'
                helperText='Escribe uno o varios correos separados por coma y luego agrégalos.'
                value={recipientInput}
                onChange={(event) => setRecipientInput(event.target.value)}
                fullWidth
              />
              <Button sx={{ mt: 1.5 }} variant='outlined' onClick={addRecipients} disabled={!recipientInput.trim()}>
                Agregar destinatarios
              </Button>
            </Box>
            <Box>
              <Typography variant='subtitle2' sx={{ mb: 1 }}>
                Destinatarios actuales
              </Typography>
              {scheduleForm.recipients.length === 0 ? (
                <Alert severity='warning'>Debes agregar al menos un destinatario para programar el reporte.</Alert>
              ) : (
                <Stack direction='row' spacing={1} flexWrap='wrap' useFlexGap>
                  {scheduleForm.recipients.map((recipient) => (
                    <Chip
                      key={recipient}
                      label={recipient}
                      onDelete={() => removeRecipient(recipient)}
                      color='primary'
                      variant='outlined'
                    />
                  ))}
                </Stack>
              )}
            </Box>
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setScheduleDialogOpen(false)}>Cancelar</Button>
          <Button variant='contained' onClick={() => saveScheduleMutation.mutate()}>
            Guardar
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  )
}

export default LmsReporting

import SignalLoader from 'src/Components/Common/SignalLoader'
import { useMemo, useState } from 'react'
import {
  Box,
  Typography,
  Paper,
  Chip,
  Divider,
  LinearProgress,
  Button,
  Alert,
  Grid,
  Accordion,
  AccordionSummary,
  AccordionDetails
} from '@mui/material'
import {
  ArrowBack as ArrowBackIcon,
  CheckCircle as CheckCircleIcon,
  Cancel as CancelIcon,
  School as SchoolIcon,
  EmojiEvents as AwardIcon,
  ExpandMore as ExpandMoreIcon
} from '@mui/icons-material'
import { useQuery } from 'react-query'
import { useParams, useNavigate } from 'react-router-dom'
import { lmsService } from 'src/services/lmsService'

const lessonStatusLabel = (status?: string) => {
  switch (status) {
    case 'completed':
      return 'Completada'
    case 'in_progress':
      return 'En progreso'
    default:
      return 'Sin iniciar'
  }
}

const lessonStatusColor = (status?: string) => {
  switch (status) {
    case 'completed':
      return 'success'
    case 'in_progress':
      return 'warning'
    default:
      return 'default'
  }
}

const StatTile = ({ label, value, color = 'text.primary' }: { label: string; value: string; color?: string }) => (
  <Paper variant="outlined" sx={{ p: 2, textAlign: 'center', height: '100%' }}>
    <Typography variant="h5" fontWeight="bold" color={color}>
      {value}
    </Typography>
    <Typography variant="caption" color="text.secondary">
      {label}
    </Typography>
  </Paper>
)

const LmsUserCourseReview = () => {
  const { userId, courseId } = useParams()
  const navigate = useNavigate()
  const [selectedAttempt, setSelectedAttempt] = useState<Record<number, number>>({})

  const { data, isLoading, error } = useQuery(
    ['lms-course-review', userId, courseId],
    () => lmsService.getCourseReviewForAdmin(Number(userId), Number(courseId)),
    { enabled: Boolean(userId && courseId) }
  )

  const stats = useMemo(() => {
    if (!data) return { quizzes: 0, attempts: 0, bestAverage: 0 }
    let quizzes = 0
    let attempts = 0
    const bests: number[] = []
    data.modules.forEach((module: any) =>
      module.lessons.forEach((lesson: any) => {
        if (!lesson.quiz) return
        quizzes++
        attempts += lesson.quiz.attempts.length
        const best = lesson.quiz.attempts.reduce((max: number, a: any) => Math.max(max, a.percentage), 0)
        if (lesson.quiz.attempts.length > 0) bests.push(best)
      })
    )
    const bestAverage = bests.length ? Math.round(bests.reduce((s, v) => s + v, 0) / bests.length) : 0
    return { quizzes, attempts, bestAverage }
  }, [data])

  if (isLoading) {
    return (
      <Box sx={{ p: 6, textAlign: 'center' }}>
        <SignalLoader />
      </Box>
    )
  }

  if (error || !data) {
    return (
      <Box sx={{ p: 3 }}>
        <Alert severity="error">No se pudo cargar el avance del usuario.</Alert>
      </Box>
    )
  }

  return (
    <Box sx={{ p: 3, maxWidth: 1100, mx: 'auto' }}>
      <Button startIcon={<ArrowBackIcon />} onClick={() => navigate(-1)} sx={{ mb: 2 }}>
        Volver
      </Button>

      {/* Encabezado */}
      <Paper variant="outlined" sx={{ p: 3, mb: 3 }}>
        <Box sx={{ display: 'flex', flexWrap: 'wrap', alignItems: 'flex-start', gap: 2 }}>
          <Box sx={{ flexGrow: 1, minWidth: 260 }}>
            <Typography variant="h5" fontWeight="bold">
              {data.user.name || `Usuario #${data.user.id}`}
            </Typography>
            <Typography variant="body2" color="text.secondary">
              {data.user.email || `ID ${data.user.id}`}
            </Typography>
            <Typography variant="subtitle1" sx={{ mt: 1 }}>
              Curso: <strong>{data.course.title}</strong>
            </Typography>
          </Box>
          <Chip
            icon={data.progress.isCompleted ? <CheckCircleIcon /> : <SchoolIcon />}
            label={data.progress.isCompleted ? 'Curso completado' : 'En progreso'}
            color={data.progress.isCompleted ? 'success' : 'primary'}
          />
        </Box>

        <Box sx={{ mt: 2, display: 'flex', alignItems: 'center', gap: 2 }}>
          <LinearProgress
            variant="determinate"
            value={data.progress.progressPercentage}
            sx={{ height: 10, borderRadius: 5, flexGrow: 1 }}
          />
          <Typography variant="h6" fontWeight="bold">
            {data.progress.progressPercentage}%
          </Typography>
        </Box>
      </Paper>

      {/* Resumen */}
      <Grid container spacing={2} sx={{ mb: 3 }}>
        <Grid item xs={6} md={3}>
          <StatTile
            label="Lecciones completadas"
            value={`${data.progress.completedLessons}/${data.progress.totalLessons}`}
          />
        </Grid>
        <Grid item xs={6} md={3}>
          <StatTile label="Quizzes" value={`${stats.quizzes}`} />
        </Grid>
        <Grid item xs={6} md={3}>
          <StatTile label="Intentos de quiz" value={`${stats.attempts}`} />
        </Grid>
        <Grid item xs={6} md={3}>
          <StatTile
            label="Mejor nota (prom.)"
            value={`${stats.bestAverage}%`}
            color={stats.bestAverage >= 70 ? 'success.main' : 'warning.main'}
          />
        </Grid>
      </Grid>

      <Alert severity="info" sx={{ mb: 3 }}>
        En las respuestas de quiz: <strong>verde</strong> = opción correcta, <strong>rojo</strong> = opción
        incorrecta que eligió el usuario.
      </Alert>

      {/* Módulos */}
      {data.modules.map((module: any) => (
        <Paper key={module.id} variant="outlined" sx={{ mb: 3, overflow: 'hidden' }}>
          <Box sx={{ p: 2, bgcolor: 'grey.50', display: 'flex', alignItems: 'center', gap: 1 }}>
            <SchoolIcon color="primary" />
            <Typography fontWeight="medium" sx={{ flexGrow: 1 }}>
              {module.title}
            </Typography>
            <Chip
              size="small"
              variant="outlined"
              label={`${module.lessons.filter((l: any) => l.progress?.status === 'completed').length}/${module.lessons.length} completadas`}
            />
          </Box>

          <Divider />

          {module.lessons.map((lesson: any, index: number) => {
            const quizAttempts = lesson.quiz?.attempts || []
            const activeId =
              selectedAttempt[lesson.quiz?.id] ??
              (quizAttempts.length ? quizAttempts[quizAttempts.length - 1].id : null)
            const active = quizAttempts.find((a: any) => a.id === activeId)

            return (
              <Box key={lesson.id} sx={{ p: 2, borderBottom: '1px solid', borderColor: 'divider' }}>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
                  <Typography variant="body2" color="text.secondary" sx={{ width: 22 }}>
                    {index + 1}.
                  </Typography>
                  <Typography fontWeight="medium" sx={{ flexGrow: 1 }}>
                    {lesson.title}
                  </Typography>
                  <Chip
                    size="small"
                    label={lessonStatusLabel(lesson.progress?.status)}
                    color={lessonStatusColor(lesson.progress?.status) as any}
                  />
                </Box>

                {lesson.quiz && (
                  <Box sx={{ mt: 2, pl: { xs: 0, md: 4 } }}>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap', mb: 1 }}>
                      <Typography variant="subtitle2" fontWeight="medium">
                        Quiz: {lesson.quiz.title}
                      </Typography>
                      <Chip size="small" variant="outlined" label={`Aprobación: ${lesson.quiz.passing_percentage}%`} />
                      {quizAttempts.length > 0 ? (
                        <>
                          <Chip
                            size="small"
                            color={quizAttempts.some((a: any) => a.passed) ? 'success' : 'error'}
                            label={quizAttempts.some((a: any) => a.passed) ? 'Aprobado' : 'No aprobado'}
                          />
                          <Chip
                            size="small"
                            variant="outlined"
                            label={`Mejor intento: ${Math.max(...quizAttempts.map((a: any) => a.percentage))}%`}
                          />
                        </>
                      ) : (
                        <Chip size="small" variant="outlined" label="Sin intentos" />
                      )}
                    </Box>

                    {quizAttempts.length > 0 && (
                      <>
                        <Typography variant="overline" color="text.secondary">
                          Intentos ({quizAttempts.length})
                        </Typography>
                        <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mb: 2 }}>
                          {quizAttempts.map((attempt: any) => (
                            <Button
                              key={attempt.id}
                              size="small"
                              variant={attempt.id === activeId ? 'contained' : 'outlined'}
                              color={attempt.passed ? 'success' : 'error'}
                              onClick={() =>
                                setSelectedAttempt((prev) => ({ ...prev, [lesson.quiz.id]: attempt.id }))
                              }
                            >
                              Intento {attempt.attempt_number} · {attempt.percentage}%
                            </Button>
                          ))}
                        </Box>

                        {active && (
                          <Accordion variant="outlined" disableGutters>
                            <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
                                <AwardIcon color={active.passed ? 'success' : 'disabled'} />
                                <Typography variant="body2" fontWeight="medium">
                                  Respuestas del Intento {active.attempt_number}
                                </Typography>
                                <Chip
                                  size="small"
                                  label={`${active.score}/${active.total_points} pts · ${active.percentage}%`}
                                />
                                <Chip
                                  size="small"
                                  color={active.passed ? 'success' : 'error'}
                                  label={active.passed ? 'Aprobado' : 'No aprobado'}
                                />
                              </Box>
                            </AccordionSummary>
                            <AccordionDetails>

                            {lesson.quiz.questions.map((question: any, questionIndex: number) => {
                              const answer = active.answers.find((a: any) => a.question_id === question.id)
                              const chosen = answer?.chosen || []
                              const toLetter = (index: number) => String.fromCharCode(65 + index)
                              const typeLabel =
                                question.type === 'multiple'
                                  ? 'Selección múltiple'
                                  : question.type === 'boolean'
                                    ? 'Verdadero / Falso'
                                    : 'Selección única'
                              const chosenLetters = chosen.map(toLetter).join(', ') || '—'
                              const correctLetters = question.correct_answers.map(toLetter).join(', ') || '—'

                              return (
                                <Paper key={question.id} variant="outlined" sx={{ p: 2, mb: 2 }}>
                                  <Box sx={{ display: 'flex', alignItems: 'flex-start', gap: 1, mb: 1.5 }}>
                                    <Chip size="small" color="primary" label={`Pregunta ${questionIndex + 1}`} />
                                    <Box sx={{ flexGrow: 1 }}>
                                      <Typography variant="subtitle1" fontWeight="medium">
                                        {question.question}
                                      </Typography>
                                      <Typography variant="caption" color="text.secondary">
                                        {typeLabel} · {question.points} punto(s)
                                      </Typography>
                                    </Box>
                                    <Chip
                                      size="small"
                                      color={answer?.is_correct ? 'success' : 'error'}
                                      icon={answer?.is_correct ? <CheckCircleIcon /> : <CancelIcon />}
                                      label={answer?.is_correct ? 'Correcta' : 'Incorrecta'}
                                    />
                                  </Box>

                                  <Typography variant="overline" color="text.secondary">
                                    Opciones de respuesta
                                  </Typography>

                                  {question.options.map((option: string, optionIndex: number) => {
                                    const isCorrect = question.correct_answers.includes(optionIndex)
                                    const isPicked = chosen.includes(optionIndex)
                                    const borderColor = isCorrect
                                      ? 'success.main'
                                      : isPicked
                                        ? 'error.main'
                                        : 'divider'
                                    const bg = isCorrect
                                      ? 'success.light'
                                      : isPicked
                                        ? 'error.light'
                                        : 'transparent'

                                    return (
                                      <Box
                                        key={optionIndex}
                                        sx={{
                                          display: 'flex',
                                          alignItems: 'center',
                                          gap: 1.5,
                                          px: 1.5,
                                          py: 0.75,
                                          mb: 0.75,
                                          borderRadius: 1,
                                          border: '1px solid',
                                          borderColor,
                                          bgcolor: bg
                                        }}
                                      >
                                        <Box
                                          sx={{
                                            width: 26,
                                            height: 26,
                                            borderRadius: '50%',
                                            border: '1px solid',
                                            borderColor,
                                            display: 'flex',
                                            alignItems: 'center',
                                            justifyContent: 'center',
                                            fontWeight: 'bold',
                                            fontSize: 13,
                                            flexShrink: 0
                                          }}
                                        >
                                          {toLetter(optionIndex)}
                                        </Box>
                                        <Typography variant="body2" sx={{ flexGrow: 1 }}>
                                          {option}
                                        </Typography>
                                        {isPicked && (
                                          <Chip
                                            size="small"
                                            color={isCorrect ? 'success' : 'error'}
                                            label="Tu respuesta"
                                          />
                                        )}
                                        {isCorrect && !isPicked && (
                                          <Chip size="small" color="success" variant="outlined" label="Correcta" />
                                        )}
                                      </Box>
                                    )
                                  })}

                                  <Box sx={{ mt: 1, display: 'flex', gap: 3, flexWrap: 'wrap' }}>
                                    <Typography variant="body2">
                                      Tu respuesta: <strong>{chosenLetters}</strong>
                                    </Typography>
                                    <Typography variant="body2">
                                      Respuesta correcta: <strong>{correctLetters}</strong>
                                    </Typography>
                                  </Box>

                                  {question.explanation && (
                                    <Typography
                                      variant="caption"
                                      color="text.secondary"
                                      sx={{ mt: 1, display: 'block' }}
                                    >
                                      {question.explanation}
                                    </Typography>
                                  )}
                                </Paper>
                              )
                            })}
                            </AccordionDetails>
                          </Accordion>
                        )}
                      </>
                    )}
                  </Box>
                )}
              </Box>
            )
          })}
        </Paper>
      ))}
    </Box>
  )
}

export default LmsUserCourseReview

import { getApiErrorReason } from 'src/utils/apiError'
import React, { useEffect, useMemo, useState } from 'react'
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  CardHeader,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  FormControlLabel,
  FormGroup,
  Grid,
  InputLabel,
  MenuItem,
  Select,
  Switch,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TablePagination,
  TableRow,
  TextField,
  Typography
} from '@mui/material'
import {
  Add as AddIcon,
  Edit as EditIcon,
  PersonOff as PersonOffIcon,
  Person as PersonIcon,
  People as PeopleIcon
} from '@mui/icons-material'
import { useMutation, useQuery, useQueryClient } from 'react-query'
import { useLmsUserOptions } from 'src/hooks/lms/useLmsUserOptions'
import useAxiosPrivate from '@utils/use-axios-private'
import { getRoleLabelEs, ROLES } from 'src/constants/roles'
import LmsPageHeader from 'src/Components/lms/admin/LmsPageHeader'
import { notify } from 'src/utils/notify'

type LmsRoleOption = {
  id: number
  name: string
  description?: string | null
}

type CustomerOption = {
  id: number
  name: string
  isActive: boolean
}

type LmsUser = {
  id: number
  name: string
  email: string
  active: boolean
  userType: 'internal' | 'client'
  customerId: number | null
  customerName: string | null
  roles: string[]
  lmsOnly: boolean
}

type LmsUsersSummary = {
  totalVisible: number
  totalFiltered: number
  lmsOnly: number
  clients: number
  inactive: number
}

type LmsUsersResponse = {
  data: LmsUser[]
  summary: LmsUsersSummary
  pagination: {
    total: number
    limit: number
    offset: number
  }
}

type LmsUserOptions = {
  roles: LmsRoleOption[]
  customers: CustomerOption[]
  defaults: {
    internalRoles: string[]
    clientRoles: string[]
    lmsOnlyRole: string
    generatedPassword: string
  }
}

type LmsUserForm = {
  nombre: string
  email: string
  password: string
  userType: 'internal' | 'client'
  customerId: string
  roles: string[]
  lmsOnly: boolean
  active: boolean
}

const emptyForm: LmsUserForm = {
  nombre: '',
  email: '',
  password: '',
  userType: 'internal',
  customerId: '',
  roles: [ROLES.EMPLOYEE],
  lmsOnly: false,
  active: true
}

const isValidEmail = (value: string) => /\S+@\S+\.\S+/.test(value)

const getRoleLabel = (roleName: string, description?: string | null) => {
  const baseLabel = getRoleLabelEs(roleName)

  return description ? `${baseLabel}: ${description}` : baseLabel
}

const getCompactRoleLabel = getRoleLabelEs

const LmsUserManagement: React.FC = () => {
  const axiosPrivate = useAxiosPrivate()
  const queryClient = useQueryClient()
  const [search, setSearch] = useState('')
  const [userTypeFilter, setUserTypeFilter] = useState<'all' | 'internal' | 'client'>('all')
  const [lmsOnlyFilter, setLmsOnlyFilter] = useState<'all' | 'only' | 'mixed'>('all')
  const [activeFilter, setActiveFilter] = useState<'all' | 'active' | 'inactive'>('all')
  const [dialogOpen, setDialogOpen] = useState(false)
  const [editingUser, setEditingUser] = useState<LmsUser | null>(null)
  const [form, setForm] = useState<LmsUserForm>(emptyForm)
  const [page, setPage] = useState(0)
  const [rowsPerPage, setRowsPerPage] = useState(10)

  const { data: optionsData } = useLmsUserOptions<LmsUserOptions>()

  const { data: usersData, isLoading } = useQuery<LmsUsersResponse>(
    ['lms-users', userTypeFilter, lmsOnlyFilter, activeFilter, search, page, rowsPerPage],
    async () => {
      const response = await axiosPrivate.get('/lms/users', {
        params: {
          userType: userTypeFilter === 'all' ? undefined : userTypeFilter,
          lmsOnly:
            lmsOnlyFilter === 'all' ? undefined : lmsOnlyFilter === 'only',
          active:
            activeFilter === 'all' ? undefined : activeFilter === 'active',
          search: search || undefined,
          limit: rowsPerPage,
          offset: page * rowsPerPage
        }
      })

      return {
        data: response.data.data || [],
        summary: response.data.summary || {
          totalVisible: 0,
          totalFiltered: 0,
          lmsOnly: 0,
          clients: 0,
          inactive: 0
        },
        pagination: response.data.pagination || {
          total: 0,
          limit: rowsPerPage,
          offset: page * rowsPerPage
        }
      }
    },
    { keepPreviousData: true }
  )

  const users = usersData?.data || []
  const usersSummary = usersData?.summary || {
    totalVisible: 0,
    totalFiltered: 0,
    lmsOnly: 0,
    clients: 0,
    inactive: 0
  }
  const totalUsers = usersData?.pagination?.total || 0
  const roleOptions = optionsData?.roles || []
  const customerOptions = optionsData?.customers || []

  const saveUserMutation = useMutation(
    async (payload: LmsUserForm) => {
      const body = {
        nombre: payload.nombre,
        email: payload.email,
        password: payload.password || undefined,
        userType: payload.userType,
        customerId: payload.userType === 'client' ? Number(payload.customerId) : null,
        roles: payload.roles,
        lmsOnly: payload.lmsOnly,
        active: payload.active
      }

      if (editingUser) {
        return axiosPrivate.put(`/lms/users/${editingUser.id}`, body)
      }

      return axiosPrivate.post('/lms/users', body)
    },
    {
      onSuccess: () => {
        queryClient.invalidateQueries(['lms-users'])
        setDialogOpen(false)
        setEditingUser(null)
        setForm(emptyForm)
        notify.success(editingUser ? 'Usuario LMS actualizado' : 'Usuario LMS creado')
      },
      onError: (error: any) => {
        notify.error(getApiErrorReason(error) || 'No se pudo guardar el usuario LMS')
      }
    }
  )

  const toggleActiveMutation = useMutation(
    async ({ userId, active }: { userId: number; active: boolean }) =>
      axiosPrivate.patch(`/lms/users/${userId}/active`, { active }),
    {
      onSuccess: (_, variables) => {
        queryClient.invalidateQueries(['lms-users'])
        notify.success(variables.active ? 'Usuario activado' : 'Usuario desactivado')
      },
      onError: () => {
        notify.error('No se pudo actualizar el estado del usuario')
      }
    }
  )

  const summary = useMemo(() => usersSummary, [usersSummary])

  const applyUserTypeDefaults = (userType: 'internal' | 'client', currentLmsOnly: boolean) => {
    const defaults = optionsData?.defaults
    if (!defaults) return

    const roles = userType === 'client' ? [...defaults.clientRoles] : [...defaults.internalRoles]
    if (currentLmsOnly && !roles.includes(defaults.lmsOnlyRole)) {
      roles.push(defaults.lmsOnlyRole)
    }

    setForm((prev) => ({
      ...prev,
      userType,
      customerId: userType === 'client' ? prev.customerId : '',
      roles
    }))
  }

  const buildCreateForm = (overrides?: Partial<LmsUserForm>) => {
    const defaults = optionsData?.defaults
    const fallbackUserType =
      overrides?.userType
      || (userTypeFilter === 'client' ? 'client' : 'internal')
    const fallbackLmsOnly =
      overrides?.lmsOnly
      ?? (lmsOnlyFilter === 'only')
    const baseRoles =
      fallbackUserType === 'client'
        ? [...(defaults?.clientRoles || ['user'])]
        : [...(defaults?.internalRoles || ['employee'])]

    const nextForm: LmsUserForm = {
      ...emptyForm,
      password: defaults?.generatedPassword || '',
      userType: fallbackUserType,
      lmsOnly: fallbackLmsOnly,
      roles: baseRoles,
      ...overrides
    }

    if (nextForm.userType === 'internal') {
      nextForm.customerId = ''
    }

    return nextForm
  }

  const handleOpenCreate = () => {
    setEditingUser(null)
    setForm(buildCreateForm())
    setDialogOpen(true)
  }

  const handleOpenCreatePreset = (userType: 'internal' | 'client', lmsOnly: boolean) => {
    setEditingUser(null)
    setForm(buildCreateForm({ userType, lmsOnly }))
    setDialogOpen(true)
  }

  const handleOpenEdit = (user: LmsUser) => {
    setEditingUser(user)
    setForm({
      nombre: user.name,
      email: user.email,
      password: '',
      userType: user.userType,
      customerId: user.customerId ? String(user.customerId) : '',
      roles: user.roles.filter((role) => role !== ROLES.LMS_ONLY),
      lmsOnly: user.lmsOnly,
      active: user.active
    })
    setDialogOpen(true)
  }

  const effectiveRoles = useMemo(() => {
    const roles = new Set(form.roles)
    const lmsOnlyRole = optionsData?.defaults?.lmsOnlyRole || ROLES.LMS_ONLY
    if (form.lmsOnly) {
      roles.add(lmsOnlyRole)
    } else {
      roles.delete(lmsOnlyRole)
    }
    return Array.from(roles)
  }, [form.roles, form.lmsOnly, optionsData])

  const normalizedName = form.nombre.trim()
  const normalizedEmail = form.email.trim()
  const needsCustomer = form.userType === 'client'
  const selectedCustomerName = customerOptions.find(
    (customer) => String(customer.id) === form.customerId
  )?.name
  const isSaveDisabled =
    saveUserMutation.isLoading ||
    normalizedName.length < 3 ||
    !isValidEmail(normalizedEmail) ||
    (!editingUser && form.password.trim().length < 8) ||
    (needsCustomer && !form.customerId) ||
    effectiveRoles.filter((role) => role !== ROLES.LMS_ONLY).length === 0

  const handleToggleRole = (roleName: string) => {
    setForm((prev) => {
      const hasRole = prev.roles.includes(roleName)
      return {
        ...prev,
        roles: hasRole ? prev.roles.filter((role) => role !== roleName) : [...prev.roles, roleName]
      }
    })
  }

  const handleSave = () => {
    saveUserMutation.mutate({
      ...form,
      roles: effectiveRoles
    })
  }

  const handleChangePage = (_event: unknown, nextPage: number) => {
    setPage(nextPage)
  }

  const handleChangeRowsPerPage = (event: React.ChangeEvent<HTMLInputElement>) => {
    setRowsPerPage(parseInt(event.target.value, 10))
    setPage(0)
  }

  useEffect(() => {
    setPage(0)
  }, [search, userTypeFilter, lmsOnlyFilter, activeFilter])

  return (
    <Box sx={{ p: 3, maxWidth: 1536, mx: 'auto' }}>
      <LmsPageHeader
        title='Gestión de Usuarios LMS'
        subtitle='Crea y administra accesos para internos, clientes y usuarios solo LMS'
        icon={<PeopleIcon />}
        actions={
          <Button variant='contained' startIcon={<AddIcon />} onClick={handleOpenCreate}>
            Nuevo Usuario LMS
          </Button>
        }
      />

      <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mb: 3 }}>
        <Chip label={`${summary.totalFiltered} usuarios filtrados`} variant='outlined' />
        <Chip label={`${summary.totalVisible} visibles en esta página`} variant='outlined' />
        <Chip label={`${summary.lmsOnly} LMS-only`} variant='outlined' />
        <Chip label={`${summary.clients} clientes`} variant='outlined' />
        <Chip label={`${summary.inactive} inactivos`} variant='outlined' />
      </Box>

      <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mb: 3 }}>
        <Button variant='outlined' size='small' onClick={() => handleOpenCreatePreset('internal', true)}>
          Nuevo interno solo LMS
        </Button>
        <Button variant='outlined' size='small' onClick={() => handleOpenCreatePreset('client', true)}>
          Nuevo cliente solo LMS
        </Button>
      </Box>

      <Card sx={{ mb: 3 }}>
        <CardHeader title='Filtros' subheader='Aísla el segmento que quieres revisar antes de crear, editar o activar accesos.' />
        <CardContent>
          <Grid container spacing={2}>
            <Grid item xs={12} md={4}>
              <TextField
                fullWidth
                label='Buscar por nombre o correo'
                value={search}
                onChange={(event) => setSearch(event.target.value)}
              />
            </Grid>
            <Grid item xs={12} md={3}>
              <TextField
                select
                fullWidth
                label='Tipo de usuario'
                value={userTypeFilter}
                onChange={(event) => setUserTypeFilter(event.target.value as 'all' | 'internal' | 'client')}
              >
                <MenuItem value='all'>Todos</MenuItem>
                <MenuItem value='internal'>Internos</MenuItem>
                <MenuItem value='client'>Clientes</MenuItem>
              </TextField>
            </Grid>
            <Grid item xs={12} md={2.5}>
              <TextField
                select
                fullWidth
                label='Acceso LMS'
                value={lmsOnlyFilter}
                onChange={(event) => setLmsOnlyFilter(event.target.value as 'all' | 'only' | 'mixed')}
              >
                <MenuItem value='all'>Todos</MenuItem>
                <MenuItem value='only'>Solo LMS</MenuItem>
                <MenuItem value='mixed'>Acceso mixto</MenuItem>
              </TextField>
            </Grid>
            <Grid item xs={12} md={2.5}>
              <TextField
                select
                fullWidth
                label='Estado'
                value={activeFilter}
                onChange={(event) => setActiveFilter(event.target.value as 'all' | 'active' | 'inactive')}
              >
                <MenuItem value='all'>Todos</MenuItem>
                <MenuItem value='active'>Activos</MenuItem>
                <MenuItem value='inactive'>Inactivos</MenuItem>
              </TextField>
            </Grid>
          </Grid>
        </CardContent>
      </Card>

      <Card>
        <CardHeader
          title='Usuarios LMS'
          subheader='Aquí puedes ajustar customer, roles y restricción LMS-only sin salir del módulo.'
        />
        <CardContent sx={{ p: 0 }}>
          <TableContainer>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell>Usuario</TableCell>
                  <TableCell>Tipo</TableCell>
                  <TableCell>Cliente</TableCell>
                  <TableCell>Roles</TableCell>
                  <TableCell>Acceso</TableCell>
                  <TableCell>Estado</TableCell>
                  <TableCell>Acciones</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {!isLoading && users.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={7} align='center' sx={{ py: 8 }}>
                      <Typography color='text.secondary'>
                        No hay usuarios LMS para los filtros actuales.
                      </Typography>
                    </TableCell>
                  </TableRow>
                ) : (
                  users.map((user) => (
                    <TableRow key={user.id}>
                      <TableCell>
                        <Typography variant='body2' fontWeight={600}>
                          {user.name}
                        </Typography>
                        <Typography variant='caption' color='text.secondary'>
                          {user.email}
                        </Typography>
                      </TableCell>
                      <TableCell>
                        <Chip
                          label={user.userType === 'client' ? 'Cliente' : 'Interno'}
                          size='small'
                          color={user.userType === 'client' ? 'secondary' : 'primary'}
                          variant='outlined'
                        />
                      </TableCell>
                      <TableCell>{user.customerName || 'Sin cliente'}</TableCell>
                      <TableCell>
                        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
                          {user.roles.filter((role) => role !== ROLES.LMS_ONLY).map((role) => (
                            <Chip key={role} label={getCompactRoleLabel(role)} size='small' variant='outlined' />
                          ))}
                        </Box>
                      </TableCell>
                      <TableCell>
                        <Chip
                          label={user.lmsOnly ? 'Solo LMS' : 'Acceso mixto'}
                          size='small'
                          color={user.lmsOnly ? 'warning' : 'default'}
                        />
                      </TableCell>
                      <TableCell>
                        <Chip
                          label={user.active ? 'Activo' : 'Inactivo'}
                          size='small'
                          color={user.active ? 'success' : 'default'}
                        />
                      </TableCell>
                      <TableCell>
                        <Box sx={{ display: 'flex', gap: 1 }}>
                          <Button size='small' startIcon={<EditIcon />} onClick={() => handleOpenEdit(user)}>
                            Editar
                          </Button>
                          <Button
                            size='small'
                            color={user.active ? 'warning' : 'success'}
                            startIcon={user.active ? <PersonOffIcon /> : <PersonIcon />}
                            onClick={() =>
                              toggleActiveMutation.mutate({
                                userId: user.id,
                                active: !user.active
                              })
                            }
                          >
                            {user.active ? 'Desactivar' : 'Activar'}
                          </Button>
                        </Box>
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </TableContainer>
          <TablePagination
            component='div'
            count={totalUsers}
            page={page}
            onPageChange={handleChangePage}
            rowsPerPage={rowsPerPage}
            onRowsPerPageChange={handleChangeRowsPerPage}
            rowsPerPageOptions={[10, 25, 50]}
            labelRowsPerPage='Usuarios por página'
            labelDisplayedRows={({ from, to, count }) => `${from}-${to} de ${count !== -1 ? count : `más de ${to}`}`}
          />
        </CardContent>
      </Card>

      <Dialog open={dialogOpen} onClose={() => setDialogOpen(false)} fullWidth maxWidth='md'>
        <DialogTitle>{editingUser ? 'Editar usuario LMS' : 'Nuevo usuario LMS'}</DialogTitle>
        <DialogContent>
          <Grid container spacing={2} sx={{ mt: 1 }}>
            <Grid item xs={12}>
              <Alert severity='info'>
                Define primero el tipo de usuario y luego ajusta el alcance. Si activas
                <strong> LMS-only</strong>, la persona quedará redirigida solo a rutas del LMS.
              </Alert>
            </Grid>
            {editingUser && (
              <Grid item xs={12}>
                <Alert severity='warning'>
                  Esta pantalla ajusta la capa LMS del usuario. Si la persona ya tiene roles de otros módulos, se conservarán al guardar.
                </Alert>
              </Grid>
            )}
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label='Nombre'
                value={form.nombre}
                onChange={(event) => setForm((prev) => ({ ...prev, nombre: event.target.value }))}
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label='Correo'
                value={form.email}
                onChange={(event) => setForm((prev) => ({ ...prev, email: event.target.value }))}
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label={editingUser ? 'Nueva contraseña (opcional)' : 'Contraseña inicial'}
                value={form.password}
                onChange={(event) => setForm((prev) => ({ ...prev, password: event.target.value }))}
                helperText={editingUser ? 'Déjalo vacío si no quieres cambiarla.' : 'Puedes usar la sugerida o escribir una propia de 8+ caracteres.'}
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                select
                fullWidth
                label='Tipo de usuario'
                value={form.userType}
                onChange={(event) => applyUserTypeDefaults(event.target.value as 'internal' | 'client', form.lmsOnly)}
              >
                <MenuItem value='internal'>Interno</MenuItem>
                <MenuItem value='client'>Cliente</MenuItem>
              </TextField>
            </Grid>
            {form.userType === 'client' && (
              <Grid item xs={12}>
                <FormControl fullWidth>
                  <InputLabel>Cliente</InputLabel>
                  <Select
                    value={form.customerId}
                    label='Cliente'
                    onChange={(event) => setForm((prev) => ({ ...prev, customerId: event.target.value }))}
                  >
                    {customerOptions.map((customer) => (
                      <MenuItem key={customer.id} value={String(customer.id)}>
                        {customer.name}
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Grid>
            )}
            <Grid item xs={12}>
              <Alert severity={form.userType === 'client' ? 'warning' : 'info'}>
                {form.userType === 'client'
                  ? 'Los usuarios cliente acceden a cursos con audiencia client o both. Si activas LMS-only, no podrán entrar a otros módulos del sistema.'
                  : 'Los usuarios internos pueden recibir cursos obligatorios. Usa Training Manager solo para responsables de operación del LMS.'}
              </Alert>
            </Grid>
            <Grid item xs={12}>
              <Alert severity='info'>
                Perfil resultante: <strong>{form.userType === 'client' ? 'Cliente' : 'Interno'}</strong>
                {needsCustomer ? ` · ${selectedCustomerName || 'Cliente pendiente por seleccionar'}` : ' · Sin empresa asociada'}
                {form.lmsOnly ? ' · Solo LMS' : ' · Acceso mixto'}
                {effectiveRoles.filter((role) => role !== ROLES.LMS_ONLY).length > 0
                  ? ` · Roles: ${effectiveRoles.filter((role) => role !== ROLES.LMS_ONLY).join(', ')}`
                  : ' · Selecciona al menos un rol operativo'}
              </Alert>
            </Grid>
            <Grid item xs={12} md={6}>
              <FormControlLabel
                control={
                  <Switch
                    checked={form.lmsOnly}
                    onChange={(event) => {
                      const checked = event.target.checked
                      setForm((prev) => ({ ...prev, lmsOnly: checked }))
                    }}
                  />
                }
                label='Restringir a LMS-only'
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <FormControlLabel
                control={
                  <Switch
                    checked={form.active}
                    onChange={(event) => setForm((prev) => ({ ...prev, active: event.target.checked }))}
                  />
                }
                label='Usuario activo'
              />
            </Grid>
            <Grid item xs={12}>
              <Typography variant='subtitle2' sx={{ mb: 1 }}>
                Roles operativos
              </Typography>
              <FormGroup>
                <Grid container spacing={1}>
                  {roleOptions
                    .filter((role) => role.name !== ROLES.LMS_ONLY)
                    .map((role) => {
                      const disabled =
                        form.userType === 'client' &&
                        (role.name === ROLES.ADMIN || role.name === ROLES.TRAINING_MANAGER || role.name === ROLES.EMPLOYEE)

                      return (
                        <Grid item xs={12} md={6} key={role.id}>
                          <FormControlLabel
                            control={
                              <Switch
                                checked={form.roles.includes(role.name)}
                                onChange={() => handleToggleRole(role.name)}
                                disabled={disabled}
                              />
                            }
                            label={getRoleLabel(role.name, role.description)}
                          />
                        </Grid>
                      )
                    })}
                </Grid>
              </FormGroup>
              <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mt: 1 }}>
                {effectiveRoles.map((role) => (
                  <Chip
                    key={role}
                    label={role === ROLES.LMS_ONLY ? 'Solo LMS' : getRoleLabel(role)}
                    size='small'
                    color={role === ROLES.LMS_ONLY ? 'warning' : 'default'}
                  />
                ))}
              </Box>
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDialogOpen(false)}>Cancelar</Button>
          <Button variant='contained' onClick={handleSave} disabled={isSaveDisabled}>
            {saveUserMutation.isLoading ? 'Guardando...' : 'Guardar'}
          </Button>
        </DialogActions>
      </Dialog>

    </Box>
  )
}

