                      thickness={4}
                      sx={{ position: 'absolute', color: 'action.hover' }}
                    />
                    <CircularProgress
                      variant='determinate'
                      value={hero.progress || 0}
                      size={88}
                      thickness={4}
                      color={heroTone.color}
                      sx={{ position: 'absolute' }}
                    />
                    <Box
                      sx={{
