                          <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, mt: 0.5 }}>
                            <Box sx={{ color: 'rgba(200,216,232,0.6)', display: 'flex', alignItems: 'center', gap: 0.5 }}>
