                              <Typography variant='caption' sx={{ fontSize: '0.73rem', color: 'rgba(200,216,232,0.6)' }}>
                                {lesson.duration}
                              </Typography>
                            </Box>
                          </Box>
                        </Box>
                      </Box>
                    )
                  })}
                </Box>
              )}
            </Box>
          )
        })}
      </Box>
    </Box>
