      }}>

        {/* Header nav */}
        <Box
          sx={{
            px: { xs: 2, md: 3 },
            height: 52,
            borderBottom: '1px solid #e2e8f0',
            bgcolor: '#ffffff',
            display: 'flex',
            alignItems: 'center',
            gap: 1,
            flexShrink: 0
          }}
        >
          <IconButton onClick={() => navigate(-1)} size='small'>
            <ArrowBackIcon sx={{ fontSize: 18 }} />
          </IconButton>
          {!isMobile && !sidebarOpen && (
            <IconButton onClick={() => setSidebarOpen(true)} size='small'>
              <MenuIcon sx={{ fontSize: 18 }} />
            </IconButton>
