const quillModules = {
  toolbar: [
    [{ header: [1, 2, 3, false] }],
    ['bold', 'italic', 'underline'],
    [{ list: 'ordered' }, { list: 'bullet' }],
    ['link', 'blockquote', 'code-block'],
    ['clean']
  ]
}

const quillFormats = [
  'header',
  'bold',
  'italic',
  'underline',
  'list',
  'link',
  'blockquote',
  'code-block'
]

interface QuillEditorProps {
  value: string
  onChange: (value: string) => void
}

const QuillEditor: React.FC<QuillEditorProps> = ({ value, onChange }) => {
  const containerRef = useRef<HTMLDivElement | null>(null)
  const quillRef = useRef<Quill | null>(null)
  const onChangeRef = useRef(onChange)

  useEffect(() => {
    onChangeRef.current = onChange
  }, [onChange])

  useEffect(() => {
    if (!containerRef.current || quillRef.current) {
      return
    }

    const host = document.createElement('div')
    containerRef.current.appendChild(host)

    const quill = new Quill(host, {
      theme: 'snow',
      modules: quillModules,
      formats: quillFormats
    })

    quill.root.innerHTML = value || ''
    quill.on('text-change', () => {
      onChangeRef.current(quill.root.innerHTML)
    })

    quillRef.current = quill

    return () => {
      quillRef.current = null
      if (containerRef.current && host.parentNode === containerRef.current) {
        containerRef.current.removeChild(host)
      }
    }
  }, [])

  useEffect(() => {
    const quill = quillRef.current
    if (!quill) {
      return
    }

    const nextValue = value || ''
    if (quill.root.innerHTML !== nextValue) {
      const selection = quill.getSelection()
      quill.root.innerHTML = nextValue
      if (selection) {
        quill.setSelection(selection)
      }
    }
  }, [value])

  return <Box className="quill-editor-shell" ref={containerRef} />
}

