  })
  const markAllAsReadMutation = useMarkAllNotificationsAsRead({
    onSuccess: () => {
      setFeedbackMessage('Se actualizó tu bandeja y ya no quedan avisos sin leer.')
    }
  })

  const notifications = data?.notifications || []

  const unreadCount = Number(
    data?.summary?.unread ?? notifications.filter((notification) => !notification.read).length
  )
  const actionRequiredCount = notifications.filter(
    (notification) => hasNotificationAction(notification) && !notification.read
  ).length

  const filteredNotifications = useMemo(() => {
    return notifications
      .filter((notification) => {
      switch (filter) {
        case 'unread':
          return !notification.read
        case 'actionRequired':
          return hasNotificationAction(notification) && !notification.read
        default:
          return true
      }
      })
      .sort((left, right) => {
        const leftPriority =
          (hasNotificationAction(left) && !left.read ? 2 : 0) + (!left.read ? 1 : 0)
        const rightPriority =
          (hasNotificationAction(right) && !right.read ? 2 : 0) + (!right.read ? 1 : 0)

        if (leftPriority !== rightPriority) {
          return rightPriority - leftPriority
        }

        return new Date(right.timestamp).getTime() - new Date(left.timestamp).getTime()
      })
  }, [filter, notifications])

  useEffect(() => {
    if (!feedbackMessage) {
      return
    }

    const timeout = window.setTimeout(() => {
      setFeedbackMessage(null)
    }, 3500)

    return () => window.clearTimeout(timeout)
  }, [feedbackMessage])

  const handleMarkAsRead = (notificationId: string) => {
    markAsReadMutation.mutate(notificationId)
  }

  const handleMarkAllAsRead = () => {
    markAllAsReadMutation.mutate()
  }

  const handleNotificationClick = (notification: Notification) => {
    setSelectedNotification(notification)
    setOpenDialog(true)

    if (!notification.read) {
      handleMarkAsRead(notification.id)
    }
  }

  const handleTakeAction = (notification: Notification) => {
    if (notification.actionUrl) {
      navigate(notification.actionUrl)
      setOpenDialog(false)
      return
    }

    if (notification.metadata?.certificateId) {
      navigate(`/lms/certificate/${notification.metadata.certificateId}`)
      setOpenDialog(false)
      return
    }

    if (notification.metadata?.courseId) {
      navigate(`/lms/course/${notification.metadata.courseId}`)
      setOpenDialog(false)
      return
    }

    if (notification.metadata?.assignmentId) {
      navigate('/lms/employee')
      setOpenDialog(false)
    }
  }

  return (
    <Box>
      <Card>
        <CardHeader
          title={
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
              <Badge badgeContent={unreadCount} color='error'>
                <NotificationsIcon />
              </Badge>
              <Typography variant='h6'>Centro de notificaciones</Typography>
            </Box>
          }
          action={
            <Box sx={{ display: 'flex', gap: 1 }}>
              <FormControl size='small' sx={{ minWidth: 150 }}>
                <InputLabel>Filtrar</InputLabel>
                <Select
                  value={filter}
                  label='Filtrar'
                  onChange={(event) =>
                    setFilter(event.target.value as 'all' | 'unread' | 'actionRequired')
                  }
                >
                  <MenuItem value='all'>Todas</MenuItem>
                  <MenuItem value='unread'>No leídas ({unreadCount})</MenuItem>
                  <MenuItem value='actionRequired'>
                    Requieren acción ({actionRequiredCount})
                  </MenuItem>
                </Select>
              </FormControl>
              {unreadCount > 0 && (
                <Button
                  size='small'
                  onClick={handleMarkAllAsRead}
                  startIcon={<MarkEmailReadIcon />}
                  disabled={markAllAsReadMutation.isLoading}
                >
                  Marcar todas
                </Button>
              )}
            </Box>
          }
        />
        <CardContent sx={{ p: 0 }}>
          {!isLoading && !error && (
            <Box sx={{ px: 3, pt: 2 }}>
              {feedbackMessage ? (
                <Alert severity='success' sx={{ mb: 2 }}>
                  {feedbackMessage}
                </Alert>
              ) : null}
              {unreadCount > 0 && (
                <Alert severity={actionRequiredCount > 0 ? 'warning' : 'info'} sx={{ mb: 2 }}>
                  Tienes {unreadCount} aviso(s) sin leer.
                </Alert>
              )}
            </Box>
          )}
          {isLoading ? (
            <Box sx={{ p: 4, textAlign: 'center' }}>
              <SignalLoader message='Cargando notificaciones...' />
            </Box>
          ) : error ? (
            <Box sx={{ p: 3 }}>
              <Alert severity='error'>
                No se pudieron cargar las notificaciones reales del LMS.
              </Alert>
            </Box>
          ) : filteredNotifications.length === 0 ? (
            <Box sx={{ p: 3, textAlign: 'center' }}>
              <NotificationsIcon sx={{ fontSize: 48, color: 'text.secondary', mb: 2 }} />
              <Typography variant='h6' color='text.secondary'>
                No hay notificaciones
              </Typography>
              <Typography variant='body2' color='text.secondary'>
                {getEmptyStateMessage(filter, userRole)}
              </Typography>
            </Box>
          ) : (
            <List>
              {filteredNotifications.map((notification, index) => (
                <React.Fragment key={notification.id}>
                  <ListItem
                    button
                    onClick={() => handleNotificationClick(notification)}
                    sx={{
                      backgroundColor: notification.read ? 'transparent' : 'action.hover',
                      '&:hover': {
                        backgroundColor: 'action.selected'
                      }
                    }}
                  >
                    <ListItemIcon>{getNotificationIcon(notification)}</ListItemIcon>
                    <ListItemText
                      primaryTypographyProps={{ component: 'div' }}
                      secondaryTypographyProps={{ component: 'div' }}
                      primary={
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap' }}>
                          <Typography
                            variant='body1'
                            fontWeight={notification.read ? 'normal' : 'bold'}
                          >
                            {getNotificationDisplayTitle(notification)}
                          </Typography>
                          {notification.severity !== 'info' && (
                            <Chip
                              label={notification.severity}
                              size='small'
                              color={getPriorityColor(notification)}
                              sx={{ fontSize: '0.7rem' }}
                            />
                          )}
                        </Box>
                      }
                      secondary={
                        <Box>
                          <Typography variant='body2' color='text.secondary'>
                            {getNotificationDisplayMessage(notification)}
                          </Typography>
                          <Typography variant='caption' color='text.secondary' sx={{ display: 'block' }}>
                            {notification.metadata?.courseTitle ||
                              notification.metadata?.certificateNumber ||
                              (notification.metadata?.isMandatory ? 'Capacitación obligatoria' : null) ||
                              'Notificación del LMS'}
                          </Typography>
                          <Typography variant='caption' color='text.secondary'>
                            {formatTimestamp(notification.timestamp)}
                          </Typography>
                        </Box>
                      }
                    />
                    <ListItemSecondaryAction>
                      {!notification.read && (
                        <IconButton
                          size='small'
                          onClick={(event) => {
                            event.stopPropagation()
                            handleMarkAsRead(notification.id)
                          }}
                          title='Marcar como leída'
                        >
                          <MarkEmailReadIcon />
                        </IconButton>
                      )}
                    </ListItemSecondaryAction>
                  </ListItem>
                  {index < filteredNotifications.length - 1 && <Divider />}
                </React.Fragment>
              ))}
            </List>
          )}
        </CardContent>
      </Card>

      <Dialog open={openDialog} onClose={() => setOpenDialog(false)} maxWidth='sm' fullWidth>
        {selectedNotification && (
          <>
            <DialogTitle>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, flexWrap: 'wrap' }}>
                {getNotificationIcon(selectedNotification)}
                <Typography variant='h6'>
                  {getNotificationDisplayTitle(selectedNotification)}
                </Typography>
                <Chip
                  label={selectedNotification.severity}
                  size='small'
                  color={getPriorityColor(selectedNotification)}
                />
              </Box>
            </DialogTitle>
            <DialogContent>
              <Typography variant='body1' sx={{ mb: 2 }}>
                {getNotificationDisplayMessage(selectedNotification)}
              </Typography>
              <Typography variant='caption' color='text.secondary'>
                {formatTimestamp(selectedNotification.timestamp)}
              </Typography>

              <Box sx={{ mt: 2, display: 'flex', gap: 1, flexWrap: 'wrap' }}>
                <Chip
                  label={getNotificationContextLabel(selectedNotification)}
                  size='small'
                  variant='outlined'
                />
                {selectedNotification.metadata?.courseTitle && (
                  <Chip
                    label={selectedNotification.metadata.courseTitle}
                    size='small'
                    variant='outlined'
                  />
                )}
                {selectedNotification.metadata?.certificateNumber && (
                  <Chip
                    label={`Certificado ${selectedNotification.metadata.certificateNumber}`}
                    size='small'
                    variant='outlined'
                  />
                )}
              </Box>

              {hasNotificationAction(selectedNotification) && (
                <Alert severity='info' sx={{ mt: 2 }}>
                  Esta notificación te puede devolver al punto correcto del LMS para continuar.
                </Alert>
              )}
            </DialogContent>
            <DialogActions>
              <Button onClick={() => setOpenDialog(false)}>Cerrar</Button>
              {hasNotificationAction(selectedNotification) && (
                <Button
                  variant='contained'
                  onClick={() => handleTakeAction(selectedNotification)}
                  startIcon={
                    selectedNotification.metadata?.certificateId ? (
                      <AwardIcon />
                    ) : (
                      <AssignmentIcon />
                    )
                  }
                >
                  {selectedNotification.actionLabel || 'Abrir en LMS'}
                </Button>
              )}
            </DialogActions>
          </>
        )}
      </Dialog>
    </Box>
  )
}

export default LmsNotificationCenter

import React, { useState, useEffect, useCallback } from 'react'
import {
  Box,
  Card,
  CardContent,
  Typography,
  Radio,
  RadioGroup,
  FormControlLabel,
  FormControl,
  Checkbox,
  Button,
  Alert,
  Chip,
  Divider,
  LinearProgress,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Paper,
  IconButton,
  Tooltip,
  Stepper,
  Step,
  StepButton
} from '@mui/material'
import {
  CheckCircle as CheckIcon,
  Cancel as CancelIcon,
  EmojiEvents as TrophyIcon,
  HelpOutline as HelpOutlineIcon,
  CheckCircleOutline as CheckCircleOutlineIcon,
  Replay as ReplayIcon,
  TimerOutlined as TimerOutlinedIcon,
  Timer as TimerIcon,
  NavigateNext as NextIcon,
  NavigateBefore as PrevIcon,
  Flag as FlagIcon,
  Warning as WarningIcon
} from '@mui/icons-material'
import LmsStatCard, { type LmsStatTone } from 'src/Components/lms/admin/LmsStatCard'

interface QuizQuestion {
  id: number
  question: string
  type: 'true-false' | 'single-choice' | 'multiple-choice'
  options: string[]
  correctAnswer: number | number[]
  explanation?: string
  points: number
  originalOptionIndices?: number[]
}

interface QuizConfiguration {
  id: number
  title: string
  instructions: string
  passingPercentage: number
  maxAttempts: number
  cooldownMinutes: number
  showCorrectAnswers: boolean
  randomizeQuestions: boolean
  shuffleAnswers: boolean
  timeLimitMinutes?: number
  allowReview: boolean
  showProgressBar: boolean
  questions: QuizQuestion[]
}

interface QuizAttempt {
  attemptNumber: number
  startedAt: Date
  answers: (number | number[])[]
  timeSpent: number
  questionIds?: number[]
  score?: number
  totalPoints?: number
  passed?: boolean
}

interface LmsQuizPlayerProps {
  quizConfig: QuizConfiguration
  userAttempts?: QuizAttempt[]
  onComplete?: (attempt: QuizAttempt) => void
  onSaveProgress?: (answers: (number | number[])[]) => void
  isPreview?: boolean
  /** Oculta el título de la pantalla de inicio cuando la página ya lo muestra. */
  hideTitle?: boolean
}

const LmsQuizPlayer: React.FC<LmsQuizPlayerProps> = ({
  quizConfig,
  userAttempts = [],
  onComplete,
  onSaveProgress,
  hideTitle = false,
  isPreview = false
}) => {
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0)
  const [userAnswers, setUserAnswers] = useState<(number | number[])[]>([])
  const [showResults, setShowResults] = useState(false)
  const [showInstructions, setShowInstructions] = useState(true)
  const [timeRemaining, setTimeRemaining] = useState<number | null>(null)
  const [startTime, setStartTime] = useState<Date | null>(null)
  const [showReviewDialog, setShowReviewDialog] = useState(false)
  const [flaggedQuestions, setFlaggedQuestions] = useState<Set<number>>(new Set())
  const [currentAttempt, setCurrentAttempt] = useState<QuizAttempt | null>(null)
  const [canStartQuiz, setCanStartQuiz] = useState(true)
  const [cooldownEndTime, setCooldownEndTime] = useState<Date | null>(null)
  const [shuffledQuestions, setShuffledQuestions] = useState<QuizQuestion[]>([])

  // Initialize quiz
  useEffect(() => {
    setCanStartQuiz(true)
    setCooldownEndTime(null)
    setShowResults(false)
    setShowInstructions(true)
    setCurrentQuestionIndex(0)
    setCurrentAttempt(null)
    setStartTime(null)
    setTimeRemaining(null)
    setFlaggedQuestions(new Set())

    // Check if user can start quiz (cooldown and max attempts)
    if (!isPreview && userAttempts.length > 0) {
      const lastAttempt = userAttempts[userAttempts.length - 1]
      const lastAttemptTime = new Date(lastAttempt.startedAt)
      const cooldownEnd = new Date(lastAttemptTime.getTime() + quizConfig.cooldownMinutes * 60000)

      if (userAttempts.length >= quizConfig.maxAttempts) {
        setCanStartQuiz(false)
      } else if (quizConfig.cooldownMinutes > 0 && new Date() < cooldownEnd) {
        setCanStartQuiz(false)
        setCooldownEndTime(cooldownEnd)
      }
    }

    // Prepare questions (shuffle if needed)
    let questions = [...quizConfig.questions]
    if (quizConfig.randomizeQuestions) {
      questions = questions.sort(() => Math.random() - 0.5)
    }

    // Shuffle answers if needed
    if (quizConfig.shuffleAnswers) {
      questions = questions.map(q => {
        if (q.type === 'true-false') return q

        const shuffledOptions = [...q.options]
        const originalIndices = shuffledOptions.map((_, index) => index)

        // Fisher-Yates shuffle
        for (let i = shuffledOptions.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1))
          ;[shuffledOptions[i], shuffledOptions[j]] = [shuffledOptions[j], shuffledOptions[i]]
          ;[originalIndices[i], originalIndices[j]] = [originalIndices[j], originalIndices[i]]
        }

        // Update correct answers based on new positions
        let newCorrectAnswer: number | number[]
        if (Array.isArray(q.correctAnswer)) {
          newCorrectAnswer = q.correctAnswer.map(oldIndex => 
            originalIndices.findIndex(newIndex => newIndex === oldIndex)
          )
        } else {
          newCorrectAnswer = originalIndices.findIndex(newIndex => newIndex === q.correctAnswer)
        }

        return {
          ...q,
          options: shuffledOptions,
          correctAnswer: newCorrectAnswer,
          originalOptionIndices: originalIndices
        }
      })
    }

    setShuffledQuestions(questions)
    setUserAnswers(new Array(questions.length).fill(undefined))
  }, [quizConfig, userAttempts, isPreview])

  // Timer effect
  useEffect(() => {
    if (startTime && quizConfig.timeLimitMinutes && timeRemaining !== null) {
      const timer = setInterval(() => {
        setTimeRemaining(prev => {
          if (prev === null || prev <= 0) {
            handleTimeUp()
            return 0
          }
          return prev - 1
        })
      }, 1000)

      return () => clearInterval(timer)
    }
  }, [startTime, quizConfig.timeLimitMinutes, timeRemaining])

  // Cooldown timer
  useEffect(() => {
    if (cooldownEndTime) {
      const timer = setInterval(() => {
        if (new Date() >= cooldownEndTime) {
          setCanStartQuiz(true)
          setCooldownEndTime(null)
        }
      }, 1000)

      return () => clearInterval(timer)
    }
  }, [cooldownEndTime])

  const handleStartQuiz = () => {
    setShowInstructions(false)
    setStartTime(new Date())

    if (quizConfig.timeLimitMinutes) {
      setTimeRemaining(quizConfig.timeLimitMinutes * 60)
    }

    const attempt: QuizAttempt = {
      attemptNumber: userAttempts.length + 1,
      startedAt: new Date(),
      answers: [],
      timeSpent: 0
    }
    setCurrentAttempt(attempt)
  }

  const handleTimeUp = useCallback(() => {
    if (!showResults) {
      handleSubmitQuiz(true)
    }
  }, [showResults])

  const handleAnswerChange = (value: number | number[]) => {
    const newAnswers = [...userAnswers]
    newAnswers[currentQuestionIndex] = value
    setUserAnswers(newAnswers)

    // Auto-save progress
    if (onSaveProgress) {
      onSaveProgress(newAnswers)
    }
  }

  const handleNextQuestion = () => {
    if (currentQuestionIndex < shuffledQuestions.length - 1) {
      setCurrentQuestionIndex(currentQuestionIndex + 1)
    }
  }

  const handlePreviousQuestion = () => {
    if (currentQuestionIndex > 0) {
      setCurrentQuestionIndex(currentQuestionIndex - 1)
    }
  }

  const handleGoToQuestion = (index: number) => {
    setCurrentQuestionIndex(index)
  }

  const handleFlagQuestion = () => {
    const newFlagged = new Set(flaggedQuestions)
    if (newFlagged.has(currentQuestionIndex)) {
      newFlagged.delete(currentQuestionIndex)
    } else {
      newFlagged.add(currentQuestionIndex)
    }
    setFlaggedQuestions(newFlagged)
  }

  const handleSubmitQuiz = (timeUp = false) => {
    if (!timeUp && quizConfig.allowReview) {
      setShowReviewDialog(true)
      return
    }

    finishQuiz()
  }

  const finishQuiz = () => {
    const endTime = new Date()
    const timeSpent = startTime ? Math.round((endTime.getTime() - startTime.getTime()) / 1000) : 0

    // Calculate score
    let totalScore = 0
    let totalPossiblePoints = 0

    shuffledQuestions.forEach((question, index) => {
      totalPossiblePoints += question.points

      const userAnswer = userAnswers[index]
      if (userAnswer !== undefined) {
        if (question.type === 'multiple-choice') {
          const userArray = Array.isArray(userAnswer) ? userAnswer : [userAnswer]
          const correctArray = Array.isArray(question.correctAnswer) ? question.correctAnswer : [question.correctAnswer]

          if (
            userArray.length === correctArray.length &&
            userArray.every((answer) => correctArray.includes(answer))
          ) {
            totalScore += question.points
          }
        } else {
          if (userAnswer === question.correctAnswer) {
            totalScore += question.points
          }
        }
      }
    })

    const passed = (totalScore / totalPossiblePoints) * 100 >= quizConfig.passingPercentage

    const submissionAnswers = userAnswers.map((answer, index) => {
      const question = shuffledQuestions[index]
      if (answer === undefined || !question?.originalOptionIndices) {
        return answer
      }

      const toOriginalIndex = (selectedIndex: number) =>
        question.originalOptionIndices?.[selectedIndex] ?? selectedIndex

      if (Array.isArray(answer)) {
        return answer.map(toOriginalIndex)
      }

      return toOriginalIndex(answer)
    })

    const completedAttempt: QuizAttempt = {
      ...currentAttempt!,
      answers: submissionAnswers,
      questionIds: shuffledQuestions.map((question) => question.id),
      timeSpent,
      score: totalScore,
      totalPoints: totalPossiblePoints,
      passed
    }

    setCurrentAttempt(completedAttempt)
    setShowResults(true)
    setShowReviewDialog(false)

    if (onComplete) {
      onComplete(completedAttempt)
    }
  }

  const isAnswerCorrect = (questionIndex: number) => {
    const question = shuffledQuestions[questionIndex]
    const userAnswer = userAnswers[questionIndex]

    if (userAnswer === undefined) return null

    if (question.type === 'multiple-choice') {
      const userArray = Array.isArray(userAnswer) ? userAnswer : [userAnswer]
      const correctArray = Array.isArray(question.correctAnswer) ? question.correctAnswer : [question.correctAnswer]
      return (
        userArray.length === correctArray.length &&
        userArray.every((answer) => correctArray.includes(answer))
      )
    } else {
      return userAnswer === question.correctAnswer
    }
  }

  const getQuestionTypeLabel = (type: string) => {
    switch (type) {
      case 'true-false': return 'Verdadero o Falso'
      case 'single-choice': return 'Selección Única'
      case 'multiple-choice': return 'Selección Múltiple'
      default: return 'Pregunta'
    }
  }

  const formatTime = (seconds: number) => {
    const minutes = Math.floor(seconds / 60)
    const remainingSeconds = seconds % 60
    return `${minutes}:${remainingSeconds.toString().padStart(2, '0')}`
  }

  const getAnsweredCount = () => {
    return userAnswers.filter(answer => answer !== undefined).length
  }

  // Show cooldown message
  if (!canStartQuiz && cooldownEndTime) {
    const remainingTime = Math.max(0, Math.ceil((cooldownEndTime.getTime() - new Date().getTime()) / 1000))
    return (
      <Card>
        <CardContent sx={{ textAlign: 'center', py: 4 }}>
          <TimerIcon sx={{ fontSize: 60, color: 'warning.main', mb: 2 }} />
          <Typography variant="h5" gutterBottom>
            Tiempo de Espera
          </Typography>
          <Typography variant="body1" color="text.secondary" sx={{ mb: 2 }}>
            Debes esperar {formatTime(remainingTime)} antes de poder intentar el quiz nuevamente.
          </Typography>
          <Alert severity="info">
            Tiempo de espera configurado: {quizConfig.cooldownMinutes} minutos entre intentos
          </Alert>
        </CardContent>
      </Card>
    )
  }

  // Show max attempts reached
  if (!canStartQuiz && userAttempts.length >= quizConfig.maxAttempts) {
    return (
      <Card>
        <CardContent sx={{ textAlign: 'center', py: 4 }}>
          <WarningIcon sx={{ fontSize: 60, color: 'error.main', mb: 2 }} />
          <Typography variant="h5" gutterBottom>
            Intentos Agotados
          </Typography>
          <Typography variant="body1" color="text.secondary" sx={{ mb: 2 }}>
            Has alcanzado el número máximo de intentos permitidos para este quiz.
          </Typography>
          <Alert severity="error">
            Intentos realizados: {userAttempts.length}/{quizConfig.maxAttempts}
          </Alert>
        </CardContent>
      </Card>
    )
  }

  // Show instructions
  if (showInstructions) {
    return (
      <Card>
        <CardContent>
          {!hideTitle && (
            <Typography variant="h4" gutterBottom sx={{ fontWeight: 700 }}>
              {quizConfig.title}
            </Typography>
          )}

          {quizConfig.instructions && (
            <Typography variant="body1" sx={{ mb: 3 }}>
              {quizConfig.instructions}
            </Typography>
          )}

          <Box
            sx={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fit, minmax(170px, 1fr))',
              gap: 2,
              mb: 3
            }}
          >
            {(
              [
                { label: 'Preguntas', value: String(shuffledQuestions.length), tone: 'blue', icon: <HelpOutlineIcon /> },
                { label: 'Puntos totales', value: String(shuffledQuestions.reduce((sum, q) => sum + q.points, 0)), tone: 'teal', icon: <TrophyIcon /> },
                { label: 'Para aprobar', value: `${quizConfig.passingPercentage}%`, tone: 'green', icon: <CheckCircleOutlineIcon /> },
                { label: 'Intentos restantes', value: String(quizConfig.maxAttempts - userAttempts.length), tone: 'orange', icon: <ReplayIcon /> },
                ...(quizConfig.timeLimitMinutes
                  ? [{ label: 'Tiempo límite', value: `${quizConfig.timeLimitMinutes} min`, tone: 'red', icon: <TimerOutlinedIcon /> }]
                  : [])
              ] as Array<{ label: string; value: string; tone: LmsStatTone; icon: React.ReactElement }>
            ).map((item) => (
              <LmsStatCard key={item.label} label={item.label} value={item.value} tone={item.tone} icon={item.icon} />
            ))}
          </Box>

          {userAttempts.length > 0 && (
            <Box sx={{ mb: 3 }}>
              <Typography variant="h6" gutterBottom>
                Intentos Anteriores
              </Typography>

              {/* Best attempt summary */}
              {(() => {
                const bestAttempt = userAttempts.reduce((best, current) =>
                  (current.score! / current.totalPoints!) > (best.score! / best.totalPoints!) ? current : best
                )
                const bestPercentage = Math.round((bestAttempt.score! / bestAttempt.totalPoints!) * 100)

                return (
                  <Paper
                    elevation={3}
                    sx={{
                      p: 3,
                      mb: 2,
                      backgroundColor: bestAttempt.passed ? '#e8f5e9' : '#fff3e0',
                      border: 2,
                      borderColor: bestAttempt.passed ? 'success.main' : 'warning.main'
                    }}
                  >
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 2 }}>
                      {bestAttempt.passed ? (
                        <CheckIcon sx={{ fontSize: 40, color: 'success.main' }} />
                      ) : (
                        <WarningIcon sx={{ fontSize: 40, color: 'warning.main' }} />
                      )}
                      <Box>
                        <Typography variant="h5" fontWeight="bold">
                          {bestAttempt.passed ? '¡Quiz Aprobado!' : 'Quiz No Aprobado'}
                        </Typography>
                        <Typography variant="body1" color="text.secondary">
                          Mejor resultado: {bestAttempt.score}/{bestAttempt.totalPoints} puntos ({bestPercentage}%)
                        </Typography>
                      </Box>
                    </Box>

                    {bestAttempt.passed && (
                      <Alert severity="success" sx={{ mb: 1 }}>
                        Has completado este quiz exitosamente. Puedes volver a intentarlo para mejorar tu puntuación.
                      </Alert>
                    )}

                    {!bestAttempt.passed && quizConfig.maxAttempts - userAttempts.length > 0 && (
                      <Alert severity="info">
                        Tienes {quizConfig.maxAttempts - userAttempts.length} intentos restantes. ¡Sigue intentando!
                      </Alert>
                    )}
                  </Paper>
                )
              })()}

              {/* All attempts list */}
              <Typography variant="subtitle2" color="text.secondary" gutterBottom sx={{ mt: 2 }}>
                Historial de {userAttempts.length} intento{userAttempts.length > 1 ? 's' : ''}:
              </Typography>
              {userAttempts.slice().reverse().map((attempt, index) => (
                <Alert
                  key={index}
                  severity={attempt.passed ? 'success' : 'error'}
                  sx={{ mb: 1 }}
                  icon={attempt.passed ? <CheckIcon /> : <CancelIcon />}
                >
                  <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <Box>
                      <strong>Intento #{attempt.attemptNumber}</strong>: {attempt.score}/{attempt.totalPoints} puntos
                      ({Math.round((attempt.score! / attempt.totalPoints!) * 100)}%)
                    </Box>
                    <Chip
                      label={attempt.passed ? 'Aprobado' : 'No aprobado'}
                      color={attempt.passed ? 'success' : 'error'}
                      size="small"
                    />
                  </Box>
                </Alert>
              ))}
            </Box>
          )}

          <Box sx={{ display: 'flex', gap: 2, justifyContent: 'center' }}>
            <Button
              variant="contained"
              size="large"
              onClick={handleStartQuiz}
              disabled={!canStartQuiz}
              color={userAttempts.length > 0 ? 'primary' : 'primary'}
            >
              {userAttempts.length > 0 ? 'Reintentar Quiz' : 'Comenzar Quiz'}
            </Button>
          </Box>

          {!canStartQuiz && userAttempts.length >= quizConfig.maxAttempts && (
            <Alert severity="warning" sx={{ mt: 2 }}>
              Has alcanzado el número máximo de intentos ({quizConfig.maxAttempts}) para este quiz.
            </Alert>
          )}

          {!canStartQuiz && cooldownEndTime && (
            <Alert severity="info" sx={{ mt: 2 }}>
              Debes esperar hasta {cooldownEndTime.toLocaleTimeString()} para poder reintentar este quiz.
            </Alert>
          )}

          {isPreview && (
            <Alert severity="info" sx={{ mt: 2 }}>
              <Typography variant="body2">
                <strong>Modo Preview:</strong> Este es un modo de prueba. Los resultados no se guardarán.
              </Typography>
            </Alert>
          )}
        </CardContent>
      </Card>
    )
  }

  // Show results
  if (showResults && currentAttempt) {
    const achievedPercentage = Math.round((currentAttempt.score! / currentAttempt.totalPoints!) * 100)
    const attemptsRemaining = Math.max(0, quizConfig.maxAttempts - userAttempts.length - 1)

    return (
      <Card>
        <CardContent>
          <Typography variant="h5" sx={{ fontWeight: 700, mb: 2 }}>
            Resultados del Quiz · {currentAttempt.passed ? '¡Aprobado!' : 'No aprobado'}
          </Typography>
          <Box
            sx={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(170px, 1fr))', gap: 2, mb: 3 }}
          >
            <LmsStatCard
              label='Resultado'
              value={`${achievedPercentage}%`}
              tone={currentAttempt.passed ? 'green' : 'red'}
              icon={<TrophyIcon />}
            />
            <LmsStatCard
              label='Puntos'
              value={`${currentAttempt.score}/${currentAttempt.totalPoints}`}
              tone='blue'
              icon={<CheckCircleOutlineIcon />}
            />
            <LmsStatCard
              label='Tiempo empleado'
              value={formatTime(currentAttempt.timeSpent)}
              tone='teal'
              icon={<TimerOutlinedIcon />}
            />
          </Box>

          <Alert severity={currentAttempt.passed ? 'success' : 'warning'} sx={{ mb: 3 }}>
            <Typography variant="body2">
              {currentAttempt.passed ? (
                <>
                  Superaste el puntaje mínimo de <strong>{quizConfig.passingPercentage}%</strong>.
                  Vuelve a la lección para continuar con el siguiente paso del curso.
                </>
              ) : (
                <>
                  Necesitas <strong>{quizConfig.passingPercentage}%</strong> para aprobar.
                  {attemptsRemaining > 0
                    ? ` Todavía puedes reintentar ${attemptsRemaining} vez${attemptsRemaining === 1 ? '' : 'es'}.`
                    : ' Ya no quedan más intentos disponibles en este quiz.'}
                </>
              )}
            </Typography>
          </Alert>

          {quizConfig.showCorrectAnswers && (
            <>
              <Divider sx={{ my: 2 }} />
              <Typography variant="h6" gutterBottom>
                Revisión de Respuestas
              </Typography>

              {shuffledQuestions.map((question, index) => {
                const isCorrect = isAnswerCorrect(index)
                const userAnswer = userAnswers[index]

                return (
                  <Box key={question.id} sx={{ mb: 3 }}>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                      <Typography variant="h6">Pregunta {index + 1}:</Typography>
                      <Chip label={getQuestionTypeLabel(question.type)} size="small" color="primary" variant="outlined" />
                      {isCorrect !== null && (
                        isCorrect ? <CheckIcon color="success" /> : <CancelIcon color="error" />
                      )}
                      {flaggedQuestions.has(index) && <FlagIcon color="warning" />}
                    </Box>

                    <Typography variant="body1" sx={{ mb: 2 }}>
                      {question.question}
                    </Typography>

                    <Box sx={{ ml: 2 }}>
                      {question.options.map((option, optionIndex) => {
                        let isSelected = false
                        let isCorrectOption = false

                        if (question.type === 'multiple-choice') {
                          const userArray = Array.isArray(userAnswer) ? userAnswer : []
                          const correctArray = Array.isArray(question.correctAnswer) ? question.correctAnswer : []
                          isSelected = userArray.includes(optionIndex)
                          isCorrectOption = correctArray.includes(optionIndex)
                        } else {
                          isSelected = userAnswer === optionIndex
                          isCorrectOption = question.correctAnswer === optionIndex
                        }

                        return (
                          <Box
                            key={optionIndex}
                            sx={{
                              display: 'flex',
                              alignItems: 'center',
                              gap: 1,
                              p: 1,
                              borderRadius: 1,
                              backgroundColor: isSelected
                                ? isCorrectOption ? 'success.light' : 'error.light'
                                : isCorrectOption ? 'success.light' : 'transparent'
                            }}
                          >
                            {question.type === 'multiple-choice' ? (
                              <Checkbox
                                checked={isSelected}
                                disabled
                                color={isCorrectOption ? 'success' : 'error'}
                              />
                            ) : (
                              <Radio
                                checked={isSelected}
                                disabled
                                color={isCorrectOption ? 'success' : 'error'}
                              />
                            )}
                            <Typography
                              variant="body2"
                              sx={{
                                color: isSelected
                                  ? isCorrectOption ? 'success.dark' : 'error.dark'
                                  : isCorrectOption ? 'success.dark' : 'text.primary'
                              }}
                            >
                              {option}
                            </Typography>
                          </Box>
                        )
                      })}
                    </Box>

                    {question.explanation && (
                      <Alert severity="info" sx={{ mt: 1 }}>
                        <Typography variant="body2">
                          <strong>Explicación:</strong> {question.explanation}
                        </Typography>
                      </Alert>
                    )}
                  </Box>
                )
              })}
            </>
          )}
        </CardContent>
      </Card>
    )
  }

  const currentQuestion = shuffledQuestions[currentQuestionIndex]
  if (!currentQuestion) {
    return (
      <Alert severity="error">
        No hay preguntas disponibles para este quiz.
      </Alert>
    )
  }

  return (
    <Box>
      {/* Header with timer and progress */}
      <Card sx={{ mb: 2 }}>
        <CardContent sx={{ py: 2 }}>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <Typography variant="h6">
              {quizConfig.title}
            </Typography>

            <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
              {timeRemaining !== null && (
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                  <TimerIcon color={timeRemaining < 300 ? 'error' : 'primary'} />
                  <Typography 
                    variant="h6" 
                    color={timeRemaining < 300 ? 'error.main' : 'primary.main'}
                  >
                    {formatTime(timeRemaining)}
                  </Typography>
                </Box>
              )}

              <Typography variant="body2" color="text.secondary">
                {getAnsweredCount()}/{shuffledQuestions.length} respondidas
              </Typography>
            </Box>
          </Box>

          {quizConfig.showProgressBar && (
            <LinearProgress
              variant="determinate"
              value={(getAnsweredCount() / shuffledQuestions.length) * 100}
              sx={{ mt: 1 }}
            />
          )}
        </CardContent>
      </Card>

      {/* Question navigation stepper - responsive design */}
      <Card sx={{ mb: 2 }}>
        <CardContent sx={{ py: 2 }}>
          {/* Mobile: Compact navigation */}
          <Box sx={{ display: { xs: 'block', md: 'none' } }}>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 1 }}>
              <Typography variant="body2" color="text.secondary">
                Pregunta {currentQuestionIndex + 1} de {shuffledQuestions.length}
              </Typography>
              <Box sx={{ display: 'flex', gap: 1 }}>
                <Button
                  size="small"
                  variant="outlined"
                  onClick={() => setShowReviewDialog(true)}
                >
                  Ver Todas
                </Button>
              </Box>
            </Box>
            <LinearProgress
              variant="determinate"
              value={((currentQuestionIndex + 1) / shuffledQuestions.length) * 100}
              sx={{ height: 6, borderRadius: 3 }}
            />
          </Box>

          {/* Desktop: Full stepper */}
          <Box sx={{ display: { xs: 'none', md: 'block' } }}>
            <Stepper nonLinear activeStep={currentQuestionIndex}>
              {shuffledQuestions.map((_, index) => (
                <Step key={index} completed={userAnswers[index] !== undefined}>
                  <StepButton onClick={() => handleGoToQuestion(index)}>
                    <Box sx={{ position: 'relative' }}>
                      {flaggedQuestions.has(index) && (
                        <FlagIcon 
                          sx={{ 
                            position: 'absolute', 
                            top: -8, 
                            right: -8, 
                            fontSize: 16, 
                            color: 'warning.main' 
                          }} 
                        />
                      )}
                    </Box>
                  </StepButton>
                </Step>
              ))}
            </Stepper>
          </Box>
        </CardContent>
      </Card>

      {/* Main question card */}
      <Card>
        <CardContent>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
            <Typography variant="h6">
              Pregunta {currentQuestionIndex + 1} de {shuffledQuestions.length}
            </Typography>
            <Box sx={{ display: 'flex', gap: 1 }}>
              <Chip label={getQuestionTypeLabel(currentQuestion.type)} color="primary" size="small" />
              <Chip label={`${currentQuestion.points} pts`} variant="outlined" size="small" />
              <Tooltip title={flaggedQuestions.has(currentQuestionIndex) ? "Quitar marca" : "Marcar para revisar"}>
                <IconButton size="small" onClick={handleFlagQuestion}>
                  <FlagIcon color={flaggedQuestions.has(currentQuestionIndex) ? 'warning' : 'disabled'} />
                </IconButton>
              </Tooltip>
            </Box>
          </Box>

          <Typography variant="h6" sx={{ mb: 3 }}>
            {currentQuestion.question}
          </Typography>

          <FormControl component="fieldset" sx={{ width: '100%' }}>
            {currentQuestion.type === 'multiple-choice' ? (
              <Box>
                {currentQuestion.options.map((option, index) => (
                  <FormControlLabel
                    key={index}
                    control={
                      <Checkbox
                        checked={
                          Array.isArray(userAnswers[currentQuestionIndex])
                            ? (userAnswers[currentQuestionIndex] as number[]).includes(index)
                            : false
                        }
                        onChange={(e) => {
                          const currentAnswers = Array.isArray(userAnswers[currentQuestionIndex])
                            ? (userAnswers[currentQuestionIndex] as number[])
                            : []

                          if (e.target.checked) {
                            handleAnswerChange([...currentAnswers, index])
                          } else {
                            handleAnswerChange(currentAnswers.filter((i) => i !== index))
                          }
                        }}
                      />
                    }
                    label={option}
                    sx={{
                      display: 'block',
                      mb: 1,
                      p: { xs: 1.5, sm: 1 },
                      borderRadius: 1,
                      border: '1px solid',
                      borderColor: 'divider',
                      '&:hover': { backgroundColor: 'action.hover' },
                      '& .MuiFormControlLabel-label': {
                        fontSize: { xs: '0.95rem', sm: '0.875rem' },
                        lineHeight: 1.4
                      }
                    }}
                  />
                ))}
              </Box>
            ) : (
              <RadioGroup
                value={userAnswers[currentQuestionIndex] ?? ''}
                onChange={(e) => handleAnswerChange(Number(e.target.value))}
              >
                {currentQuestion.options.map((option, index) => (
                  <FormControlLabel
                    key={index}
                    value={index}
                    control={<Radio />}
                    label={option}
                    sx={{
                      display: 'block',
                      mb: 1,
                      p: { xs: 1.5, sm: 1 },
                      borderRadius: 1,
                      border: '1px solid',
                      borderColor: 'divider',
                      '&:hover': { backgroundColor: 'action.hover' },
                      '& .MuiFormControlLabel-label': {
                        fontSize: { xs: '0.95rem', sm: '0.875rem' },
                        lineHeight: 1.4
                      }
                    }}
                  />
                ))}
              </RadioGroup>
            )}
          </FormControl>

          <Box sx={{ 
            display: 'flex', 
            justifyContent: 'space-between', 
            alignItems: 'center', 
            mt: 3,
            flexDirection: { xs: 'column', sm: 'row' },
            gap: 2
          }}>
            <Button
              variant="outlined"
              startIcon={<PrevIcon />}
              onClick={handlePreviousQuestion}
              disabled={currentQuestionIndex === 0}
              sx={{ width: { xs: '100%', sm: 'auto' } }}
            >
              Anterior
            </Button>

            <Box sx={{ display: 'flex', gap: 1, width: { xs: '100%', sm: 'auto' } }}>
              {currentQuestionIndex === shuffledQuestions.length - 1 ? (
                <Button
                  variant="contained"
                  color="success"
                  onClick={() => handleSubmitQuiz()}
                  sx={{ width: { xs: '100%', sm: 'auto' } }}
                >
                  Finalizar Quiz
                </Button>
              ) : (
                <Button
                  variant="contained"
                  endIcon={<NextIcon />}
                  onClick={handleNextQuestion}
                  sx={{ width: { xs: '100%', sm: 'auto' } }}
                >
                  Siguiente
                </Button>
              )}
            </Box>
          </Box>

          {isPreview && (
            <Alert severity="info" sx={{ mt: 2 }}>
              <Typography variant="body2">
                <strong>Modo Preview:</strong> Este es un modo de prueba. Los resultados no se guardarán.
              </Typography>
            </Alert>
          )}
        </CardContent>
      </Card>

      {/* Review Dialog */}
      <Dialog open={showReviewDialog} onClose={() => setShowReviewDialog(false)} maxWidth="md" fullWidth>
        <DialogTitle>Revisar Respuestas</DialogTitle>
        <DialogContent>
          <Typography variant="body1" sx={{ mb: 2 }}>
            Revisa tus respuestas antes de enviar el quiz. Las preguntas sin responder aparecen marcadas.
          </Typography>

          <Box sx={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(60px, 1fr))', gap: 1 }}>
            {shuffledQuestions.map((_, index) => (
              <Button
                key={index}
                variant={userAnswers[index] !== undefined ? 'contained' : 'outlined'}
                color={flaggedQuestions.has(index) ? 'warning' : 'primary'}
                size="small"
                onClick={() => {
                  setCurrentQuestionIndex(index)
                  setShowReviewDialog(false)
                }}
              >
                {index + 1}
                {flaggedQuestions.has(index) && <FlagIcon sx={{ ml: 0.5, fontSize: 16 }} />}
              </Button>
            ))}
          </Box>

          <Alert severity="warning" sx={{ mt: 2 }}>
            Preguntas sin responder: {shuffledQuestions.length - getAnsweredCount()}
          </Alert>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setShowReviewDialog(false)}>
            Continuar Editando
          </Button>
          <Button onClick={finishQuiz} variant="contained" color="success">
            Enviar Quiz Final
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  )
}

export default LmsQuizPlayer

import SignalLoader from 'src/Components/Common/SignalLoader'
import React, { useState, useRef, useEffect } from 'react'
import {
  Box,
  IconButton,
  Slider,
  Typography,
  Paper,
  Alert
} from '@mui/material'
import {
  PlayArrow as PlayIcon,
  Pause as PauseIcon,
  VolumeUp as VolumeUpIcon,
  VolumeOff as VolumeOffIcon,
  Fullscreen as FullscreenIcon,
  FullscreenExit as FullscreenExitIcon
} from '@mui/icons-material'
import { api } from 'src/config'
import useAxiosPrivate from 'src/utils/use-axios-private'
import { buildGDriveEmbedUrl } from 'src/utils/gdrive'

import { headerText } from 'src/utils/responseHeaders'
interface LmsVideoPlayerProps {
  src: string
  videoSource: 'minio' | 'youtube' | 'gdrive'
  title?: string
  onProgress?: (currentTime: number, duration: number) => void
  onComplete?: () => void
  autoPlay?: boolean
  controls?: boolean
}

const LmsVideoPlayer: React.FC<LmsVideoPlayerProps> = ({
  src,
  videoSource,
  title,
  onProgress,
  onComplete,
  autoPlay = false,
  controls = true
}) => {
  const axiosPrivate = useAxiosPrivate()
  const videoRef = useRef<HTMLVideoElement>(null)
  const containerRef = useRef<HTMLDivElement>(null)
  const [isPlaying, setIsPlaying] = useState(false)
  const [currentTime, setCurrentTime] = useState(0)
  const [duration, setDuration] = useState(0)
  const [volume, setVolume] = useState(1)
  const [isMuted, setIsMuted] = useState(false)
  const [isFullscreen, setIsFullscreen] = useState(false)
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [resolvedSrc, setResolvedSrc] = useState(videoSource === 'minio' ? '' : src)

  // YouTube video handling
  const getYouTubeEmbedUrl = (url: string): string => {
    const videoId = extractYouTubeVideoId(url)
    if (!videoId) return url
    return `https://www.youtube.com/embed/${videoId}?enablejsapi=1&rel=0&modestbranding=1`
  }

  const extractYouTubeVideoId = (url: string): string | null => {
    const patterns = [
      /(?:youtube\.com\/watch\?v=|youtu\.be\/|youtube\.com\/embed\/)([^&\n?#]+)/,
      /youtube\.com\/watch\?.*v=([^&\n?#]+)/
    ]
    
    for (const pattern of patterns) {
      const match = url.match(pattern)
      if (match) return match[1]
    }
    return null
  }

  const validateYouTubeUrl = (url: string): boolean => {
    return extractYouTubeVideoId(url) !== null
  }

  // Video event handlers
  const handlePlay = () => {
    if (videoRef.current) {
      if (isPlaying) {
        videoRef.current.pause()
      } else {
        videoRef.current.play()
      }
    }
  }

  const handleTimeUpdate = () => {
    if (videoRef.current) {
      const current = videoRef.current.currentTime
      const total = videoRef.current.duration
      
      setCurrentTime(current)
      
      if (onProgress) {
        onProgress(current, total)
      }

      // Check if video is completed (95% threshold to account for buffering)
      if (total > 0 && current / total >= 0.95 && onComplete) {
        onComplete()
      }
    }
  }

  const handleLoadedMetadata = () => {
    if (videoRef.current) {
      setDuration(videoRef.current.duration)
      setIsLoading(false)
    }
  }

  const handleSeek = (value: number) => {
    if (videoRef.current) {
      videoRef.current.currentTime = value
      setCurrentTime(value)
    }
  }

  const handleVolumeChange = (value: number) => {
    if (videoRef.current) {
      videoRef.current.volume = value
      setVolume(value)
      setIsMuted(value === 0)
    }
  }

  const handleMute = () => {
    if (videoRef.current) {
      if (isMuted) {
        videoRef.current.volume = volume
        setIsMuted(false)
      } else {
        videoRef.current.volume = 0
        setIsMuted(true)
      }
    }
  }

  const handleFullscreen = () => {
    if (!isFullscreen) {
      if (containerRef.current?.requestFullscreen) {
        containerRef.current.requestFullscreen()
      }
    } else {
      if (document.exitFullscreen) {
        document.exitFullscreen()
      }
    }
  }

  const formatTime = (time: number): string => {
    const minutes = Math.floor(time / 60)
    const seconds = Math.floor(time % 60)
    return `${minutes}:${seconds.toString().padStart(2, '0')}`
  }

  // Handle fullscreen changes
  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement)
    }

    document.addEventListener('fullscreenchange', handleFullscreenChange)
    return () => {
      document.removeEventListener('fullscreenchange', handleFullscreenChange)
    }
  }, [])

  useEffect(() => {
    if (videoSource !== 'minio') {
      setResolvedSrc(src)
      setIsLoading(false)
      setError(null)
      return
    }

    let isCancelled = false
    let objectUrl: string | null = null

    const loadProtectedVideo = async () => {
      try {
        setIsLoading(true)
        setError(null)
        setResolvedSrc('')

        const response = await axiosPrivate.get<ArrayBuffer>(
          src.startsWith('http') ? src : `${api()}${src.startsWith('/') ? src : `/${src}`}`,
          {
            responseType: 'arraybuffer',
            withCredentials: true
          }
        )

        const contentType =
          headerText(response.headers, 'content-type') ||
          headerText(response.headers, 'Content-Type') ||
          'video/mp4'
        const blob = new Blob([response.data], { type: contentType })

        if (!blob.size) {
          throw new Error('El video llegó vacío')
        }
        objectUrl = URL.createObjectURL(blob)

        if (!isCancelled) {
          setResolvedSrc(objectUrl)
        }
      } catch (loadError) {
        if (!isCancelled) {
          setError(loadError instanceof Error ? loadError.message : 'Error al cargar el video')
          setIsLoading(false)
        }
      }
    }

    void loadProtectedVideo()

    return () => {
      isCancelled = true
      if (objectUrl) {
        URL.revokeObjectURL(objectUrl)
      }
    }
  }, [src, videoSource])

  // Handle video errors
  const handleError = () => {
    const mediaError = videoRef.current?.error
    const mediaErrorMessage = mediaError
      ? `Error al cargar el video (codigo ${mediaError.code})`
      : 'Error al cargar el video'

    setError(mediaErrorMessage)
    setIsLoading(false)
  }

  // Google Drive iframe
  if (videoSource === 'gdrive') {
    const embedUrl = buildGDriveEmbedUrl(src)
    return (
      <Box
        ref={containerRef}
        sx={{
          position: 'relative',
          width: '100%',
          paddingBottom: '56.25%',
          height: 0,
          overflow: 'hidden'
        }}
      >
        <Box
          component="iframe"
          src={embedUrl}
          title={title || 'Video de Google Drive'}
          sx={{
            position: 'absolute',
            top: 0,
            left: 0,
            width: '100%',
            height: '100%',
            border: 'none'
          }}
          allow="autoplay"
          allowFullScreen
        />
      </Box>
    )
  }

  // YouTube iframe for YouTube videos
  if (videoSource === 'youtube') {
    if (!validateYouTubeUrl(src)) {
      return (
        <Alert severity="error">
          URL de YouTube no válida: {src}
        </Alert>
      )
    }

    return (
      <Box
        ref={containerRef}
        sx={{
          position: 'relative',
          width: '100%',
          paddingBottom: '56.25%', // 16:9 aspect ratio
          height: 0,
          overflow: 'hidden'
        }}
      >
        <Box
          component="iframe"
          src={getYouTubeEmbedUrl(src)}
          title={title || 'Video de YouTube'}
          sx={{
            position: 'absolute',
            top: 0,
            left: 0,
            width: '100%',
            height: '100%',
            border: 'none'
          }}
          allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
          allowFullScreen
        />
      </Box>
    )
  }

  // Custom video player for MinIO videos
  return (
    <Paper
      ref={containerRef}
      sx={{
        position: 'relative',
        backgroundColor: 'black',
        borderRadius: 1,
        overflow: 'hidden'
      }}
    >
      {error ? (
        <Alert severity="error" sx={{ m: 2 }}>
          {error}
        </Alert>
      ) : (
        <>
          {resolvedSrc ? (
            <video
              key={resolvedSrc}
              ref={videoRef}
              src={resolvedSrc}
              style={{
                width: '100%',
                height: 'auto',
                display: 'block'
              }}
              onPlay={() => setIsPlaying(true)}
              onPause={() => setIsPlaying(false)}
              onTimeUpdate={handleTimeUpdate}
              onLoadedMetadata={handleLoadedMetadata}
              onError={handleError}
              autoPlay={autoPlay}
              preload="metadata"
            />
          ) : null}

          {controls && (
            <Box
              sx={{
                position: 'absolute',
                bottom: 0,
                left: 0,
                right: 0,
                background: 'linear-gradient(transparent, rgba(0,0,0,0.8))',
                color: 'white',
                p: 2
              }}
            >
              {/* Progress Bar */}
              <Box sx={{ mb: 1 }}>
                <Slider
                  value={currentTime}
                  max={duration}
                  onChange={(_, value) => handleSeek(value as number)}
                  sx={{
                    color: 'primary.main',
                    '& .MuiSlider-thumb': {
                      width: 12,
                      height: 12
                    }
                  }}
                />
              </Box>

              {/* Controls */}
              <Box
                sx={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: 1
                }}
              >
                <IconButton
                  onClick={handlePlay}
                  sx={{ color: 'white' }}
                  disabled={isLoading}
                >
                  {isPlaying ? <PauseIcon /> : <PlayIcon />}
                </IconButton>

                <Typography variant="caption" sx={{ color: 'white', minWidth: 80 }}>
                  {formatTime(currentTime)} / {formatTime(duration)}
                </Typography>

                <Box sx={{ flexGrow: 1 }} />

                {/* Volume Control */}
                <IconButton
                  onClick={handleMute}
                  sx={{ color: 'white' }}
                >
                  {isMuted ? <VolumeOffIcon /> : <VolumeUpIcon />}
                </IconButton>

                <Box sx={{ width: 100 }}>
                  <Slider
                    value={isMuted ? 0 : volume}
                    max={1}
                    step={0.1}
                    onChange={(_, value) => handleVolumeChange(value as number)}
                    sx={{
                      color: 'white',
                      '& .MuiSlider-thumb': {
                        width: 8,
                        height: 8
                      }
                    }}
                  />
                </Box>

                <IconButton
                  onClick={handleFullscreen}
                  sx={{ color: 'white' }}
                >
                  {isFullscreen ? <FullscreenExitIcon /> : <FullscreenIcon />}
                </IconButton>
              </Box>
            </Box>
          )}

          {isLoading && (
            <Box
              sx={{
                position: 'absolute',
                top: '50%',
                left: '50%',
                transform: 'translate(-50%, -50%)',
                color: 'white'
              }}
            >
              <SignalLoader size='small' message='Cargando video...' />
            </Box>
          )}
        </>
      )}
    </Paper>
  )
}

export default LmsVideoPlayer

import { getApiErrorReason } from 'src/utils/apiError'
