import { PERMISSIONS } from 'src/constants/permissions'
import { useCan } from '@utils/functions'
import { notify } from 'src/utils/notify'
import { logger } from 'src/utils/logger'
/**
 * MaintenanceDashboard component provides an admin interface for managing maintenance tickets
 * Includes statistics, ticket management, and real-time updates
 */
const MaintenanceDashboard: React.FC = () => {
  useAxiosPrivate() // Initialize axios interceptors for automatic token refresh
  const navigate = useNavigate()
  const theme = useTheme()
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'))
  const $userStore = useStore(userStore)
  // Por defecto, no mostrar los tickets completados
  const [filters, setFilters] = useState<MaintenanceFilters>({
    status: Object.values(MaintenanceStatus).filter(
      (s) => s !== MaintenanceStatus.COMPLETED
    )
  })
  const [page, setPage] = useState(1)
  const [showFilters, setShowFilters] = useState(false)
  const [editDialogOpen, setEditDialogOpen] = useState(false)
  const [selectedTicket, setSelectedTicket] =
    useState<MaintenanceTicket | null>(null)
  const [editData, setEditData] = useState<MaintenanceUpdateRequest>({})
  const [costsDialogOpen, setCostsDialogOpen] = useState(false)
  const [technicalReportDialogOpen, setTechnicalReportDialogOpen] =
    useState(false)
  const [shortcutsHelpOpen, setShortcutsHelpOpen] = useState(false)
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false)
  const [ticketToDelete, setTicketToDelete] =
    useState<MaintenanceTicket | null>(null)

  const limit = 12
  const surfaceSx = {
    backgroundColor: '#ffffff',
    borderRadius: '14px',
    border: '1px solid #e5e7eb',
    boxShadow: '0 1px 3px rgba(15, 23, 42, 0.08)'
  }

  const showToast = (
    message: string,
    severity: 'success' | 'error' | 'warning' | 'info'
  ) => {
    notify[severity](message)
  }

  // Check user permissions
  // Sin alcance total sobre los tickets (capacidad), solo se ven y operan los asignados a uno mismo
  const isTechnician = !useCan(PERMISSIONS.MAINTENANCE_TICKET_MANAGE_ALL)
  const canListTechnicians = useCan(PERMISSIONS.MAINTENANCE_TECHNICIAN_LIST)
  const canCreateTickets = useCan(PERMISSIONS.MAINTENANCE_TICKET_CREATE)

  // Get technician ID if user is a technician
  const currentTechnicianEmail = useMemo(() => {
    if (!isTechnician) return null
    logger.log('User email:', $userStore)
    // Hardcode technician ID 4 for kat34433@laoia.com for testing
    return $userStore.email
  }, [isTechnician, $userStore.email])

  // For technicians, filter to only show their assigned tickets
  const technicianFilters = useMemo(() => {
    if (!isTechnician || !currentTechnicianEmail) return filters

    return {
      ...filters,
      assignedTechnicianEmail: currentTechnicianEmail // Using numeric technician ID
    }
  }, [filters, isTechnician, currentTechnicianEmail])

  // Filter allowed statuses for technicians (they can't change to 'new' or 'assigned')
  const allowedStatuses = useMemo(() => {
    if (!isTechnician) return Object.values(MaintenanceStatus)

    return [
      MaintenanceStatus.IN_PROGRESS,
      MaintenanceStatus.ON_HOLD,
      MaintenanceStatus.WAITING_PARTS,
      MaintenanceStatus.WAITING_CUSTOMER,
      MaintenanceStatus.COMPLETED
    ]
  }, [isTechnician])

  // API hooks
  const {
    data: stats,
    isLoading: statsLoading,
    refetch: refetchStats
  } = useMaintenanceStats(currentTechnicianEmail)
  const {
    data: ticketsData,
    isLoading: ticketsLoading,
    refetch: refetchTickets
  } = useMaintenanceTickets(technicianFilters, page, limit)
  const { data: currentTechnician } = useTechnicianByEmail(
    currentTechnicianEmail || ''
  )
  const {
    data: technicalReport,
    isLoading: technicalReportLoading,
    refetch: refetchTechnicalReport
  } = useMaintenanceTechnicalReport(
    selectedTicket?.status === MaintenanceStatus.COMPLETED && selectedTicket?.id
      ? selectedTicket.id
      : ''
  )
  // Only admins can access technicians list
  const { data: technicians } = useMaintenanceTechnicians(canListTechnicians)
  const updateTicketMutation = useUpdateMaintenanceTicket()
  const updateTechnicianMutation = useUpdateMaintenanceTechnician()
  const deleteTicketMutation = useDeleteMaintenanceTicket()
  const uploadFilesMutation = useUploadMaintenanceFiles()
  const upsertTechnicalReportMutation = useUpsertMaintenanceTechnicalReport()
  const generateTechnicalReportMutation = useGenerateTechnicalReport()

  const completionRate = useMemo(() => {
    const total = stats?.metrics?.totalTickets || 0
    const completed = stats?.metrics?.completedTickets || 0
    if (!total) return 0
    return Math.round((completed / total) * 100)
  }, [stats?.metrics?.completedTickets, stats?.metrics?.totalTickets])

  const urgentTickets = useMemo(() => {
    return (
      stats?.priorityStats?.find(
        ({ priority }) => priority === MaintenancePriority.URGENT
      )?.count || 0
    )
  }, [stats?.priorityStats])

  const activeTickets = useMemo(() => {
    return stats?.metrics?.pendingTickets || 0
  }, [stats?.metrics?.pendingTickets])

  const avgResolutionTimeDisplay = useMemo(() => {
    const value = stats?.metrics?.avgResolutionTimeHours || 0
    if (value >= 24) {
      const days = value / 24
      return days >= 10 ? `${Math.round(days)}d` : `${days.toFixed(1)}d`
    }
    return value >= 10 ? `${Math.round(value)}h` : `${value.toFixed(1)}h`
  }, [stats?.metrics?.avgResolutionTimeHours])

  const technicalReportCompletion = useMemo(() => {
    if (!technicalReport) return 0

    const checkpoints = [
      technicalReport.finalDiagnosis,
      technicalReport.rootCause,
      technicalReport.activities?.length,
      technicalReport.parts?.length,
      technicalReport.verificationProtocolType,
      technicalReport.verificationTests?.length,
      technicalReport.recommendations,
      technicalReport.scopeClause,
      technicalReport.responsibilityClause
    ]

    const completed = checkpoints.filter(Boolean).length
    return Math.round((completed / checkpoints.length) * 100)
  }, [technicalReport])

  // WebSocket for real-time updates
  useMaintenanceWebSocket({
    onTicketUpdate: (ticket) => {
      logger.log('Ticket updated via WebSocket:', ticket)
      refetchTickets()
      refetchStats()
    },
    onNotification: (notification) => {
      logger.log('New notification:', notification)
      // You could integrate with a notification system here
    }
  })

  // Keyboard shortcuts
  useKeyboardShortcuts({
    onNewTicket: () => {
      if (canCreateTickets) {
        navigate('/maintenance/new')
      }
    },
    onToggleFilters: () => {
      setShowFilters((prev) => !prev)
    },
    onRefreshData: () => {
      refetchTickets()
      refetchStats()
      showToast('Datos actualizados', 'success')
    },
    onFocusSearch: () => {
      // Focus search field in filters
      const searchField = document.getElementById('quick-search-field')
      if (searchField) {
        searchField.focus()
      } else {
        // If filters are collapsed, expand them first
        if (!showFilters) {
          setShowFilters(true)
          // Focus after a brief delay to allow expansion
          setTimeout(() => {
            const searchFieldDelayed =
              document.getElementById('quick-search-field')
            searchFieldDelayed?.focus()
          }, 100)
        }
      }
    },
    onShowHelp: () => {
      setShortcutsHelpOpen(true)
    },
    onCloseModal: () => {
      if (editDialogOpen) {
        setEditDialogOpen(false)
      } else if (shortcutsHelpOpen) {
        setShortcutsHelpOpen(false)
      }
    },
    enabled: true
  })

  // Equipment types for filters (this could come from an API)
  const equipmentTypes = useMemo(() => {
    if (!ticketsData?.tickets) return []
    const types = new Set(ticketsData.tickets.map((t) => t.equipmentType))
    return Array.from(types)
  }, [ticketsData?.tickets])

  // Ordenar tickets por prioridad (urgente -> alta -> media -> baja) y luego por fecha de creación (más antiguos primero)
  const sortedTickets = useMemo(() => {
    if (!ticketsData?.tickets) return []

    const priorityOrder = {
      [MaintenancePriority.URGENT]: 4,
      [MaintenancePriority.HIGH]: 3,
      [MaintenancePriority.MEDIUM]: 2,
      [MaintenancePriority.LOW]: 1
    }

    return [...ticketsData.tickets].sort((a, b) => {
      // Primero ordenar por prioridad (más alta primero)
      const priorityDiff = priorityOrder[b.priority] - priorityOrder[a.priority]
      if (priorityDiff !== 0) {
        return priorityDiff
      }

      // If priorities are the same, sort by creation date (oldest first)
      const dateA = new Date(a.createdAt).getTime()
      const dateB = new Date(b.createdAt).getTime()
      return dateA - dateB
    })
  }, [ticketsData?.tickets])

  const handleEditTicket = (ticket: MaintenanceTicket) => {
    if (maintenanceSignaturesEnabled && ticket.customerSignatureData) {
      showToast(
        'Este ticket ya fue firmado por el cliente y su contenido técnico quedó bloqueado',
        'warning'
      )
      return
    }

    if (
      isTechnician &&
      ticket.assignedTechnician?.email !== $userStore.email &&
      Number(ticket.assignedTechnician?.id) !== Number(currentTechnician?.id)
    ) {
      showToast('Solo puedes editar tickets asignados a tu usuario', 'warning')
      return
    }

    setSelectedTicket(ticket)
    logger.log('🚀 ~ handleEditTicket ~ ticket:', ticket)
    setEditData({
      status: ticket.status,
      assignedTechnician: ticket.assignedTechnicianId || '',
      scheduledDate: ticket.scheduledDate || '',
      equipmentType: ticket.equipmentType || '',
      equipmentBrand: ticket.equipmentBrand || '',
      equipmentModel: ticket.equipmentModel || '',
      equipmentSerial: ticket.equipmentSerial || '',
      location: ticket.location || '',
      priority: ticket.priority,
      intakePhysicalCondition: ticket.intakePhysicalCondition || '',
      receivedAccessories: ticket.receivedAccessories || ''
    })
    setEditDialogOpen(true)
  }

  const handleSaveEdit = async () => {
    if (!selectedTicket) return

    // Check if changing to COMPLETED status
    if (
      editData.status === MaintenanceStatus.COMPLETED &&
      selectedTicket.status !== MaintenanceStatus.COMPLETED
    ) {
      // Open costs dialog instead of saving directly
      setCostsDialogOpen(true)
      return
    }

    try {
      await updateTicketMutation.mutateAsync({
        id: selectedTicket.id,
        data: editData
      })
      // Refresh tickets to ensure proper re-ordering after priority/status changes
      refetchTickets()
      refetchStats()
      setEditDialogOpen(false)
      setSelectedTicket(null)
      setEditData({})
      showToast('Ticket actualizado exitosamente', 'success')
    } catch (error: any) {
      logger.error('Error updating ticket:', error)
      const errorMessage =
        getApiErrorReason(error) ||
        'Error al actualizar el ticket'
      showToast(errorMessage, 'error')
    }
  }

  const handleCompleteWithCosts = async (
    workPerformed: string,
    technicianWorkMinutes: number,
    costs: any[],
    completionPhotos: CompletionPhotoInput[],
    technicianSignature: {
      technicianSignatureData?: string | null
      saveTechnicianSignature?: boolean
    }
  ) => {
    if (!selectedTicket) return

    try {
      const targetTechnicianId =
        currentTechnician?.id || selectedTicket.assignedTechnician?.id

      if (
        technicianSignature.saveTechnicianSignature &&
        targetTechnicianId &&
        technicianSignature.technicianSignatureData
      ) {
        await updateTechnicianMutation.mutateAsync({
          id: targetTechnicianId,
          data: {
            signatureData: technicianSignature.technicianSignatureData
          }
        })
      }

      const completionPayload = isTechnician
        ? {
            status: MaintenanceStatus.COMPLETED,
            workPerformed,
            technicianWorkMinutes,
            costs,
            technicianSignatureData: maintenanceSignaturesEnabled
              ? technicianSignature.technicianSignatureData ||
                selectedTicket.technicianSignatureData ||
                currentTechnician?.signatureData ||
                selectedTicket.assignedTechnician?.signatureData ||
                null
              : null
          }
        : {
            ...editData,
            status: MaintenanceStatus.COMPLETED,
            workPerformed,
            technicianWorkMinutes,
            costs,
            technicianSignatureData: maintenanceSignaturesEnabled
              ? technicianSignature.technicianSignatureData ||
                selectedTicket.technicianSignatureData ||
                selectedTicket.assignedTechnician?.signatureData ||
                null
              : null
          }

      await updateTicketMutation.mutateAsync({
        id: selectedTicket.id,
        data: completionPayload
      })
      if (completionPhotos.length > 0) {
        await Promise.all(
          completionPhotos.map((photo) =>
            uploadFilesMutation.mutateAsync({
              ticketId: selectedTicket.id,
              files: [photo.file],
              category: 'repair_photo',
              description:
                photo.description?.trim() ||
                'Evidencia fotográfica del servicio completado',
              isPublic: false
            })
          )
        )
      }
      setCostsDialogOpen(false)
      setEditDialogOpen(false)
      setSelectedTicket(null)
      setEditData({})
      refetchTickets()
      refetchStats()
      showToast(
        completionPhotos.length > 0
          ? 'Ticket completado y fotos adjuntadas exitosamente'
          : 'Ticket completado exitosamente',
        'success'
      )
    } catch (error: any) {
      logger.error('Error completing ticket:', error)
      const errorMessage =
        getApiErrorReason(error) ||
        'Error al completar el ticket'
      showToast(errorMessage, 'error')
      throw error
    }
  }

  const handleViewTicket = (ticket: MaintenanceTicket) => {
    // Navigate to ticket details page using React Router
    navigate(`/maintenance/tickets/${ticket.id}`)
  }

  const handleOpenTechnicalReport = (ticket: MaintenanceTicket) => {
    if (maintenanceSignaturesEnabled && ticket.customerSignatureData) {
      showToast(
        'El reporte técnico ya no puede editarse después de la firma del cliente',
        'warning'
      )
      return
    }
    setSelectedTicket(ticket)
    setTechnicalReportDialogOpen(true)
  }

  const handleSaveTechnicalReport = async (
    reportData: MaintenanceTechnicalReportRequest
  ) => {
    if (!selectedTicket?.id) return

    try {
      await upsertTechnicalReportMutation.mutateAsync({
        ticketId: selectedTicket.id,
        data: reportData
      })
      await refetchTechnicalReport()
      refetchTickets()
      refetchStats()
      showToast('Reporte técnico guardado exitosamente', 'success')
    } catch (error: any) {
      logger.error('Error saving technical report:', error)
      const errorMessage =
        getApiErrorReason(error) ||
        'Error al guardar el reporte técnico'
      showToast(errorMessage, 'error')
      throw error
    }
  }

  const handleGenerateTechnicalReport = () => {
    if (!selectedTicket?.id) return

    generateTechnicalReportMutation.mutate(selectedTicket.id, {
      onSuccess: () => {
        showToast('Reporte técnico generado exitosamente', 'success')
      },
      onError: (error: any) => {
        logger.error('Error generating technical report:', error)
        showToast('Error al generar reporte técnico', 'error')
      }
    })
  }

  const handleDeleteClick = (ticket: MaintenanceTicket) => {
    setTicketToDelete(ticket)
    setDeleteDialogOpen(true)
  }

  const confirmDelete = async () => {
    if (!ticketToDelete) return

    try {
      await deleteTicketMutation.mutateAsync(ticketToDelete.id)
      setDeleteDialogOpen(false)
      setTicketToDelete(null)
      refetchTickets()
      refetchStats()
      showToast('Ticket eliminado exitosamente', 'success')
    } catch (error: any) {
      logger.error('Error deleting ticket:', error)
      const errorMessage =
        getApiErrorReason(error) ||
        'Error al eliminar el ticket'
      showToast(errorMessage, 'error')
    }
  }

  const handleRefresh = () => {
    refetchStats()
    refetchTickets()
  }

  return (
    <Container maxWidth='xl' sx={{ py: 3 }}>
      <LmsPageHeader
        title='Dashboard de Mantenimiento'
        subtitle='Gestión integral de tickets y técnicos'
        icon={<Dashboard />}
        actions={
          <Box display='flex' gap={1} flexWrap='wrap' alignItems='center'>
            <Tooltip title='Actualizar datos'>
              <IconButton onClick={handleRefresh} aria-label='Actualizar datos del dashboard'>
                <Refresh />
              </IconButton>
            </Tooltip>
            <Tooltip title='Atajos de teclado (Shift + ?)'>
              <IconButton onClick={() => setShortcutsHelpOpen(true)} aria-label='Mostrar atajos de teclado'>
                <Help />
              </IconButton>
            </Tooltip>
            <Button
              variant='outlined'
              startIcon={!isMobile && <FilterList />}
              onClick={() => setShowFilters(!showFilters)}
              aria-label={showFilters ? 'Ocultar filtros' : 'Mostrar filtros'}
              aria-expanded={showFilters}
              aria-controls='maintenance-filters-section'
              sx={{ color: '#00897B', borderColor: '#00BFA5', '&:hover': { borderColor: '#00897B', bgcolor: '#E0F7F4' } }}
            >
              {isMobile ? <FilterList /> : 'Filtros'}
            </Button>
            <Button
              variant='outlined'
              startIcon={!isMobile && <Assessment />}
              href='/maintenance/analytics'
              sx={{ color: '#00897B', borderColor: '#00BFA5', '&:hover': { borderColor: '#00897B', bgcolor: '#E0F7F4' } }}
            >
              {isMobile ? <Assessment /> : 'Analíticas'}
            </Button>
            {!isTechnician && (
              <Button
                variant='contained'
                startIcon={!isMobile && <Add />}
                href='/maintenance/report'
                sx={{ bgcolor: '#00BFA5', whiteSpace: 'nowrap', '&:hover': { bgcolor: '#00ACC1' } }}
              >
                {isMobile ? <Add /> : 'Nueva Solicitud'}
              </Button>
            )}
          </Box>
        }
      />

      {/* Stats Cards */}
      <Grid container spacing={3} mb={3} role='region' aria-label='Estadísticas del dashboard'>
        {statsLoading ? (
          <>
            <Grid item xs={12}><StatCardSkeleton /></Grid>
          </>
        ) : (
          <>
            <Grid item xs={6} md={3}>
              <LmsStatCard label='Total Tickets' value={stats?.metrics?.totalTickets || 0} icon={<Assignment />} tone='teal' />
            </Grid>
            <Grid item xs={6} md={3}>
              <LmsStatCard label='Pendientes' value={stats?.metrics?.pendingTickets || 0} icon={<Build />} tone='orange' />
            </Grid>
            <Grid item xs={6} md={3}>
              <LmsStatCard label='Completados' value={stats?.metrics?.completedTickets || 0} icon={<CheckCircle />} tone='green' />
            </Grid>
            <Grid item xs={6} md={3}>
              <LmsStatCard label='Tiempo Promedio' value={avgResolutionTimeDisplay} caption='Promedio de cierre' icon={<TrendingUp />} tone='blue' />
            </Grid>
          </>
        )}
      </Grid>

      {/* Additional Stats */}
      <Grid
        container
        spacing={{ xs: 2, sm: 2, md: 3 }}
        mb={{ xs: 2, sm: 3, md: 3 }}
      >
        <Grid item xs={12} md={8}>
          <Paper
            sx={{
              p: { xs: 2, sm: 3 },
              ...surfaceSx
            }}
          >
            <Box mb={3}>
              <Typography
                variant='h6'
                gutterBottom
                sx={{
                  fontSize: { xs: '1.125rem', sm: '1.25rem' },
                  fontWeight: 600,
                  color: '#0f172a',
                  mb: 0.5
                }}
              >
                Tickets por Prioridad
              </Typography>
              <Typography variant='body2' sx={{ color: '#64748b' }}>
                Vista rápida para detectar carga operativa y urgencias sin
                saturar el tablero.
              </Typography>
            </Box>
            <Grid container spacing={{ xs: 1, sm: 2 }}>
              {stats?.priorityStats &&
                stats.priorityStats.map(({ priority, count }) => (
                  <Grid item xs={6} sm={4} key={priority}>
                    <Box
                      textAlign='center'
                      sx={{
                        p: { xs: 1.75, sm: 2 },
                        borderRadius: '12px',
                        backgroundColor: '#fbfdfb',
                        border: '1px solid #e5e7eb'
                      }}
                    >
                      <Typography
                        variant='h5'
                        sx={{
                          fontSize: { xs: '1.25rem', sm: '1.5rem' },
                          fontWeight: 700,
                          color: '#0f172a',
                          mb: 1
                        }}
                      >
                        {count}
                      </Typography>
                      <MaintenancePriorityBadge
                        priority={priority as MaintenancePriority}
                        size='small'
                      />
                    </Box>
                  </Grid>
                ))}
            </Grid>
          </Paper>
        </Grid>

        <Grid item xs={12} md={4}>
          <Paper
            sx={{
              p: { xs: 2, sm: 3 },
              height: '100%',
              ...surfaceSx
            }}
          >
            <Box mb={2.5}>
              <Typography
                variant='h6'
                gutterBottom
                sx={{
                  fontSize: { xs: '1.125rem', sm: '1.25rem' },
                  fontWeight: 600,
                  color: '#0f172a',
                  mb: 0.5
                }}
              >
                Panorama Rápido
              </Typography>
              <Typography variant='body2' sx={{ color: '#64748b' }}>
                Resumen operativo para leer el tablero de un vistazo.
              </Typography>
            </Box>

            <Box sx={{ display: 'grid', gap: 1.5 }}>
              {[
                {
                  label: 'Cierre efectivo',
                  value: `${completionRate}%`,
                  helper: 'Tickets completados sobre el total',
                  color: '#00A651',
                  background: '#e8f7ef'
                },
                {
                  label: 'Carga activa',
                  value: `${activeTickets}`,
                  helper: 'Tickets que siguen en operación',
                  color: '#b45309',
                  background: '#fff7ed'
                },
                {
                  label: 'Urgencias abiertas',
                  value: `${urgentTickets}`,
                  helper: 'Casos que necesitan más atención',
                  color: '#dc2626',
                  background: '#fef2f2'
                }
              ].map((item) => (
                <Box
                  key={item.label}
                  sx={{
                    borderRadius: '12px',
                    border: '1px solid #e5e7eb',
                    p: 1.75,
                    backgroundColor: '#ffffff'
                  }}
                >
                  <Box
                    display='flex'
                    alignItems='center'
                    justifyContent='space-between'
                    gap={2}
                  >
                    <Box>
                      <Typography
                        variant='body2'
                        sx={{ fontWeight: 600, color: '#0f172a', mb: 0.25 }}
                      >
                        {item.label}
                      </Typography>
                      <Typography variant='caption' sx={{ color: '#64748b' }}>
                        {item.helper}
                      </Typography>
                    </Box>
                    <Box
                      sx={{
                        minWidth: 68,
                        px: 1.25,
                        py: 0.75,
                        borderRadius: '999px',
                        textAlign: 'center',
                        fontWeight: 700,
                        color: item.color,
                        backgroundColor: item.background
                      }}
                    >
                      {item.value}
                    </Box>
                  </Box>
                </Box>
              ))}
            </Box>
          </Paper>
        </Grid>

        {/* <Grid item xs={12} md={6}>
          <Paper elevation={2} sx={{ p: 3 }}>
            <Typography variant="h6" gutterBottom>
              Información Financiera
            </Typography>
            <Grid container spacing={2}>
              <Grid item xs={6}>
                <Typography variant="body2" color="text.secondary">
                  Ingresos Totales
                </Typography>
                <Typography variant="h5" color="success.main">
                  ${stats?.totalRevenue?.toLocaleString() || 0}
                </Typography>
              </Grid>
              <Grid item xs={6}>
                <Typography variant="body2" color="text.secondary">
                  Costo Promedio
                </Typography>
                <Typography variant="h5" color="primary">
                  ${stats?.averageCost?.toLocaleString() || 0}
                </Typography>
              </Grid>
            </Grid>
          </Paper>
        </Grid> */}
      </Grid>

      {/* Filters */}
      {showFilters && (
        <Box
          mb={3}
          id='maintenance-filters-section'
          role='region'
          aria-label='Sección de filtros'
        >
          <MaintenanceFiltersComponent
            filters={filters}
            onFiltersChange={(newFilters) => setFilters({ ...newFilters })}
            technicians={technicians || []}
            equipmentTypes={equipmentTypes}
            loading={ticketsLoading}
            resultsCount={ticketsData?.pagination.totalItems}
          />
        </Box>
      )}

      {/* Tickets Grid */}
      <Paper
        sx={{
          p: { xs: 2, sm: 3 },
          ...surfaceSx
        }}
      >
        <Box
          display='flex'
          flexDirection={{ xs: 'column', sm: 'row' }}
          justifyContent='space-between'
          alignItems={{ xs: 'flex-start', sm: 'center' }}
          mb={{ xs: 2, sm: 3 }}
          gap={{ xs: 1, sm: 0 }}
        >
          <Box>
            <Typography
              variant='h6'
              sx={{
                fontSize: { xs: '1.125rem', sm: '1.25rem' },
                fontWeight: 600,
                color: '#0f172a',
                display: 'flex',
                alignItems: 'center',
                flexWrap: 'wrap',
                gap: 1
              }}
            >
              Tickets de Mantenimiento
              {ticketsData?.pagination.totalItems && (
                <Chip
                  label={`${ticketsData.pagination.totalItems} total`}
                  size='small'
                  sx={{
                    backgroundColor: '#e8f7ef',
                    color: '#00A651',
                    fontWeight: 600
                  }}
                />
              )}
            </Typography>
            <Typography variant='body2' sx={{ mt: 0.5, color: '#64748b' }}>
              Tarjetas más ligeras para priorizar lectura rápida y acciones
              frecuentes.
            </Typography>
          </Box>
        </Box>

        {ticketsLoading ? (
          <Grid
            container
            spacing={{ xs: 2, sm: 2, md: 3 }}
            role='status'
            aria-live='polite'
          >
            {[...Array(6)].map((_, index) => (
              <Grid item xs={12} sm={6} lg={4} key={index}>
                <TicketCardSkeleton />
              </Grid>
            ))}
          </Grid>
        ) : !sortedTickets.length ? (
          <Alert severity='info' role='status'>
            No se encontraron tickets con los filtros aplicados.
          </Alert>
        ) : (
          <>
            <Grid container spacing={{ xs: 2, sm: 2, md: 3 }}>
              {sortedTickets.map((ticket) => (
                <Grid item xs={12} sm={6} lg={4} key={ticket.id}>
                  <MaintenanceTicketCard
                    ticket={ticket}
                    onView={handleViewTicket}
                    onEdit={handleEditTicket}
                    onDelete={
                      !isTechnician &&
                      [
                        MaintenanceStatus.PENDING,
                        MaintenanceStatus.ASSIGNED,
                        MaintenanceStatus.CANCELLED
                      ].includes(ticket.status as MaintenanceStatus)
                        ? handleDeleteClick
                        : undefined
                    }
                    showActions={true}
                  />
                </Grid>
              ))}
            </Grid>

            {/* Pagination */}
            {ticketsData && ticketsData.pagination.totalPages > 1 && (
              <Box display='flex' justifyContent='center' mt={{ xs: 2, sm: 3 }}>
                <Pagination
                  count={ticketsData.pagination.totalPages}
                  page={page}
                  onChange={(_, newPage) => setPage(newPage)}
                  color='primary'
                  aria-label='Paginación de tickets'
                  size={isMobile ? 'small' : 'medium'}
                  siblingCount={isMobile ? 0 : 1}
                  boundaryCount={1}
                  sx={{
                    '& .MuiPaginationItem-root': {
                      minWidth: { xs: 32, sm: 36 },
                      height: { xs: 32, sm: 36 },
                      fontSize: { xs: '0.813rem', sm: '0.875rem' }
                    }
                  }}
                />
              </Box>
            )}
          </>
        )}
      </Paper>

      {/* Delete Confirmation Dialog */}
      <Dialog
        open={deleteDialogOpen}
        onClose={() => setDeleteDialogOpen(false)}
        aria-labelledby='alert-dialog-title'
        aria-describedby='alert-dialog-description'
      >
        <DialogTitle id='alert-dialog-title'>
          {'¿Eliminar ticket de mantenimiento?'}
        </DialogTitle>
        <DialogContent>
          <Typography variant='body1' gutterBottom>
            ¿Estás seguro de que deseas eliminar el ticket{' '}
            <strong>#{ticketToDelete?.ticketCode}</strong>?
          </Typography>
          <Alert severity='warning' sx={{ mt: 2 }}>
            Esta acción no se puede deshacer. Se eliminarán todos los
            comentarios y archivos asociados.
          </Alert>
        </DialogContent>
        <DialogActions>
          <Button
            onClick={() => setDeleteDialogOpen(false)}
            color='primary'
            disabled={deleteTicketMutation.isLoading}
          >
            Cancelar
          </Button>
          <Button
            onClick={confirmDelete}
            color='error'
            variant='contained'
            autoFocus
            disabled={deleteTicketMutation.isLoading}
          >
            {deleteTicketMutation.isLoading ? 'Eliminando...' : 'Eliminar'}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Edit Ticket Dialog */}
      <Dialog
        open={editDialogOpen}
        onClose={() => setEditDialogOpen(false)}
        maxWidth='sm'
        fullWidth
        fullScreen={isMobile}
        aria-labelledby='edit-ticket-dialog-title'
        aria-describedby='edit-ticket-dialog-description'
      >
        <DialogTitle id='edit-ticket-dialog-title'>
          <Box
            display='flex'
            justifyContent='space-between'
            alignItems='center'
          >
            <Typography
              variant='h6'
              sx={{ fontSize: { xs: '1.125rem', sm: '1.25rem' } }}
            >
              Editar Ticket #{selectedTicket?.ticketCode}
            </Typography>
            {isMobile && (
              <IconButton
                onClick={() => setEditDialogOpen(false)}
                aria-label='Cerrar'
                sx={{ minWidth: 44, minHeight: 44 }}
              >
                <Cancel />
              </IconButton>
            )}
          </Box>
        </DialogTitle>
        <DialogContent
          id='edit-ticket-dialog-description'
          sx={{ pt: { xs: 2.5, sm: 3 }, overflowY: 'auto' }}
        >
          <Grid container spacing={{ xs: 1, sm: 2 }} sx={{ mt: 0.5 }}>
            <Grid item xs={12} sm={6}>
              <FormControl fullWidth size={isMobile ? 'small' : 'medium'}>
                <Typography
                  variant='caption'
                  sx={{
                    mb: 0.75,
                    px: 0.5,
                    fontWeight: 600,
                    color: '#64748b',
                    letterSpacing: '0.02em'
                  }}
                >
                  Estado
                </Typography>
                <Select
                  id='edit-status-select'
                  value={editData.status || ''}
                  onChange={(e) =>
                    setEditData((prev) => ({
                      ...prev,
                      status: e.target.value as MaintenanceStatus
                    }))
                  }
                  aria-label='Seleccionar estado del ticket'
                  disabled={
                    selectedTicket?.status === MaintenanceStatus.COMPLETED
                  }
                >
                  {allowedStatuses.map((status) => (
                    <MenuItem key={status} value={status}>
                      <MaintenanceStatusBadge status={status} size='small' />
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>

            {!isTechnician && (
              <Grid item xs={12} sm={6}>
                <FormControl fullWidth size={isMobile ? 'small' : 'medium'}>
                  <Typography
                    variant='caption'
                    sx={{
                      mb: 0.75,
                      px: 0.5,
                      fontWeight: 600,
                      color: '#64748b',
                      letterSpacing: '0.02em'
                    }}
                  >
                    Prioridad
                  </Typography>
                  <Select
                    id='edit-priority-select'
                    value={editData.priority || ''}
                    onChange={(e) =>
                      setEditData((prev) => ({
                        ...prev,
                        priority: e.target.value as MaintenancePriority
                      }))
                    }
                    aria-label='Seleccionar prioridad del ticket'
                    disabled={
                      selectedTicket?.status === MaintenanceStatus.COMPLETED
                    }
                  >
                    {Object.values(MaintenancePriority).map((priority) => (
                      <MenuItem key={priority} value={priority}>
                        <MaintenancePriorityBadge
                          priority={priority}
                          size='small'
                        />
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Grid>
            )}

            {!isTechnician && (
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  size={isMobile ? 'small' : 'medium'}
                  label='Tipo de equipo'
                  value={editData.equipmentType || ''}
                  onChange={(e) =>
                    setEditData((prev) => ({
                      ...prev,
                      equipmentType: e.target.value
                    }))
                  }
                />
              </Grid>
            )}

            {!isTechnician && (
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  size={isMobile ? 'small' : 'medium'}
                  label='Marca'
                  value={editData.equipmentBrand || ''}
                  onChange={(e) =>
                    setEditData((prev) => ({
                      ...prev,
                      equipmentBrand: e.target.value
                    }))
                  }
                />
              </Grid>
            )}

            {!isTechnician && (
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  size={isMobile ? 'small' : 'medium'}
                  label='Modelo'
                  value={editData.equipmentModel || ''}
                  onChange={(e) =>
                    setEditData((prev) => ({
                      ...prev,
                      equipmentModel: e.target.value
                    }))
                  }
                />
              </Grid>
            )}

            {!isTechnician && (
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  size={isMobile ? 'small' : 'medium'}
                  label='Número de serie'
                  value={editData.equipmentSerial || ''}
                  onChange={(e) =>
                    setEditData((prev) => ({
                      ...prev,
                      equipmentSerial: e.target.value
                    }))
                  }
                />
              </Grid>
            )}

            {!isTechnician && (
              <Grid item xs={12}>
                <TextField
                  fullWidth
                  size={isMobile ? 'small' : 'medium'}
                  label='Ubicación del equipo'
                  value={editData.location || ''}
                  onChange={(e) =>
                    setEditData((prev) => ({
                      ...prev,
                      location: e.target.value
                    }))
                  }
                />
              </Grid>
            )}

            {!isTechnician && (
              <Grid item xs={12}>
                <FormControl fullWidth size={isMobile ? 'small' : 'medium'}>
                  <InputLabel id='edit-technician-label'>
                    Técnico Asignado
                  </InputLabel>
                  <Select
                    labelId='edit-technician-label'
                    id='edit-technician-select'
                    value={editData.assignedTechnician || ''}
                    onChange={(e) =>
                      setEditData((prev) => ({
                        ...prev,
                        assignedTechnician: e.target.value,
                        status:
                          prev.status === MaintenanceStatus.PENDING &&
                          Boolean(e.target.value)
                            ? MaintenanceStatus.ASSIGNED
                            : prev.status
                      }))
                    }
                    label='Técnico Asignado'
                    aria-label='Seleccionar técnico asignado'
                    disabled={
                      selectedTicket?.status === MaintenanceStatus.COMPLETED
                    }
                  >
                    <MenuItem value=''>Sin asignar</MenuItem>
                    {technicians
                      ?.filter((t) => t.status === 'active')
                      .sort((a, b) => {
                        const aCapacity = a.maxWorkload - a.workload
                        const bCapacity = b.maxWorkload - b.workload
                        return bCapacity - aCapacity
                      })
                      .map((technician) => {
                        const utilizationPct =
                          (technician.workload / technician.maxWorkload) * 100
                        const isFull =
                          technician.workload >= technician.maxWorkload
                        const isNearFull = utilizationPct >= 80

                        return (
                          <MenuItem
                            key={technician.id}
                            value={technician.id}
                            disabled={isFull}
                          >
                            <Box
                              display='flex'
                              flexDirection='column'
                              width='100%'
                            >
                              <Box
                                display='flex'
                                alignItems='center'
                                gap={1}
                                width='100%'
                              >
                                <Avatar
                                  sx={{
                                    width: 32,
                                    height: 32,
                                    fontSize: '0.875rem',
                                    bgcolor: isFull
                                      ? 'error.main'
                                      : isNearFull
                                        ? 'warning.main'
                                        : 'success.main'
                                  }}
                                >
                                  {technician.name
                                    .split(' ')
                                    .map((n) => n[0])
                                    .join('')
                                    .toUpperCase()}
                                </Avatar>

                                <Box flex={1}>
                                  <Typography
                                    variant='body2'
                                    fontWeight='medium'
                                  >
                                    {technician.name}
                                  </Typography>
                                  <Typography
                                    variant='caption'
                                    color='text.secondary'
                                  >
                                    {technician.specialization || 'General'}
                                  </Typography>
                                </Box>

                                <Box
                                  display='flex'
                                  gap={0.5}
                                  alignItems='center'
                                >
                                  <Chip
                                    size='small'
                                    label={`${technician.workload}/${technician.maxWorkload}`}
                                    color={
                                      isFull
                                        ? 'error'
                                        : isNearFull
                                          ? 'warning'
                                          : 'success'
                                    }
                                    variant='outlined'
                                  />
                                  {isFull && (
                                    <Chip
                                      size='small'
                                      label='Completo'
                                      color='error'
                                    />
                                  )}
                                </Box>
                              </Box>

                              <Box width='100%' mt={1}>
                                <LinearProgress
                                  variant='determinate'
                                  value={utilizationPct}
                                  color={
                                    isFull
                                      ? 'error'
                                      : isNearFull
                                        ? 'warning'
                                        : 'success'
                                  }
                                  sx={{ height: 4, borderRadius: 2 }}
                                />
                              </Box>
                            </Box>
                          </MenuItem>
                        )
                      })}
                  </Select>
                </FormControl>
              </Grid>
            )}

            {!isTechnician && (
              <Grid item xs={12}>
                <TextField
                  fullWidth
                  size={isMobile ? 'small' : 'medium'}
                  id='edit-scheduled-date'
                  label='Fecha Programada'
                  type='datetime-local'
                  value={
                    editData.scheduledDate
                      ? new Date(editData.scheduledDate)
                          .toISOString()
                          .slice(0, 16)
                      : ''
                  }
                  onChange={(e) =>
                    setEditData((prev) => ({
                      ...prev,
                      scheduledDate: e.target.value
                        ? new Date(e.target.value).toISOString()
                        : undefined
                    }))
                  }
                  InputLabelProps={{ shrink: true }}
                  aria-label='Seleccionar fecha y hora programada'
                  inputProps={{
                    'aria-describedby': 'scheduled-date-helper'
                  }}
                />
              </Grid>
            )}

            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                size={isMobile ? 'small' : 'medium'}
                id='edit-intake-physical-condition'
                label='Condición inicial del equipo'
                value={editData.intakePhysicalCondition || ''}
                onChange={(e) =>
                  setEditData((prev) => ({
                    ...prev,
                    intakePhysicalCondition: e.target.value
                  }))
                }
                multiline
                minRows={3}
                placeholder='Rayones, golpes, faltantes o condición general al iniciar la intervención'
              />
            </Grid>

            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                size={isMobile ? 'small' : 'medium'}
                id='edit-received-accessories'
                label='Accesorios disponibles'
                value={editData.receivedAccessories || ''}
                onChange={(e) =>
                  setEditData((prev) => ({
                    ...prev,
                    receivedAccessories: e.target.value
                  }))
                }
                multiline
                minRows={3}
                placeholder='Cables, sensores, fuente, batería, adaptadores u otros accesorios disponibles durante el servicio'
              />
            </Grid>

            {/* Capacity Warning Alert */}
            {editData.assignedTechnician &&
              (() => {
                const selectedTech = technicians?.find(
                  (t) => t.id === editData.assignedTechnician
                )
                if (!selectedTech) return null

                const utilizationPct =
                  (selectedTech.workload / selectedTech.maxWorkload) * 100

                if (utilizationPct >= 80 && utilizationPct < 100) {
                  return (
                    <Grid item xs={12}>
                      <Alert severity='warning' sx={{ mt: 2 }}>
                        <AlertTitle>
                          Técnico casi en capacidad máxima
                        </AlertTitle>
                        <Typography variant='body2'>
                          <strong>{selectedTech.name}</strong> tiene{' '}
                          <strong>{selectedTech.workload}</strong> de{' '}
                          <strong>{selectedTech.maxWorkload}</strong> tickets
                          asignados ({utilizationPct.toFixed(0)}% utilización).{' '}
                          Considere asignar a un técnico con menos carga de
                          trabajo.
                        </Typography>
                      </Alert>
                    </Grid>
                  )
                }

                if (utilizationPct >= 100) {
                  return (
                    <Grid item xs={12}>
                      <Alert severity='error' sx={{ mt: 2 }}>
                        <AlertTitle>Técnico en capacidad máxima</AlertTitle>
                        <Typography variant='body2'>
                          <strong>{selectedTech.name}</strong> ha alcanzado su
                          capacidad máxima ({selectedTech.workload}/
                          {selectedTech.maxWorkload} tickets). Por favor
                          seleccione otro técnico disponible.
                        </Typography>
                      </Alert>
                    </Grid>
                  )
                }

                return null
              })()}
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setEditDialogOpen(false)}>Cancelar</Button>
          {selectedTicket?.status === MaintenanceStatus.COMPLETED && (
            <Button
              onClick={() => handleOpenTechnicalReport(selectedTicket)}
              variant='outlined'
              startIcon={<Science />}
            >
              {technicalReport?.updatedAt
                ? `Reporte técnico ${technicalReportCompletion}%`
                : 'Reporte técnico'}
            </Button>
          )}
          <Button
            onClick={handleSaveEdit}
            variant='contained'
            disabled={updateTicketMutation.isLoading}
          >
            {updateTicketMutation.isLoading ? 'Guardando...' : 'Guardar'}
          </Button>
        </DialogActions>
      </Dialog>

      <MaintenanceTechnicalReportDialog
        open={technicalReportDialogOpen}
        onClose={() => setTechnicalReportDialogOpen(false)}
        report={technicalReport}
        equipmentType={selectedTicket?.equipmentType}
        loading={technicalReportLoading}
        saving={upsertTechnicalReportMutation.isLoading}
        generatingPdf={generateTechnicalReportMutation.isLoading}
        onSave={handleSaveTechnicalReport}
        onGeneratePdf={handleGenerateTechnicalReport}
      />

      {/* Completion Costs Dialog */}
      <CompletionCostsDialog
        open={costsDialogOpen}
        onClose={() => setCostsDialogOpen(false)}
        onComplete={handleCompleteWithCosts}
        technicianName={selectedTicket?.assignedTechnician?.name}
        storedTechnicianSignature={
          selectedTicket?.technicianSignatureData ||
          (isTechnician
            ? currentTechnician?.signatureData ||
              selectedTicket?.assignedTechnician?.signatureData ||
              null
            : selectedTicket?.assignedTechnician?.signatureData || null)
        }
        canCaptureTechnicianSignature={
          !(
            selectedTicket?.technicianSignatureData ||
            currentTechnician?.signatureData ||
            selectedTicket?.assignedTechnician?.signatureData
          )
        }
        signaturesEnabled={maintenanceSignaturesEnabled}
        loading={
          updateTicketMutation.isLoading ||
          uploadFilesMutation.isLoading ||
          updateTechnicianMutation.isLoading
        }
      />


      {/* Keyboard Shortcuts Help Modal */}
      <KeyboardShortcutsHelp
        open={shortcutsHelpOpen}
        onClose={() => setShortcutsHelpOpen(false)}
      />
    </Container>
  )
}

export default MaintenanceDashboard

import { getApiErrorReason } from 'src/utils/apiError'
import { confirmDialog } from 'src/utils/confirm'
import SignalLoader from 'src/Components/Common/SignalLoader'
import { useMemo, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import {
  Alert,
  Autocomplete,
  Box,
  Button,
  Chip,
  Container,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControlLabel,
  Grid,
  IconButton,
  MenuItem,
  Paper,
  Stack,
  Switch,
  TextField,
  Typography
} from '@mui/material'
import {
  Add,
  ArrowBack,
  Assignment,
  CheckCircleOutline,
  DeleteOutline,
  EditOutlined,
  PlaylistAddCheck
} from '@mui/icons-material'
import {
  useCreateMaintenanceProtocolTemplate,
  useDeleteMaintenanceProtocolTemplate,
  useMaintenanceProtocolTemplates,
  useMaintenanceToolEquipmentSearch,
  useUpdateMaintenanceProtocolTemplate
} from '../../hooks/useMaintenance'
import type {
  MaintenanceProtocolTemplate,
  MaintenanceProtocolTemplateRequest,
  MaintenanceTechnicalReportTest,
  MaintenanceTechnicalReportTool,
  MaintenanceToolEquipmentSummary
} from '../../types/maintenance'

import LmsPageHeader from 'src/Components/lms/admin/LmsPageHeader'
import LmsStatCard from 'src/Components/lms/admin/LmsStatCard'
import { logger } from 'src/utils/logger'
const surfaceSx = {
  borderRadius: '16px',
  border: '1px solid #e5e7eb',
  boxShadow: '0 8px 24px rgba(15, 23, 42, 0.06)',
  backgroundColor: '#ffffff'
}

const emptyTool = (): MaintenanceTechnicalReportTool => ({
  name: '',
  serial: '',
  calibrationDue: null,
  internalCode: null,
  location: null
})

const emptyTest = (): MaintenanceTechnicalReportTest => ({
  parameter: '',
  result: 'PASA',
  value: '',
  notes: ''
})

const defaultFormState = {
  name: '',
  code: '',
  description: '',
  appliesToText: '',
  riskClass: '',
  recommendations: '',
  sortOrder: 0,
  isActive: true,
  tools: [emptyTool()],
  tests: [emptyTest()]
}

const toFormState = (protocol?: MaintenanceProtocolTemplate | null) => {
  if (!protocol) return defaultFormState

  return {
    name: protocol.name,
    code: protocol.code,
    description: protocol.description || '',
    appliesToText: protocol.appliesTo.join(', '),
    riskClass: protocol.riskClass || '',
    recommendations: protocol.recommendations || '',
    sortOrder: protocol.sortOrder || 0,
    isActive: protocol.isActive,
    tools: protocol.tools.length ? protocol.tools : [emptyTool()],
    tests: protocol.tests.length ? protocol.tests : [emptyTest()]
  }
}

const MaintenanceProtocols = () => {
  const navigate = useNavigate()
  const { data: protocols = [], isLoading } = useMaintenanceProtocolTemplates()
  const createProtocolMutation = useCreateMaintenanceProtocolTemplate()
  const updateProtocolMutation = useUpdateMaintenanceProtocolTemplate()
  const deleteProtocolMutation = useDeleteMaintenanceProtocolTemplate()

  const [dialogOpen, setDialogOpen] = useState(false)
  const [currentProtocol, setCurrentProtocol] =
    useState<MaintenanceProtocolTemplate | null>(null)
  const [formState, setFormState] = useState(defaultFormState)
  const [formError, setFormError] = useState<string | null>(null)
  const [toolSearch, setToolSearch] = useState('')
  const { data: toolEquipmentOptions = [], isFetching: toolSearchLoading } =
    useMaintenanceToolEquipmentSearch(toolSearch)

  const activeCount = useMemo(
    () => protocols.filter((protocol) => protocol.isActive).length,
    [protocols]
  )

  const resetDialog = () => {
    setCurrentProtocol(null)
    setFormState(defaultFormState)
    setFormError(null)
    setDialogOpen(false)
  }

  const openCreateDialog = () => {
    setCurrentProtocol(null)
    setFormState(defaultFormState)
    setFormError(null)
    setDialogOpen(true)
  }

  const openEditDialog = (protocol: MaintenanceProtocolTemplate) => {
    setCurrentProtocol(protocol)
    setFormState(toFormState(protocol))
    setFormError(null)
    setDialogOpen(true)
  }

  const updateTool = (
    index: number,
    field: keyof MaintenanceTechnicalReportTool,
    value: string | null
  ) => {
    setFormState((prev) => ({
      ...prev,
      tools: prev.tools.map((tool, idx) =>
        idx === index ? { ...tool, [field]: value } : tool
      )
    }))
  }

  const updateTest = (
    index: number,
    field: keyof MaintenanceTechnicalReportTest,
    value: string
  ) => {
    setFormState((prev) => ({
      ...prev,
      tests: prev.tests.map((test, idx) =>
        idx === index ? { ...test, [field]: value } : test
      )
    }))
  }

  const buildPayload = (): MaintenanceProtocolTemplateRequest => ({
    name: formState.name.trim(),
    code: formState.code.trim(),
    description: formState.description.trim() || null,
    appliesTo: formState.appliesToText
      .split(',')
      .map((keyword) => keyword.trim())
      .filter(Boolean),
    riskClass: formState.riskClass.trim() || null,
    recommendations: formState.recommendations.trim() || null,
    sortOrder: Number(formState.sortOrder) || 0,
    isActive: formState.isActive,
    tools: formState.tools
      .map((tool) => ({
        name: tool.name.trim(),
        serial: tool.serial?.trim() || null,
        calibrationDue: tool.calibrationDue || null,
        internalCode: tool.internalCode?.trim() || null,
        location: tool.location?.trim() || null
      }))
      .filter((tool) => tool.name),
    tests: formState.tests
      .map((test) => ({
        parameter: test.parameter.trim(),
        result: (test.result || 'PASA').trim().toUpperCase(),
        value: test.value?.trim() || '',
        notes: test.notes?.trim() || ''
      }))
      .filter((test) => test.parameter)
  })

  const handleSave = async () => {
    const payload = buildPayload()

    if (!payload.name) {
      setFormError('El nombre del protocolo es obligatorio.')
      return
    }

    if (!payload.code) {
      setFormError('El código del protocolo es obligatorio.')
      return
    }

    try {
      if (currentProtocol) {
        await updateProtocolMutation.mutateAsync({
          id: currentProtocol.id,
          data: payload
        })
      } else {
        await createProtocolMutation.mutateAsync(payload)
      }
      resetDialog()
    } catch (error: any) {
      setFormError(
        getApiErrorReason(error) ||
          error?.message ||
          'No se pudo guardar el protocolo.'
      )
    }
  }

  const handleDelete = async (protocol: MaintenanceProtocolTemplate) => {
    const { isConfirmed } = await confirmDialog({
      title: 'Eliminar protocolo',
      text: `Vas a eliminar el protocolo "${protocol.name}". Esta acción no se puede deshacer.`,
      confirmLabel: 'Eliminar',
      tone: 'danger'
    })

    if (!isConfirmed) return

    try {
      await deleteProtocolMutation.mutateAsync(protocol.id)
    } catch (error) {
      logger.error(error)
    }
  }

  return (
    <Container maxWidth='xl' sx={{ py: 3 }}>
      <Button
        startIcon={<ArrowBack />}
        onClick={() => navigate('/maintenance')}
        sx={{ mb: 1, color: 'text.secondary', textTransform: 'none', fontWeight: 600 }}
      >
        Volver al dashboard
      </Button>

      <LmsPageHeader
        title='Protocolos de Mantenimiento'
        subtitle='Catálogo editable de protocolos para el reporte técnico.'
        icon={<PlaylistAddCheck />}
        actions={
          <Button variant='contained' startIcon={<Add />} onClick={openCreateDialog} sx={{ bgcolor: '#00BFA5', whiteSpace: 'nowrap', '&:hover': { bgcolor: '#00ACC1' } }}>
            Nuevo protocolo
          </Button>
        }
      />

      <Grid container spacing={3} sx={{ mb: 3 }}>
        <Grid item xs={12} sm={4}>
          <LmsStatCard label='Total protocolos' value={protocols.length} icon={<PlaylistAddCheck />} tone='teal' />
        </Grid>
        <Grid item xs={12} sm={4}>
          <LmsStatCard label='Activos' value={activeCount} icon={<CheckCircleOutline />} tone='green' />
        </Grid>
        <Grid item xs={12} sm={4}>
          <LmsStatCard
            label='Uso esperado'
            value='Presets'
            caption='Disponibles como presets del reporte técnico'
            icon={<Assignment />}
            tone='blue'
          />
        </Grid>
      </Grid>

      {isLoading ? (
        <SignalLoader message='Cargando protocolos...' />
      ) : protocols.length === 0 ? (
        <Alert severity='warning'>
          No hay protocolos registrados. Puedes crear el primero desde aquí.
        </Alert>
      ) : (
        <Grid container spacing={2}>
          {protocols.map((protocol) => (
            <Grid item xs={12} md={6} lg={4} key={protocol.id}>
              <Paper sx={{ ...surfaceSx, p: 2.5, height: '100%' }}>
                <Stack
                  direction='row'
                  justifyContent='space-between'
                  alignItems='flex-start'
                  spacing={1}
                >
                  <Box>
                    <Typography variant='h6' sx={{ fontWeight: 700 }}>
                      {protocol.name}
                    </Typography>
                    <Typography variant='body2' color='text.secondary'>
                      {protocol.code}
                    </Typography>
                  </Box>
                  <Chip
                    size='small'
                    color={protocol.isActive ? 'success' : 'default'}
                    label={protocol.isActive ? 'Activo' : 'Inactivo'}
                  />
                </Stack>

                <Typography
                  variant='body2'
                  color='text.secondary'
                  sx={{ mt: 1.5, minHeight: 42 }}
                >
                  {protocol.description || 'Sin descripción registrada.'}
                </Typography>

                <Stack
                  direction='row'
                  spacing={1}
                  flexWrap='wrap'
                  sx={{ mt: 1.5 }}
                >
                  {protocol.riskClass && (
                    <Chip
                      size='small'
                      variant='outlined'
                      label={protocol.riskClass}
                    />
                  )}
                  <Chip
                    size='small'
                    variant='outlined'
                    label={`${protocol.tools.length} herramienta(s)`}
                  />
                  <Chip
                    size='small'
                    variant='outlined'
                    label={`${protocol.tests.length} prueba(s)`}
                  />
                </Stack>

                <Box sx={{ mt: 1.5 }}>
                  <Typography variant='caption' color='text.secondary'>
                    Aplica a:
                  </Typography>
                  <Stack
                    direction='row'
                    spacing={1}
                    flexWrap='wrap'
                    sx={{ mt: 0.75 }}
                  >
                    {protocol.appliesTo.length ? (
                      protocol.appliesTo.map((keyword) => (
                        <Chip
                          key={`${protocol.id}-${keyword}`}
                          size='small'
                          label={keyword}
                        />
                      ))
                    ) : (
                      <Chip size='small' label='Sin keywords' />
                    )}
                  </Stack>
                </Box>

                <Stack direction='row' spacing={1} sx={{ mt: 2 }}>
                  <Button
                    size='small'
                    startIcon={<EditOutlined />}
                    onClick={() => openEditDialog(protocol)}
                  >
                    Editar
                  </Button>
                  <Button
                    size='small'
                    color='error'
                    startIcon={<DeleteOutline />}
                    onClick={() => handleDelete(protocol)}
                  >
                    Eliminar
                  </Button>
                </Stack>
              </Paper>
            </Grid>
          ))}
        </Grid>
      )}

      <Dialog open={dialogOpen} onClose={resetDialog} fullWidth maxWidth='lg'>
        <DialogTitle>
          {currentProtocol ? 'Editar protocolo' : 'Nuevo protocolo'}
        </DialogTitle>
        <DialogContent dividers>
          <Stack spacing={2.5} sx={{ mt: 1 }}>
            {formError && <Alert severity='error'>{formError}</Alert>}

            <Grid container spacing={2}>
              <Grid item xs={12} md={5}>
                <TextField
                  fullWidth
                  label='Nombre'
                  value={formState.name}
                  onChange={(e) =>
                    setFormState((prev) => ({ ...prev, name: e.target.value }))
                  }
                />
              </Grid>
              <Grid item xs={12} md={3}>
                <TextField
                  fullWidth
                  label='Código'
                  value={formState.code}
                  onChange={(e) =>
                    setFormState((prev) => ({ ...prev, code: e.target.value }))
                  }
                />
              </Grid>
              <Grid item xs={12} md={2}>
                <TextField
                  fullWidth
                  type='number'
                  label='Orden'
                  value={formState.sortOrder}
                  onChange={(e) =>
                    setFormState((prev) => ({
                      ...prev,
                      sortOrder: Number(e.target.value) || 0
                    }))
                  }
                />
              </Grid>
              <Grid item xs={12} md={2}>
                <FormControlLabel
                  control={
                    <Switch
                      checked={formState.isActive}
                      onChange={(e) =>
                        setFormState((prev) => ({
                          ...prev,
                          isActive: e.target.checked
                        }))
                      }
                    />
                  }
                  label='Activo'
                  sx={{ mt: 1 }}
                />
              </Grid>
              <Grid item xs={12}>
                <TextField
                  fullWidth
                  multiline
                  minRows={2}
                  label='Descripción'
                  value={formState.description}
                  onChange={(e) =>
                    setFormState((prev) => ({
                      ...prev,
                      description: e.target.value
                    }))
                  }
                />
              </Grid>
              <Grid item xs={12} md={4}>
                <TextField
                  fullWidth
                  label='Clase de riesgo'
                  value={formState.riskClass}
                  onChange={(e) =>
                    setFormState((prev) => ({
                      ...prev,
                      riskClass: e.target.value
                    }))
                  }
                />
              </Grid>
              <Grid item xs={12} md={8}>
                <TextField
                  fullWidth
                  label='Aplica a'
                  helperText='Separa keywords por coma. Ej: monitor, signos vitales, spo2'
                  value={formState.appliesToText}
                  onChange={(e) =>
                    setFormState((prev) => ({
                      ...prev,
                      appliesToText: e.target.value
                    }))
                  }
                />
              </Grid>
              <Grid item xs={12}>
                <TextField
                  fullWidth
                  multiline
                  minRows={2}
                  label='Recomendaciones por defecto'
                  value={formState.recommendations}
                  onChange={(e) =>
                    setFormState((prev) => ({
                      ...prev,
                      recommendations: e.target.value
                    }))
                  }
                />
              </Grid>
            </Grid>

            <Paper variant='outlined' sx={{ p: 2 }}>
              <Stack
                direction='row'
                justifyContent='space-between'
                alignItems='center'
                sx={{ mb: 2 }}
              >
                <Typography variant='subtitle1' sx={{ fontWeight: 700 }}>
                  Herramientas por defecto
                </Typography>
                <Button
                  size='small'
                  startIcon={<Add />}
                  onClick={() =>
                    setFormState((prev) => ({
                      ...prev,
                      tools: [...prev.tools, emptyTool()]
                    }))
                  }
                >
                  Herramienta
                </Button>
              </Stack>
              <Stack spacing={1.5}>
                {formState.tools.map((tool, index) => (
                  <Grid container spacing={1} key={`protocol-tool-${index}`}>
                    <Grid item xs={12} md={5}>
                      <Autocomplete<
                        MaintenanceToolEquipmentSummary,
                        false,
                        false,
                        true
                      >
                        freeSolo
                        options={toolEquipmentOptions}
                        loading={toolSearchLoading}
                        value={null}
                        inputValue={tool.name || ''}
                        onInputChange={(_, value) => {
                          setToolSearch(value)
                          updateTool(index, 'name', value)
                        }}
                        onChange={(_, value) => {
                          if (!value || typeof value === 'string') return

                          updateTool(index, 'name', value.equipmentName)
                          updateTool(index, 'serial', value.serialNumber || '')
                          updateTool(
                            index,
                            'internalCode',
                            value.internalCode || ''
                          )
                          updateTool(index, 'location', value.location || '')
                          updateTool(
                            index,
                            'calibrationDue',
                            value.nextCalibrationDate
                              ? String(value.nextCalibrationDate).slice(0, 10)
                              : null
                          )
                        }}
                        getOptionLabel={(option) =>
                          typeof option === 'string'
                            ? option
                            : `${option.internalCode} - ${option.equipmentName}`
                        }
                        isOptionEqualToValue={(option, value) =>
                          option.id === value.id
                        }
                        renderInput={(params) => (
                          <TextField
                            {...params}
                            fullWidth
                            label='Nombre'
                            helperText='Busca un equipo del inventario o escribe manualmente.'
                          />
                        )}
                        renderOption={(props, option) => (
                          <Box component='li' {...props}>
                            <Box>
                              <Typography variant='body2' fontWeight={700}>
                                {option.internalCode} - {option.equipmentName}
                              </Typography>
                              <Typography
                                variant='caption'
                                color='text.secondary'
                              >
                                {option.brand} {option.model} | Serie:{' '}
                                {option.serialNumber}
                                {option.nextCalibrationDate
                                  ? ` | Vence: ${new Date(option.nextCalibrationDate).toLocaleDateString('es-CO')}`
                                  : ''}
                              </Typography>
                            </Box>
                          </Box>
                        )}
                      />
                    </Grid>
                    <Grid item xs={12} md={3}>
                      <TextField
                        fullWidth
                        label='Serie'
                        value={tool.serial || ''}
                        onChange={(e) =>
                          updateTool(index, 'serial', e.target.value)
                        }
                      />
                    </Grid>
                    <Grid item xs={12} md={3}>
                      <TextField
                        fullWidth
                        type='date'
                        label='Calibración vence'
                        InputLabelProps={{ shrink: true }}
                        value={tool.calibrationDue || ''}
                        onChange={(e) =>
                          updateTool(
                            index,
                            'calibrationDue',
                            e.target.value || null
                          )
                        }
                      />
                    </Grid>
                    {(tool.internalCode || tool.location) && (
                      <Grid item xs={12} md={11}>
                        <Stack
                          direction={{ xs: 'column', sm: 'row' }}
                          spacing={1}
                          alignItems={{ xs: 'flex-start', sm: 'center' }}
                        >
                          {tool.internalCode && (
                            <Chip
                              size='small'
                              color='primary'
                              variant='outlined'
                              label={`Código interno: ${tool.internalCode}`}
                            />
                          )}
                          {tool.location && (
                            <Typography
                              variant='caption'
                              color='text.secondary'
                            >
                              Ubicación: {tool.location}
                            </Typography>
                          )}
                        </Stack>
                      </Grid>
                    )}
                    <Grid item xs={12} md={1}>
                      <IconButton
                        onClick={() =>
                          setFormState((prev) => ({
                            ...prev,
                            tools:
                              prev.tools.length > 1
                                ? prev.tools.filter((_, idx) => idx !== index)
                                : [emptyTool()]
                          }))
                        }
                      >
                        <DeleteOutline />
                      </IconButton>
                    </Grid>
                  </Grid>
                ))}
              </Stack>
            </Paper>

            <Paper variant='outlined' sx={{ p: 2 }}>
              <Stack
                direction='row'
                justifyContent='space-between'
                alignItems='center'
                sx={{ mb: 2 }}
              >
                <Typography variant='subtitle1' sx={{ fontWeight: 700 }}>
                  Pruebas por defecto
                </Typography>
                <Button
                  size='small'
                  startIcon={<PlaylistAddCheck />}
                  onClick={() =>
                    setFormState((prev) => ({
                      ...prev,
                      tests: [...prev.tests, emptyTest()]
                    }))
                  }
                >
                  Prueba
                </Button>
              </Stack>
              <Stack spacing={1.5}>
                {formState.tests.map((test, index) => (
                  <Grid container spacing={1} key={`protocol-test-${index}`}>
                    <Grid item xs={12} md={4}>
                      <TextField
                        fullWidth
                        label='Parámetro'
                        value={test.parameter}
                        onChange={(e) =>
                          updateTest(index, 'parameter', e.target.value)
                        }
                      />
                    </Grid>
                    <Grid item xs={12} md={2}>
                      <TextField
                        select
                        fullWidth
                        label='Resultado'
                        value={test.result}
                        onChange={(e) =>
                          updateTest(index, 'result', e.target.value)
                        }
                      >
                        <MenuItem value='PASA'>PASA</MenuItem>
                        <MenuItem value='NO PASA'>NO PASA</MenuItem>
                        <MenuItem value='OBSERVADO'>OBSERVADO</MenuItem>
                      </TextField>
                    </Grid>
                    <Grid item xs={12} md={2}>
                      <TextField
                        fullWidth
                        label='Valor'
                        value={test.value || ''}
                        onChange={(e) =>
                          updateTest(index, 'value', e.target.value)
                        }
                      />
                    </Grid>
                    <Grid item xs={12} md={3}>
                      <TextField
                        fullWidth
                        label='Notas'
                        value={test.notes || ''}
                        onChange={(e) =>
                          updateTest(index, 'notes', e.target.value)
                        }
                      />
                    </Grid>
                    <Grid item xs={12} md={1}>
                      <IconButton
                        onClick={() =>
                          setFormState((prev) => ({
                            ...prev,
                            tests:
                              prev.tests.length > 1
                                ? prev.tests.filter((_, idx) => idx !== index)
                                : [emptyTest()]
                          }))
                        }
                      >
                        <DeleteOutline />
                      </IconButton>
                    </Grid>
                  </Grid>
                ))}
              </Stack>
            </Paper>
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button onClick={resetDialog}>Cancelar</Button>
          <Button
            variant='contained'
            onClick={handleSave}
            disabled={
              createProtocolMutation.isLoading ||
              updateProtocolMutation.isLoading
            }
          >
            {currentProtocol ? 'Guardar cambios' : 'Crear protocolo'}
          </Button>
        </DialogActions>
      </Dialog>
    </Container>
  )
}

export default MaintenanceProtocols

import { getApiErrorReason } from 'src/utils/apiError'
import SignalLoader from 'src/Components/Common/SignalLoader'
import React, { useState } from 'react'
import {
  Container,
  Paper,
  Typography,
  Box,
  TextField,
  Button,
  Grid,
  Alert,
  Stepper,
  Step,
  StepLabel,
  Card,
  CardContent,
  FormControl,
  Chip,
  Divider
} from '@mui/material'
import { Build, CheckCircle, Send, Error } from '@mui/icons-material'
import { useFormik } from 'formik'
import * as Yup from 'yup'
import {
  MaintenanceCreateRequest,
  MaintenancePriority
} from '../../types/maintenance'
import { useCreateMaintenanceTicket } from '../../hooks/useMaintenance'
import MaintenanceFileUpload from '../../Components/Maintenance/MaintenanceFileUpload'
import MaintenanceErrorBoundary from '../../Components/Maintenance/MaintenanceErrorBoundary'

import { logger } from 'src/utils/logger'
const validationSchema = Yup.object({
  customerName: Yup.string()
    .min(2, 'El nombre debe tener al menos 2 caracteres')
    .max(100, 'El nombre no puede exceder 100 caracteres')
    .required('El nombre es requerido'),
  customerEmail: Yup.string()
    .email('Email inválido')
    .required('El email es requerido'),
  customerPhone: Yup.string()
    .min(10, 'El teléfono debe tener al menos 10 dígitos')
    .required('El teléfono es requerido'),
  equipmentType: Yup.string().required('El tipo de equipo es requerido'),
  equipmentBrand: Yup.string().required('La marca es requerida'),
  equipmentModel: Yup.string().required('El modelo es requerido'),
  equipmentSerial: Yup.string().required('El número de serie es requerido'),
  issueDescription: Yup.string()
    .min(10, 'La descripción debe tener al menos 10 caracteres')
    .max(1000, 'La descripción no puede exceder 1000 caracteres')
    .required('La descripción del problema es requerida'),
  location: Yup.string().required('La ubicación es requerida')
})

const steps = [
  'Información Personal',
  'Datos del Equipo',
  'Descripción del Problema',
  'Confirmación'
]

/**
 * MaintenanceReport component provides a public form for creating maintenance requests
 * This is accessible without authentication for customers to report equipment issues
 */
const MaintenanceReport: React.FC = () => {
  const [activeStep, setActiveStep] = useState(0)
  const [files, setFiles] = useState<File[]>([])
  const [submissionResult, setSubmissionResult] = useState<{
    success: boolean
    ticketNumber?: string
    message: string
  } | null>(null)

  const createTicketMutation = useCreateMaintenanceTicket()

  const formik = useFormik<MaintenanceCreateRequest>({
    initialValues: {
      customerName: '',
      customerEmail: '',
      customerPhone: '',
      equipmentType: '',
      equipmentBrand: '',
      equipmentModel: '',
      equipmentSerial: '',
      issueDescription: '',
      location: '',
      files: []
    },
    validationSchema,
    onSubmit: async (values) => {
      try {
        const submitData = {
          ...values,
          priority: MaintenancePriority.MEDIUM,
          files: files
        }

        const result = await createTicketMutation.mutateAsync(submitData)

        setSubmissionResult({
          success: true,
          ticketNumber:
            result?.ticketNumber || result?.ticket?.ticketCode || 'Sin número',
          message:
            'Solicitud enviada exitosamente. Su ticket ha sido creado y está pendiente de asignación. Recibirá una confirmación por email.'
        })

        // Reset form
        formik.resetForm()
        setFiles([])
        setActiveStep(0)
      } catch (error: any) {
        logger.error('Maintenance form submission error:', error)
        let errorMessage = 'Error al enviar la solicitud. Intente nuevamente.'

        if (getApiErrorReason(error)) {
          errorMessage = getApiErrorReason(error) ?? errorMessage
        } else if (error.message) {
          errorMessage = error.message
        }

        setSubmissionResult({
          success: false,
          message: errorMessage
        })
      }
    }
  })

  const handleNext = () => {
    if (activeStep < steps.length - 1) {
      setActiveStep(activeStep + 1)
    }
  }

  const handleBack = () => {
    if (activeStep > 0) {
      setActiveStep(activeStep - 1)
    }
  }

  const handleFilesChange = (newFiles: File[]) => {
    setFiles((prev) => [...prev, ...newFiles])
  }

  const handleFileRemove = (index: number) => {
    setFiles((prev) => prev.filter((_, i) => i !== index))
  }

  const isStepValid = (step: number) => {
    switch (step) {
      case 0:
        return (
          !formik.errors.customerName &&
          !formik.errors.customerEmail &&
          !formik.errors.customerPhone &&
          formik.values.customerName &&
          formik.values.customerEmail &&
          formik.values.customerPhone
        )
      case 1:
        return (
          !formik.errors.equipmentType &&
          !formik.errors.equipmentBrand &&
          !formik.errors.equipmentModel &&
          !formik.errors.equipmentSerial &&
          formik.values.equipmentType &&
          formik.values.equipmentBrand &&
          formik.values.equipmentModel &&
          formik.values.equipmentSerial
        )
      case 2:
        return (
          !formik.errors.issueDescription &&
          !formik.errors.location &&
          formik.values.issueDescription &&
          formik.values.location
        )
      case 3:
        return true
      default:
        return false
    }
  }

  const renderStepContent = (step: number) => {
    switch (step) {
      case 0:
        return (
          <Grid container spacing={3}>
            <Grid item xs={12}>
              <Typography variant='h6' gutterBottom>
                Información de Contacto
              </Typography>
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                name='customerName'
                label='Nombre Completo'
                value={formik.values.customerName}
                onChange={formik.handleChange}
                onBlur={formik.handleBlur}
                error={
                  formik.touched.customerName &&
                  Boolean(formik.errors.customerName)
                }
                helperText={
                  formik.touched.customerName && formik.errors.customerName
                }
                required
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                name='customerEmail'
                label='Email'
                type='email'
                value={formik.values.customerEmail}
                onChange={formik.handleChange}
                onBlur={formik.handleBlur}
                error={
                  formik.touched.customerEmail &&
                  Boolean(formik.errors.customerEmail)
                }
                helperText={
                  formik.touched.customerEmail && formik.errors.customerEmail
                }
                required
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                name='customerPhone'
                label='Teléfono'
                value={formik.values.customerPhone}
                onChange={formik.handleChange}
                onBlur={formik.handleBlur}
                error={
                  formik.touched.customerPhone &&
                  Boolean(formik.errors.customerPhone)
                }
                helperText={
                  formik.touched.customerPhone && formik.errors.customerPhone
                }
                required
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                name='location'
                label='Cliente / Ubicación'
                value={formik.values.location}
                onChange={formik.handleChange}
                onBlur={formik.handleBlur}
                error={
                  formik.touched.location && Boolean(formik.errors.location)
                }
                helperText={formik.touched.location && formik.errors.location}
                required
              />
            </Grid>
          </Grid>
        )

      case 1:
        return (
          <Grid container spacing={3}>
            <Grid item xs={12}>
              <Typography variant='h6' gutterBottom>
                Información del Equipo
              </Typography>
            </Grid>
            <Grid item xs={12} md={6}>
              <FormControl fullWidth required>
                <TextField
                  fullWidth
                  name='equipmentType'
                  label='Tipo de Equipo'
                  value={formik.values.equipmentType}
                  onChange={formik.handleChange}
                  onBlur={formik.handleBlur}
                  error={
                    formik.touched.equipmentType &&
                    Boolean(formik.errors.equipmentType)
                  }
                  helperText={
                    formik.touched.equipmentType && formik.errors.equipmentType
                  }
                  required
                />
              </FormControl>
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                name='equipmentBrand'
                label='Marca'
                value={formik.values.equipmentBrand}
                onChange={formik.handleChange}
                onBlur={formik.handleBlur}
                error={
                  formik.touched.equipmentBrand &&
                  Boolean(formik.errors.equipmentBrand)
                }
                helperText={
                  formik.touched.equipmentBrand && formik.errors.equipmentBrand
                }
                required
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                name='equipmentModel'
                label='Modelo'
                value={formik.values.equipmentModel}
                onChange={formik.handleChange}
                onBlur={formik.handleBlur}
                error={
                  formik.touched.equipmentModel &&
                  Boolean(formik.errors.equipmentModel)
                }
                helperText={
                  formik.touched.equipmentModel && formik.errors.equipmentModel
                }
                required
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                name='equipmentSerial'
                label='Número de Serie'
                value={formik.values.equipmentSerial}
                onChange={formik.handleChange}
                onBlur={formik.handleBlur}
                error={
                  formik.touched.equipmentSerial &&
                  Boolean(formik.errors.equipmentSerial)
                }
                helperText={
                  formik.touched.equipmentSerial &&
                  formik.errors.equipmentSerial
                }
                required
              />
            </Grid>
          </Grid>
        )

      case 2:
        return (
          <Grid container spacing={3}>
            <Grid item xs={12}>
              <Typography variant='h6' gutterBottom>
                Descripción del Problema
              </Typography>
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                multiline
                rows={4}
                name='issueDescription'
                label='Describa el problema detalladamente'
                value={formik.values.issueDescription}
                onChange={formik.handleChange}
                onBlur={formik.handleBlur}
                error={
                  formik.touched.issueDescription &&
                  Boolean(formik.errors.issueDescription)
                }
                helperText={
                  formik.touched.issueDescription &&
                  formik.errors.issueDescription
                }
                required
              />
            </Grid>
            <Grid item xs={12}>
              <Typography variant='subtitle2' gutterBottom>
                Archivos Adjuntos (Opcional)
              </Typography>
              <MaintenanceFileUpload
                files={files.map((file, index) => ({
                  id: index.toString(),
                  ticketId: '',
                  fileName: file.name,
                  originalName: file.name,
                  fileType: file.type,
                  fileSize: file.size,
                  filePath: '',
                  uploadedBy: '',
                  uploadedAt: '',
                  isImage: file.type.startsWith('image/'),
                  isVideo: file.type.startsWith('video/')
                }))}
                onFilesChange={handleFilesChange}
                onFileRemove={(fileId) => handleFileRemove(parseInt(fileId))}
                maxFiles={5}
                maxSizeInMB={10}
              />
            </Grid>
          </Grid>
        )

      case 3:
        return (
          <Grid container spacing={3}>
            <Grid item xs={12}>
              <Typography variant='h6' gutterBottom>
                Confirmación de Datos
              </Typography>
            </Grid>
            <Grid item xs={12}>
              <Card variant='outlined'>
                <CardContent>
                  <Typography variant='subtitle1' gutterBottom>
                    Información de Contacto
                  </Typography>
                  <Typography variant='body2' color='text.secondary'>
                    <strong>Nombre:</strong> {formik.values.customerName}
                  </Typography>
                  <Typography variant='body2' color='text.secondary'>
                    <strong>Email:</strong> {formik.values.customerEmail}
                  </Typography>
                  <Typography variant='body2' color='text.secondary'>
                    <strong>Teléfono:</strong> {formik.values.customerPhone}
                  </Typography>
                  <Typography variant='body2' color='text.secondary'>
                    <strong>Ubicación:</strong> {formik.values.location}
                  </Typography>

                  <Divider sx={{ my: 2 }} />

                  <Typography variant='subtitle1' gutterBottom>
                    Información del Equipo
                  </Typography>
                  <Typography variant='body2' color='text.secondary'>
                    <strong>Tipo:</strong> {formik.values.equipmentType}
                  </Typography>
                  <Typography variant='body2' color='text.secondary'>
                    <strong>Marca:</strong> {formik.values.equipmentBrand}
                  </Typography>
                  <Typography variant='body2' color='text.secondary'>
                    <strong>Modelo:</strong> {formik.values.equipmentModel}
                  </Typography>
                  <Typography variant='body2' color='text.secondary'>
                    <strong>Serie:</strong> {formik.values.equipmentSerial}
                  </Typography>

                  <Divider sx={{ my: 2 }} />

                  <Typography variant='subtitle1' gutterBottom>
                    Problema Reportado
                  </Typography>
                  <Typography variant='body2' color='text.secondary' paragraph>
                    {formik.values.issueDescription}
                  </Typography>

                  {files.length > 0 && (
                    <>
                      <Divider sx={{ my: 2 }} />
                      <Typography variant='subtitle1' gutterBottom>
                        Archivos Adjuntos
                      </Typography>
                      <Box display='flex' flexWrap='wrap' gap={1}>
                        {files.map((file, index) => (
                          <Chip
                            key={index}
                            label={file.name}
                            size='small'
                            variant='outlined'
                            color='primary'
                          />
                        ))}
                      </Box>
                    </>
                  )}
                </CardContent>
              </Card>
            </Grid>
          </Grid>
        )

      default:
        return null
    }
  }

  if (submissionResult) {
    return (
      <Container maxWidth='md' sx={{ py: 4 }}>
        <Paper elevation={3} sx={{ p: 4 }}>
          <Box textAlign='center'>
            {submissionResult.success ? (
              <>
                <CheckCircle color='success' sx={{ fontSize: 64, mb: 2 }} />
                <Typography variant='h4' gutterBottom color='success.main'>
                  ¡Solicitud Enviada!
                </Typography>
                <Typography variant='h6' gutterBottom>
                  Número de Ticket:{' '}
                  <strong>{submissionResult.ticketNumber}</strong>
                </Typography>
                <Typography variant='body1' color='text.secondary' paragraph>
                  {submissionResult.message}
                </Typography>
                <Typography variant='body2' color='text.secondary' paragraph>
                  Puede hacer seguimiento de su solicitud usando el número de
                  ticket en la página de seguimiento.
                </Typography>
                <Box mt={3}>
                  <Button
                    variant='contained'
                    onClick={() =>
                      (window.location.href = '/maintenance/tracking')
                    }
                    sx={{ mr: 2 }}
                  >
                    Hacer Seguimiento
                  </Button>
                  <Button
                    variant='outlined'
                    onClick={() => setSubmissionResult(null)}
                  >
                    Nueva Solicitud
                  </Button>
                </Box>
              </>
            ) : (
              <>
                <Error color='error' sx={{ fontSize: 64, mb: 2 }} />
                <Typography variant='h4' gutterBottom color='error.main'>
                  Error al Enviar
                </Typography>
                <Typography variant='body1' color='text.secondary' paragraph>
                  {submissionResult.message}
                </Typography>
                <Button
                  variant='contained'
                  onClick={() => setSubmissionResult(null)}
                >
                  Intentar Nuevamente
                </Button>
              </>
            )}
          </Box>
        </Paper>
      </Container>
    )
  }

  return (
    <MaintenanceErrorBoundary>
      <Container maxWidth='md' sx={{ py: 4 }}>
        {/* @ts-ignore - Material-UI Paper type compatibility issue */}
        <Paper elevation={3} sx={{ p: 4 }}>
          {/* Header */}
          <Box textAlign='center' mb={4}>
            <Build color='primary' sx={{ fontSize: 48, mb: 2 }} />
            <Typography variant='h4' gutterBottom>
              Solicitud de Mantenimiento
            </Typography>
            <Typography variant='body1' color='text.secondary'>
              Complete el siguiente formulario para reportar un problema con su
              equipo médico
            </Typography>
          </Box>

          {/* Stepper */}
          <Box sx={{ mb: 4 }}>
            <Stepper activeStep={activeStep}>
              {steps.map(
                (label: string, index: number): React.JSX.Element => (
                  <Step key={`step-${index}`}>
                    <StepLabel>{label}</StepLabel>
                  </Step>
                )
              )}
            </Stepper>
          </Box>

          {/* Loading indicator */}
          {createTicketMutation.isLoading && (
            <Box mb={2}>
              <SignalLoader size='small' message='Enviando solicitud...' />
            </Box>
          )}

          {/* Error display */}
          {!!createTicketMutation.error && (
            <Alert severity='error' sx={{ mb: 2 }}>
              Error al enviar la solicitud. Verifique los datos e intente
              nuevamente.
            </Alert>
          )}

          {/* Form content */}
          <form onSubmit={formik.handleSubmit}>
            <Box mb={4}>{renderStepContent(activeStep)}</Box>

            {/* Navigation buttons */}
            <Box display='flex' justifyContent='space-between'>
              <Button
                disabled={activeStep === 0}
                onClick={handleBack}
                variant='outlined'
              >
                Anterior
              </Button>

              {activeStep === steps.length - 1 ? (
                <Button
                  type='submit'
                  variant='contained'
                  disabled={!formik.isValid || createTicketMutation.isLoading}
                  endIcon={<Send />}
                >
                  Enviar Solicitud
                </Button>
              ) : (
                <Button
                  onClick={handleNext}
                  variant='contained'
                  disabled={!isStepValid(activeStep)}
                >
                  Siguiente
                </Button>
              )}
            </Box>
          </form>
        </Paper>
      </Container>
    </MaintenanceErrorBoundary>
  )
}

